window.__D("text/torat-shmuel/c028",{"p":[[2000450255,"כמה א\"א לפניו<sup data-n=\"2399\">1389</sup> ובד\"ה וארא אל אברהם בפי' קוב\"ה בגלותא סליק לעילא ולעילא כו' ובד\"ה כי עמך מקו\"ח<sup data-n=\"2400\">1390</sup> בפי' רם על כל גוים הוי' ובד\"ה ויאבק איש עמו בפי' אם תגביהי כנשר, וזהו שמבחי' אלף יכול להיות יניקה גם לבחי' ארור, ועד\"ז ארז\"ל ברבות בראשית ס\"פ י\"ב ע\"פ ביום עשות ה' אלקים<sup data-n=\"2401\">1391</sup> שאלמלא הי' נבה\"ע במדת החסד לבד בלי שיתוף מדה\"ד הי' חטאין סגיאין וכנ\"ל, &lt;ס&gt;\nּ והיינו כי מצד ורב חסד יוכל להשפיע חיות גם במקום שאין בו הביטול כו' ולכן כדי שיהי' העולם צדיקים הוצרך להיות שיתוף מדה\"ד, וז\"ע החכ' שיש בה ג\"כ קצת דין<sup data-n=\"2402\">1392</sup> כו' להיות ואוהב את יעקב, ושונא את הרשעים, ולכן בית הוא סימן ברכה, וז\"ע פותח בברוך שהוא שיומשך ע\"י צינור מהכתר בחכ' במקום הביטול כו', ואחר שנמשך בחכ' שוב לא יוכלו החיצונים לקבל כי אור אבא דוחה החיצוני' כמבואר בדרוש הנגעים הנ\"ל<sup data-n=\"2403\">1393</sup>, ולכן א\"צ לחותם, אך אור אבא מאיר רק עד האצי' משא\"כ בבריאה אינו מאיר אור אבא, ולכן ומשם יפרד, וע\"כ יוכל להיות יניקה גם לטורי דפרודא ממש, ולזה צ\"ל חותם בברוך שעם היות שבבי\"ע יש חיצוני' וצריך ליתן להם חיות ויניקה, מ\"מ יומשך רק כפי המדה מבחי' מותרות ולא מעיקר השפע, ועמ\"ש ע\"פ אם בן הוא<sup data-n=\"2404\">1394</sup> והמתן אותו ואם בת היא וחיה שיניקת החיצונים מעלמא דאתגלי' הנק' עלמא דנוק' ולכן שם צ\"ל חותם, ועמ\"ש מזה בביאור ע\"פ וכל בניך<sup data-n=\"2405\">1395</sup> בענין א\"ת בניך אלא בונייך, וז\"ע חייב אינש לבסומי בפורי'<sup data-n=\"2406\">1396</sup> עד דלא ידעי בין ארור המן לברוך מרדכי, כי הנה המן שהפיל פור הוא הגורל<sup data-n=\"2407\">1397</sup> היינו לבחי' כחשוכה<sup data-n=\"2408\">1398</sup> כאורה ששם כעין עד דלא ידעי בין ארור המן לברוך מרדכי, ר\"ל ששם המן יוכל להיות לו השפעה כי שממית בידים תתפש כו' ורבו פשעיך מה תעשה לו<sup data-n=\"2409\">1399</sup> כו', כי בחכ' דוקא הוא בחי' ברוך מרדכי, משא\"כ בבחי' דכחשיכה כאורה משם גם ארור יש לו יניקה, וז\"ע האלף כו' כנ\"ל, והנס דפורים זהו ע\"ד פותח בברוך שמשם דוקא היינו מבחי' עד דלא ידעי כו' המשיכו להיות ברוך מרדכי ושיהי' ארור המן ולא יהי' לו יניקה כו', וכמ\"כ חותם בברוך כי הטבעת וחותם המלך ניטלה מהמן וניתן למרדכי, וע' בזח\"א ס\"פ תולדות קמ\"ה א' ע\"פ פיה פתחה בחכ'<sup data-n=\"2410\">1400</sup> דא ב' דבראשית כו', ד\"א דא ה' בתראה ועמ\"ש מזה",[["2399","1389","<b>בפ' בשלח. . לפניו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א בשלח סא, א</a>."],["2400","1390","<b>ובד\"ה כי עמך מקו\"ח</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">תו\"א מקץ לד, ד</a> ואילך."],["2401","1391","<b>ביום עשות ה' אלקים</b>: בראשית ב, ד."],["2402","1392","<b>החכ'. . קצת דין</b>: ראה שערי אורה שער ט צב, ב. מערכת אלקות פ\"ד מערכת שמות המדות ד\"ה השני' בסופה ובפי' החייט שם. פרדס שער מהות והנהגה ש\"ח, פ\"ה. פ\"ו. שער המכריעין ש\"ט, פ\"ה. ע\"ח שער א\"א שי\"ג, פ\"ו. מבו\"ש ש\"ג ח\"ב פ\"ו בשם המערכת. מאמרי אדה\"א נ\"ך ע' שיג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670138\" data-slug=\"torat-chaim\" data-id=\"2300670138\">תו\"ח בראשית לא, ד</a> ובהערה 40."],["2403","1393","<b>בדרוש הנגעים הנ\"ל</b>: ע\"ח שהובא בלקו\"ת בהערה 1353."],["2404","1394","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540388\" data-slug=\"torat-chaim\" data-id=\"2300540388\">אם בן הוא</b>: שמות א</a>, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540388\" data-slug=\"torat-chaim\" data-id=\"2300540388\">תו\"ח שמות ח\"א כו, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450660\" data-slug=\"or-hatorah-hb\" data-id=\"8316450660\">לד, סע\"ב</a> ואילך. אוה\"ת שמות כרך ז ע' ב'תקט ואילך. כרך ח ע' ב'תתמו. אוה\"ת כאן ע' 1130."],["2405","1395","<b>ע\"פ וכל בניך</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380840\" data-slug=\"likkutei-torah\" data-id=\"4001380840\">לקו\"ת ראה לא, א</a>."],["2406","1396","<b>חייב אינש לבסומי בפורי'</b>: ראה מגילה ז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071020\" data-slug=\"likkutei-sichot\" data-id=\"1300071020\">לקו\"ש ויקרא כרך ז ע' 20</a> הערה 2."],["2407","1397","<b>שהפיל פור הוא הגורל</b>: אסתר ג, ז."],["2408","1398","<b>כחשוכה</b>: ב: כחשיכה. בלקו\"ת לג\"פ ובאוה\"ת: דכחשיכא."],["2409","1399","<b>ורבו פשעיך מה תעשה לו</b>: איוב לה, ו."],["2410","1400","<b>פיה פתחה בחכ'</b>: משלי לא, כו."]]],[2000450256,"בסידור ע\"פ מזמור לתודה<sup data-n=\"2411\">1401</sup>, ועכ\"ז יובן ענין פותח בברוך, ועמ\"ש מענין קמץ בכתר ופתח בחכ'<sup data-n=\"2412\">1402</sup>, ובענין פי' פותח את ידיך<sup data-n=\"2413\">1403</sup> א\"ת ידיך אלא יודיך<sup data-n=\"2414\">1404</sup> בד\"ה כי ההרים ימושו<sup data-n=\"2415\">1405</sup>, ומ\"ש ע\"פ ופתחת עליו פתוחי חותם<sup data-n=\"2416\">1406</sup> בד\"ה ועשית ציץ<sup data-n=\"2417\">1407</sup>, ולפ\"ז פותח בברוך היינו שלא יהי' יניקה מצד ריבוי החסד וחותם בברוך שלא יהי' רבוי היניקה מצד ההשתלשלות<sup data-n=\"2418\">1408</sup> ממה\"ד מסטרא דשמאלא, וז\"ע<sup data-n=\"2419\">1409</sup> גדול העונה אמן יותר מן המברך, כי הברכה מתחיל בבית ואמן באלף, והיינו כי אחר שהתחיל בברוך אזי גם מהאלף נמשך ג\"כ בבחי' זו, ולכן עשה\"ד מתחילין באלף, כי אחר שהתחיל התו' בבית שהוא סימן ברכה, כמו\"כ מבחי' הכתר עליון יומשך בחי' זו כו', וענין עניית אמן זהו קיום הברכה וכמ\"ש ברע\"מ ר\"פ עקב דרע\"א ע\"א דא &lt;סא&gt;\nּ איהו<sup data-n=\"2420\">1410</sup> דורנא<sup data-n=\"2421\">1411</sup> בקיומא כדקא יאות, ומאן איהו דא ברכה דאתיבו עלה<sup data-n=\"2422\">1412</sup> אמן וכנ\"ל, והיינו כי אמן גימ' הוי' אד' יחו\"ע ויחו\"ת<sup data-n=\"2423\">1413</sup>, שגם ביחו\"ת מקיים ברכה וגילוי זה להיות ביטול היש כמ\"ש סד\"ה משה ידבר<sup data-n=\"2424\">1414</sup> בפי' והאלקי' יעננו בקול, וקיום זה זהו כענין חותם בברוך, והחותם עיקרו ע\"י המקיף עליון שהוא הכתר, ולכן ארז\"ל חותמו של הקב\"ה אמת<sup data-n=\"2425\">1415</sup>, נמצא מתחיל החותם באות אלף והסיום עד תיו ע\"ש אני ראשון ואני אחרון<sup data-n=\"2426\">1416</sup> כמ\"ש במד\"ר וישלח פ' פ\"א<sup data-n=\"2427\">1417</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> ולכן במטבע קצר א\"צ אלא לפתוח בברוך, ואזי בל תמוט, כי לא יגורך רע אבל במטבע ארוך עלמא דאתגלי', ומשם יפרד צ\"ל חותם, אותיות חומת אני חומה זו תו', חשמל מגין, ענין שבריאת העולמות מתחיל באות ב' סימן ברכה אע\"פ שאות אלף גבוה יותר, אלא כי פי' פתחה בחכ' ע\"ד פותח בברוך, ולכן גדול העונה אמן שמתחיל באלף ע\"ד חותמו של הקב\"ה אמת כו'.</span>",[["2411","1401","<b>בסידור ע\"פ מזמור לתודה</b>: שחרית מה, ב."],["2412","1402","<b>קמץ בכתר ופתח בחכ'</b>: ראה ת\"ז ת\"ע קכט, ב. סידור שער הק\"ש פה, סע\"ג, ואילך. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שמב. מאמרי אדה\"א במדבר ח\"ב ע' תקפה. אוה\"ת ואתחנן ע' שפב."],["2413","1403","<b>פותח את ידיך</b>: תהלים קמה, טז."],["2414","1404","<b>א\"ת ידיך אלא יודיך</b>: ראה ת\"ז בהקדמה ז, ב. תס\"ט קו, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תרעט."],["2415","1405","<b>בד\"ה כי ההרים ימושו</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380879\" data-slug=\"likkutei-torah\" data-id=\"4001380879\">לקו\"ת תצא מ, ג</a>. מאמרי אדה\"ז ענינים ע' לד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680150\" data-slug=\"torat-chaim\" data-id=\"2300680150\">תו\"ח ויחי רמא, ג</a>. ובהערה 40."],["2416","1406","<b>ופתחת עליו פתוחי חותם</b>: תצוה כח, לו."],["2417","1407","<b>בד\"ה ועשית ציץ</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370372\" data-slug=\"torah-or\" data-id=\"3901370372\">תו\"א תצוה פג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370374\" data-slug=\"torah-or\" data-id=\"3901370374\">פד, א</a>. אוה\"ת שם ע' א'תשנב ואילך."],["2418","1408","<b>ההשתלשלות</b>: וכ\"ה בהשמטות ותיקונים בלקו\"ת לג\"פ."],["2419","1409","<b>וז\"ע. . פ\"א</b>: לשון הקיצור כאן ע' תקסו."],["2420","1410","<b>איהו</b>: כ\"ה גם בלקו\"ת לג\"פ ובאוה\"ת. ובזהר: הוא."],["2421","1411","<b>דורנא</b>: כ\"ה גם בלקו\"ת לג\"פ. ובאוה\"ת: דרונא. ראה לעיל הערה 599."],["2422","1412","<b>עלה</b>: כ\"ה גם בלקו\"ת לג\"פ ובאוה\"ת. ובזהר: עליה."],["2423","1413","<b>גימ'. . ויחו\"ת</b>: בלקו\"ת לג\"פ ובאוה\"ת מובא זה בשורה שלאח\"ז, בהשמטת ב' תיבות האחרונות."],["2424","1414","<b>סד\"ה משה ידבר</b>: יתרו יט, יט. תו\"א שם סח, ג."],["2425","1415","<b>חותמו של הקב\"ה אמת</b>: שבת נה, א."],["2426","1416","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["2427","1417","<b>פ' פ\"א</b>: ס\"ב."]]],[2000450257,"<h3>שלח לך אנשים כו' ועתה נבוא</h3>\nלה) <b>ועתה</b><sup data-n=\"2428\">1418</sup> נבוא לענין ב' ברכות הראשונות של הנשואין<sup data-n=\"2429\">1421</sup> שהם יוצר האדם ואשר יצר<sup data-n=\"2430\">1420</sup> את האדם בצלמו<sup data-n=\"2431\">1419</sup>, אשר הראשונה היא מטבע קצר שפותחת בברוך ואינה חותמת בברוך, והשני' היא מטבע ארוך פותחת בברוך וחותמת בברוך, והענין כי הנה בגמ' פ\"ק דכתובות ד\"ח ע\"א אמרו אשר ב' ברכות אלו הם כנגד אדם וחוה, ומתחילה ר\"ל דהיינו כמ\"ד אדם וחוה נבראו בב' יצירות וע\"ש בפי' רש\"י ובשט\"מ שיישב קושיית התוס' על פרש\"י, גם מהרש\"א בח\"א יישב פרש\"י, ואח\"כ העלו בגמ' דהיינו גם כמ\"ד חדא יצירה הואי, היינו כמ\"ד פ\"ב דערובין די\"ח ע\"א ע\"פ ויבן את הצלע שמתחילת ברייתו נברא בשני פרצופים זכר מלפניו ונקיבה מאחור שזהו נק' יצירה אחת, וצלחו לשניים<sup data-n=\"2432\">1422</sup>, ועשה מהנקיבה חוה וכדאיתא ג\"כ פב\"ת דברכות ד\"ס<sup data-n=\"2433\">1423</sup> ע\"א ואעפ\"כ מברכין על אדם וחוה ב' ברכות משום דאזלינן בתר מח', ובמח' עלה לברוא אותם שנים כמ\"ש זכר ונקבה בראם ולבסוף לא נברא אלא אחד היינו דו פרצופים שנק' יצירה א' לפרש\"י כמ\"ש כי בצלם אלקים<sup data-n=\"2434\">1424</sup> עשה את האדם, ולכן מ\"ד דמברך<sup data-n=\"2435\">1425</sup> שני ברכות עליהם היינו משם דבתר מח' אזלינן מה שעלה במח' לברוא שנים, כן מתבאר<sup data-n=\"2436\">1426</sup> בגמ' שם, ולכאו' אינו מובן מדוע נעשה מהמח' עיקר יותר מהמעשה שלא נברא אלא אחד, ומצאתי בזה פי' אמיתי בספר הפלאה פ\"ק דכתובות שם בד\"ה שהכל ברא לכבודו, וז\"ל וידוע כי צלם אלקים הוא בנשמה והיינו כדאיתא לקמן ששנים עלו במח' להבראות והוא בריאת הנשמות במח', אבל הגוף נברא אחד כו' עכ\"ל לענינינו. והוא מדברי מהר\"מ אלשיך בפ' בראשית כדלקמן, מבואר &lt;סב&gt;\nּ מדבריו שמה שעלה במחשבה לברוא שנים אף שלבסוף לא נברא אלא אחד, אין ר\"ל שהמחשבה<sup data-n=\"2437\">1427</sup> לא נעשה דבר, כי אם נבראו שנים ממש דהיינו הנשמות שלהם שזהו עיקר בחי' בצלמינו כדמותינו, היו שנים ממש, אלא שלבסוף היינו בבריאת הגוף נברא אחד דו פרצופין ולכן אתי שפיר הא דבתר מחשבה אזלינן כי הרי",[["2428","1418","<b>ועתה</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (ט\"ז מההמשך והוא) ד\"ה: שלח לך אנשים (הכולל פרקים ל\"ה — ל\"ו). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש.\nמאמר זה — פל\"ה — הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560199\" data-slug=\"or-hatorah-hb\" data-id=\"8316560199\">אוה\"ת בראשית כאן כרך ג ע' תקסו</a> ואילך. והקיצור שם ע' תקסז. לפל\"ו — הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560201\" data-slug=\"or-hatorah-hb\" data-id=\"8316560201\">אוה\"ת כאן ע' תקסז</a> ואילך. והקיצור שם ע' תקסח.\nחלק מפרק זה נכתב בגוכתי\"ק. והמשך המאמר נכתב בכת\"י הר\"ש סופר, כמצויין לקמן במקומו."],["2429","1421","<b>הראשונות של הנשואין</b>: בלקו\"ת לג\"פ ובאוה\"ת: הראשוני' של נשואין. בתו\"א: ראשונות של נשואין."],["2430","1420","<b>ב' ברכות הראשונות. . יוצר האדם ואשר יצר</b>: ראה רש\"י כתובות ח, א ד\"ה שמח. ועוד."],["2431","1419","<b>ועתה נבוא. . בצלמו</b>: לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א כאן ו, ג</a>."],["2432","1422","<b>וצלחו לשניים</b>: לשון רש\"י ברכות סא, א ד\"ה דו פרצופים."],["2433","1423","<b>ד\"ס</b>: בלקו\"ת לג\"פ ובאוה\"ת: דס\"א."],["2434","1424","<b>כי בצלם אלקים</b>: נח ט, ו."],["2435","1425","<b>דמברך</b>: בלקו\"ת לג\"פ : המברך. ותיקן הר\"ש סופר עה\"ג כבפנים."],["2436","1426","<b>מתבאר</b>: באוה\"ת: נתבאר. ובהשמטות ותיקונים בלקו\"ת לג\"פ כבפנים."],["2437","1427","<b>שהמחשבה</b>: וכ\"ה באוה\"ת. ובספר הליקוטים דא\"ח ”צ\"צ\" מערכת ברכת חתנים ע' תרה בשולי היריעה מציין שבגוכתי\"ק הצ\"צ: שמהמחשבה. וכ\"ה בב ובלקו\"ת לג\"פ."]]],[2000450258,"העיקר הוא בריאת הנשמה, והגוף הוא טפל להנשמה, וכיוצא בזה פי' בשל\"ה<sup data-n=\"2438\">1428</sup> בענין מארז\"ל בתחלה עלה במחשבה<sup data-n=\"2439\">1429</sup> לברוא את העולם במדה\"ד ראה שאין העולם מתקיים כו' דאין ר\"ל שהמחשבה היה לבטלה כו' יעו\"ש, ואם נעמיק בהדברים יותר לפמ\"ש בזהר ובכהאריז\"ל שגם זו\"נ למעלה שהם מקור כל הנשמות דאבי\"ע נבראו ג\"כ דו פרצופין דהיינו יצירה אחת, וכמבואר באריכות בפע\"ח גבי ר\"ה בדרוש הנסירה<sup data-n=\"2440\">1430</sup>, ובע\"ח שכ\"ח שער הנסירה<sup data-n=\"2441\">1431</sup>, ובזח\"ג פ' אחרי דע\"ז ב' וח\"א בראשית דל\"ה ע\"א, א\"כ לפ\"ז צריך לפרש ענין שבמחשבה עלה לברוא שתים שהנשמות היו שתים ורק הגוף היה אחד, עכצ\"ל דפי' הגוף היינו הכלים דע\"ס דזו\"נ שהם הנקראים גופין כמ\"ש בת\"ז במאמר דפתח אליהו וכמה גופין תקינת לון כו' חסד דרועא ימינא כו' ועיין הפי' מזה באג\"ה סי' ג' בד\"ה וילבש צדקה כשריון, והנשמות דזו\"נ הם האורות דע\"ס, בחי' ע\"ס בלי מה<sup data-n=\"2442\">1432</sup>, למעלה ממהות הכלים, והם נבראו שתים, והיינו כמו חו\"ב שהם שנים, רק שהן תרין ריעין, וזהו ענין שעלה במחשבה לברוא שתים כי מחשבה היינו חו\"ב<sup data-n=\"2443\">1433</sup> או כתר, ועיין בלק\"ת בשה\"ש<sup data-n=\"2444\">1434</sup> ע\"פ יונתי בחגוי<sup data-n=\"2445\">1435</sup> בהביאור בענין כי לא מחשבותי מחשבותיכם יעו\"ש. ומה שנבראו גוף אחד פי' מהרש\"א בחידושי אגדות פ\"ק דכתובות כדי שיהי' שלום ביניהם יותר כיון שהיו יצירה אחת ממש, וכן למעלה בזו\"נ דאצי' כי המ' יורדת בבי\"ע ומתרחקת כו', ולכן מבקשת שימני כחותם<sup data-n=\"2446\">1436</sup> כו', ע' זח\"ב משפטים קי\"ד א', ולולי שנבראו גוף אחד ממש לא הי' חושש כ\"כ על תיקונה כו' ע\"כ נבראו גוף אחד שיחוש עליה ועל תיקונה כמו על עצמו משא\"כ באו\"א א\"צ לזה כי הם תרין ריעין דלא מתפרשין, ועיין במהרמ\"א פ' בראשית ע\"פ ויפל ה' אלקים תרדמה<sup data-n=\"2447\">1437</sup> כו' וע\"פ זאת הפעם<sup data-n=\"2448\">1438</sup> עצם מעצמי, מבואר כעין מ\"ש בספר הפלאה הנ\"ל וכעין מ\"ש במהרש\"א, וכעין מ\"ש בביאור דיונתי הנ\"ל בפי' כי לא מחשבותי מחשבותיכם.\n<span data-k=\"ks\"><b>קיצור.</b> ענין ב' ברכות דנשואין יוצר ואשר יצר מטבע קצר ומטבע ארוך הם נגד אדם וחוה, ואף שנבראו ביצירה אחת ד\"ו פרצופים אעפ\"כ מברכין שני ברכות דיוצר משום דעלה במחשבה לברוא אותם שנים ולבסוף לא נברא אלא אחד, ואזלינן בתר מחשבה כי לא מחשבותי מחשבותיכם והיינו שממחשבה זו נבראו הנשמות שנים רק שהגוף היה אחד וכן למעלה בזו\"נ שנבראו ד\"ו פרצופין ואח\"כ צ\"ל נסירה כנודע &lt;סג&gt;\nּ בכוונת ר\"ה זהו רק בהכלים דע\"ס שלהם, אבל האור והנשמה שלהם הם שנים כמו או\"א, ונבראו בגוף אחד כי להיותן דודים ולא ריעים דלא </span>",[["2438","1428","<b>פי' בשל\"ה</b>: כ\"ה גם באוה\"ת כאן."],["2439","1429","<b>בתחלה עלה במחשבה</b>: ראה רש\"י בראשית א, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תכ."],["2440","1430","<b>בפע\"ח. . בדרוש הנסירה</b>: פ\"א."],["2441","1431","<b>ובע\"ח שער כ\"ח שער הנסירה</b>: בדפוס שקלאב. ובדפוסים אחרים שכ\"ט."],["2442","1432","<b>ע\"ס בלי מה</b>: ס\"י פ\"א, מ\"ב."],["2443","1433","<b>חו\"ב</b>: בלקו\"ת לג\"פ ובאוה\"ת: חכמה."],["2444","1434","<b>בלק\"ת בשה\"ש</b>: יז, ג ואילך."],["2445","1435","<b>יונתי בחגוי</b>: שה\"ש ב, יד."],["2446","1436","<b>שימני כחותם</b>: ח, ו."],["2447","1437","<b>ויפל ה' אלקים תרדמה</b>: בראשית ב, כא."],["2448","1438","<b>זאת הפעם</b>: בראשית שם, כג."]]],[2000450259,"<b>מתפרשין</b> ע\"כ עי\"ז שהם בהתהוות גוף אחד יהי' עזה כמות אהבה<sup data-n=\"2449\">1439</sup> כו', ולכן שימני כחותם כו'.\nלו) <b>והנה</b><sup data-n=\"2450\">1440</sup> אדם וחוה רומזים לתשב\"כ ותשבע\"פ<sup data-n=\"2451\">1441</sup>, כי אדם הראשון פי' במא\"א א' ל\"ב שהוא אבא עילאה פרצוף ראשון שניכר באצילות, ופי' אבא עילאה היינו עצמיות החכמה שלמעלה מבחי' נה\"י דאבא השפעת החכמה הנק' בע\"ח ישראל סבא<sup data-n=\"2452\">1442</sup> כו' ומשארז\"ל<sup data-n=\"2453\">1443</sup> בב\"ב ס\"פ חז\"ה דף נ\"ח ע\"א במאמר ר' בנאה הוה מציין מערתא שהיה במערה דאברהם ושרה<sup data-n=\"2454\">1444</sup>, כי מטא למערתא דאדם הראשון יצתה ב\"ק ואמ\"ל<sup data-n=\"2455\">1445</sup> נסתכלת בדמות דיוקני (ופרש\"י<sup data-n=\"2456\">1446</sup> יעקב דאמרינן בסמוך שופריה דיעקב מעין שופריה דאדה\"ר) בדיוקני עצמה (דהיינו אדם הראשון דכתיב גביה<sup data-n=\"2457\">1447</sup> בצלם אלקים ברא אותו<sup data-n=\"2458\">1448</sup> ) אל תסתכל, הרי יעקב נק' רק דמות דיוקני לגבי אדה\"ר ובעה\"ק ח\"א פי\"ז פי' שנק' דיוקני כי הוא בדמות קונו כו', אך בצלם<sup data-n=\"2459\">1449</sup> תרגום ברם בדיוקנא, ופי' וענין קנין הוא אצילות כמ\"ש בד\"ה ואלה המשפטים<sup data-n=\"2460\">1450</sup> גבי כי תקנה עבד עברי ההפרש בין קנין לבריאה וזהו ענין כל הנקרא בשמי<sup data-n=\"2461\">1451</sup> כו', ונמצא דיוקני היינו בחי' בצלמנו וענין דמות דיוקני זהו בחי' כדמותינו שאינו העצם, ועד\"ז אפי' יעקב שהוא בחי' ת\"ת<sup data-n=\"2462\">1452</sup> אינו רק דמות לגבי חכמה עילאה כי עיקר השראת אור א\"ס הוא בחכמה<sup data-n=\"2463\">1453</sup>, וזהו ענין וארא אל אברהם כו' ושמי הוי' לא נודעתי להם<sup data-n=\"2464\">1454</sup> שהוא השראת אור א\"ס שבחכמה עילאה זה לא נתגלה האבות<sup data-n=\"2465\">1455</sup> שהם בחי' חג\"ת<sup data-n=\"2466\">1456</sup>",[["2449","1439","<b>עזה כמות אהבה</b>: שה\"ש ח, ו."],["2450","1440","<b>והנה</b>: פרק זה הוא לשון אוה\"ת כאן ע' תקסז ואילך. פרק זה והקיצור נכתב בכת\"י הר\"ש סופר."],["2451","1441","<b>והנה. . ותשבע\"פ</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א כאן ו, ג</a>."],["2452","1442","<b>נה\"י דאבא. . בע\"ח ישראל סבא</b>: ראה שם שער המוחין ש\"כ, פי\"ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370228\" data-slug=\"torah-or\" data-id=\"3901370228\">תו\"א שמות נ, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381236\" data-slug=\"likkutei-torah\" data-id=\"4001381236\">לקו\"ת שה\"ש כו, ד</a> ואילך מפע\"ח. סידור שער התפילין יא, ג."],["2453","1443","<b>ומשארז\"ל</b>: בלקו\"ת לג\"פ ובאוה\"ת: וזשארז\"ל."],["2454","1444","<b>ושרה</b>: וכ\"ה בלקו\"ת לג\"פ ובאוה\"ת. ובגמרא ליתא."],["2455","1445","<b>ואמ\"ל</b>: בגמ': ואמרה. תיבת לו נמצא ברבינו גרשום ובע\"י."],["2456","1446","<b>ופרש\"י</b>: וכ\"ה באוה\"ת כאן. וראה גם לקמן בחלק ההנחות ד\"ה גדול יהי' על יד הערה 105: ”שפי' רש\"י (צ\"ל הרשב\"ם)\"."],["2457","1447","<b>גביה</b>: נוסח הרשב\"ם שבע\"י. ובנוסח שבגמ': בי'."],["2458","1448","<b>בצלם אלקים ברא אותו</b>: בראשית א, כז."],["2459","1449","<b>אך בצלם</b>: תהלים לט, ז. בעבודת הקדש מהדורת ירושלים תשנ\"ב: בדיקנא. וצ\"ל: בדיוקנא כבתרגום וכבפנים."],["2460","1450","<b>בד\"ה ואלה המשפטים</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a> (ובהנסמן במ\"מ בריש המאמר שם). עו, ב. לעיל המשך אם כסף תלוה פי\"ג ובהערה 273."],["2461","1451","<b>כל הנקרא בשמי</b>: ישעי' מג, ז."],["2462","1452","<b>יעקב. . ת\"ת</b>: ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג תוספות שב, א. לעיל המשך אם כסף תלוה פ\"ב ובהנסמן שם."],["2463","1453","<b>השראת אור א\"ס הוא בחכמה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a> (ובמ\"מ הגהות והע\"ק שם). פל\"ה בהג\"ה (ובמ\"מ הגהות והע\"ק שם). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380365\" data-slug=\"likkutei-torah\" data-id=\"4001380365\">לקו\"ת במדבר יד, ב</a> [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג]. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540658\" data-slug=\"torat-chaim\" data-id=\"2300540658\">תו\"ח שמות ח\"א ז, ד</a> הערה 333."],["2464","1454","<b>וארא. . לא נודעתי להם</b>: וארא ו, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540245\" data-slug=\"torat-chaim\" data-id=\"2300540245\">תו\"ח בא ח\"א קיג, ב</a> והערה 102. לעיל המשך וידבר וגו' ויצוום על יד הערה 12."],["2465","1455","<b>האבות</b>: בלקו\"ת לג\"פ ובאוה\"ת: להאבות."],["2466","1456","<b>האבות. . חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540325\" data-slug=\"torat-chaim\" data-id=\"2300540325\">תו\"ח וארא ח\"א סא, ד</a>. וש\"נ."]]],[2000450260,"אלא זה נמשך ע\"י התורה שהיא<sup data-n=\"2467\">1458</sup> הנק' משל הקדמוני<sup data-n=\"2468\">1457</sup>, והחכמה נק' אמת שגבוה גם מהחסד וכמ\"ש בד\"ה אלה מסעי<sup data-n=\"2469\">1459</sup> דרוש השלישי בהביאור<sup data-n=\"2470\">1460</sup> גבי ויכתוב משה<sup data-n=\"2471\">1461</sup>, ומ\"ש בד\"ה ביום השמע\"צ<sup data-n=\"2472\">1462</sup> בפי' תתן אמת ליעקב<sup data-n=\"2473\">1463</sup> כו' כי אל דיעות<sup data-n=\"2474\">1464</sup> כו' ע\"ש, ועל חכמה עילאה אמר שלמה אחכמה והיא רחוקה ממני<sup data-n=\"2475\">1465</sup>, ולכן נאמר ותתצב אחותו מרחוק<sup data-n=\"2476\">1466</sup>, ע\"ש מרחוק ה' נראה לי<sup data-n=\"2477\">1467</sup>, ולכן אדה\"ר שהוא אבא עילאה נק' האבות אצלו דמות דיוקני כו', וזהו ענין מ\"ה שמו ומה שם בנו<sup data-n=\"2478\">1468</sup> כמ\"ש<sup data-n=\"2479\">1469</sup> בפ' יתרו בד\"ה ענין האבות הן הן המרכבה<sup data-n=\"2480\">1470</sup>, מה שמו היינו חכמה כח מה<sup data-n=\"2481\">1471</sup>, הוא אדם הראשון בחי' תורה, ועמ\"ש בפי' כמראה אדם<sup data-n=\"2482\">1472</sup> בד\"ה ותחת רגליו<sup data-n=\"2483\">1473</sup> כמעשה לבנת הספיר, ומה שם בנו אדם תתאה הוא ז\"א<sup data-n=\"2484\">1474</sup> והוא ענין האבות שהם חג\"ת והם בחי' מרכבה לגבי אדם עילאה שהוא החכמה, אלא שיפה כח הבן והמרכבה להעלות את בחי' האדם שהוא חכמה לקשרה ולחברה באור א\"ס שלמעלה מהחכמה כו' וכיון שהם בחי' מרכבה לכן נק' דמות דיוקני, דוגמת פני אדם שבמרכבה לגבי בחי' כמראה אדם שעל הכסא כו' שאינו אלא &lt;סד&gt;\nּ דמות כמ\"ש ודמות החיות<sup data-n=\"2485\">1475</sup> כו' כך עד\"ז במרכבתא עילאה דאצי' בחי' אדם תתאה ז\"א לגבי אדם הראשון אבא עילאה ולכן אדה\"ר הי' לו אלף שנה<sup data-n=\"2486\">1476</sup> כי אלף בחכמה<sup data-n=\"2487\">1477</sup> ע\"ד אאלפך חכמה<sup data-n=\"2488\">1478</sup>, ומזה נתן ע' שנה לדוד<sup data-n=\"2489\">1479</sup>, דהיינו ז' מדות שבמ' דאבא כו', ועכ\"פ מזה מובן איך אדם הראשון זהו תשב\"כ שהיא ח\"ע ולכן כמו שבחכמה נאמר אחכמה",[["2467","1458","<b>שהיא</b>: באוה\"ת: שהוא. בלקו\"ת לג\"פ כבפנים."],["2468","1457","<b>התורה. . משל הקדמוני</b>: שמו\"א כד, כג וברש\"י שם. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ב ע' תב. שמות ח\"ב ע' שפג. סה\"מ תרכ\"ז ע' פז. לעיל המשך וידבר וגו' ויצוום פ\"ט ובהערה *176."],["2469","1459","<b>והחכמה נק' אמת. . בד\"ה אלה מסעי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380698\" data-slug=\"likkutei-torah\" data-id=\"4001380698\">לקו\"ת מסעי צג, ג</a>. א."],["2470","1460","<b>בהביאור</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: פ\"ד."],["2471","1461","<b>ויכתוב משה</b>: מסעי לג, ב."],["2472","1462","<b>ביום השמע\"צ</b>: לקו\"ת שמ\"ע פג, א ואילך."],["2473","1463","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["2474","1464","<b>כי אל דיעות</b>: שמו\"א ב, ג."],["2475","1465","<b>אחכמה והיא רחוקה ממני</b>: קהלת ז, כג. ראה זהר רע\"מ פינחס רכג, א."],["2476","1466","<b>ותתצב אחותו מרחוק</b>: שמות ב, ד. ראה גם ביאוה\"ז וארא לח, א. ויצא קלד, ב. שע\"ת טו, ג."],["2477","1467","<b>מרחוק ה' נראה לי</b>: ירמי' לא, ב. ראה גם ע\"ח שער הארת המוחין של\"ב, פ\"א. פע\"ח שער העמידה ש\"ט, ספי\"ג."],["2478","1468","<b>מ\"ה שמו ומה שם בנו</b>: משלי ל, ד."],["2479","1469","<b>כמ\"ש</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: בת\"א."],["2480","1470","<b>בד\"ה ענין האבות הן הן המרכבה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370324\" data-slug=\"torah-or\" data-id=\"3901370324\">תו\"א יתרו עג, א</a>."],["2481","1471","<b>חכמה כח מה</b>: זהר רע\"מ צו כח, א. לד, א."],["2482","1472","<b>כמראה אדם</b>: יחזקאל א, כו."],["2483","1473","<b>בד\"ה ותחת רגליו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370342\" data-slug=\"torah-or\" data-id=\"3901370342\">תו\"א משפטים עז, א</a>."],["2484","1474","<b>אדם תתאה הוא ז\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370324\" data-slug=\"torah-or\" data-id=\"3901370324\">תו\"א יתרו עג, א</a>. אוה\"ת כאן ע' תקסז. סה\"מ תרל\"ב ח\"א ע' יד וע' יז."],["2485","1475","<b>ודמות החיות</b>: יחזקאל א, יג."],["2486","1476","<b>אדה\"ר הי' לו אלף שנה</b>: ראה ב\"ר פי\"ט, ח. פכ\"ב, א. הנסמן בסמוך בהערה 1479."],["2487","1477","<b>אלף בחכמה</b>: ראה גם אוה\"ת כאן. המשך והחרים תרל\"א ע' כו. וככה תרל\"ז פקי\"ז."],["2488","1478","<b>אאלפך חכמה</b>: איוב לג, לג."],["2489","1479","<b>נתן ע' שנה לדוד</b>: ראה זהר וישלח קסח, א. בראשית נה, סע\"א. לך צא, ב. מאמרי אדה\"א קונטרסים ע' שנא. וש\"נ."]]],[2000450261,"והיא רחוקה שמאירה רק מרחוק כמ\"כ בתשב\"כ נרמזות ההלכות רק ברמז בעלמא ביתור אות ובתשבע\"פ הן מתבארות יפה כו' כי היא בחי' בינה<sup data-n=\"2490\">1481</sup> רחובות הנהר בחי' אות הא<sup data-n=\"2491\">1482</sup> שיש לה אורך ורוחב וכמ\"ש מזה בד\"ה ביום השמע\"צ<sup data-n=\"2492\">1480</sup>, ות\"א כנישין תהי לכון, ושם פ\"ג, אבל החכמה היא אות יוד שהיא רק נקודה א' שכל הנעלם ועמ\"ש מזה בבה\"ז פ' אחרי<sup data-n=\"2493\">1483</sup> דע\"ט ע\"ב במאמר הביאו עלי כפרה כו' יעו\"ש מענין אות יוד דשם, ותושבע\"פ זהו ענין חוה, ולכן ארז\"ל בפרק חזקת שם שרה לגבי חוה כקוף בפני אדם, כי שרה היא מלשון שררה<sup data-n=\"2494\">1485</sup> בחי' מל'<sup data-n=\"2495\">1486</sup> ולגבי בינה<sup data-n=\"2496\">1484</sup> נק' כקוף כו', ועד\"ז נק' מ' לגבי בינה כנר בפני האבוקה<sup data-n=\"2497\">1487</sup> כי בבינה גילוי ש\"ע<sup data-n=\"2498\">1488</sup> נהורין<sup data-n=\"2499\">1489</sup> דא\"א וזהו ענין האבוקה כמ\"ש במ\"א<sup data-n=\"2500\">*1490</sup>, והנה בחי' חוה היינו גילוי כי תרגום ויגד וחוי<sup data-n=\"2501\">1490</sup>, והתרגום ענינו גילוי וביאור<sup data-n=\"2502\">1491</sup> כמו מאן דמתרגם לי חבית אליבא דחד תנא כו' בב\"מ פרק המפקיד דמ\"א ע\"א, ומבואר בזהר ויחי דף רל\"ד ב' בכל<sup data-n=\"2503\">1492</sup> לשון ויגד אגידה הוא בחי' חכמה יעו\"ש הטעם, וא\"כ וחוי שהוא תרגום ויגד היינו גילוי החכמה והוא בחי' בינה, וזהו ענין תשבע\"פ כמ\"ש<sup data-n=\"2504\">1493</sup> בפ' וארא בביאור ע\"פ לכן אמור לבנ\"י<sup data-n=\"2505\">1494</sup>, בענין ארץ טובה ורחבה, וזהו יום ליום יביע אומר<sup data-n=\"2506\">1495</sup>, כי אמר ודעת י\"ל ג\"כ ע\"ד תשב\"כ ותשבע\"פ, אמר ע\"ד וידבר ה' אל משה לאמר<sup data-n=\"2507\">1496</sup>, יביע אמר כמו מעיין הנובע נביעת האמר דרך כלל ועשו להם ציצית<sup data-n=\"2508\">1497</sup> כו' והדעת זהו ביאור הדברים לאשורן ולכן הוא בלילה שאז למד משה",[["2490","1481","<b>בינה רחובות הנהר</b>: וישלח לו, ז. ראה זהר אד\"ר נשא קמב, א."],["2491","1482","<b>בינה. . אות הא</b>: ראה פרדס שער האותיות שער כז, פ\"ח. הנסמן במאמרי אדה\"א בראשית ע' רלג."],["2492","1480","<b>ובתשבע\"פ. . בינה. . בד\"ה ביום השמע\"צ</b>: לקו\"ת שמ\"ע פה, ב. ראה בסמוך בפנים. מאמרי אדה\"א דברים ח\"ד ע' א'תנ. וש\"נ. במדבר ח\"ג ע' תתקפ. וש\"נ."],["2493","1483","<b>החכמה. . יוד. . בבה\"ז פ' אחרי</b>: עו, ג. ולהצ\"צ כרך א ע' שסב. וראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשסד."],["2494","1485","<b>שרה. . שררה</b>: רש\"י נח יא, כט. וראה רש\"י לך יז, טו. ברכות יג, א. ב\"ר רפמ\"ז."],["2495","1486","<b>שרה. . מל'</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381222\" data-slug=\"likkutei-torah\" data-id=\"4001381222\">לקו\"ת</a> להאריז\"ל ח\"ש כג, ב."],["2496","1484","<b>חוה. . בינה</b>: ראה פרדס שער אם הא\"ס הוא הכתר ש\"ג, פ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670325\" data-slug=\"torat-chaim\" data-id=\"2300670325\">תו\"ח בראשית כג, ד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450664\" data-slug=\"or-hatorah-hb\" data-id=\"8316450664\">אוה\"ת כאן ע' 1134</a>."],["2497","1487","<b>מ' לגבי בינה כנר בפני האבוקה</b>: פסחים ח, א. ראה גם אוה\"ת ח\"ש ע' 254. ויצא ע' קעז."],["2498","1488","<b>האבוקה. . ש\"ע נהורין</b>: ראה פע\"ח שער השבת שי\"ח, פכ\"ד ד\"ה מהחברים. אוה\"ת ויצא שם. שה\"ש ח\"ב ע' תשכ. וראה גם אוה\"ת וישלח כרך ז ע' 2462: שע\"ה נהורין."],["2499","1489","<b>ש\"ע נהורין</b>: ראה זהר אד\"ר נשא קכח, ב. ע\"ח שער א\"א שי\"ג, פי\"ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010096\" data-slug=\"or-hatorah-hb\" data-id=\"8159010096\">אוה\"ת מטות ע' א'רעב</a>. המשך תער\"ב ח\"ב ע' א'רה."],["2500","*1490","<b>האבוקה כמ\"ש במ\"א</b>: ראה אוה\"ת שה\"ש כרך ב ע' תשכ ואילך."],["2501","1490","<b>תרגום ויגד וחוי</b>: נח ט, כב. ועוד."],["2502","1491","<b>והתרגום ענינו גילוי וביאור</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381184\" data-slug=\"likkutei-torah\" data-id=\"4001381184\">לקו\"ת שה\"ש יג, ד</a>. מאמרי אדה\"ז תקס\"ד ע' קלה וע' קמא. מאמרי אדה\"א הנחות תקע\"ז ע' קנ וע' רמא. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450434\" data-slug=\"or-hatorah-hb\" data-id=\"8316450434\">אוה\"ת</a> צפני' כרך ב ע' תתקד."],["2503","1492","<b>בכל</b>: בלקו\"ת לג\"פ ובאוה\"ת: דכל."],["2504","1493","<b>כמ\"ש</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: בת\"א. ראה גם לעיל הערה 1469. הערה 1460."],["2505","1494","<b>בפ' וארא. . לכן אמור לבנ\"י</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370257\" data-slug=\"torah-or\" data-id=\"3901370257\">תו\"א שם נז, ג</a> ואילך. נט, ב."],["2506","1495","<b>אומר</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: ולילה ללילה יחוה דעת [באוה\"ת ניתוסף: כו']."],["2507","1496","<b>וידבר ה' אל משה לאמר</b>: וארא ו, י. כט. בא יג, א. ועוד."],["2508","1497","<b>ועשו להם ציצית</b>: שלח טו, לח."]]],[2000450262,"תשבע\"פ כמ\"ש במדרש תלים ע\"פ זה<sup data-n=\"2509\">1498</sup> והוא<sup data-n=\"2510\">1499</sup> המברר עה\"ד טו\"ר וזהו יחוה דעת, והנה מבואר במ\"א בד\"ה לך לך מארצך<sup data-n=\"2511\">1500</sup> שיש בבחי' בינה מעלה יתירה מבחכמה כו' כי התגלות עתיק הוא בבינה כו' שכדי להיות כח הגילוי למטה נמשך מבחי' עליונה יותר, וכן בתשבע\"פ שהיא<sup data-n=\"2512\">1501</sup> מבינה יש בה מה\"ט ג\"כ מעלה יתירה מבחכמה וזהו בינה יתירה ניתנה באשה שהיא תשבע\"פ<sup data-n=\"2513\">1502</sup>, וזהו כתר לי זעיר ואחוך באיוב רסי' ל\"ו, כתר הוא ענין המתנה ושתיקה<sup data-n=\"2514\">1503</sup> כי סייג לחכמה שתיקה<sup data-n=\"2515\">1504</sup>, סייג היינו גדר שהוא מקיף על הדבר כמ\"כ פי' סייג לחכמה, כי השתיקה הוא מה שא\"א להתגלות בשכל, כמו שתוק כך עלה במחשבה<sup data-n=\"2516\">1505</sup> שהוא מה שלמעלה מההשגה, וכן בקי\"ס נא' ואתם תחרישון<sup data-n=\"2517\">1506</sup> כו', ועמ\"ש בביאור ע\"פ אלה פקודי המשכן<sup data-n=\"2518\">1507</sup> בענין מ\"ע ומל\"ת בחי' לא הוא כענין שתיקה כו', ומבואר לעיל אשר בחי' הבינה שהוא להיות גלוי החכמה צ\"ל &lt;סה&gt;\nּ המשכה לזה מבחי' עתיקא וזהו כתר לי זעיר ואחוך שמבחי' כתר נמשך בחי' ואחוך יחוה דעת כו', גם חוה פי' ברבות פ' בראשית פ' ך' לשון חויא<sup data-n=\"2519\">1508</sup> ויש בחי' זו בתשבע\"פ, כי הנה את התנינים הגדולים<sup data-n=\"2520\">1509</sup> פי' בבחיי פ' בראשית<sup data-n=\"2521\">1510</sup> שהם<sup data-n=\"2522\">1511</sup> ד' מחנות שכינה שהן מחול לשכינתו של הקב\"ה לקלסו ולרוממו מלשון שירות<sup data-n=\"2523\">1512</sup> ותשבחות מלשון שם יתנו צדקות הוי', שופטי' סי' ה' י\"א, ובמ\"צ<sup data-n=\"2524\">1513</sup> שם כי<sup data-n=\"2525\">1514</sup> יתנו ענין דבור כי ושננתם לבניך<sup data-n=\"2526\">1515</sup> תרגומו ותתננון, וזהו ג\"כ ענין לימוד המשניות כמשארז\"ל פ\"ק דב\"ב ד\"ח ע\"פ כי יתנו בגוים<sup data-n=\"2527\">1517</sup> עתה אקבצם שהוא ענין לימוד המשניות<sup data-n=\"2528\">1516</sup>, וע\"כ נקראו מארי משנה תנינים מלשון תנינא, תנן, הנזכר בגמרא",[["2509","1498","<b>במדרש תלים ע\"פ זה</b>: (יום ליום יביע אומר) וכ\"ה באוה\"ת כאן. ולעיל פכ\"ו על יד הערה *990 מביאו בשם הילקוט."],["2510","1499","<b>והוא</b>: בלקו\"ת לג\"פ ובאוה\"ת: ותשבע\"פ היא [באוה\"ת: הוא]."],["2511","1500","<b>בד\"ה לך לך מארצך</b>: ראה תו\"א ר\"פ לך. סה\"מ תש\"ד ע' 53 והערה לשם בע' 52. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550494\" data-slug=\"torat-chaim\" data-id=\"2300550494\">תו\"ח תצוה ח\"ב שסז, ד</a>. וש\"נ."],["2512","1501","<b>שהיא</b>: בלקו\"ת לג\"פ ובאוה\"ת: שהוא."],["2513","1502","<b>בינה יתירה. . תשבע\"פ</b>: נדה מה, ב. ראה מאמרי אדה\"א שמות ח\"א ע' סה. וש\"נ (ובהנסמן בריש המאמר שם). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540778\" data-slug=\"torat-chaim\" data-id=\"2300540778\">תו\"ח שמות ח\"א י, ב</a>. וש\"נ."],["2514","1503","<b>כתר. . המתנה ושתיקה</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ע' שנט. המשך תער\"ב ח\"א ע' א."],["2515","1504","<b>סייג לחכמה שתיקה</b>: אבות פ\"ג, מי\"ג."],["2516","1505","<b>שתוק כך עלה במחשבה</b>: מנחות כט, ב."],["2517","1506","<b>ואתם תחרישון</b>: בשלח יד, יד."],["2518","1507","<b>בביאור ע\"פ אלה פקודי המשכן</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">לקו\"ת פקודי ו, ד</a>."],["2519","1508","<b>חוה. . חויא</b>: ב\"ר פ\"כ, יא — נעתק לקמן על יד הערה 1693."],["2520","1509","<b>את התנינים הגדולים</b>: בראשית א, כא."],["2521","1510","<b>בבחיי פ' בראשית</b>: שם. מובא גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450664\" data-slug=\"or-hatorah-hb\" data-id=\"8316450664\">אוה\"ת (כאן) ע' 1134</a> ו(לעיל) ע' תקג."],["2522","1511","<b>שהם</b>: בלקו\"ת לג\"פ ובאוה\"ת כבפנים. באוה\"ת לעיל: הם. ובבחיי: הן."],["2523","1512","<b>מלשון שירות</b>: בלקו\"ת לג\"פ ובאוה\"ת (כאן ולעיל) כבפנים. ובבחיי: בשירות."],["2524","1513","<b>ובמ\"צ</b>: ובמצודת ציון. בלקו\"ת לג\"פ ובאוה\"ת כאן: ובמצ\"צ. הובא גם לעיל שם. ושם כבפנים."],["2525","1514","<b>כי</b>: בלקו\"ת לג\"פ ובאוה\"ת כאן: כ'. באוה\"ת דלעיל: פי'."],["2526","1515","<b>ושננתם לבניך</b>: ואתחנן ו, ז."],["2527","1517","<b>כי יתנו בגוים</b>: הושע ח, י."],["2528","1516","<b>פ\"ק דב\"ב ד\"ח ע\"פ כי יתנו. . לימוד המשניות</b>: וכ\"ה באוה\"ת כאן ובאוה\"ת דלעיל. וראה אוה\"ת הושע ע' תלח: ”פ\"ק דב\"ב ד\"ח ע\"א\". ראה ויק\"ר פ\"ז, ג. ועוד. הובא באוה\"ת הושע שם. וראה אוה\"ת שמות ע' יז. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091250\" data-slug=\"likkutei-sichot\" data-id=\"1300091250\">לקו\"ש</a> ה' מנ\"א כרך ט ע' 250 הערה 18."]]],[2000450263,"כ\"כ בספר עה\"כ<sup data-n=\"2529\">1518</sup> בשם אורי וישעי<sup data-n=\"2530\">1519</sup>, כי כמו שבנחש דקליפה בעל לה\"ר נק' נחש, כמ\"כ<sup data-n=\"2531\">1520</sup> בקדושה כח הדבור בד\"ת ואשים דברי בפיך<sup data-n=\"2532\">1521</sup> כו', וזהו חשן המשפט חשן אותיות נחש<sup data-n=\"2533\">1523</sup> כו', ולכן ארז\"ל יומא פ\"ב דך\"ג<sup data-n=\"2534\">1524</sup> כל ת\"ח שאינו נוקם ונוטר כנחש כו', וזהו ענין חוה לשון חויא, שיש בחי' זו בקדושה<sup data-n=\"2535\">1522</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> ענין אדם וחוה הם תשב\"כ ותשבע\"פ, אדה\"ר אבא עילאה מה שמו, ובחי' יעקב נק' ומה שם בנו ז\"א הוא דמות דיוקני לגבי אבא, וזהו ושמי הוי' לא נודעתי להם כ\"א זה נמשך ע\"י עסק התורה, וזהו ענין האבות הן הן המרכבה לבחי' תורה, אך אור אבא תושב\"כ מאיר מרחוק אחכמה והיא רחוקה ממני רק ברמיזא, והגילוי הוא ע\"י תשבע\"פ בינה רחובות הנהר והוא חוה תרגום ויגד וחוי, וזהו ולילה ללילה יחוה דעת, ובינה יתירה ניתנה באשה תשבע\"פ, כתר לי זעיר ואחוך, גם חוה לשון חויא, ושננתם תרגום ותתננון, כי יתנו בגוים בחי' התנינים הגדולים, תנינא תנן<sup data-n=\"2536\">1525</sup>, ואשים דברי בפיך.</span>",[["2529","1518","<b>בספר עה\"כ</b>: לבעל סה\"ד מערכת תנין: ”ת\"ח ת[נ]ינא בעל משנה\". הובא גם באוה\"ת (כאן) ר\"ע תקס\"ח ו(לעיל) ע' 1006 סט\"ו (בשינויים)."],["2530","1519","<b>אורי וישעי</b>: בעה\"כ שם: תפלה פי\"ד [צ\"ל: פט\"ו נז, ד]. מ' אברהם במ' אליעזר הכהן נכד בעל מתנות כהונה [ברלין] תע\"ד (סדה\"ד שמות ספרים בערכו)."],["2531","1520","<b>כמ\"כ</b>: בלקו\"ת לג\"פ ובאוה\"ת כאן ניתוסף: לעומת זה."],["2532","1521","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["2533","1523","<b>חשן אותיות נחש</b>: ראה טעמי המצות להאריז\"ל פ' תצוה מצות אפוד וחשן. ראה גם שער המצות שם. שער הכוונות ענין ספה\"ע דרוש יב. מאמרי אדה\"א דברים ח\"ב ע' תרט. פיה\"מ קא, ג."],["2534","1524","<b>דך\"ג</b>: ראה שם כב, סע\"ב ואילך."],["2535","1522","<b>כו' וזהו. . בקדושה</b>: בלקו\"ת לג\"פ ליתא. והוסיפו הר\"ש סופר עה\"ג."],["2536","1525","<b>כי יתנו. . תנן</b>: בלקו\"ת לג\"פ ליתא. והוסיפו הר\"ש סופר עה\"ג."]]],[2000450264,"<h3>פי' פתחה כו' והנה ברכת יוצר האדם</h3>\nלז) <b>והנה</b><sup data-n=\"2537\">1526</sup> ברכת יוצר האדם הוא כנגד אדה\"ר<sup data-n=\"2538\">1527</sup> ותשב\"כ דהיינו שהברכה הוא כענין הידוע בפי' על שלא ברכו בתורה תחלה<sup data-n=\"2539\">1528</sup> דהכוונה כדי להמשיך אור א\"ס בחכמה, כמ\"ש מזה בלק\"ת פ' ראה<sup data-n=\"2540\">1529</sup> ע\"פ וכל בניך ובד\"ה שיר",[["2537","1526","<b>והנה</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (י\"ז מההמשך והוא) ד\"ה: פיה פתחה בחכ' (פרק ל\"ז). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש.\nברשימת המאמרים שבס' התולדות אדמו\"ר מהר\"ש (ע' 19 וכן במפתח להמשך זה הנדפס) נרשם ד\"ה: ”פיה פתחה כו' והנה ברכת יוצר האדם (לז-לח)\". ובהערה לשם: ”מסופקני קצת אם פל\"ח מקומו בדרוש זה או בד\"ה צור תעודה\". הנה עפ\"י הנרשם במפתח שבריש בוך 1089 רק פל\"ז נכלל במאמר זה.\nמאמר זה פל\"ז — הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560203\" data-slug=\"or-hatorah-hb\" data-id=\"8316560203\">אוה\"ת בראשית כאן כרך ג ע' תקסח</a> ואילך. והקיצור שם ע' 1138.\nהמאמר נכתב בכת\"י הר\"ש סופר. פרט לציון הפרק ועוד תיקון שנרשם בגוכתי\"ק."],["2538","1527","<b>ברכת יוצר האדם. . אדה\"ר</b>: ראה רש\"י כתובות ח, א."],["2539","1528","<b>שלא ברכו בתורה תחלה</b>: ב\"מ פה, ב. נדרים פא, א. ראה גם דרך חיים פא, א. סה\"מ תרכ\"ט ע' רצ. וש\"נ. תרל\"ג ח\"ב ע' תלו ואילך וש\"נ."],["2540","1529","<b>בלק\"ת פ' ראה</b>: כט, א. ראה אוה\"ת ואתחנן ס\"ע רנב ואילך."]]],[2000450265,"השירים<sup data-n=\"2541\">1530</sup> פ\"ב בפי' הקב\"ה יושב ועוסק בתורה<sup data-n=\"2542\">1531</sup> ומ\"ש בד\"ה נ\"ח<sup data-n=\"2543\">1532</sup> כו' ומזוזה מימין, ועמ\"ש בד\"ה אכלוהו היום<sup data-n=\"2544\">1533</sup> בפי' נותן התורה לשון הוה<sup data-n=\"2545\">1534</sup>, והמשכה זו בחכמה זהו ענין יוצר האדם וכמ\"ש בד\"ה זכור ושמור<sup data-n=\"2546\">1535</sup> בדבור אחד נאמרו, כי התורה נק' אדם שדרך כלל הוא ג' קוין תורה ועבודה וגמ\"ח ובפרטיות מתחלק לרמ\"ח איברים כו' אבל אור א\"ס ב\"ה הוא רם ונשא כי לאו מכל אלין מדות איהו כלל ושם נאמר כי לא אדם הוא<sup data-n=\"2547\">1536</sup> כו', וכדי להמשיך מבחי' כי לא אדם לבחי' אדם להיות אנת הוא חכים<sup data-n=\"2548\">1537</sup> כו' זהו ענין ברכו בתורה והוא ענין יוצר האדם, אך פי' יוצר היינו כנודע שיש אדם דבריאה ואדם דיצירה כו' ומבואר בע\"ח מהת\"ז שאדם קדמון<sup data-n=\"2549\">1538</sup> נק' אדם דבריאה, וזהו &lt;סו&gt;\nּ דרך כלל כתר עליון<sup data-n=\"2550\">1539</sup> שנאמר בו ישת חשך סתרו<sup data-n=\"2551\">1540</sup> וכתיב ובורא חושך<sup data-n=\"2552\">1541</sup>, שנק' חשך ע\"ש שאין בו שום תפיסא והשגה כמ\"ש בד\"ה ראשי המטות<sup data-n=\"2553\">1542</sup> ובד\"ה שחורה אני ונאוה<sup data-n=\"2554\">1543</sup>, דרוש הראשון, וזהו בחי' אדם קדמון כמ\"ש בפרדס ערך אדם<sup data-n=\"2555\">1544</sup> שנקרא כן הכתר להורות כי הוא קדמון לכל האצילות כו' וגם י\"ל הטעם כי בו מלובש אור א\"ס שהוא קדמון ולכן נק' ועתיק יומין<sup data-n=\"2556\">1545</sup> כי לא שיש בו ערך שנים וזמן ח\"ו כי הוא קדמון שלמעלה מגדר זמן כו' אלא שלשכך האוזן במה שהיא יכולה לשמוע<sup data-n=\"2557\">1546</sup> נק' כן, לומר שהוא הפך ענין ההתחדשות שנים, וע\"כ נק' עתיק יומין, לומר שהוא הפך מהמחודש ח\"ו, וכמו שנק' חכם אף שהוא מרומם למעלה מגדר החכמה אלא שהכוונה לשלול ממנו הפך",[["2541","1530","<b>ובד\"ה שיר השירים</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381134\" data-slug=\"likkutei-torah\" data-id=\"4001381134\">לקו\"ת שה\"ש א, ב</a>."],["2542","1531","<b>הקב\"ה יושב ועוסק בתורה</b>: ע\"ז ג, ב."],["2543","1532","<b>בד\"ה נ\"ח</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מב, ג</a> [סוד\"ה והנה התורה]. הובא בלקו\"ת ראה שם."],["2544","1533","<b>בד\"ה אכלוהו היום</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א בשלח סה, ב</a>. ראה אוה\"ת בשלח ע' תקצז."],["2545","1534","<b>נותן התורה לשון הוה</b>: ראה גם ס' החיים — לר' חיים בר' בצלאל אחי המהר\"ל — ס' זכיות ספ\"א (סע\"ד). של\"ה כה, א. קצב, א. ט\"ז לשו\"ע או\"ח סמ\"ז. ס\"ה. מאמרי אדה\"א הנחות תקע\"ז ע' שז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540591\" data-slug=\"torat-chaim\" data-id=\"2300540591\">תו\"ח שמות ח\"א לב, ד</a> ובהערה 270. סה\"מ תרכ\"ט ר\"ע קיז. וש\"נ. לקמן (בחלק ההנחות) הנחה רד\"ה ואהי' אצלו אמון."],["2546","1535","<b>בד\"ה זכור ושמור</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370317\" data-slug=\"torah-or\" data-id=\"3901370317\">תו\"א יתרו עא, סע\"ב</a>."],["2547","1536","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["2548","1537","<b>אנת הוא חכים</b>: וכ\"ה בלקו\"ת לג\"פ כאן [ובסידור אדה\"ז סדר מנחת ערב שבת — לקמן (בחלק ההנחות) בהנחה ד\"ה פי' פתחה בחכמה על יד הערה 62. ד\"ה שיר המעלות ממעמעקים על יד הערה 19]. באוה\"ת כאן (ע' תקסח) תיבת: הוא ליתא. [וכן ב] ת\"ז בהקדמה יז, ב."],["2549","1538","<b>אדם דבריאה ואדם דיצירה. . שאדם קדמון</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"א. ת\"ז תי\"ט מב, א. מאמרי אדה\"ז על ענינים בתחילתן ובהנסמן במ\"מ לשם. אוה\"ת על ענינים ע' עז. סה\"מ תש\"ח ע' 113 בהערה. הנסמן בסה\"מ תרל\"ב ח\"א ע' ד."],["2550","1539","<b>שאדם קדמון. . כתר עליון</b>: ראה גם בסמוך בפנים. לקו\"ת שמ\"ע פט, ג. שה\"ש יח, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' פב. תקס\"ה ח\"ב ס\"ע תרסא."],["2551","1540","<b>כתר. . ישת חשך סתרו</b>: זהר רע\"מ פינחס רכה, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380078\" data-slug=\"likkutei-torah\" data-id=\"4001380078\">לקו\"ת ויקרא א, א</a>."],["2552","1541","<b>ובורא חושך</b>: ישעי מה, ז."],["2553","1542","<b>בד\"ה ראשי המטות</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת מטות פא, ב</a>."],["2554","1543","<b>ובד\"ה שחורה אני ונאוה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381147\" data-slug=\"likkutei-torah\" data-id=\"4001381147\">לקו\"ת שה\"ש ד, ג</a>."],["2555","1544","<b>בפרדס ערך אדם</b>: שעה\"כ שכ\"ג, פ\"א בערכו."],["2556","1545","<b>ועתיק יומין</b>: דניאל ז, ט. ראה גם עט\"ר ע' ח."],["2557","1546","<b>שלשכך האוזן. . לשמוע</b>: מכילתא יתרו יט, יח. תנחומא שם יג.\n1547)חכם. . חי כמבואר בספרי המחקר: ראה מו\"נ ח\"א פנ\"ח. ס' העקרים מאמר ב פ\"ז. פכ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380066\" data-slug=\"likkutei-torah\" data-id=\"4001380066\">לקו\"ת פקודי ו, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע ח ואילך."]]],[2000450266,"החכמה וכו' וכן בענין חי, כמבואר בספרי המחקר, ועד\"ז הוא ענין ועתיק יומין ולפי שבחי' זו שהיא הארת אור א\"ס מלובש בכתר נק' הכתר ג\"כ אדם קדמון, שעם היותו בחי' אדם דבריאה מלובש בו הארת אור א\"ס שהוא קדמון כו', וכמבואר בע\"ח שבחי' ע\"י מלובש ומאיר בא\"א<sup data-n=\"2558\">1548</sup>, ומ\"מ נק' אדם דבריאה, שהרי הוא נאצל ונתהוה וכמ\"ש בע\"ח שמ\"א פ\"ג<sup data-n=\"2559\">1549</sup> שיש בכתר ב' בחי' הא' מה שאינו במנין ע\"ס והוא בחי' ע\"י והב' מה שהוא בחשבון ע\"ס וזהו ענין א\"א וע\"כ מצד בחי' זו השנית נק' אדם דבריאה כו', ואף שבע\"ח פי' שא\"ק שהוא אדם דבריאה הוא למעלה<sup data-n=\"2560\">1550</sup> מהכתר<sup data-n=\"2561\">1551</sup> מ\"מ הרי א\"ק הוא כתר דכללות העולמות, וכמ\"ש במ\"ח מסכת כללות העולמות רפ\"ב<sup data-n=\"2562\">1552</sup> שאדם קדמון הוא סוד האריך של הארבע<sup data-n=\"2563\">1553</sup> עולמות אבי\"ע, ואצילות הוא חכמה דכללות, בריאה הוא בינה דכללות כו' ע\"ש, ולכן בחי' כתר ואריך אנפין נק' אדם דבריאה, וחכמה שהיא בכלל אצילות נק' יוצר האדם אדם דיצירה, בחי' יוצר אור<sup data-n=\"2564\">1554</sup>, וכן החכמה הוא אור וגילוי כו', ובזה יובן הפסוק בישעי' סי' מ\"ג לפני לא נוצר<sup data-n=\"2565\">1555</sup> אל ואחרי לא יהיה שהקשו הראב\"ע והרד\"ק איך שייך לשון נוצר באלקות, שהוא קדמון וכן לשון לפני כו', אך התירוץ כי שם אל נק' בו הבורא ית' ע\"י התלבשות בספירת החכמה<sup data-n=\"2566\">1556</sup> והחסד<sup data-n=\"2567\">1557</sup>, וכן אלקים נק' ע\"י התלבשותו במדת הגבורה<sup data-n=\"2568\">1558</sup> וכמשנ\"ת מזה באריכות בד\"ה להבין מ\"ש באוצ\"ח<sup data-n=\"2569\">1559</sup> בתחלתו שם פ\"א ועפמ\"ש ברבות סדר<sup data-n=\"2570\">1561</sup> שמות פ\"ג<sup data-n=\"2571\">1560</sup> שמי אתה מבקש לידע לפי מעשי אני נקרא כו' ע\"ש, ובת\"א פ' בא בד\"ה בעצם היום הזה יצאו כל צבאות ה', ובד\"ה משה ידבר<sup data-n=\"2572\">1562</sup> ובד\"ה אשירה להוי'<sup data-n=\"2573\">1563</sup> כי גאה גאה בפי' ושמרו דרך הוי'<sup data-n=\"2574\">1564</sup>, משא\"כ מצד",[["2558","1548","<b>בע\"ח שבחי' ע\"י. . בא\"א</b>: ראה ע\"ח שער המלכים שי\"א, פ\"ד. שער א\"א שי\"ג, פ\"א."],["2559","1549","<b>בע\"ח שער מ\"א פ\"ג</b>: במהדורת שקלב תק\"ס. ובהוצאות אחרות שמ\"ב, פ\"א."],["2560","1550","<b>שבע\"ח פי' שא\"ק. . למעלה מהכתר</b>: לדוגמא ראה דרוש עגויו\"ש ש\"א, ענף ד."],["2561","1551","<b>מהכתר</b>: בלקו\"ת לג\"פ ובאוה\"ת כאן ניתוסף: דאצי'."],["2562","1552","<b>במ\"ח. . רפ\"ב</b>: בסדר נזיקין. ראה גם המשך תער\"ב ח\"א ע' ב. ע' שלו. ח\"ג ע' א'שצא. ע' א'תו [ושם: שער כללות]. ע' א'תלט. בהערה הבאה."],["2563","1553","<b>הארבע</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380705\" data-slug=\"likkutei-torah\" data-id=\"4001380705\">לקו\"ת</a> לג\"פ ובאוה\"ת. במ\"ח ובלקו\"ת מסעי צה, ב: ארבע."],["2564","1554","<b>דיצירה בחי' יוצר אור</b>: ישעי מה, ז. ראה גם הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540181\" data-slug=\"torat-chaim\" data-id=\"2300540181\">תו\"ח בשלח ח\"א קמד, ג</a> הערה 41. סה\"מ תרכ\"ז ע' רפו. וש\"נ."],["2565","1555","<b>בישעי' סי' מ\"ג לפני לא נוצר</b>: פסוק י. ראה גם אוה\"ת שמות ע' לט וע' מה ואילך. ד\"ה אשר ברא שו\"ש תשל\"ט פ\"ג. וש\"נ (קונט' י\"ד כסלו תש\"נ — סה\"מ מלוקט ד ע' פב)."],["2566","1556","<b>אל. . החכמה</b>: ראה פרדס שער השמות ש\"כ, פ\"ה. מאמרי אדה\"א שמות ח\"א ס\"ע רטז. וש\"נ."],["2567","1557","<b>אל. . והחסד</b>: ראה זהר אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 39."],["2568","1558","<b>אלקים. . הגבורה</b>: ראה זהר יתרו פג, ב. הנסמן בתו\"ח שם הערה 41."],["2569","1559","<b>בד\"ה להבין מ\"ש באוצ\"ח</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380298\" data-slug=\"likkutei-torah\" data-id=\"4001380298\">לקו\"ת ויקרא בהוספות נא, ג</a>."],["2570","1561","<b>סדר</b>: וכ\"ה בתיקונים והשמטות בלקו\"ת לג\"פ."],["2571","1560","<b>ברבות סדר שמות פ\"ג</b>: ס\"ו."],["2572","1562","<b>ובד\"ה משה ידבר</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370302\" data-slug=\"torah-or\" data-id=\"3901370302\">תו\"א יתרו סז, ג</a>."],["2573","1563","<b>ובד\"ה אשירה להוי'</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370283\" data-slug=\"torah-or\" data-id=\"3901370283\">תו\"א בשלח סג, ב</a>."],["2574","1564","<b>ושמרו דרך הוי'</b>: וירא יח, יט."]]],[2000450267,"מהותו ועצמותו אינו נתפס בשם וכמ\"ש ג\"כ בלק\"ת פ' אחרי סד\"ה כי ביום הזה יכפר דרוש הראשון, וכיון שכן נמצא שם אל הגם דקאי על הבורא ית' ממש ולא על ספירת החסד והחכמה עצמן ח\"ו, אך כיון ששם זה אינו שייך במהותו ועצמותו מצד עצמו אלא ע\"י התלבשותו במדת החכמה והחסד וכמאמר לפי מעשי אני נקרא, אז &lt;סז&gt;\nּ דוקא יתכן לו' שם זה, לכך שייך לקרוא על שם זה לשון נוצר אל, כי לשון נוצר הוא ענין הגלוי הנמשך מן ההעלם כמו חומר וצורה<sup data-n=\"2575\">1565</sup>, שהצורה הוא הגילוי מן החומר ההיולי כמ\"ש הרמב\"ן בפי' החומש ר\"פ בראשית, ובע\"ח שמ\"א פ\"ג פי' הכתר הוא דוגמת החומר ההיולי, וממנו נמשכו ד' צורות ד' יסודות חו\"ב תו\"מ כו' ע\"ש, ולכן נק' זה יוצר אור, שממשיך גלוי האור מבחי' ישת חשך סתרו כו' ועמ\"ש סד\"ה כי ביום הזה יכפר הנ\"ל בפי' ושמתיך בנקרת הצור<sup data-n=\"2576\">1566</sup> כו', וזהו פי' לפני לא נוצר אל, כי אל היינו הארה ע\"ד מ\"ש אל ה' ויאר לנו<sup data-n=\"2577\">1567</sup>, והיינו גלוי החכמה שהיא<sup data-n=\"2578\">1568</sup> הנק' ראשית הגלוי הנמשך מהעלם הכתר הנק' ישת חשך סתרו, וזהו לפני לא נוצר אל פי' לפני החכמה דאצילות שהיא ראשית הגלוי וראשית מנין העשר ספירות<sup data-n=\"2579\">1569</sup> לא נוצר אל דהיינו שלא נתגלה בבחי' צורה וגילוי בחי' אל כו' שהוא ענין חכים ולא בחכמה ידיעא כו' וגם בחכמה יש ל\"ב נתיבות פליאות חכמה<sup data-n=\"2580\">1570</sup>, והנתיב הראשון נק' נתיב לא ידעו עיט<sup data-n=\"2581\">1571</sup>, רק ל\"א נתיבות הם נמשכים בבחי' גילוי ומהם נמשך לכל צדיק וצדיק ש\"י עולמות<sup data-n=\"2582\">1572</sup> כי כל נתיב כלול מיו\"ד לכן מבחי' ל\"א נתיבות נמשך ש\"י<sup data-n=\"2583\">1573</sup> עולמות והם ג\"כ קנה חכמה קנה בינה ב\"פ קנה גימטריא ש\"י, וזהו ג\"כ ענין יקר, מ\"ש<sup data-n=\"2584\">1574</sup> כל הון יקר ונעים<sup data-n=\"2585\">1575</sup>, יקרה היא מפנינים<sup data-n=\"2586\">1576</sup>, ובמדרש רבה ויקרא רפ\"ב עשרה דברים נקראו יקר<sup data-n=\"2587\">1577</sup> כו' ע\"ש, וזהו ענין נוצר אל גלוי ל\"א נתיבות",[["2575","1565","<b>חומר וצורה</b>: ראה מו\"נ ח\"א פי\"ז. הנסמן במאמרי אדה\"א דברים ח\"ד ע' קעו. שמות ח\"א ע' כג. סה\"מ תרכ\"ט ע' יז. וש\"נ."],["2576","1566","<b>ושמתיך בנקרת הצור</b>: תשא לג, כב. וכן הוא בלקו\"ת. בלקו\"ת לג\"פ ובאוה\"ת: ונצבת על הצור — תשא שם כא, וכן העתיק הר\"ש סופר כאן. ותיקן כ\"ק אדמו\"ר מהר\"ש כנ\"ל."],["2577","1567","<b>אל ה' ויאר לנו</b>: תהלים קיח, כז. ראה אגה\"ק ס\"ז (קיב, א). אוה\"ת בהר כרך ד ע' א'קמד. סה\"מ תרכ\"ז ע' רסא."],["2578","1568","<b>שהיא</b>: בלקו\"ת לג\"פ ובאוה\"ת: שהוא."],["2579","1569","<b>החכמה. . וראשית מנין העשר ספירות</b>: ראה רמ\"ז לזהר ואתחנן רסה, ב (קצד, א (ד\"ה לארקא). סע\"ב)."],["2580","1570","<b>ל\"ב נתיבות פליאות חכמה</b>: ס\"י פ\"א, מ\"א. ראה הנסמן במאמרי אדה\"א בראשית ע' ג."],["2581","1571","<b>נתיב לא ידעו עיט</b>: איוב כח, ז. ת\"ז ת\"ל עג, ב. פרדס שער הנתיבות שי\"ב, פ\"ג נתיב הא'."],["2582","1572","<b>לכל צדיק. . ש\"י עולמות</b>: עוקצי' בסופה."],["2583","1573","<b>כל נתיב כלול מיו\"ד. . ל\"א. . ש\"י</b>: ראה גם אוה\"ת בהעלותך ס\"ע תיט. המשך והחרים תרל\"א ע' עה. סה\"מ תרכ\"ט ע' רלד. תרל\"ב ח\"א ע' קנט. המשך וככה תרל\"ז פ\"י ע' יג. מאמר ד\"ה מאימתי קוראי' את שמע תרמ\"ב ע' 5."],["2584","1574","<b>מ\"ש</b>: כ\"ה גם בלקו\"ת לג\"פ ובאוה\"ת כאן."],["2585","1575","<b>כל הון יקר ונעים</b>: משלי כד, ב."],["2586","1576","<b>יקרה היא מפנינים</b>: משלי ג, טו."],["2587","1577","<b>עשרה דברים נקראו יקר</b>: בויק\"ר שם: ”עשרה נקראו יקרים\". וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380402\" data-slug=\"likkutei-torah\" data-id=\"4001380402\">לקו\"ת נשא כג, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080174\" data-slug=\"or-hatorah-hb\" data-id=\"8160080174\">אוה\"ת ויצא ח\"א ע' קעד</a>. ויקרא כרך א ע' רלד. במדרש שמואל פ\"ח. שוח\"ט וילקוט המכירי תהלים קטז, טו. ילקוט שמעוני שמו\"א ג, א (רמז צז) הובא: ”עשרה דברים נקראו יקרים\". ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270260\" data-slug=\"or-hatorah-hb\" data-id=\"8316270260\">אוה\"ת וישב ח\"ב ס\"ע רס</a> ובכרך ה ע' תתצב: ”עשרה דברים יקרים נבראו בעולם\". כהלשון בפנים מובא גם בלקו\"ת לג\"פ ובאוה\"ת כאן־ ירמי' ע' שעט־ מג\"א ע' קנג."]]],[2000450268,"החכמה<sup data-n=\"2588\">*1578</sup> מבחי' ההעלם של נתיב לא ידעו עיט בחי' ישת חשך סתרו כו', ואין זה תימא אם שם אל, לא קאי אלא על האור והזיו ממנו ית' המלובש בחכמה וחסד, ולא על מהותו ועצמותו מצד עצמו, שהרי מצינו שאפילו יעקב אבינו קראו הקב\"ה אל כמשארז\"ל פ\"ב דמגילה די\"ח ע\"א ע\"פ ויקרא לו אל אלקי ישראל<sup data-n=\"2589\">1578</sup>, דפירשו<sup data-n=\"2590\">1579</sup> אשר אלקי ישראל קרא ליעקב אל, להיותו מרכבה<sup data-n=\"2591\">1580</sup> לתפארת דאצילות, וקרוב לזה מצאתי אשר פי' בכלי פז בישעי' סי' מ\"ג גבי והדרך השני ותוכן כוונתו כי הארתו ית' לברוא העולמות כולן ולהחיותן ולקיימן, זהו רק הארה מעצמותו אבל מהותו ועצמותו נשגב לבדו, וכל השמות מה שנקרא בורא ויוצר זהו בבחי' הארה זו ובבחי' זו נק' אל היינו בעל היכולת להוות כל נמצא ושליט עליהן ושאר השמות, וגילוי הארה זו מעצמותו שייך לקרוא לשון יצירה ע\"ד יוצר אור, ועז\"נ לפני לא נוצר אל, זהו תוכן הענין אע\"פ שאין לשונו כן<sup data-n=\"2592\">1581</sup>, וזהו ענין יוצר האדם שהיא חכמה עילאה, שזהו בחי' אדם הראשון וברכה שניה אשר יצר את האדם בצלמו הוא נגד תשבע\"פ חכמה תתאה בחי' חוה<sup data-n=\"2593\">1582</sup>, ע' מענין ח\"ע וח\"ת בד\"ה כי אברהם<sup data-n=\"2594\">1884</sup> לא ידענו<sup data-n=\"2595\">1583</sup>, ומענין את בד\"ה ואתחנן אל ה'<sup data-n=\"2596\">1585</sup>, ובענין אותיות בד\"ה מזוזה מימין<sup data-n=\"2597\">1586</sup>, ומענין ב\"פ בצלמו בצלם בד\"ה כי תצא<sup data-n=\"2598\">1587</sup>, ומענין עדי עד בד\"ה שובה ישראל &lt;סח&gt;\nּ עד<sup data-n=\"2599\">1588</sup> ע\"ש בפי' עד, וע' בזח\"ג שלח דקנ\"ט ע\"א בענין תלת עלמין אית ליה לקודב\"ה ובפי' הרמ\"ז שם שנגד זה ג\"פ קדוש והם עולם הא\"ס שלפני<sup data-n=\"2600\">1589</sup> האצי', ואצילות, ובריאה כו', וזהו ענין ג' ברכות אלו דנשואין שהכל ברא לכבודו בחי' ולכבודי בראתיו<sup data-n=\"2601\">1590</sup> בחי' א\"ק שנק' אדם דבריאה אח\"כ יוצר האדם בחי' יצרתיו והוא חכמה עילאה שהיא בחי' אצילות בכלל, אח\"כ אשר יצר כו' דמות תבניתו הוא ח\"ת מקור דבי\"ע בחי' אף עשיתיו כו', ועמ\"ש עוד מענין יוצר אור בד\"ה הבאים ישרש<sup data-n=\"2602\">1591</sup> בפי' יעקב בראך ישראל",[["2588","*1578","<b>אל. . ל\"א נתיבות החכמה</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה פי' פתחה בחכמה על יד הערה 73. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450491\" data-slug=\"or-hatorah-hb\" data-id=\"8316450491\">אוה\"ת</a> בראשית כאן ע' 1136. מיכה ע' תצא. סה\"מ תרכ\"ט ע' רלד. המשך וככה תרל\"ז פ\"י."],["2589","1578","<b>ויקרא לו אל אלקי ישראל</b>: וישלח לג, כ. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540157\" data-slug=\"torat-chaim\" data-id=\"2300540157\">תו\"ח בשלח ח\"א רמו, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550400\" data-slug=\"torat-chaim\" data-id=\"2300550400\">ויקהל ח\"ב שפט, ג</a> ובהנסמן בהנ\"ל. אוה\"ת בהר כרך ד ע' א'קמד ואילך. סה\"מ תרכ\"ז ס\"ע קיג ואילך. תרל\"ב ח\"א ע' לז ואילך ובהנסמן שם. תרל\"ג ח\"א ע' מח ואילך. וש\"נ. מאמר ד\"ה את שבתותי תשמרו תרי\"ב [ד\"ה והנה ארז\"ל — יודפס בעז\"ה בפלח הרמון ויקרא]."],["2590","1579","<b>דפירשו</b>: באוה\"ת כאן ר\"ע תקסט: ופירושו. בלקו\"ת לג\"פ כבפנים."],["2591","1580","<b>ליעקב. . מרכבה</b>: ראה זהר וישלח קעג, ב. לעיל המשך וידבר וגו' ויצוום פי\"ג הערה 226."],["2592","1581","<b>כן</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף עוד שורה."],["2593","1582","<b>אשר יצר את האדם. . חוה</b>: ראה רש\"י כתובות ח, א."],["2594","1884","<b>כי אברהם</b>: בלקו\"ת לג\"פ ובאוה\"ת: כי אתה אבינו כי אברהם."],["2595","1583","<b>ח\"ע וח\"ת בד\"ה כי אברהם לא ידענו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370418\" data-slug=\"torah-or\" data-id=\"3901370418\">תו\"א מג\"א צג, א</a> ואילך."],["2596","1585","<b>ומענין את בד\"ה ואתחנן אל ה'</b>: לקו\"ת ואתחנן ב, ג."],["2597","1586","<b>ובענין אותיות בד\"ה מזוזה מימין</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370189\" data-slug=\"torah-or\" data-id=\"3901370189\">תו\"א מקץ מב, א</a> ואילך."],["2598","1587","<b>ב\"פ בצלמו בצלם בד\"ה כי תצא</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380863\" data-slug=\"likkutei-torah\" data-id=\"4001380863\">לקו\"ת תצא לו, סע\"ג</a> ואילך."],["2599","1588","<b>בד\"ה שובה ישראל עד</b>: לקו\"ת ש\"ש סז, ג."],["2600","1589","<b>שלפני</b>: באוה\"ת: לפני. ובהשמטות ותיקונים בלקו\"ת לג\"פ כבפנים."],["2601","1590","<b>ולכבודי בראתיו</b>: ישעי' מג, ז."],["2602","1591","<b>בד\"ה הבאים ישרש</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370241\" data-slug=\"torah-or\" data-id=\"3901370241\">תו\"א אור שמות נד, סע\"א</a>. ד."]]],[2000450269,"יצרך<sup data-n=\"2603\">1592</sup> כו', וענין והתקין לו ממנו בנין עדי עד פי' בהפלאה<sup data-n=\"2604\">1593</sup> ע\"ד ותבואי בעדי עדיים<sup data-n=\"2605\">1594</sup> ועמ\"ש מזה ע\"פ אלה פקודי המשכן<sup data-n=\"2606\">1595</sup> משכן העדות כו', והיינו כמ\"ש ע\"פ כ\"א בזאת יתהלל<sup data-n=\"2607\">1596</sup> כו' שעיקר המכוון הוא להיות בי\"ע וזהו וייצר בשני יודין, ואמרו שב' יודין הרומזים לשני יצירות הם כנגד יצ\"ט ויצה\"ר<sup data-n=\"2608\">1597</sup>, והם שייכי ג\"כ לאדם וחוה כי אתערותא דדכורא לגבי נוק' הוא ע\"י יצה\"ר אלא שבשרשו אינו רע<sup data-n=\"2609\">1599</sup> ממש אלא ע\"ד שמאלו<sup data-n=\"2610\">1598</sup> תחת לראשי<sup data-n=\"2611\">1600</sup> כו', וידוע כי טוב זה יצ\"ט מאד זה יצה\"ר כשנהפך לטוב, וזהו ע\"י הבירור מבחי' ח\"ת בירור עה\"ד טו\"ר כו', וזהו והי' ביום ההוא יצאו מים חיים מירושלים<sup data-n=\"2612\">1601</sup> כו' וכן נאמר באברהם לך לך מארצך כו' אל הארץ אשר אראך שהיא בחי' מ'<sup data-n=\"2613\">1602</sup> שעי\"ז דוקא אשר אראך בחי' עין בעין יראו<sup data-n=\"2614\">1603</sup>, ולכן והתקין לו ממנו בנין עדי עד שהוא ענין בעדי עדיים, ועמ\"ש עוד בלק\"ת בשה\"ש סד\"ה קול דודי<sup data-n=\"2615\">1604</sup> גבי ומקפץ על הגבעות כו', ובביאור ע\"פ עלי באר<sup data-n=\"2616\">1605</sup> שהמ' היא כתר בע\"ס דאור חוזר ממטה למעלה, ולכן ממנה נמשך העדי עדיים שהם הכתרים כו' ועיין באג\"ה סי' כ\"ט בד\"ה אשת חיל עטרת בעלה<sup data-n=\"2617\">1606</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> יוצר האדם הוא תשב\"כ וצ\"ל פותח בברוך כידוע מענין על שלא ברכו בתורה תחלה, להמשיך מבחי' כי לא אדם בבחי' אדם<sup data-n=\"2618\">1607</sup> ג' קווין, ופי' יוצר היינו גילוי מההעלם מבחי' א\"ק, ע\"ד יוצר אור ובורא חושך, ישת חשך סתרו, וזהו ועתיק יומין יתיב, כי א\"ק הוא כתר דכללות וזהו ענין לפני לא נוצר אל, אל היינו נהירא דחכמתא, אל<sup data-n=\"2619\">1608</sup> ה' ויאר לנו, גם המשכת ל\"א נתיבות מבחי' נתיב לא ידעו עיט, ונק' להנחיל אוהבי יש, יקר, וקרוב לזה פי' בכלי פז, וברכת אשר יצר היא<sup data-n=\"2620\">1609</sup> תשבע\"פ, נמצא ג' ברכות שהכל ברא בבחי' א\"ק יוצר<sup data-n=\"2621\">1610</sup> האדם אדם דיצי' </span>",[["2603","1592","<b>יעקב בראך ישראל יצרך</b>: ויק\"ר פל\"ו, ד. יל\"ש ישעי' מג, א (בין רמז תנב — תנה)."],["2604","1593","<b>פי' בהפלאה</b>: כתובות ח, א."],["2605","1594","<b>ותבואי בעדי עדיים</b>: יחזקאל טז, ל."],["2606","1595","<b>אלה פקודי המשכן</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380059\" data-slug=\"likkutei-torah\" data-id=\"4001380059\">לקו\"ת פקודי ד, ד</a> ואילך."],["2607","1596","<b>כ\"א בזאת יתהלל</b>: ירמי' ט, כג. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' מג."],["2608","1597","<b>וייצר בשני יודין. . יצ\"ט ויצה\"ר</b>: בראשית ב, ז וראה בתרגום יוב\"ע שם. ברכות סא, א. אוה\"ת בראשית כרך ג ע' 1046 ואילך."],["2609","1599","<b>יצה\"ר. . שבשרשו אינו רע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560117\" data-slug=\"or-hatorah-hb\" data-id=\"8316560117\">אוה\"ת בראשית כרך ג</a> <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770201\" data-slug=\"or-hatorah-hb\" data-id=\"8316770201\">ע 1014. ע' תקכה</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940418\" data-slug=\"or-hatorah-hb\" data-id=\"8159940418\">כאן ע' תקסט</a>. לקמן ע' 1160 ואילך. שמע\"צ ע' א'תשפו. יחזקאל ע' תיח. ביאוה\"ז — להצ\"צ תזריע כרך ב ע' תתקה. סה\"מ תרלג ח\"ב ע' תלט ואילך."],["2610","1598","<b>אתערותא דדכורא לגבי נוק'. . שמאלו</b>: זהר ח\"ש קלג, א. אוה\"ת שם."],["2611","1600","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["2612","1601","<b>והי'. . מים חיים מירושלים</b>: זכרי' יד, ח."],["2613","1602","<b>לך. . אל הארץ. . מ'</b>: לך יב, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370049\" data-slug=\"torah-or\" data-id=\"3901370049\">תו\"א לך יא, ב</a>."],["2614","1603","<b>עין בעין יראו</b>: ישעי' נב, ח."],["2615","1604","<b>בלק\"ת. . קול דודי</b>: טו, ג."],["2616","1605","<b>ובביאור ע\"פ עלי באר</b>: לקו\"ת חוקת סג, ג."],["2617","1606","<b>בעלה</b>: בלקו\"ת לג\"פ ובאוה\"ת נמצא כאן קטע נוסף."],["2618","1607","<b>בבחי' אדם</b>: וכ\"ה בלקו\"ת לג\"פ. באוה\"ת: הוא."],["2619","1608","<b>אל</b>: וכ\"ה בלקו\"ת לג\"פ. באוה\"ת: ואל."],["2620","1609","<b>היא</b>: בלקו\"ת לג\"פ ובאוה\"ת: הוא."],["2621","1610","<b>יוצר</b>: וכ\"ה בלקו\"ת לג\"פ. באוה\"ת: ויוצר."]]],[2000450270,"<b>ואשר</b> יצר בחי' אף עשיתיו, תלת עלמין, אמת<sup data-n=\"2622\">1611</sup> ג\"פ קדוש, והתקין לו ממנו בנין עדי עד, ותבואי בעדי עדיים כי אחעט\"ב<sup data-n=\"2623\">1612</sup>, וייצר ב' יצרים וטוב מאד זה יצה\"ר כשנהפך לטוב, יצאו מ\"ח מירושלים, וזהו לך לך כו' אל הארץ<sup data-n=\"2624\">1613</sup> כו'<sup data-n=\"2625\">1614</sup>.",[["2622","1611","<b>תלת עלמין אמת</b>: וכ\"ה בלקו\"ת לג\"פ ובאוה\"ת כאן. לעיל בפנים (בין הערות 1588-9): תלת עלמין אית. ואולי גם כאן צ\"ל כן."],["2623","1612","<b>אחעט\"ב</b>: משלי יב, ד."],["2624","1613","<b>כו' אל הארץ</b>: וכ\"ה בלקו\"ת לג\"פ. באוה\"ת: מארצך."],["2625","1614","<b>כו'</b>: וכ\"ה בהשמטות ותיקונים בלקו\"ת לג\"פ."]]],[2000450271,"<h3>צור תעודה כו' וביאור ענין שצ\"ל חותם</h3>\nלח) <b>וזהו</b><sup data-n=\"2626\">1615</sup> ג\"כ ענין כי הנה יוצר הרים<sup data-n=\"2627\">1616</sup>, פי' כמ\"ש בזהר שיש טורי נהורא והם חג\"ת דאצילות, ויש טורי חשוכא<sup data-n=\"2628\">1617</sup> חג\"ת שבכתר, והרים הגבהה<sup data-n=\"2629\">1618</sup> בחי' רצוא ושוב, אברהם קראו הר<sup data-n=\"2630\">1619</sup> כו' כמ\"ש בד\"ה כי ההרים ימושו<sup data-n=\"2631\">1620</sup> כו' וטורי חשוכא הם בחי' מטי ולא &lt;סט&gt;\nּ מטי, כי ההשפעה מאוא\"ס באצי' צ\"ל ג\"כ ע\"י צמצום והתפשטות<sup data-n=\"2632\">1621</sup> שאל\"כ לא יוכלו לקבל, וזהו ענין מטולמ\"ט והם הנק' טורי חשוכא ועמ\"ש בפי' ושקל בפלס הרים<sup data-n=\"2633\">1622</sup> בד\"ה אתם נצבים<sup data-n=\"2634\">1623</sup>, וגילוי ע\"ס דאצי' מבחי' טורי חשוכא וע\"ס הגנוזות נק' כי הנה יוצר הרים ועמ\"ש בד\"ה קול דודי<sup data-n=\"2635\">1624</sup>",[["2626","1615","<b>וזהו</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (י\"ח מההמשך והוא) ד\"ה: צור תעודה חתום תו' — פ' חו\"ב (הכולל פרקים ל\"ח — ל\"ט). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש.\nברשימת המאמרים שבס' התולדות אדמו\"ר מהר\"ש ע' 19 (וכן במפתח להמשך זה הנדפס) נרשם ד\"ה: ”פיה פתחה כו' והנה ברכת יוצר האדם (לז-לח)\". ובהערה לשם: ”מסופקני קצת אם פל\"ח מקומו בדרוש זה או בד\"ה צור תעודה\". הנה עפ\"י הנרשם במפתח שבריש בוך 1089 שייך פל\"ח למאמר זה. בבוך 145 ע' מא (חסר כל ההמשך ומתחיל מאמצע פל\"ח בהתיבות: והנה ידוע בענין אשה כי תזריע) ובראשו נרשם: פ' חו\"ב שנת תרל\"ח.\nמאמר זה פל\"ח — הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560207\" data-slug=\"or-hatorah-hb\" data-id=\"8316560207\">אוה\"ת בראשית כאן כרך ג ע' 1138</a> ואילך בשינויים קלים. והקיצור שם ע' תקע. פל\"ט הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560207\" data-slug=\"or-hatorah-hb\" data-id=\"8316560207\">אוה\"ת בראשית כאן כרך ג ע' תקע</a> ואילך. ישעי כרך א ע' קעח ואילך. ע' קפ. והקיצור שם ע' תקעא.\nמאמר זה נכתב בכת\"י הר\"ש סופר. פרט לציוני הפרקים והערה אחת ועוד איזה תיקונים שנרשמו בגוכתי\"ק כמצויין להלן."],["2627","1616","<b>כי הנה יוצר הרים</b>: עמוס ד, יג."],["2628","1617","<b>טורי נהורא. . טורי חשוכא</b>: ראה זהר פינחס רמט, ב. ראה גם בענין טורי נהורא וחשוכא ביאוה\"ז קרח צג, ג. פינחס קטז, א ואילך. קיז, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שכח. תקס\"ט ע' טז ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"א ע' פח. וש\"נ. דברים ח\"ג ע' תתקצה. וש\"נ. שע\"ת קלט, ג ובהנסמן במ\"מ לשם. שעה\"י קכז, ב ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670546\" data-slug=\"torat-chaim\" data-id=\"2300670546\">תו\"ח לך צ, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670254\" data-slug=\"torat-chaim\" data-id=\"2300670254\">וירא קיב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540969\" data-slug=\"torat-chaim\" data-id=\"2300540969\">שמות ח\"א טז, א</a>. וש\"נ. אוה\"ת ר\"ה ע' א'שצ. עמוס ע' תסט. שופטים כרך ג' ע' א'קסא. תהלים ע' רכה."],["2629","1618","<b>הגבהה</b>: וכ\"ה באוה\"ת כאן (וההערה שבשולי היריעה שם מיותרת) ובהשמטות ותיקונים בלקו\"ת לג\"פ."],["2630","1619","<b>אברהם קראו הר</b>: ראה רש\"י ויצא כח, יז. שוח\"ט פא, ב. מאמרי אדה\"א דברים ח\"ב ע' תרסו. וש\"נ. שה\"א קה, א ובהערה 2. ש\"א צח, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540562\" data-slug=\"torat-chaim\" data-id=\"2300540562\">תו\"ח וארא ח\"א עז, סע\"ג</a> ואילך."],["2631","1620","<b>בד\"ה כי ההרים ימושו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380877\" data-slug=\"likkutei-torah\" data-id=\"4001380877\">לקו\"ת תצא מ, א</a>. אוה\"ת תצא ע' תתרכה. ישעי' כרך ב ע' תתכז."],["2632","1621","<b>והתפשטות</b>: וכ\"ה בהשמטות ותיקונים בלקו\"ת לג\"פ."],["2633","1622","<b>ושקל בפלס הרים</b>: ישעי' מ, יב."],["2634","1623","<b>בד\"ה אתם נצבים</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380899\" data-slug=\"likkutei-torah\" data-id=\"4001380899\">לקו\"ת נצבים מה, א</a>. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקצח. וש\"נ."],["2635","1624","<b>בד\"ה קול דודי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381191\" data-slug=\"likkutei-torah\" data-id=\"4001381191\">לקו\"ת שה\"ש טו, ג</a>."]]],[2000450272,"בפי' מדלג על ההרים, וזהו ע\"ד הנ\"ל בפי' יוצר האדם, ובורא רוח ומגיד לאדם מה שיחו שיהי' שיחו בבחי' מה וביטול והוא ע\"י עסק התורה וכמ\"ש ע\"פ תבנה ותכונן עיר סיחון<sup data-n=\"2636\">1625</sup> כו'. ושם מענין מה אהבתי תורתך<sup data-n=\"2637\">1627</sup> כל היום היא שיחתי, קווצותיו תלתלי'<sup data-n=\"2638\">1628</sup> כו' ע\"ש. והמורם שפי' וענין מותרי מוחין שיוצא מהשערות, הנה זהו שלא כדרך מה שבא בהשגה, וא\"כ זהו מה שלמעלה מהשגה, וכן צ\"ל בענין שערות דדיקנא שבאים לאחר השלמת מוחין דגדלות דוקא כנודע, שג\"כ מה שלא בא בהשגת השכל בא בהשערות היינו מה שלמעלה מהשגה, שגם בלמעלה מהשגה יש מדריגות, שמה שבמוחין דקטנות הוא למעלה מהשגה זהו במוחין דגדלות בבחי' השגה כו', ומקור לזה י\"ל שפי' מותרי מוחין הוא ע\"ד שפי' בלק\"ת בדרושי ר\"ה בד\"ה אתם נצבי'<sup data-n=\"2639\">1629</sup>, מי אל<sup data-n=\"2640\">1631</sup> כמוך<sup data-n=\"2641\">1630</sup> כשיריים הוא בחי' המקיף שנשאר בבחי' שיריים שא\"א להאיר בפנימי<sup data-n=\"2642\">1626</sup>.\n<b>והנה</b> ידוע בענין אשה כי תזריע<sup data-n=\"2643\">1632</sup> וילדה זכר שתלה הכתוב נקבות בזכרים כו' ואת דינה בתו<sup data-n=\"2644\">1633</sup>, ע\"ד אבא יסד ברתא וזהו בחכמה יסד ארץ<sup data-n=\"2645\">1634</sup> שהיא מ' משא\"כ כונן שמים ז\"א הוא בתבונה וכמ\"ש בד\"ה וייצר ה' אלקים<sup data-n=\"2646\">1635</sup> את האדם, והנה שמים וארץ הם ג\"כ תשב\"כ ותשבע\"פ, נמצא תשב\"כ הנק' דכר ז\"א ושמים וה\"ע יוצר האדם נמשך מהתבונה ותשבע\"פ נוק' וארץ שרשה מהחכמה שלמעלה מהבינה, ולכן ברכת יוצר האדם רק פותח בברוך והיינו מה שנמשך מהבינה בז\"א כי כל ברכה היא מבינה דהיינו מעלמא דאתכסי' כו', אך בברכת אשר יצר את האדם בצלמו שכנגד נוק' הוא ג\"כ חותם בברוך לפי ששרשה מהחכמה, ויסוד אבא ארוך ונמשך ומתפשט ג\"כ למטה להיות חותם בברוך, ומצינו מעלת חותם בברוך גבי אברהם שנאמר והיה ברכה<sup data-n=\"2647\">1636</sup> וארז\"ל יכול יהא<sup data-n=\"2648\">1638</sup> חותם<sup data-n=\"2649\">1639</sup> בכולן<sup data-n=\"2650\">1637</sup> ת\"ל והיה ברכה בך חותמין, ואפ\"ל כי פי' חותם בברוך זהו ענין המבורך שהוא ביסוד הנק' חותם כנודע מענין חותמך פתילך ומטך<sup data-n=\"2651\">1640</sup> וזהו ענין בן פורת",[["2636","1625","<b>תבנה ותכונן עיר סיחון</b>: חוקת כא, כז. לקו\"ת חוקת סו, א."],["2637","1627","<b>מה אהבתי תורתך</b>: תהלים קיט, צז."],["2638","1628","<b>קווצותיו תלתלי'</b>: שה\"ש ה, יא."],["2639","1629","<b>בלק\"ת בדרושי ר\"ה בד\"ה אתם נצבי'</b>: הכותרת בלקו\"ת היא פרשת נצבים."],["2640","1631","<b>בד\"ה. . מי אל כמוך</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380968\" data-slug=\"likkutei-torah\" data-id=\"4001380968\">לקו\"ת ר\"ה סב, ב</a>."],["2641","1630","<b>בד\"ה אתם נצבי' מי אל כמוך</b>: תיבות אלו ניתוספו בין השיטין."],["2642","1626","<b>ושם. . בפנימי</b>: נרשם בגוכתי\"ק בצד הימני של העמוד בשני טורים."],["2643","1632","<b>אשה כי תזריע</b>: תזריע יב, ב. נדה לא, א."],["2644","1633","<b>ואת דינה בתו</b>: ויגש מו, טו."],["2645","1634","<b>בחכמה יסד ארץ</b>: משלי ג, יט."],["2646","1635","<b>בד\"ה וייצר ה' אלקים</b>: מאמרי אדה\"ז על פרשיות התורה ח\"א ע' כ ואילך. ע' לג ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a>. ג."],["2647","1636","<b>והיה ברכה</b>: לך יב, ב."],["2648","1638","<b>יהא</b>: בפסחים שם: יהו. בלקו\"ת לג\"פ ובאוה\"ת: יהיו. באוה\"ת לך כרך ד ע' 1390: יהי'."],["2649","1639","<b>חותם</b>: בפסחים שם חותמין. וכ\"ה בלקו\"ת לג\"פ ובאוה\"ת."],["2650","1637","<b>יכול יהא חותם בכולן</b>: פסחים קיז, ב."],["2651","1640","<b>חותמך פתילך ומטך</b>: וישב לח, יח [ושם: ופתילך (וכ\"ה בלקו\"ת לג\"פ וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770311\" data-slug=\"or-hatorah-hb\" data-id=\"8316770311\">אוה\"ת</a>). אבל כ\"ה גם לקמן פל\"ט]. ראה זהר אחרי עב, א ובהגהות מהרח\"ו שם. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600741\" data-slug=\"or-hatorah-hb\" data-id=\"8316600741\">אוה\"ת</a> לך כרך ג ע' תרצו. בא ע' שיא. שה\"ש ח\"ב ע' תשמא."]]],[2000450273,"יוסף<sup data-n=\"2652\">1641</sup> ל' פריה ורביה שהוא רבוי הברכה וכמ\"ש בזח\"ב תרומה קל\"ה ב', וזהו ענין ברכות לראש צדיק<sup data-n=\"2653\">1642</sup> בזח\"א ויצא קס\"ב<sup data-n=\"2654\">1643</sup>, ונק' חותם כמ\"ש חתום תורה בלמודי<sup data-n=\"2655\">1644</sup> שהם נו\"ה הנק' למודי הוי' המריקים השפע אל היסוד כו' כמ\"ש בזהר ס\"פ צו דל\"ה ע\"א, והנה חסד אתגלי בפומא דאמה<sup data-n=\"2656\">1645</sup> וזה\"ע בקר דאברהם ובקר דיוסף<sup data-n=\"2657\">1646</sup>, וע\"כ בך חותמין, וגם החתימה מגן אברהם בחי' מגין<sup data-n=\"2658\">1647</sup> זהו כענין חותם &lt;ע&gt;\nּ מגן הוא לכל החוסים בו<sup data-n=\"2659\">1648</sup> כמ\"ש בת\"א בד\"ה בכ\"ה בכסלו<sup data-n=\"2660\">1649</sup>, ועמ\"ש מענין מגן אברהם בת\"א פ' לך<sup data-n=\"2661\">1650</sup> ע\"פ אנכי מגן לך, וגם אברהם אבר מ\"ה<sup data-n=\"2662\">1651</sup> היינו יסוד אבא שמסתיים ביסוד ז\"א כו', גם כמ\"ש השקיפה ממעון כו' וברך<sup data-n=\"2663\">1652</sup> כו' וארז\"ל כל השקפה<sup data-n=\"2664\">1653</sup> כו'<sup data-n=\"2665\">1654</sup> והיינו שאפי' מדה\"ד תתהפך לרחמים, ויהי' מזה הברכה<sup data-n=\"2666\">1655</sup>, והיינו ע\"י המשכה מבחי' כתר דלית שמאלא כו', וארז\"ל ברבות שמות ספ\"ב<sup data-n=\"2667\">1656</sup> בענין והגעתם אל המשקוף<sup data-n=\"2668\">1657</sup> זה אברהם כו' ויצחק ויעקב ב' מזוזות הפתח ולכן בך חותמין שיהי' השקיפה כו' וברך כו' ועמ\"ש בד\"ה יפה שיחתן<sup data-n=\"2669\">1658</sup> של עבדי אבות כו', ועמש\"ל<sup data-n=\"2670\">1659</sup> פי' וחותם בברוך כדי שלא יהי' יניקה מצד מדה\"ד וכנ\"ל<sup data-n=\"2671\">1660</sup> שמבחי' הגבורות והדין משתלשל יניקתם כו', והחותם לזה היינו ענין השקיפה כו' וברך כי השקפה<sup data-n=\"2672\">1661</sup> בכ\"מ היא מדה\"ד וישקף אל מחנה מצרים<sup data-n=\"2673\">1662</sup> כו' ושיהי' מתהפך מדה\"ד",[["2652","1641","<b>בן פורת יוסף</b>: ויחי מט, כב. ראה גם [בנוסף להמצויין בפנים] <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680136\" data-slug=\"torat-chaim\" data-id=\"2300680136\">תו\"ח ויחי רמד, ב</a> הערה 23."],["2653","1642","<b>ברכות לראש צדיק</b>: משלי י, ו."],["2654","1643","<b>קס\"ב</b>: ע\"א."],["2655","1644","<b>חתום תורה בלימודי</b>: ישעי' ח, טז."],["2656","1645","<b>חסד אתגלי בפומא דאמה</b>: ראה זהר בא לו, א. אד\"ר נשא קמב, א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' פג."],["2657","1646","<b>בקר דאברהם ובקר דיוסף</b>: זהר בלק רד, א ואילך. ראה גם ביאוה\"ז בלק קט, א. סידור שחרית לשבת קפט, א. אוה\"ת ויצא כרך ה ע' 1738. בהעלותך ע' שמג, ואילך. תצוה ע' א'תשסג ואילך."],["2658","1647","<b>מגין</b>: וכ\"ה בלקו\"ת לג\"פ. ובאוה\"ת: מגן."],["2659","1648","<b>מגן הוא לכל החוסים בו</b>: שמו\"ב כב, לא. תהלים יח, לא."],["2660","1649","<b>בת\"א בד\"ה בכ\"ה בכסלו</b>: כט, ג סוד\"ה והנה."],["2661","1650","<b>בת\"א פ' לך</b>: יב, א."],["2662","1651","<b>אברהם אבר מ\"ה</b>: ראה זהר בהקדמה ד, א. לקו\"ת להאריז\"ל ר\"פ לך."],["2663","1652","<b>השקיפה. . וברך</b>: תבוא כו, טו."],["2664","1653","<b>כל השקפה</b>: ראה ירושלמי ספ\"ה דמעשר שני. תנחומא תשא יד. שמו\"ר ר\"פ מא. רש\"י וירא יח, טז."],["2665","1654","<b>כל השקפה כו'</b>: בלקו\"ת לג\"פ ובאוה\"ת באים כאן הוספות."],["2666","1655","<b>הברכה</b>: בלקו\"ת לג\"פ ובאוה\"ת נמצא כאן ציון למדרש."],["2667","1656","<b>ברבות שמות ספ\"ב</b>: וכ\"ה בלקו\"ת לג\"פ ובאוה\"ת כאן. בא ס\"ע שיז: ”וכן אמרו במדרש פ' בא פי\"ז [, ג] ובפ' שמות ספ\"ב\". ע' שיג. ע' שכה. אבל באוה\"ת חנוכה ח\"ב ע' שכח־ ואתחנן כרך ו' ע' ב'רעט: ”וברבות סדר שמות ס\"פ א'\". וכ\"ה לפנינו."],["2668","1657","<b>והגעתם אל המשקוף</b>: בא יב, כב."],["2669","1658","<b>בד\"ה יפה שיחתן</b>: ראה אוה\"ת ח\"ש ע' 260."],["2670","1659","<b>ועמש\"ל</b>: ראה לעיל ספל\"ד. בכת\"י הר\"ש סופר וכן בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: סוף אות יו\"ד די\"ל. ומחקו כ\"ק אדמו\"ר מהר\"ש."],["2671","1660","<b>וכנ\"ל</b>: ראה לעיל פ\"ל־ פל\"א. בכת\"י הר\"ש סופר וכן בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: סעי' ח. ומחקו כ\"ק אדמו\"ר מהר\"ש."],["2672","1661","<b>השקפה</b>: בלקו\"ת לג\"פ ובאוה\"ת: השקיפה."],["2673","1662","<b>וישקף אל מחנה מצרים</b>: בשלח יד, כד [בדילוג השם]."]]],[2000450274,"למדה\"ר<sup data-n=\"2674\">1663</sup> זהו ענין השקיפה כו' וברך כו' ואזי ממילא אין נמשך יניקה לחיצוני' כו'<sup data-n=\"2675\">1664</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> ענין כי הנה יוצר הרים טורי נהורא הנמשכים מטורי חשוכא, עוד יאמר כי פותח בברוך זהו ע\"ד כונן שמים בתבונה, אך בחכמה יסד ארץ זהו חותם בברוך, וזהו ענין המבורך, ברכות לראש צדיק, ונק' חתום תורה בלמודי, בך יהיו חותמין וענין מגן אברהם, וענין אברהם אבר מ\"ה יס\"א ארוך כו' לכן ממנו בא החותם, עוי\"ל פותח בברוך שלא יהי' יניקה מרבוי החסד, וחותם בברוך זהו שלא יהי' יניקה מחמת מדה\"ד כנז\"ל<sup data-n=\"2676\">1665</sup> וזהו השקיפה כו' וברך, וזהו בך חותמין כי המשקוף זהו אברהם כו' האדם הגדול<sup data-n=\"2677\">1666</sup> כו'.</span>\nלט) <b>וביאור</b> ענין<sup data-n=\"2678\">1667</sup> שצ\"ל חותם בברוך בבחינת חוה ותשבע\"פ היינו כמארז\"ל פ\"ז דיומא דע\"ב סע\"ב ע\"פ וזאת התורה אשר שם משה<sup data-n=\"2679\">1668</sup> זכה נעשית לו סם חיים לא זכה כו' וזהו ע\"ד משארז\"ל ע\"פ אעשה לו עזר כנגדו<sup data-n=\"2680\">1669</sup>, זכה עוזרתו לא זכה כנגדו ביבמות פרק הבע\"י דס\"ג ע\"א, וקאי על חוה שהיא ג\"כ תשבע\"פ שעז\"נ ראה חיים עם אשה<sup data-n=\"2681\">1670</sup> אשר אהבת כמ\"ש בלק\"ת פ' פנחס<sup data-n=\"2682\">1671</sup> בד\"ה קדש ישראל, והיינו לפי כי תשבע\"פ היא ח\"ת שירדה לעלמא דפרודא ונתלבשה בדברים גשמיים כו', וכמ\"ש בת\"א פ' שמות<sup data-n=\"2683\">1672</sup> בד\"ה קול דודי, שלכן נאמר על תשבע\"פ שחורה אני<sup data-n=\"2684\">1673</sup>, שאין נראה בה שום אור כלל, אבל באמת ונאוה כו', וזהו לבון הלכתא כו' ללבנם בלובן העליון כו' יעו\"ש, ולכן נק' תשבע\"פ עה\"ד טו\"ר וכמ\"ש בזח\"א בראשית דכ\"ז סע\"ב ובבה\"ז שם, ובאג\"ה<sup data-n=\"2685\">1674</sup> בד\"ה והמשכילים יזהירו, לכך זכה כשעוסק לשמה ולקיימה נעשית לו סם חיים כי מברר עה\"ד טו\"ר ומחברו עם עץ החיים ונק' וזאת שממשיך הוא\"ו לבחי' זאת התורה כמ\"ש בזח\"ג ר\"פ חקת דקע\"ט ע\"ב, וע\"י שעה\"ד נתברר הרי",[["2674","1663","<b>למדה\"ר</b>: בלקו\"ת לג\"פ ובאוה\"ת נמצא כאן הוספה."],["2675","1664","<b>כו'</b>: בלקו\"ת לג\"פ ובאוה\"ת נמצא כאן הוספה."],["2676","1665","<b>כנז\"ל</b>: ראה לעיל ספל\"ד. בכת\"י הר\"ש סופר וכן בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: סעי' יו\"ד. ומחקו כ\"ק אדמו\"ר מהר\"ש."],["2677","1666","<b>אברהם. . האדם הגדול</b>: יהושע יד, טו וברש\"י (בשם מדרש אגדה). איוב לב, ב. ב\"ר פי\"ד, ו. במדב\"ר פי\"ג, ג. אוה\"ת יהושע ע' ד. וש\"נ. בראשית כאן ע' תקע. ח\"ש ח\"א ע' קכ (ח\"ב ע' תמב). חנוכה ח\"ב ע' שכח. במדבר ע' נא ואילך. ר\"ה ע' א'רפז. המשך מים רבים תרל\"ו פקי\"ד. ח\"ב ע' רנ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201320\" data-slug=\"likkutei-sichot\" data-id=\"1300201320\">לקו\"ש לך כרך כ ע' 307</a>."],["2678","1667","<b>וביאור ענין</b>: בלקו\"ת לג\"פ וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560207\" data-slug=\"or-hatorah-hb\" data-id=\"8316560207\">אוה\"ת</a>: וביאור הענין.\nהבא להלן הוא לשון אוה\"ת בראשית כאן כרך ג ע' תקע ואילך. ישעי' ע' קעח ואילך. ע' קפ. בשינויים קלים. והקיצור שם ע' תקעא."],["2679","1668","<b>וזאת התורה אשר שם משה</b>: ואתחנן ד, מה."],["2680","1669","<b>אעשה לו עזר כנגדו</b>: בראשית ב, יח."],["2681","1670","<b>ראה חיים עם אשה</b>: קהלת ט, ט."],["2682","1671","<b>בלק\"ת פ' פנחס</b>: פ, ב."],["2683","1672","<b>בת\"א פ' שמות</b>: נא, סע\"ב ואילך."],["2684","1673","<b>שחורה אני</b>: שה\"ש א, ה."],["2685","1674","<b>ובאג\"ה</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: סי' כ\"ו."]]],[2000450275,"&lt;עא&gt;\nּ מתגלה אורות דתהו שלמעלה מהתיקון והיינו כמ\"ש היש בה עץ אם אין<sup data-n=\"2686\">1675</sup> דבחי' עץ היינו עה\"ח אבל אין הוא מה שלמעלה מעה\"ח והוא נמשך ע\"י בירור עה\"ד שמהפך היש לאין כו' וזהו ענין סם חיים ועמ\"ש בפי' ממעל לעצים<sup data-n=\"2687\">1676</sup>, וע' בזח\"ג ר\"פ תזריע דמ\"ב ע\"ב ע\"פ גמלתהו טוב<sup data-n=\"2688\">1677</sup> ולא רע כל ימי חייה בגין דכתיב ועץ הדעת טוב ורע<sup data-n=\"2689\">1678</sup>, טוב אימתי בזמנא דאינון ימי השמים נהרין עלה ומזדווגן<sup data-n=\"2690\">1679</sup> עמה כדקא יאות, דאינון ימי חייה בגין דעץ החיים שדר לה חיים ונהרין<sup data-n=\"2691\">1680</sup> לה, ובההוא זמנא גמלתהו טוב ולא רע, ופי' המק\"מ כי עה\"ד טו\"ר היא המ' שרגליה יורדות מות<sup data-n=\"2692\">1681</sup> הנקרא רע, אך ע\"י דאינון ימי השמים שהם ו\"ק דז\"א נהרין עלה, עי\"ז היא בחי' טוב ולא רע ונותנת לתחתונים שפע טוב וכאלו נותנת לז\"א ולכן אמר גמלתהו טוב, והרמ\"ז פי' שע\"י שנמשך לה מעץ החיים נמשך לה כח לעשות הבירור לברר הטוב מק\"נ שהיא עה\"ד טו\"ר באמת, והיינו משום כי בחכמה אתברירו<sup data-n=\"2693\">1682</sup> והאיש דרכו לכבש<sup data-n=\"2694\">1683</sup> ע\"כ צ\"ל נמשך לה הכח לברר מבחי' חכמה וז\"א כו', ולכן כשעוסק בתשבע\"פ לשמה שעי\"ז ממשיך בה מבחי' עץ החיים, כי הנה בחי' חיים היינו אמונה ואהבה ויראה כמ\"ש צדיק באמונתו יחיה<sup data-n=\"2695\">1684</sup>, וביראה כתיב יראת ה' לחיים<sup data-n=\"2696\">1685</sup>, ובאהבה כתי' כי טוב חסדך מחיים<sup data-n=\"2697\">1686</sup>, וכתיב ובחרת בחיים כו' לאהבה את ה' אלקיך<sup data-n=\"2698\">1688</sup> ס\"פ נצבים<sup data-n=\"2699\">1687</sup>, וכן בחכמה נאמר והחכ' תחי', לכן ע\"י בחי' אלו בעסק התורה ממשיך בתשבע\"פ מבחי' עץ החיים ואזי גמלתהו טוב ע\"י שמבררת הטוב מעה\"ד טו\"ר, וזהו שנעשית לו סם חיים, משא\"כ לא זכה שאין לבו זך, ועוסק בה שלא לשמה כ\"א להיות יש ודבר שעי\"ז מפריד תשבע\"פ מבחי' חכמה כח מה שהיא בחי' עץ החיים, ששם הוא הביטול האמיתי<sup data-n=\"2700\">1689</sup>, ולכן אומרי' ונפשי כעפר לכל תהי' ועי\"ז פתח לבי בתורתיך<sup data-n=\"2701\">1690</sup>, משא\"כ בבחי' גאות ויש, וע\"י שנמשך אחר הישות ומפריד",[["2686","1675","<b>היש בה עץ אם אין</b>: שלח יג, כ."],["2687","1676","<b>בפי' ממעל לעצים</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380483\" data-slug=\"likkutei-torah\" data-id=\"4001380483\">לקו\"ת שלח מב, סע\"ד</a> ואילך."],["2688","1677","<b>גמלתהו טוב</b>: משלי לא, יב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380777\" data-slug=\"likkutei-torah\" data-id=\"4001380777\">לקו\"ת עקב טו, רע\"ד</a>."],["2689","1678","<b>ועץ הדעת טוב ורע</b>: בראשית ב, ט."],["2690","1679","<b>ומזדווגן</b>: בלקו\"ת לג\"פ־ אוה\"ת כאן־ משלי ע' תקסח: מזדווגין. בזהר כבפנים."],["2691","1680","<b>ונהרין</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380777\" data-slug=\"likkutei-torah\" data-id=\"4001380777\">לקו\"ת</a> לג\"פ־ אוה\"ת כאן־ לקו\"ת עקב טו, רע\"ד. בזהר ואוה\"ת משלי שם: ונהיר."],["2692","1681","<b>שרגליה יורדות מות</b>: משלי ה, ה. ראה זהר ויחי רכא, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600564\" data-slug=\"or-hatorah-hb\" data-id=\"8316600564\">אוה\"ת משלי כרך א ע' תקסד</a> ואילך. לקמן מאמר ד\"ה בנים אתם על יד הערה 15. קונט' עה\"ח ע' 27 אילך."],["2693","1682","<b>בחכמה אתברירו</b>: ראה זהר היכלות פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550161\" data-slug=\"torat-chaim\" data-id=\"2300550161\">תו\"ח תשא ח\"ב שפד, ד</a> ואילך."],["2694","1683","<b>והאיש דרכו לכבש</b>: יבמות סה, ב."],["2695","1684","<b>צדיק באמונתו יחיה</b>: חבקוק ב, ד [ושם: וצדיק — ראה שה\"א ח, ב ובהערה 3. לקמן (בחלק ההנחות) הנחה ד\"ה לה\"ע אכילת מצה ובהערה 32]."],["2696","1685","<b>יראת ה' לחיים</b>: משלי יט, כג. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקלט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540435\" data-slug=\"torat-chaim\" data-id=\"2300540435\">תו\"ח בא ח\"א ק, א</a>. וש\"נ."],["2697","1686","<b>כי טוב חסדך מחיים</b>: תהלים סג, ד."],["2698","1688","<b>אלקיך</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: כו'."],["2699","1687","<b>ובחרת בחיים. . לאהבה. . ס\"פ נצבים</b>: ל, יט. כ."],["2700","1689","<b>האמיתי</b>: בלקו\"ת לג\"פ ובאוה\"ת: אמיתי."],["2701","1690","<b>ונפשי כעפר. . בתורתיך</b>: ברכות יז, א. סיום תפלת העמידה (אלקי נצור). ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קכח. מאמרי אדה\"א קונטרסים ע' שפא. וש\"נ. שערי אורה ע' לו ובהערה 3."]]],[2000450276,"ח\"ת מח\"ע בחי' ונרגן מפריד אלוף<sup data-n=\"2702\">1691</sup>, וגורם בחי' רגליה יורדות כו', ולא נעשה הבירור מעה\"ד טו\"ר שעיקר הכח לברר הוא ע\"י כח מה וביטול בחכמה אתברירו כנ\"ל ולכן נעשית לו כו'<sup data-n=\"2703\">1692</sup> ע\"ד שנהפך המטה לנחש, ואז נק' חוה לשון חויא כפשוטו כמשארז\"ל ברבות בראשית ספ\"ך בפי' חוה, חוייא<sup data-n=\"2704\">1693</sup> חיוך<sup data-n=\"2705\">1694</sup> ואת חוייא דאדם כו' ע\"ש<sup data-n=\"2706\">1695</sup> כי הנחש הוא ג\"ק הטמאות<sup data-n=\"2707\">1696</sup> היונקי' מק\"נ<sup data-n=\"2708\">1697</sup>, וק\"נ יונקת מהמ' הנק' חוה<sup data-n=\"2709\">1698</sup> כו', וזהו ע\"ד הנחש השיאני<sup data-n=\"2710\">1699</sup>, בא נחש על חוה<sup data-n=\"2711\">1700</sup>, ומזה נמשך הזוהמא, כמ\"כ שייך בחי' זו בעוסק בתשבע\"פ הנק' חוה בדרך לא זכה שאמרו פ\"ז דיומא<sup data-n=\"2712\">1701</sup> שנעשית לו סם מות מפני שממשיך בא<sup data-n=\"2713\">1702</sup> נחש כו', ועמ\"ש בבה\"ז פ' וישלח<sup data-n=\"2714\">1703</sup> בענין ופושעים יכשלו בם<sup data-n=\"2715\">1704</sup> דקאי על לא זכה כו', ועמ\"ש מענין תשב\"כ ותשבע\"פ שהם עה\"ח ועה\"ד בלק\"ת בד\"ה בשעה שהקדימו ישראל נעשה<sup data-n=\"2716\">1705</sup>, ובאג\"ה בד\"ה והמשכילים יזהירו<sup data-n=\"2717\">1706</sup> כו' ועמ\"ש ע\"פ וברך את לחמך ואת מימיך<sup data-n=\"2718\">1707</sup> &lt;עב&gt;\nּ דקאי על תשב\"כ ותשבע\"פ, וזהו ענין דואג ואחיתופל כו' שנטרדו<sup data-n=\"2719\">1708</sup> כו', וע\"כ כדי להיות זכה נעשית לו סם חיים לזה צ\"ל חותם בברוך, וע' בבה\"ז ר\"פ בראשית במאמר כשושנה<sup data-n=\"2720\">1709</sup> בין החוחים, שלפי שהיא בין החוחים נמשך בה י\"ג מדה\"ר מא\"א לנטרא לה, וברבות ס\"פ במדבר פ\"ה<sup data-n=\"2721\">1710</sup> ע\"פ למען שמי אאריך אפי ותהלתי אחטם לך<sup data-n=\"2722\">1711</sup>, דורש אחטם לשון חותם כו' שימני כחותם כו' והיא גרמה להם שלא נכרתו בגלות הוי לבלתי הכריתך עכ\"ל.",[["2702","1691","<b>ונרגן מפריד אלוף</b>: משלי טז, כח."],["2703","1692","<b>כו'</b>: בלקו\"ת לג\"פ ובאוה\"ת נמצא כאן הוספה."],["2704","1693","<b>חוייא</b>: בלקו\"ת לג\"פ ובב\"ר דפוס אמשטרדם שנת ת\"א-ב: חיויא. באוה\"ת ובב\"ר: חויא."],["2705","1694","<b>חיוך</b>: וכ\"ה בלקו\"ת לג\"פ ובאוה\"ת. בב\"ר: חוויך. ובב\"ר דפוס אמשטרדם שנת ת\"א-ב: חויך."],["2706","1695","<b>ע\"ש</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: דהיינו."],["2707","1696","<b>הנחש הוא ג\"ק הטמאות</b>: ראה גם אוה\"ת בראשית כרך ג ע' 1152. ע' תקעז ס\"ד. תו\"ח בשלח ח\"א קלז, ד ובהערה 264."],["2708","1697","<b>ג\"ק הטמאות היונקי' מק\"נ</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450559\" data-slug=\"or-hatorah-hb\" data-id=\"8316450559\">אוה\"ת עקב ע' תקנט</a> ס\"ח."],["2709","1698","<b>מהמ' הנק' חוה</b>: ראה מאמרי אדה\"א בראשית ע' סד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670146\" data-slug=\"torat-chaim\" data-id=\"2300670146\">תו\"ח וירא צח, ד</a>."],["2710","1699","<b>הנחש השיאני</b>: בראשית ג, יג."],["2711","1700","<b>בא נחש על חוה</b>: שבת קמו, רע\"א."],["2712","1701","<b>פ\"ז דיומא</b>: נסמן בפנים בריש הפרק."],["2713","1702","<b>בא</b>: בלקו\"ת לג\"פ ובאוה\"ת: בה."],["2714","1703","<b>בבה\"ז פ' וישלח</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: דף קע\"ה (והוא ציון מקומו בזהר). ראה ביאוה\"ז שם כ, ד."],["2715","1704","<b>ופושעים יכשלו בם</b>: הושע יד, י."],["2716","1705","<b>בלק\"ת. . נעשה</b>: במדבר יג, ג."],["2717","1706","<b>ובאגה\"ק בד\"ה והמשכילים יזהירו</b>: סכ\"ו ע' קמד ואילך. הובא בלקו\"ת שם."],["2718","1707","<b>וברך את לחמך ואת מימיך</b>: משפטים כג, כה. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' תיא."],["2719","1708","<b>דואג ואחיתופל כו' שנטרדו</b>: ראה סנהדרין צ, א (במשנה)."],["2720","1709","<b>בבה\"ז. . כשושנה</b>: ראה ד\"ה ר' חזקי' פתח תקס\"ז נדפס במאמרי אדה\"ז תקס\"ו ע' שפו. ביאוה\"ז להצ\"צ כרך ב ע' תקצא ס\"ו."],["2721","1710","<b>וברבות ס\"פ במדבר פ\"ה</b>: ס\"ו."],["2722","1711","<b>למען שמי. . אחטם לך</b>: ישעי' מח, ט. ראה גם בפיסקא הבאה. אוה\"ת ר\"ה ע' א'תג."]]],[2000450277,"<b>והנה</b> אחטם לשון חוטם שהוא בחי' ריח, וכמ\"ש בלק\"ת ס\"פ שלח<sup data-n=\"2723\">1712</sup> בד\"ה וישלח יהושע כו' בענין לבעל החוטם אני מתפלל והיינו דכתיב ותהלתי אחטם לך בזח\"ג נשא דק\"ל סע\"ב, ומשם מקור הברכה כמ\"ש וירח את ריח בגדיו ויברכהו<sup data-n=\"2724\">1713</sup> כו' ומשם נמשך לבלתי אכריתך כי כרת נמשך מכתר דקליפה כרתיאל במא\"א כ' ט\"ו, והוא נמשך ע\"י ביטול תורה שע\"ז נאמר הכרת תכרת<sup data-n=\"2725\">1714</sup> כו'<sup data-n=\"2726\">1715</sup>, אבל ע\"י ותהלתי אחטם לך מבחי' כתר עליון דקדושה, עי\"ז נופלים הקליפות ונמשך לבלתי אכריתך כו' וזהו עצמו ענין החותם, וכנ\"ל בענין השקיפה כו' וברך כו' היינו ביטול כוחות הדין שנמשך ע\"י ההמשכה מא\"א כו', ועמ\"ש בלק\"ת פ' נשא<sup data-n=\"2727\">1716</sup> בד\"ה הוי' יחתו מריביו<sup data-n=\"2728\">1717</sup> ועיין ברבות וישב פרשה פ\"ה<sup data-n=\"2729\">1718</sup> ע\"פ חותמך פתילך ומטך, חותמך זו מ' המד\"א שימני כחותם, היינו שבמ' נמשך מבחי' ותהלתי אחטם לך כמ\"ש תהלה<sup data-n=\"2730\">1719</sup> לדוד<sup data-n=\"2731\">1720</sup>.\n<b>אך</b> הדרך שיזכה האדם לחותם זה י\"ל בהקדים הפסוק צור תעודה חתום תורה בלמודי בישעי' סי' ח' ט\"ז, ופרש\"י צור תעודה לשון העדותי בכם היום<sup data-n=\"2732\">1722</sup> לשון התראה קשור התראתי, וחתום התורה על לב לימודי, תלמידך יראי<sup data-n=\"2733\">1723</sup> שמים הנקראים למודי הוי', ואם תאמר אין לשון קשירה נופל בלימוד התורה שנאמר<sup data-n=\"2734\">1724</sup> קשרם על לוח לבך<sup data-n=\"2735\">1725</sup> עכ\"ל<sup data-n=\"2736\">1721</sup>, ויש<sup data-n=\"2737\">1726</sup> לפרש לפ\"ז צור תעודה קשור התעודה היינו ע\"ד בחי' משכן העדות, שהוא יחוד חו\"ב, והם מוחא ולבא, לשעבד המוח והלב, וענין צור וקשירה אפ\"ל בחי' קטרת לשון קשר<sup data-n=\"2738\">1727</sup>, בחד קטירא אתקטרנא ביה, והקשורים ליעקב<sup data-n=\"2739\">1728</sup>, עמ\"ש מזה בביאור ע\"פ נשא<sup data-n=\"2740\">1729</sup>,",[["2723","1712","<b>בלק\"ת ס\"פ שלח</b>: נא, ד ס\"ב."],["2724","1713","<b>וירח את ריח בגדיו ויברכהו</b>: תולדות כז, כז."],["2725","1714","<b>הכרת תכרת</b>: שלח טו, לא. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a> ובמ\"מ, הגהות והע\"ק שם."],["2726","1715","<b>כו'</b>: וכ\"ה באוה\"ת כאן. ובלקו\"ת לג\"פ: וגו'."],["2727","1716","<b>בלק\"ת פ' נשא</b>: כה, ג."],["2728","1717","<b>מריביו</b>: בלקו\"ת לג\"פ ובאוה\"ת ניתוסף: כו'."],["2729","1718","<b>ברבות וישב פרשה פ\"ה</b>: ס\"ט."],["2730","1719","<b>תהלה לדוד</b>: תהלים קמה, א."],["2731","1720","<b>לדוד</b>: בלקו\"ת לג\"פ ובאוה\"ת נמצא כאן הוספה."],["2732","1722","<b>העדותי בכם היום</b>: ואתחנן ד, כו. נצבים ל, יט."],["2733","1723","<b>יראי</b>: וכ\"ה באוה\"ת שבהערה 1726. ברש\"י שם: ויראי [אבל בכמה הוצאות ומהם: אמשטרדם תנ\"ט־ ת\"ס־ תפ\"ד — תפ\"ח־ תקכ\"ח. פראג תס\"ו. זולצבאך תקכ\"ט מובא כבפנים]."],["2734","1724","<b>התורה שנאמר</b>: ועד\"ז באוה\"ת שבהערה 1726 [ושם: התורה נא']. ברש\"י שם: תורה נופל הוא בו שנאמר."],["2735","1725","<b>קשרם על לוח לבך</b>: ברש\"י: קשרם על לבך תמיד — משלי ו, כא. הלשון שבפנים מובא באבן עזרא בא ג, ט. אוה\"ת שבהערה הבאה [וראה משלי ג, ג. ז, ג]."],["2736","1721","<b>אך הדרך. . עכ\"ל</b>: לשון אוה\"ת כאן ע' תקעא רפט\"ז. ושם: והנה הדרך."],["2737","1726","<b>ויש</b>: מכאן ואילך לשון אוה\"ת ישעי' כרך א ע' קעח ס\"ב. ע' קפ ס\"ה."],["2738","1727","<b>קטרת לשון קשר</b>: ראה גם לעיל המשך אם כסף תלוה פי\"א ובהערה 204."],["2739","1728","<b>והקשורים ליעקב</b>: ויצא ל, מב."],["2740","1729","<b>בביאור ע\"פ נשא</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380399\" data-slug=\"likkutei-torah\" data-id=\"4001380399\">לקו\"ת נשא כב, ד</a>."]]],[2000450278,"ומענין קטרת בד\"ה ושאבתם מים, דרוש הראשון<sup data-n=\"2741\">1730</sup>, וענין למודי הוי' נתבאר בד\"ה וכל בניך<sup data-n=\"2742\">1731</sup> למודי הוי' שיהי' התורה חתום בלבם, ע\"ד כחותם על לבך, דפי' בזח\"ב משפטים קיד\"א אורחא<sup data-n=\"2743\">1732</sup> דחותם כיון דאתדבק באתר<sup data-n=\"2744\">1733</sup> דאתדבק שביק ביה כל דיוקניה אע\"ג דההוא חותם אזיל הכא והכא ולא קיימא תמן והא אתעבר מיניה כל דיוקניה שביק תמן, ותמן קיימא, אוף הכא אמרה כנ\"י כיון דאתדבקנא בך כל דיוקני להוי חקיק בך, דאע\"ג דאיזיל הכא או הכא תשכח דיוקני חקיק בך ותדכר לי עכ\"ל. ומבואר במ\"א דיוקני הוא שרש ומקור הנשמה שהיא קשורה ודבוקה בה', ועל הארת הנשמה<sup data-n=\"2745\">1734</sup> המלובשת בגוף אמר אע\"ג דאיזיל הכא או הכא כו', ולפ\"ז כמ\"כ &lt;עג&gt;\nּ ענין חתום תורה בלב למודי הוי', היינו התורה שלומד תהי' חקוקה בלבו ממש, עד שאפילו בשעה שאין עוסק בה, עכ\"ז היא חקוקה בלבו וכמו מי שיודע המשנה בע\"פ ודמי כמונח ליה בקופסא<sup data-n=\"2746\">1735</sup>, הרי אף בשעה שעוסק בשארי ענינים המשנה קבועה וחקוקה במוחו ולבו, וזה נק' זקן שקנה חכמה<sup data-n=\"2747\">1736</sup>, שהיא קנויה בו ממש, וכמ\"ש מזה בלק\"ת פ' קדושי'<sup data-n=\"2748\">1737</sup> ע\"פ והדרת פני זקן, וע\"י שהתורה חתום בלבו מעורר בחי' שימני כחותם על לבך, דיוקני חקיק בך, ועמ\"ש ע\"פ אם בחקתי תלכו<sup data-n=\"2749\">1738</sup> מענין אותיות החקיקה שהם גבוהים מאד בחי' גליף גליפו בטהירו עילאה<sup data-n=\"2750\">1739</sup>, ושכמ\"כ בנשמות יש בחי' זו בעה\"נ ישבו אבותיכם בחי' ישראל עלו במחשבה, וזהו כי חק לישראל הוא<sup data-n=\"2751\">1740</sup> שיומשך בו מבחי' אותיות החקיקה כמ\"ש בלק\"ת סד\"ה תקעו בחדש<sup data-n=\"2752\">1741</sup>, דרוש הראשון, ועמ\"ש בת\"א פ' תצוה בד\"ה ועשית ציץ בפי' ופתחת עליו פתוחי חותם, וז\"ע מ\"ש<sup data-n=\"2753\">1742</sup> ברבות ס\"פ במדבר פ\"ה הנ\"ל<sup data-n=\"2754\">1743</sup> ע\"פ למען שמי אאריך אפי ותהלתי אחטם לך, דורש אחטם לשון חותם קץ הגאולה החתום (כמו חתום הוא באוצרתי בפ' האזינו<sup data-n=\"2755\">1744</sup> ) גם חותמה לטובה כמ\"ש שימני כחותם כו' והיא גרמה להם שלא נכרתו",[["2741","1730","<b>בד\"ה ושאבתם מים דרוש הראשון</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381038\" data-slug=\"likkutei-torah\" data-id=\"4001381038\">לקו\"ת סוכות עח, ג</a> ואילך. ואולי הכוונה לד\"ה זה שנדפס במאמרי אדה\"ז אתהלך לאזניא ע' קלב שהוא נו\"א מד\"ה זה שבלקו\"ת."],["2742","1731","<b>בד\"ה וכל בניך</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת ראה כט, א</a>."],["2743","1732","<b>אורחא</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158100193\" data-slug=\"or-hatorah-hb\" data-id=\"8158100193\">אוה\"ת</a> כאן. בזהר ובאוה\"ת שה\"ש כרך ג ע' תתקצו: ארחא."],["2744","1733","<b>באתר</b>: וכ\"ה באוה\"ת כאן. בזהר: בההוא אתר."],["2745","1734","<b>דיוקני. . הנשמה. . הארת הנשמה</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770365\" data-slug=\"or-hatorah-hb\" data-id=\"8316770365\">אוה\"ת שה\"ש ח\"ב ע' תשלג</a>."],["2746","1735","<b>ודמי כמונח ליה </b>[באוה\"ת: לו]<b> בקופסא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380302\" data-slug=\"likkutei-torah\" data-id=\"4001380302\">לקו\"ת</a> הוספות לויקרא נב, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תתקכב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940301\" data-slug=\"or-hatorah-hb\" data-id=\"8159940301\">אוה\"ת ויקרא כרך ב ע' תשג</a>."],["2747","1736","<b>זקן שקנה חכמה</b>: תו\"כ קדושים יט, לב. קדושין לב, ב. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשמ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550516\" data-slug=\"torat-chaim\" data-id=\"2300550516\">תו\"ח משפטים ח\"ב ש, ב</a> ואילך."],["2748","1737","<b>בלק\"ת פ' קדושי'</b>: ל, ד."],["2749","1738","<b>אם בחקתי תלכו</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380275\" data-slug=\"likkutei-torah\" data-id=\"4001380275\">לקו\"ת ויקרא מו, ב</a>."],["2750","1739","<b>גליף גליפו בטהירו עילאה</b>: זהר בראשית טו, א."],["2751","1740","<b>כי חק לישראל הוא</b>: תהלים פא, ה."],["2752","1741","<b>בלק\"ת סד\"ה תקעו בחדש</b>: ר\"ה נד, ד."],["2753","1742","<b>וז\"ע מ\"ש</b>: באוה\"ת כאן ע' קעט: וע'. וכן העתיק הר\"ש סופר. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["2754","1743","<b>הנ\"ל</b>: ניתוסף בגוכתי\"ק בין השיטין."],["2755","1744","<b>חתום הוא באוצרתי </b>[ב: באוצרותי]<b> בפ' האזינו</b>: לב, לד בהוספת תיבת: הוא."]]],[2000450279,"בגלות הוי לבלתי הכריתך עכ\"ל, וכ' המ\"כ פי' אחטם אפתח החותם, גם אחטם ל' ריח והוא מכתר וזהו הגורם לבלתי הכריתך שהכרת נמשך מכתר דקליפה וע\"י אחטם גורם לבלתי הכריתך, שע\"י הארת כתר עליון מתבטל ואתכפיא הכתר דקליפה, גם מבחי' אחטם לך יומשך והריחו ביראת ה'<sup data-n=\"2756\">1745</sup>, וכ\"ז י\"ל שנמשך ע\"י חתום תורה בלמודי שכמ\"כ ממשיך מלמעלה שימני כחותם, כמו שאמרו נרך בידי ונרי בידך<sup data-n=\"2757\">1746</sup>, היינו נר ה' נשמת אדם<sup data-n=\"2758\">1747</sup> היא בידו של הקב\"ה, ונרי היינו נר מצוה ותורה אור<sup data-n=\"2759\">1748</sup> היא בידך אם אתה משמר נרי<sup data-n=\"2760\">1749</sup> אני משמר נרך, לכן ע\"י חתום תורה בלמודי, גורם ותהלתי אחטם לך ובחי' שימני כחותם<sup data-n=\"2761\">1750</sup> כו', גם י\"ל צור תעודה זהו ע\"י התפלה וידעת היום<sup data-n=\"2762\">1751</sup> כו', וזהו כענין פותח<sup data-n=\"2763\">1752</sup> בברוך דהמכוון להמשיך גלוי אוא\"ס בהתורה והיינו ע\"י וכל בניך למודי הוי' בינה בן י\"ה<sup data-n=\"2764\">1753</sup> רצוא ושוב שבתפלה, וזהו צור תעודה אשר תעודה הוא ענין עדות<sup data-n=\"2765\">1754</sup> לישראל וידעת כו' והשבות כו' ואתם עדי<sup data-n=\"2766\">1755</sup> וכן שמע ישראל<sup data-n=\"2767\">1756</sup> ע' רבתי ד' רבתי בחי' עד<sup data-n=\"2768\">1757</sup> והוא הדעת בסוכ\"ע ושיהי' בבחי' ריעים תרין ריעין כו', אח\"כ חתום תורה זהו חותם בברוך וכנ\"ל דהיינו ע\"י שיהי' התורה קשור וחתום<sup data-n=\"2769\">1758</sup> וחקוק בלבו עי\"ז ממשיך חותם בברוך.\n<span data-k=\"ks\"><b>קיצור.</b> מה שצ\"ל חותם בברוך, כי אשר שם משה זכה נעשית לו סם חיים שעה\"ד טו\"ר נתברר ומתחבר<sup data-n=\"2770\">1759</sup> בעה\"ח וממשיך מבחי' אין שלמעלה מבחי' עץ והיינו ע\"י שממשיך תחלה מעה\"ח חיים אמונה אהוי\"ר, משא\"כ לא זכה ונמשך אחר היש וכענין המטה שנהפך כו', ושיהי' זכה זהו ע\"י חותם בברוך שהחותם נמשך ממקום &lt;עד&gt;\nּ עליון יסוד אבא ומשם כח בירור עה\"ד כי בחכמה לא הי' שבה\"כ, גם חותם ותהלתי אחטם.</span>",[["2756","1745","<b>והריחו ביראת ה'</b>: ישעי' יא, ג."],["2757","1746","<b>נרך בידי ונרי בידך</b>: ראה ויק\"ר פל\"א ד. בסמוך בהערה 1749."],["2758","1747","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["2759","1748","<b>נר מצוה ותורה אור</b>: משלי ו, כג."],["2760","1749","<b>אם אתה משמר נרי</b>: ראה דב\"ר ד, ד. מדרש תהלים יז, ח ובהנסמן לשם. בעה\"ט ואתחנן ד, ט."],["2761","1750","<b>כחותם</b>: ע\"כ לשון אוה\"ת ישעי' — ראה הערה 1726."],["2762","1751","<b>וידעת היום</b>: ואתחנן ד, לט."],["2763","1752","<b>וזהו כענין פותח</b>: מכאן עד סיום הפרק לשון אוה\"ת ישעי' שם ע' קפ ס\"ה [ותיבת: כענין, ליתא שם]."],["2764","1753","<b>בינה בן י\"ה</b>: ראה זהר רע\"מ תרומה קנח, א. נשא קכג, סע\"א. אגה\"ת פ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540489\" data-slug=\"torat-chaim\" data-id=\"2300540489\">תו\"ח שמות ח\"א מז, א</a>. וש\"נ."],["2765","1754","<b>תעודה. . עדות</b>: ראה אוה\"ת בראשית כאן ע' 1142. וש\"נ."],["2766","1755","<b>ואתם עדי</b>: ישעי' מג, י."],["2767","1756","<b>שמע ישראל</b>: ואתחנן ו, ד."],["2768","1757","<b>ע' רבתי ד'. . עד</b>: זהר רע\"מ פינחס רלו, ב."],["2769","1758","<b>וחתום</b>: תוקן ע\"פ ב."],["2770","1759","<b>ומתחבר</b>: וכ\"ה בהשמטות ותיקונים בלק\"ת לג\"פ."]]],[2000450280,"<h3>הי' רמ\"א חייב אדם לברך כו' ועתה יש להבין</h3>\nמם) ועתה<sup data-n=\"2771\">1760</sup> יש להבין ענין ברכות התפלה מ\"ש בזהר שהם מתתא לעילא<sup data-n=\"2772\">1761</sup>, ומתחלה<sup data-n=\"2773\">1762</sup> יש לבאר<sup data-n=\"2774\">1763</sup> שגם בברכת הנהנין והמצות יש המשכה והעלאה והמשכה, כמש\"כ בבמאה\"ז<sup data-n=\"2775\">1764</sup> בפי' בא\"י אלקינו הוא המשכה מחו\"ב הנקרא ברוך לחג\"ת המרומזים בתיבות אתה הוי' אלקינו, ואחר<sup data-n=\"2776\">1765</sup> שקבלו המשכה זו עולים לבינה ואז<sup data-n=\"2777\">1766</sup> נק' הבינה מלך העולם, ואזי מקבלים שם חג\"ת עיקר הברכה והשפע הפנימית, כמ\"ש הרמ\"ז ר\"פ עקב<sup data-n=\"2778\">1767</sup> בד\"ה לנחתא אחרנין מלעילא, וסד\"ה ומתמן שירותא, וז\"ל וכבר הזכרתי<sup data-n=\"2779\">1768</sup> למעלה כי ב' מיני שפע הם א' המשפיע כח בתחתון להתעלות אל העליון ואחר שנתעלו שם מקבלים השפע האמיתי למזון העולמות והנה בברוך שם הוא<sup data-n=\"2780\">1769</sup> כוונת קיבול שפע הראשון, ואח\"כ אומרים אתה הוי' אלקינו שהם חסד ת\"ת וגבורה שעולים אל הבינה שהיא מלך העולם ושם מקבלים השפע והוא גמר הברכה וכמשי\"ת לקמן בפרטות עכ\"ל*. ויש לבאר ע\"פ מ\"ש בענין מי ברא",[["2771","1760","<b>ועתה</b>: ברשימת המאמרים שמופיע בריש הבוך 1089 נרשם כאן מאמר (י\"ט מההמשך והוא) ד\"ה: הי' רמ\"א חייב אדם לברך מ\"ב — פ' פינחס (הכולל פרקים מ' — מ\"ב). היינו שבעת אמירת הדרוש היתה פתיחא זו, ולע\"ע אין ידוע אם גם פתיחה זו נרשמה בפ\"ע ע\"י כ\"ק אדמו\"ר מהר\"ש. בבוך 145 ע' מה (ראה אודותיו לעיל בהערה 1615) בכותרת: בס\"ד פ' פינחס שנת תרל\"ח.\nמאמר זה פ\"מ — לשון ביאורי הזהר להצ\"צ כרך א ע' תקעו ואילך (נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450551\" data-slug=\"or-hatorah-hb\" data-id=\"8316450551\">אוה\"ת עקב ע' תקנא</a> ואילך). הקיצור ביאוה\"ז שם ע' תקפ (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450580\" data-slug=\"or-hatorah-hb\" data-id=\"8316450580\">אוה\"ת שם ע' תקנה</a>). פמ\"א — ראה ביאוה\"ז כאן ס\"ע תקעז ואילך (נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450555\" data-slug=\"or-hatorah-hb\" data-id=\"8316450555\">אוה\"ת עקב ע' תקנג</a>). מאמרי אדה\"ז תקס\"ח ח\"ב ע' תשח. פמ\"ב — ראה ביאוה\"ז כאן ס\"ע תקעח ואילך (נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450553\" data-slug=\"or-hatorah-hb\" data-id=\"8316450553\">אוה\"ת עקב ע' תקנג</a> ואילך). סה\"מ תרס\"ט ע' צה.\nהמאמר נכתב בכת\"י הר\"ש סופר, פרט לציוני הפרקים, וכן איזה תיקונים, הקיצורים לפרקים מא. מב. והקטע האחרון ד\"ה ועפ\"ז שנכתבו בגוכתי\"ק. כמצויין להלן במקומו."],["2772","1761","<b>ברכות התפלה. . מתתא לעילא</b>: זהר רע\"מ עקב רעא, א."],["2773","1762","<b>ומתחלה</b>: בכת\"י הר\"ש סופר כתב: והנה מתחלה. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["2774","1763","<b>ומתחלה יש לבאר</b>: מכאן לשון ביאוה\"ז שבהערה 1760."],["2775","1764","<b>כמש\"כ בבמאה\"ז</b>: בביאוה\"ז כאן וכן העתיק הר\"ש סופר: והנה במש\"כ. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["2776","1765","<b>ואחר</b>: בביאוה\"ז כאן וכן העתיק הר\"ש סופר: ואזי אח\"כ. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["2777","1766","<b>ואז</b>: בביאוה\"ז כאן וכן העתיק הר\"ש סופר: ואזי. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["2778","1767","<b>ר\"פ עקב</b>: ניתוסף בין השיטין בגוכתי\"ק."],["2779","1768","<b>הזכרתי</b>: ברמ\"ז: הזכרתיו."],["2780","1769","<b>הוא</b>: ברמ\"ז: היא."]]],[2000450281,"אלה<sup data-n=\"2781\">1774</sup> שבחי' מי זהו בינה, אלה היינו ו\"ק<sup data-n=\"2782\">1775</sup> ונקרא ברא אלה שכמו שבין אצילות לבריאה יש פרסא המפסקת כו' כך מה שת\"ת דבינה נעשה כתר לז\"א<sup data-n=\"2783\">1776</sup> זהו כענין פרסא המפסקת וזהו מבטן מי יצא הקרח וזהו ועל ראשי החיות חיון עילאין חג\"ת<sup data-n=\"2784\">1777</sup> רקיע כעין הקרח כמ\"ש בסידור<sup data-n=\"2785\">1778</sup> בד\"ה הנותן שלג כצמר, ולכן נק' הבינה מלך העולם על חג\"ת, ועמ\"ש בפירוש הפסוק כי אמרתי עולם חסד יבנה<sup data-n=\"2786\">1779</sup>, גם כי כערך המ' הנק' שכינה<sup data-n=\"2787\">1780</sup> לגבי בי\"ע כן הבינה לגבי חג\"ת שהרי לכן נק' ג\"כ שכינה היינו שכינתא עילאה<sup data-n=\"2788\">1781</sup> וזהו ענין נובלות בינה שכינה<sup data-n=\"2789\">1782</sup> ולכן כל עיקר בחי' יוהכ\"פ זהו ענין התגלות אימא עילאה<sup data-n=\"2790\">1783</sup> כו', וע\"כ עלייתם לבינה זהו עילוי גדול ע\"ד עילוי הבריאה באצי' ולכן נצרך לזה תחלה המשכה מלמעלה (וגם יצ\"מ מצר מי<sup data-n=\"2791\">1784</sup> שזהו שיאיר מי בבחי' אלה<sup data-n=\"2792\">1785</sup> כמ\"ש במ\"א) וכמ\"ש בפע\"ח פ\"א משער הברכות שההעלאה הוא ע\"י ג' ידות שם מ\"ב כו', וכן נת' בד\"ה תלתא אינון זמינין מקדש<sup data-n=\"2793\">1786</sup> שהזימון ע\"י סנהדרין עיני העדה שהם מבחי' חכ'<sup data-n=\"2794\">1787</sup> ע\"כ הם שלוחו של אדם העליון חכמה עילאה להזמין ולהעלות חג\"ת לחו\"ב כו', ועוד יובן ענין עלייה זו ע\"ד הנזכר בלק\"ת ס\"פ ואתחנן בד\"ה ואהבת את פ\"א, וז\"ל כי שמע שם ע' עין רבתי הוא מקור המדות דהיינו כשהמדות הם בשכל* שאז הן בבחי' גדלות משא\"כ כשנעשות מדות גמורות אחר שנמשכו ללב להיות התפעלות האהבה",[["2781","1774","<b>בענין מי ברא אלה</b>: ישעי' מ, כו. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרמו (נו\"ש)."],["2782","1775","<b>אלה. . היינו ו\"ק</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">ז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550515\" data-slug=\"torat-chaim\" data-id=\"2300550515\">תו\"ח משפטים ח\"ב רצא, ד</a> ובהערה 268."],["2783","1776","<b>שת\"ת דבינה נעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["2784","1777","<b>חיון עילאין חג\"ת</b>: ראה זהר ויקהל ריא, א. ריג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. בהערה הבאה."],["2785","1778","<b>בסידור</b>: שחרית סד, א."],["2786","1779","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["2787","1780","<b>המ' הנק' שכינה</b>: ראה זהר רע\"מ תצא רפא, ב. פרדס שער טעם האצילות ש\"ב, פ\"ב. שעה\"כ שכ\"ג, פכ\"א מערכת שכינה. לקוטי הש\"ס להאריז\"ל בחלק פי' מארז\"ל ע\"ד הסוד ד\"ה כ\"מ שנמצא השכינה (ב\"ב תשל\"ב ע' כג). <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא</a> פנ\"ב. אגה\"ק סכ\"ה (קלט, א). מאמרי אדה\"א הנחות תקע\"ז ע' כא. וש\"נ."],["2788","1781","<b>בינה. . שכינתא עילאה</b>: ראה פרדס שער עה\"כ שכ\"ג, פכ\"א מערכת שכינה. זהר הרקיע בראשית א, א [שער מאמרי הרשב\"י לזהר שם (טו, א)]. אוה\"ת ר\"ה ע' א'רצח. שם כרך ו ע' ב'תסז. סה\"מ תרכ\"ו ע' רנג הובא לקמן במאמר ד\"ה שיר המעלות ממעמקים על יד הערה 85."],["2789","1782","<b>נובלות בינה שכינה</b>: ראה ע\"ח שער הכללים בשם רז\"ל. מאמרי אדה\"א ויקרא ח\"ב ע' תתסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670191\" data-slug=\"torat-chaim\" data-id=\"2300670191\">תו\"ח לך פב, ג</a> ובהערה 20. שמות ח\"א ג, ב ובהערה 150."],["2790","1783","<b>יוהכ\"פ. . התגלות אימא עילאה</b>: ראה תז\"ח צג, ג. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יום בסופו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380684\" data-slug=\"likkutei-torah\" data-id=\"4001380684\">לקו\"ת מסעי צ, א</a>. סידור שער יוהכ\"פ רמט, ד ואילך. לקמן מאמר ד\"ה ואשא אתכם על יד הערה 75."],["2791","1784","<b>יצ\"מ מצר מי</b>: ראה פע\"ח שער חה\"מ שכ\"א, פ\"ז. סידור האריז\"ל פיסקא עבדים היינו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370260\" data-slug=\"torah-or\" data-id=\"3901370260\">תו\"א וארא נח, ב</a>."],["2792","1785","<b>שיאיר מי בבחי' אלה</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרלב ואילך (נוסח א). ע' תרלה (נוסח ב). ע' תרמו ואילך (נוסח א). ע' תרנ (נוסח ב')."],["2793","1786","<b>בד\"ה תלתא אינון זמינון מקדש</b>: סידור שער המועדים רכ, א ואילך."],["2794","1787","<b>חכ'</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450552\" data-slug=\"or-hatorah-hb\" data-id=\"8316450552\">אוה\"ת עקב כאן ע' תקנב</a>. ועד\"ז בסידור. ובביאוה\"ז כאן ר\"ע תקעז: אדם.\n*1788)כשהמדות הם בשכל: ראה גם לקמן מאמר ד\"ה ישמח משה ובהערה 17."]]],[2000450282,"גמורה ויראה גמורה הן בבחי' קטנות ואין להם<sup data-n=\"2795\">1788</sup> ערך לכשהם בשכל שאז האוי\"ר הם גדולים ביתר שאת כו' ולכן נקרא<sup data-n=\"2796\">1789</sup> המדות בשם זעיר אנפין שנתקטנו ונעשו זעיר לשון מועט עכ\"ל, ומשם יובן ג\"כ שכדי להעלות חג\"ת בבינה זהו ע\"י שהאדם מעלה המדות שלו אהוי\"ר ורחמים &lt;עה&gt;\nּ בהשכל וההתבוננות ע\"ד וראו מי ברא אלה כו'. עוד יובן העלאה זו ע\"ד הנז' בזהר פ' יתרו דפ\"ח<sup data-n=\"2797\">1790</sup> בענין השבת שאז עולין ו\"ק שהם שרש שיתא יומין דחול לגבי יומא שביעאה בינה שהוא יום השבת ומקבלין שם שפע מן הנמשך מטלא דבדולחא מו\"ס ולכן לא ירד מן בשבת<sup data-n=\"2798\">1791</sup> כו' כמ\"ש במ\"א, נמצא עליות ו\"ק לגבי בינה זהו מעלת יום השבת שהוא שבת להוי' בד\"ה לבאר ענין יוהכ\"פ<sup data-n=\"2799\">1792</sup>, ועד\"ז יובן מה שע\"י הברכה הוא עליית חג\"ת לבינה כו'. וענין שנקרא הבינה מלך העולם יובן ע\"ד הנזכר בזח\"ב ר\"פ יתרו דס\"ז ב' דאית מלך לעילא ברזא<sup data-n=\"2800\">1793</sup> דקה\"ק כו', ובמ\"א נת' ע\"ד ההפרש בין מלכות דוד שהי' מרכבה למדת<sup data-n=\"2801\">1797</sup> המל'<sup data-n=\"2802\">1795</sup> ח\"ת<sup data-n=\"2803\">1796</sup>, למלך המשיח<sup data-n=\"2804\">1794</sup>, כמו המלוכה על החכמה כו', וע' בענין אז ישיר<sup data-n=\"2805\">1798</sup> כו' המלך עומד אגוסטוס שהוא מלך אדיר<sup data-n=\"2806\">1800</sup> יושב<sup data-n=\"2807\">1799</sup> כו', גם ע\"ד מ\"ש בד\"ה קול דודי בפי' עד שנגלה עליהם<sup data-n=\"2808\">1802</sup> מלך מלכי המלכים כו' בלק\"ת בשה\"ש<sup data-n=\"2809\">1801</sup>, ובפ' צו בד\"ה מצה זו פ\"ג פי' המלכים נה\"י, ומלכי חג\"ת, ומלך מלכי היינו חב\"ד כו' ע\"ש*.",[["2795","1788","<b>להם</b>: בלקו\"ת: להן."],["2796","1789","<b>נקרא</b>: בלקו\"ת: נק'."],["2797","1790","<b>דפ\"ח</b>: ע\"א."],["2798","1791","<b>לא ירד מן בשבת</b>: בשלח טז, ה. כב ואילך. ראה גם אוה\"ת בשלח ע' תרלו־ ע' תרלח."],["2799","1792","<b>בד\"ה לבאר ענין יוהכ\"פ</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו\"ת יוה\"כ סח, ב</a>."],["2800","1793","<b>דאית. . ברזא</b>: וכ\"ה בביאוה\"ז כאן. בזהר: אית. . דאיהו רזא. וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550044\" data-slug=\"torat-chaim\" data-id=\"2300550044\">תו\"ח יתרו ח\"ב רסט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550045\" data-slug=\"torat-chaim\" data-id=\"2300550045\">רעג, ג</a>."],["2801","1797","<b>המל' ח\"ת</b>: ראה לקוטי הש\"ס להאריז\"ל חולין כ, ב ד\"ה לכי."],["2802","1795","<b>דוד. . למדת המל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["2803","1796","<b>שהי' מרכבה למדת המל' ח\"ת</b>: ניתוסף בגוכתי\"ק בין השיטין."],["2804","1794","<b>ההפרש בין מלכות דוד. . למלך המשיח</b>: ראה ביאוה\"ז — להצ\"צ — יתרו ע' רמד. אוה\"ת שמואל כרך א ע' מט."],["2805","1798","<b>אז ישיר</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפו. תקס\"ה ח\"א ע' רלו. אוה\"ת בשלח ע' תצ. בהערה הבאה."],["2806","1800","<b>אגוסטוס שהוא מלך אדיר</b>: מתנות כהונה לשמו\"ר שם."],["2807","1799","<b>המלך עומד אגוסטוס. . יושב</b>: ראה שמו\"ר רפכ\"ג. שה\"א לג, ב הערה 20. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540475\" data-slug=\"torat-chaim\" data-id=\"2300540475\">תו\"ח בא ח\"א ק, ג</a> הערה 184. בהערה שלפנ\"ז."],["2808","1802","<b>עד שנגלה עליהם</b>: הגדה ש\"פ פיסקא מצה זו."],["2809","1801","<b>בד\"ה קול דודי. . בלק\"ת בשה\"ש</b>: יד, ד."]]],[2000450283,"<span data-k=\"ks\"><b>קיצור.</b> ואחר שחג\"ת קבלו מברוך יסוד או\"א אזי עולים לבינה ונקרא אז הבינה מלך העולם, הנה מי בינה ברא אלה חג\"ת, ויש פרסא מפסיק ביניהם, רקיע כעין הקרח, שע\"ג חיון עילאין, מבטן מי יצא הקרח, ולכן נק' הבינה מלך על חג\"ת הנק' עולם, ולכן עלייתם לבינה זהו ע\"ד ומעין עליית הבריאה באצי', וכענין יצ\"מ ממצר מי, היינו כאשר אין מי מאיר בבחי' אלה, ויצ\"מ בחי' גילוי מי ברא אלה, ואזי נעשה גילוי מלך העולם, אית מלך לעילא רזא דקדה\"ק, וגם יש לפרש מלך העולם להיות עולם חסד יבנה ר\"ל עולם שלא יופסק החסד.</span>\nמא) <b>ועתה</b><sup data-n=\"2810\">1807</sup> יש להבין החילוק שבין ברכת הנהנין שהיא מעילא לתתא ובין ברכת התפלה שהיא מתתא לעילא כו', והענין הוא דהנה החילוק שבין ברכת הנהנין לברכת התפלה הוא דברכת הנהנין הוא ע\"ד מאכל דוקא וכיוצא, אבל בלא מאכל אסור לברך, וברכת התפלה הוא להיפך שאסור לאכול קודם התפלה<sup data-n=\"2811\">1808</sup> וכן שכור אסור להתפלל<sup data-n=\"2812\">1809</sup>, משא\"כ בברכת הנהנין שגם שכור יכול לברך<sup data-n=\"2813\">1810</sup>. ולהבין זה, הנה ידוע שיש ב' בחי' השפעות<sup data-n=\"2814\">1811</sup> הא' היא השפעת חיות לכל העולמות להחיותן ולקיימן והוא הנקרא בחי' מזון שאינו רק לחדש הישינות ולא חדש מעיקרו, והב' הוא השפעה והמשכה חדשה ממש כמ\"ש אור חדש על ציון תאיר<sup data-n=\"2815\">1812</sup>. וביאור הענין דהנה כתי' ובטובו מחדש בכי\"ת מע\"ב<sup data-n=\"2816\">1813</sup> שבכל יום נתחדש החיות, והיינו שגם לאחר שכבר נתהוו מאין ליש בעיקר מציאותם אין להם קיום המציאות בבחי' אור וחיות תמידי בלתי השפעת אור וחיות מלמעלה להחיותן תמיד בבחי' מזון, ובלתי זה לא הי' קיום למציאותן כלל והיו חוזרי' ומתבטלי' לאין כמקדם, וכמ\"ש עיני כל אליך ישברו<sup data-n=\"2817\">1814</sup> ואתה נותן להם את אכלם בעתו כו', ומ\"מ אין זה חידוש גמור אלא הכל על אופן אחד ואינו רק לחדש הישינות &lt;עו&gt;\nּ וכמו למשל בחי' מזון שלמטה שע\"י המאכל שאדם",[["2810","1807","<b>ועתה</b>: לפרק זה ראה ביאוה\"ז כאן ס\"ע תקעז ואילך (נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450553\" data-slug=\"or-hatorah-hb\" data-id=\"8316450553\">אוה\"ת עקב ע' תקנג</a>). מאמרי אדה\"ז תקס\"ח ח\"ב ע' תשח."],["2811","1808","<b>שאסור לאכול קודם התפלה</b>: ברכות י, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380108\" data-slug=\"likkutei-torah\" data-id=\"4001380108\">לקו\"ת צו ח, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380606\" data-slug=\"likkutei-torah\" data-id=\"4001380606\">בלק עב, א</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תשנו. וש\"נ. שמות ח\"א ס\"ע קפב ואילך. וש\"נ. לקמן פמ\"ב."],["2812","1809","<b>שכור אסור להתפלל</b>: ראה ערובין סד, א. סידור שער בהמ\"ז קיד, ג־ קטז, א ואילך. סה\"מ עת\"ר ע' קיא. תש\"ד ע' 96. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061334\" data-slug=\"likkutei-sichot\" data-id=\"1300061334\">לקו\"ש משפטים כרך ו ס\"ע 324</a>."],["2813","1810","<b>בברכת הנהנין שגם שכור יכול לברך</b>: ראה ירושלמי תרומות פ\"א, ה\"ג ובמראה הפנים שם. זהר תרומה קנג, ב הובא בסידור שם. שו\"ע אדה\"ז הל' ברהמ\"ז סו\"ס קפה."],["2814","1811","<b>ב' בחי' השפעות</b>: ראה גם שע\"ת כח, ג ובהערה 26. סה\"מ תרכ\"ט ע' קצה. וש\"נ."],["2815","1812","<b>אור חדש על ציון תאיר</b>: ראה בסמוך בפנים: שאומרים בתפלה — ברכת ק\"ש שחרית (לא-ל ברוך — נוסח אשכנז). ראה סידור שחרית סח, ב. מאמרי אדה\"ז תקס\"ז ע' לט. סהמ\"צ להצ\"צ קעא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680305\" data-slug=\"torat-chaim\" data-id=\"2300680305\">תו\"ח ויחי רמז, ג</a>. מאמרי אדה\"א נ\"ך ע' רלה. סה\"מ תרכ\"ט ע' קט. וש\"נ. פלח הרמון שמות ע' רנז. ויקרא מאמר ד\"ה וספרתם — ענין ספה\"ע. שה\"ש נח, א. לקוטי ביאורים לר' הלל — ווארשא תרכ\"ח — הקדמת דרך חיים נא, רע\"ד."],["2816","1813","<b>כתי' ובטובו מחדש בכי\"ת מע\"ב</b>: ברכת יוצר."],["2817","1814","<b>עיני כל אליך ישברו</b>: תהלים קמה, טו."]]],[2000450284,"אוכל נתחדש חיותו שהמאכל מחבר את הנפש עם הגוף להחיותו ולקיימו, ובלתי המאכל הי' נפרד הנפש מהגוף וא\"כ ע\"י המאכל נתחדש חיותו וקיומו שממשיך אור וחיות של הנפש לתוך הגוף מ\"מ אין זה דבר חדש וכמשארז\"ל בכל יום נעשה האדם ברי' חדשה<sup data-n=\"2818\">1815</sup> שהוא הכל על אופן אחד היום כמו אתמול כו', וכך למעלה אעפ\"י שמתחדש תמיד מאין ליש וכמ\"ש ונהר יוצא מעדן שתמיד יוצא בלי הפסק וכמ\"ש בכ\"ד<sup data-n=\"2819\">1816</sup> שאו\"א שהוא בחי' אין ויש כנודע זיווגייהו תדיר לצורך קיום מציאות העולם, והיינו יחוד חיצוני דאו\"א כמ\"ש בע\"ח מ\"מ אין זה חידוש גמור רק לחדש את הישינות, וזהו ענין ברכת הנהנין והמצות שהוא ברכה והמשכה בתוס' וריבוי מבחי' סוכ\"ע לבחי' ממכ\"ע שהוא רק מן ההעלם אל הגילוי כמ\"ש ברוך הוי' מן העולם ועד העולם מעלמא דאתכסי' לעלמא דאתגלי', אבל לא הולדת אור המשכה חדשה לגמרי, שיהי' הגילוי בבריאה כמו באצי', וזהו שהשיב יעקב ליוסף ידעתי בני ידעתי<sup data-n=\"2820\">1817</sup> גם הוא יהי' לעם וגם הוא יגדל ואולם אחיו הקטן יגדל ממנו ולכן שכל את ידיו<sup data-n=\"2821\">1818</sup>, דלכאו' אינו מובן כי הרי יוסף ביקש שיברך למנשה ביד ימינו ויהי' באמת מנשה הגדול יותר מאחר שבברכת יעקב הדבר תלוי ואם באמת אינו תלוי בברכתו למה הי' צריך לברך כלל, אלא ודאי שענין הברכה הוא רק להמשיך מן ההעלם לגילוי, וזהו איש אשר כברכתו<sup data-n=\"2822\">1819</sup> בירך אותם דהיינו כמו שהוא במקורו בירך אותם למטה להיות בגילוי, אבל אין בכח הברכה לשנות הסדר ולהוליד אור חדש ממש כנ\"ל רק בכח הברכה להמשיך שלא ישאר בהעלם ולהמשיך לגילוי כו', ולכן אמר ידעתי כו', והיינו שבשרש אפרים גדול יותר ממנשה וא\"א לשנות המקור רק להמשיך המקור כמו שהוא מהעלם לגילוי ולכן שכל את ידיו לתת יד ימינו על אפרים שכדי להמשיך מקורו שהוא יותר גדול צריך יד ימין, וזהו עד\"מ הזריעה שאם זורעין חטים לא יצמיח שעורי' או משעורים לא יצמיח חטים אלא ע\"י הזריעה הוא מתברך בתוס' וריבוי, אבל ענין ברכת התפלה הוא להמשיך אור חדש לגמרי וכמו שאומרים בתפלה אור חדש על ציון תאיר, שענין התפלה הוא בקשת רפואת החולים וברכת השנים, שהוא אע\"פ שנפסק בר\"ה עפ\"י הרצון שבסדר השתלשלו' שימות ח\"ו או שלא יהי' ברכה ח\"ו מבקשי' יהי רצון שיהא המשכת רצון מבעל הרצון<sup data-n=\"2823\">1820</sup> שהוא המשכת אור חדש ממש, וכמו התפלה דאבות ששרה היתה עקרה שאפי' בית ולד<sup data-n=\"2824\">1821</sup> לא הי' לה וע\"י תפלתן המשיכו שיהי' לה",[["2818","1815","<b>וכמשארז\"ל בכל יום נעשה האדם ברי' חדשה</b>: ראה ב\"ר רפע\"ח. שו\"ת הרשב\"א ח\"א סקצ\"א (ב\"י לטו\"ח ס\"ד ד\"ה ומשמע). שו\"ע אדה\"ז מהדו\"ק דיני נט\"י ס\"ד, ס\"א. סי\"ג. סי\"ד. רס\"ו. רס\"ז. סידור סדר הנטילה ד\"ה אם עשה בסופו."],["2819","1816","<b>בכ\"ד</b>: בכת\"י הר\"ש סופר: בזהר. ותוקן בגוכתי\"ק כבפנים."],["2820","1817","<b>ידעתי בני ידעתי</b>: ויחי מח, יט. ראה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תשח. סה\"מ תרס\"ט ע' צד ואילך. וראה גם המשך תער\"ב ח\"ב ע' תשלז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101038\" data-slug=\"likkutei-sichot\" data-id=\"1300101038\">לקו\"ש לך כרך י ע' 38</a> ואילך."],["2821","1818","<b>שכל את ידיו</b>: שם מח, יד. ראה גם מאמרי אדה\"א במדבר ח\"א ע' סז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680175\" data-slug=\"torat-chaim\" data-id=\"2300680175\">תו\"ח וישב רו, ד</a>."],["2822","1819","<b>איש אשר כברכתו</b>: ויחי מט, כח."],["2823","1820","<b>מבעל הרצון</b>: ראה גם לקמן (בחלק ההנחות) מאמר ד\"ה ביום ההוא יהי' ובהערה 20."],["2824","1821","<b>ששרה. . בית ולד</b>: נח יא, ל. יבמות סד, ב."]]],[2000450285,"בנים<sup data-n=\"2825\">1822</sup>, שזהו אור חדש לגמרי ולא נמצא לזה משל בגשמיות כ\"א מכח ההולדה שהוא בחי' המשכה חדשה ממש ממוח האב להוליד ולד שלם בצלמו כדמותו בחכ' ושכל כו', ועיין בבה\"ז פ' פנחס<sup data-n=\"2826\">1823</sup> ובלק\"ת פ' אמור<sup data-n=\"2827\">1824</sup> בביאור ע\"פ ונקדשתי כו'.\n&lt;עז&gt;\nּ\n<span data-k=\"ks\"><b>קיצור.</b> שיש ב' בחי' בהשפעה הא' בחי' חידוש הישינות ובחי' או\"ח, ובהמ\"צ והנהנין זהו ע\"ד חידוש הישינות אבל תפלה היא המשכת או\"ח, יהי רצון כו'. </span>\nמב) <b>וזהו</b><sup data-n=\"2828\">1825</sup> שתפלה כנגד תמידין תקנום<sup data-n=\"2829\">1826</sup> וכן כנגד קטרת<sup data-n=\"2830\">1827</sup> כמ\"ש תכון תפלתי קטרת לפניך<sup data-n=\"2831\">1828</sup> שהוא ענין בחי' ריח וכמ\"ש ריח ניחוח להוי'<sup data-n=\"2832\">1829</sup>, והנה ריח הוא דבר שהנשמה נהנית<sup data-n=\"2833\">1830</sup> ממנו ולא הגוף, וענין אכילה הוא לחבר הנשמה עם הגוף דהיינו המשכת אורות בכלים, והנה למעלה ענין האכילה הוא המשכת אורות בכלים, כי כמה גופין תקינת לון חסד דרועא ימינא גבורה דרועא שמאלא, וכדי להמשיך אורות בכלים הוא ע\"י ברכת הנהנין והמצות שע\"י השבח וההילול שברא מאין ליש מעורר התחברות אין ויש שהוא ענין המשכת אורות בכלים וכן ע\"י המצות כי רמ\"ח פקודין הם רמ\"ח אברי' דמלכא שהם בחי' כלים להשראת אוא\"ס כמו האברים שהם כלים לחיות הנפש, וענין ריח הוא דבר שהנשמה נהנית ולא הגוף שהוא המשכה למעלה מבחי' אורות בכלים שהוא בחי' המשכת אור חדש לגמרי, פי' שע\"י הקרבנות והקטרת ממשיכים רצון חדש שיתכפר העון אף שפגם ברצון שבתו\"מ, וזהו ג\"כ ענין התפלה, דהנה כדי להמשיך אור חדש והמשכה חדשה ממש מאוא\"ס ב\"ה שהוא למעלה מעלה מבחי' אורות בכלים צריך להיות העלאת מ\"ן במס\"נ דוקא שהוא בנפש ג\"כ למעלה מבחי' אורות בכלים שהוא למעלה מהשכל, וכן התפלה<sup data-n=\"2834\">1831</sup> כחה גדול יותר לפקוד עקרות אף שלא הי' בהם כח הלידה כנ\"ל<sup data-n=\"2835\">1832</sup>, והיינו לפי שהתפלה באה ממקום גבוה יותר כו', וזהו ענין הקב\"ה מתפלל<sup data-n=\"2836\">1833</sup> כו', וא\"כ צ\"ל מה שברוך דצלותא במ' וברוך דבה\"נ למעלה יותר. אך הענין כמ\"ש במ\"א עד\"מ ב' בנ\"א<sup data-n=\"2837\">1834</sup> א' עומד",[["2825","1822","<b>בנים</b>: יצחק ובת — ראה ב\"ב טז, ב."],["2826","1823","<b>בבה\"ז פ' פנחס</b>: קטו, ג."],["2827","1824","<b>ובלק\"ת פ' אמור</b>: לג, ג ואילך."],["2828","1825","<b>וזהו</b>: לפרק זה ראה ביאוה\"ז כאן ס\"ע תקעח ואילך (נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450553\" data-slug=\"or-hatorah-hb\" data-id=\"8316450553\">אוה\"ת עקב ע' תקנג</a> ואילך). סה\"מ תרס\"ט ע' צה. מאמר ד\"ה ויאמר לו יהונתן ש\"מ מ\"ח תשמ\"ג."],["2829","1826","<b>שתפלה כנגד תמידין תקנום</b>: ראה ברכות כו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>."],["2830","1827","<b>שתפלה כנגד. . קטרת</b>: ראה גם לעיל המשך אם כסף תלוה פי\"א ובהנסמן בהערה 154."],["2831","1828","<b>תכון תפלתי קטרת לפניך</b>: תהלים קמא, ב."],["2832","1829","<b>ריח ניחוח להוי'</b>: ויקרא א, ט."],["2833","1830","<b>ריח. . שהנשמה נהנית</b>: ראה ברכות מג, ב. ראה גם ש\"א ז, ב. יא, ב."],["2834","1831","<b>התפלה. . בסופו</b>: לשון הביאוה\"ז כאן ע' תקעח ואילך."],["2835","1832","<b>כנ\"ל</b>: (ניתוסף בגוכתי\"ק בין השיטין) ספמ\"א."],["2836","1833","<b>הקב\"ה מתפלל</b>: ברכות ז, א."],["2837","1834","<b>עד\"מ ב' בנ\"א</b>: משל זה מובא בדא\"ח בריבוי מקומות ומהם: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450556\" data-slug=\"or-hatorah-hb\" data-id=\"8316450556\">אוה\"ת עקב כאן ע' תקנו</a> ומציין: בד\"ה ואתחנן — ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרסז. מאמרי אדה\"א הנחות תקע\"ז ע' רסח. וש\"נ. שע\"ת ק, ב ובהערה 18. תו\"ח בשלח ח\"א קצו, ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450667\" data-slug=\"or-hatorah-hb\" data-id=\"8316450667\">אוה\"ת</a> <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450553\" data-slug=\"or-hatorah-hb\" data-id=\"8316450553\">עקב כאן ע' תקנג</a>. ביאוה\"ז כאן ע' תקעח. סה\"מ תרל\"ב ח\"א ע' קיח. וש\"נ."]]],[2000450286,"למעלה וא' למטה יש ב' אופנים שיתייחדו הא' שהעליון יורד ע\"ד וירד ה' על הר סיני<sup data-n=\"2838\">1835</sup> הב' שהתחתון עולה כמו שיהי' לע\"ל הזדככו' החומר כמ\"ש בסידור<sup data-n=\"2839\">1836</sup> סד\"ה אד' שפתי תפתח שזהו ענין כורע בברוך<sup data-n=\"2840\">1837</sup> וענין זוקף בשם יעו\"ש, וא\"כ הבחי' הב' גבוה יותר ועד\"ז ההפרש בין ברהמ\"ז שהעליון יורד כו' ובין צלותא שהתחתון עולה וצ\"ל הזדככות החומר ע\"כ אסור לאכול קודם התפלה שיהי' הזדככות החומר כו', ואפשר מה\"ט ג\"כ קודם הלימוד מותר לאכול אף שת\"ת כנגד כולם<sup data-n=\"2841\">1838</sup> כי הוא ג\"כ המשכה מלמעלה למטה ועוד כי נק' לכו לחמו בלחמי אכלו ריעים לעילא<sup data-n=\"2842\">1839</sup>, משא\"כ תפלה היא מגעת בבחי' שלמעלה מחו\"ב הנק' אכלו רעים ועמ\"ש בד\"ה ששת ימים<sup data-n=\"2843\">1840</sup> תאכל מצות דרוש השני פרק שני בענין שש\"פ לעתיד שאין שייך בו אוכל נפש לפי שהוא למעלה מבחי' אכלו רעים חו\"ב כו', וכן התפלה נק' ריח כמו קרבן או אפילו כמו קטרת וזהו לבעל החוטם אני מתחנן<sup data-n=\"2844\">1841</sup> ותהלתי אחטם לך, ולכן קודם התפלה הנשמה באפו שלא נמשך עדיין בחי' אחטם &lt;עח&gt;\nּ כו', וע' מענין<sup data-n=\"2845\">1842</sup> ריח שהוא דבר שהנשמה נהנה ממנו ולא הגוף ואכילה הגוף נהנה, ועמ\"ש בלק\"ת בשה\"ש בביאור ע\"פ באתי לגני פ\"ב בענין אריתי מורי כו' ובפ' נשא סד\"ה זאת חנוכת המזבח, ובד\"ה אלה מסעי דרוש השני בסופו ובהביאור שם בסופו.\n<b>ועפ\"ז</b><sup data-n=\"2846\">1843</sup> יובן ענין חייב אדם לברך מאה ברכות שנא' מה ה' אלקי', ופירש\"י קרי בי' מאה, ופי' התוס' בדברי רש\"י כמו א\"ת מ\"ה אלא מאה (וע' בחא\"ג פי' בא\"א), ולכאו' הלא כתי' מה ואיך אמר קרי בי' מאה. אך הענין הוא דפי' מ\"ה הוא ש' הוי' במילוי אלפין דאיהו אורח אצי' שנת' בפתח אלי'<sup data-n=\"2847\">1844</sup> דאיהו חיים לגופא, ונמצא זהו כמו ברכת המצות והנהנין, ופי' קרי בי' מאה היינו לקרות ולהמשיך בי' האלף ע\"ד קורא בתורה<sup data-n=\"2848\">1845</sup>, או קורא ושונה<sup data-n=\"2849\">1846</sup>, והיינו ע\"י",[["2838","1835","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["2839","1836","<b>כמ\"ש בסידור</b>: תפלת ר\"ה רלח, ד."],["2840","1837","<b>כורע בברוך</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380258\" data-slug=\"likkutei-torah\" data-id=\"4001380258\">לקו\"ת בהר מב, ג</a>. עט\"ר שער ר\"ה פי\"ד. פלח הרמון ויקרא מאמר ד\"ה את שבתותי תקצ\"ח."],["2841","1838","<b>שת\"ת כנגד כולם</b>: פאה פ\"א, מ\"א. ראה מאמרי אדה\"א שמות ח\"ב ע' תקעא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550594\" data-slug=\"torat-chaim\" data-id=\"2300550594\">תו\"ח תצוה ח\"ב שלו, א</a>."],["2842","1839","<b>אכלו ריעים לעילא</b>: שה\"ש ה, א. זהר ויקרא ד, א."],["2843","1840","<b>בד\"ה ששת ימים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380139\" data-slug=\"likkutei-torah\" data-id=\"4001380139\">לקו\"ת צו טו, ד</a>."],["2844","1841","<b>לבעל החוטם אני מתחנן</b>: זהר אד\"ר נשא קל, ב. ראה גם מאמרי אדה\"ז תקס\"ט ס\"ע רלג ואילך. מאמרי אדה\"א דרושי חתונה ח\"א ע' קלב ואילך [ושם ובע' קלז: בגמרא] ובהנסמן בע' קלז. נ\"ך ע' תקפח ואילך. תרכ\"ז ע' נד. וש\"נ."],["2845","1842","<b>וע' מענין</b>: בביאוה\"ז כאן ובכת\"י הר\"ש סופר: והנה. ותוקן בגוכתי\"ק כבפנים."],["2846","1843","<b>ועפ\"ז</b>: מכאן ואילך נרשם בגוכתי\"ק."],["2847","1844","<b>שנת' בפתח אלי'</b>: ראה ת\"ז בהקדמה יז, א."],["2848","1845","<b>קורא בתורה</b>: ברכות י, ב. יג, א (במשנה). ועוד."],["2849","1846","<b>קורא ושונה</b>: ברכות יז, א. ועוד."]]],[2000450287,"התפילה שממשיך יהי רצון מבעהר\"צ להיות רצון חדש שזהו בחי' אלף אלופו ש\"ע כו', ולכן לא נא' בפירוש מאה, כי אם הי' נא' בפירוש ה\"ז בחי' אורות המתיישבים בכלים כו' והמשכה זו היא מלמעלה מאורות בכלים כו', ולכן כתי' מה רק רש\"י פי' קרי הוי ממשיך בי' ע\"י התפילה בחי' האלף להיות מאה, והתו' פי' א\"ת מ\"ה כו' פי' כי יש קרי וכתי' שהם העלם וגילוי<sup data-n=\"2850\">1847</sup> ע\"ד שפי' בכ\"ד מארז\"ל לא כמו שאני נכתב אני נקרא, ולכן אמרו א\"ת מה שלא יהי' הגילוי רק בחי' מה לבד דאיהו אורח אצי' אורות בכלי', אלא מאה המשכת האלף ע\"י התפילה כו'. ומאמר זה א' ר\"מ דוקא כי מאיר הוא ל' מאור<sup data-n=\"2851\">1848</sup> שלמעלה מבחי' אור, וכמארז\"ל מנהיר עיני חכמי'<sup data-n=\"2852\">1849</sup> מקור האור בחי' מאור לכן הי' יכול לגלות מפסוק מה ה' אלקי' שהמכוון שימשיכו בחי' האלף ג\"כ ע\"י התפילה. ואומרו לשון חייב כי יש רשות וחובה, רשות בחי' היותר גבוה וכמשנ\"ת בענין תפילת ערבית רשות<sup data-n=\"2853\">1850</sup>, ובענין שש\"פ מה שביעי רשות<sup data-n=\"2854\">1851</sup>, והמכוון כאן להמשיך מבחי' רשות בבחי' חובה אורות בכלים ע\"י מאה ברכות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> תפילה ריח, אורות בכלי', ולמעלה מבחי' אורות בכלי', ועכ\"ז זהו מתתא לעילא, ע\"ד לע\"ל הזדככות, לבעל החוטם אני מתפלל, וזהו א\"ת מ\"ה אורות בכלים אלא מאה אלף שלמעלה מאורות בכלים, להמשיך בחובה אורות בכלים מבחי' רשות היינו מלמעלה מאורות בכלים.</span>",[["2850","1847","<b>קרי וכתי' שהם העלם וגילוי</b>: ראה אגה\"ק סי\"ט קכח, א (וראה גם שיעורים בס' התניא שם ע' 1506). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211412\" data-slug=\"likkutei-sichot\" data-id=\"1300211412\">לקו\"ש יתרו כרך כא ע' 403</a>."],["2851","1848","<b>מאיר הוא ל' מאור</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' יט. ע' כא. מאמרי אדה\"א במדבר ח\"ב ע' תרסה. אוה\"ת וישב כרך ו' ר\"ע תתרצג."],["2852","1849","<b>מנהיר עיני חכמי'</b>: ערובין יג, ב."],["2853","1850","<b>תפילת ערבית רשות</b>: ברכות כז, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381046\" data-slug=\"likkutei-torah\" data-id=\"4001381046\">לקו\"ת סוכות פ, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381226\" data-slug=\"likkutei-torah\" data-id=\"4001381226\">שה\"ש כד, ב</a>. ביאוה\"ז ח\"ש יג, סע\"ד ואילך. ולהצ\"צ כרך א ע' פה ואילך. סה\"מ תרס\"ח ע' קע. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251155\" data-slug=\"likkutei-sichot\" data-id=\"1300251155\">לקו\"ש ויצא כרך כה ס\"ע 155</a> ואילך."],["2854","1851","<b>מה שביעי רשות</b>: פסחים קכ, א. מכילתא ורש\"י בא יב, טו. שו\"ע אדה\"ז הל' פסח סתע\"ה, סל\"ב. ראה ביאוה\"ז להצ\"צ שם ע' צה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221033\" data-slug=\"likkutei-sichot\" data-id=\"1300221033\">לקו\"ש חה\"פ כרך כב ע' 33</a>. וש\"נ."]]],[2000450288,"<h3>ואשא אתכם על כנפי נשרים כו'</h3>\n<b></b><b>בס\"ד א' דחה\"ש לח, אהת\"פ</b>\n<b></b>אלפי שנאן ג' פי' כו' השמים כסאי כו' דבר מתוך דבר\n[חה\"ש]\n<b>ואשא</b> אתכם על כנפי נשרים<sup data-n=\"2855\">1</sup> ואביא אתכם אלי<sup data-n=\"2856\">2</sup>, ות' לפולחני, וכ\"פ רש\"י. וצ\"ל היכן מצינו שנשא אותם על כנפי נשרים, ומה שפי'<sup data-n=\"2857\">3</sup> כמו על כנפי נשרים, אינו על כנפי נשרים, וגם צ\"ל לאיזה צורך הי' לשאת על כנפי נשרים בשביל לקבל",[["2855","1","<b>ואשא אתכם על כנפי נשרים</b>: מכאן מתחיל סדרה של י\"ב מאמרים (שנאמרו בהפסקות דרושים אחרים), שחלק מהם נאמרו בש. ז. (תרל\"ח), וחלק מהם נאמרו בשנה שלאח\"ז (שנת תרל\"ט), כמו שיצויין לקמן במקומם. במאמרים אלו נתבארו הדרושים דהשמים כסאי וביאוריו שנאמרו בשנת תקס\"ה. דרושים אלו נכתבו בבוך 1162<sup data-n=\"e29\">*</sup> ומשם הועתקו בבוך זה (1089 שהוא הכולל מאמרי תרל\"ח) בכת\"י הר\"ש סופר ומעט מזעיר בגוכתי\"ק כמצויין להלן בריש כל מאמר ובמקומו.\nמאמר זה מבאר פסקא ראשונה מד\"ה השמים כסאי שב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a>. ונדפס גם (מלבד הפתיחה והסיום) בלקו\"ת לג\"פ א, א. אוה\"ת בראשית כרך ו ס\"ע תתרכג ואילך.\nכאמור לעיל הנה כאן (ובלקו\"ת לג\"פ) באו דרושי אדה\"ז (הן ההנחה שבתו\"א והן הנחותיו של כ\"ק אדמו\"ר האמצעי) עם הגהות מכ\"ק אדמו\"ר הצ\"צ ואדמו\"ר מהר\"ש, וכדי להפריד ביניהם, היינו לידע איזה חצאי עיגול הם מאדמו\"ר האמצעי שבאה בתוך הנחותיו, ואיזה היא הגהת הצ\"צ, ואיזה היא הגהת אדמו\"ר מהר\"ש, לזה באים ג' סימנים והם: כל הבא בתוך חצאי עיגול ( ) הם מכ\"ק אדמו\"ר מהר\"ש. הבא בחצאי ריבוע [] הם מכ\"ק אדמו\"ר הצ\"צ. ודברים המובאים בתוך חצאי עיגול שהם בתוך חצאי מרובע [( )] הם מכ\"ק אדמו\"ר האמצעי.\nהמאמר שלפנינו נעתק מבוך 1089 שהוא משנת תרל\"ח כנ\"ל, הוא כת\"י ר\"ש סופר. התאריך שבראשיתו: ”בס\"ד א' דחה\"ש לח, אהת\"פ\" [ אחר התפלה]. לא העתיקה הנ\"ל, ונעתק כאן מגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש שנמצא בבוך 1162.\nדרוש זה שנרשם כמאמר אחד ולא צויין (במפתח של בוך 1089) שהי' עוד פתיחה, הנה מהנחות כ\"ק אדמו\"ר מהורש\"ב [שנדפס לקמן בחלק ההנחות] אנו יודעים שנאמר בשני פעמים, היינו פעם הראשון בפתיחה זו עד להלן ד\"ה וכיצד שעל יד הערה *81 שנאמר ביום א' דחה\"ש. ובפעם השני מד\"ה וכיצד (שעל יד הערה *81) ובפתיחה ואהי' אצלו אמון ונאמר ביום השבת ב' דחה\"ש.\nלקמן (בחלק ההנחות) בהנחה ד\"ה ומקנה רב על יד הערה 136 מציין למאמר דידן בשם: ”משנת\"ל בד\"ה השמים כסאי\". בסה\"מ תרמ\"ג ע' כב מציין למאמר זה: ובד\"ה ואשא אתכם על כנפי נשרים (ל\"ח שהוא השמים כסאי שבתו\"א). ושם ע' לא בשולי הגליון: ואשא, השמים, ומקנה רב (ל\"ח). ונזכר גם לקמן במאמר ד\"ה פי' פתחה בחכ' על יד הערה 9.\nבבוך 701 ע' תקג נמצא המאמר ובתוכו רשום הגהות (ששילב ממה ששמע בשעת מעשה — מוסגרים בשני חצאי לבנה) מא' השומעים בכותרת: בס\"ד חגה\"ש תרל\"ח כפי מה ששמעתי רשמתי בזכרוני הגהות וח\"ו להשען ע\"ז. ונמצא רק ארבעה עמודים. הגהות אלו נעתקו כאן בשולי היריעה בסימון א ב וכו'."],["2856","2","<b>ואשא אתכם. . אלי</b>: יתרו יט, ד. מכאן עד התיבות וצריך להבין שבריש פסקא ג נמצא בבוך 1162 בגוכתי\"ק."],["2857","3","<b>ומה שפי'</b>: ראה ת\"א ומפרשים שם."],["e29","*","<b>בבוך 1162 בתחלתו באה רשימה בגוכתי\"ק של כ\"ק אדמו\"ר מהר\"ש איך לסדר ספר לקו\"ת לג\"פ [ לג' פרשיות, בראשית נח לך לך]. בסוף הספר מונח דרוש השמים כסאי כת\"י הר\"ש סופר [שבראשיתו נרשם בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש</b>: ”שר\"ח מנ\"א תקס\"ה\"], ונעתקה ההנחה שנדפסה בתו\"א בתחילתו, ושני ביאוריו שנדפסו במאמרי אדה\"ז תקס\"ה ח\"ב (שהם הנחותיו של כ\"ק אדמו\"ר האמצעי) ע' תשטו ואילך, ע' תשנט ואילך מש\"פ עקב וניתוספו בה הגהות הצ\"צ. בראשית הבוך באים הגהות־ הפתיחות־ וסיומים של כ\"ק אדמו\"ר מהר\"ש.\nדרושים הנ\"ל בבוך 1162 נכתבו בגוכתי\"ק בנייר גודל שונה (מוקטן) מהדרושים שנכתבו בבוך זה 1089. מתחלה נרשמו ההגהות על המאמר (ואולי נכתבו שני פעמים, היינו שבפעם השני באו הוספות וכו' בעט אחר) ובראשו בצד השמאלי שבע' נרשם: ”בס\"ד בל\"ח ג' מלב\"י\" [ פ' במדבר תרל\"ח יום ג' מ' לספירה למנין בני ישראל] ובשורה שלאח\"ז באמצע העמוד נרשם: ”הגהות לד\"ה השמי' כסאי,\" ואחר ההגהות נרשם הפתיחה והסיום (דהמאמר דתרל\"ח, וכן לאח\"ז על ביאוריו). אמנם בבוך זה 1089 בחלק המאמרים באו הפתיחה־ הסיום־ הגהות כנרשם להלן בריש כל מאמר במקומו. וכנראה שכוונתו הק' היתה שדרושים אלו הנה חלק הפתיחות וכו' יועתקו בבוך זה 1089, ואילו חלק ההגהות ישמשו לשני המקומות היינו הן להדרושים שיבואו בבוך זה דשנת תרל\"ח. וכן בספר לקו\"ת לג\"פ כשיבא זמנו להדפיסו, ולא יצטרך לערכו עוה\"פ."]]],[2000450289,"התורה<sup data-n=\"e7\">א</sup>. הנה כתיב רכב אלקי' רבותים אלפי שנאן (תלים ס\"ח<sup data-n=\"2858\">4</sup> ), ויש בפי' פסוק זה ג' פי', הא' כמארז\"ל בפ\"ק דע\"ז<sup data-n=\"2859\">5</sup> בלילה מאי קעבד קוב\"ה רוכב על כרוב קל שלו ושט בח\"י אלף עלמין שנא' רכב אלקי' רבותים אלפי שנאן, קדרש אלפי אינם מהרבותים א\"כ נשאר ח\"י אלף, ובת\"י<sup data-n=\"2860\">6</sup> פי' ך\"ב אלף והיינו רבותים הם כף אלף, אלפי ב' אלפי', וכ\"מ מהמד\"ר משפטי'<sup data-n=\"2861\">7</sup> ע\"פ הנה אנכי שולח מלאך<sup data-n=\"2862\">8</sup> נותן לו חצי מחנהו, שנא' יפול מצדך אלף ורבבה<sup data-n=\"2863\">9</sup>, א\"כ כל מחנהו הוא ך\"ב אלף<sup data-n=\"e8\">ב</sup>, ורש\"י פי'<sup data-n=\"2864\">10</sup> רבותים פעמים אלפי, והיינו ד' רבוי אלפי' ובמספרינו זהו מ' רבוי (מיליאן), שנאן פי' מלשון שנונין חדים, ע\"ד ושננתם<sup data-n=\"2865\">11</sup>, שארז\"ל קדושין דל\"א שיהי' ד\"ת חדודי' בפיך, וכמו זה שינון וזה שינון גבי אין מפסיקי' לק\"ש<sup data-n=\"2866\">12</sup>. ולהבין כ\"ז צ\"ל מ\"ש אתם ראיתם<sup data-n=\"2867\">13</sup> כי מן השמים דברתי עמכם, לא תעשון אתי<sup data-n=\"2868\">14</sup> אלקי כסף ואלקי זהב<sup data-n=\"e9\">ג</sup>, שלכאו' אין להם קישור וחיבור כלל וכי מ\"ע<sup data-n=\"2869\">15</sup> עשיית אלקי כסף וזהב למה שדיבר עמם מן השמים, שאם הי' אומר לא תעשון כדמות מלאכי' המשמשי' במרום או דמות שמש וירח הי' מתיישב הטעם מה שדיבר עמנו מן השמים כו', והגם כי בדרשות רז\"ל<sup data-n=\"2870\">16</sup> וכן פי' רש\"י לא",[["2858","4","<b>רכב אלקי'. . תלים ס\"ח</b>: פסוק יח."],["2859","5","<b>בפ\"ק דע\"ז</b>: ראה שם ג, ב."],["2860","6","<b>ובת\"י</b>: לתהלים כאן. ועד\"ז הובא לקמן בההנחה. וכ\"ה (ת\"י על תהלים) גם באוה\"ת (יהל אור) תהלים עה\"פ ע' רלו. ועוד. ראה מגילה ג, א. שו\"ת זכר יהוסף — לר' יוסף זכרי' שאוועל — סקכ\"א."],["2861","7","<b>מהמד\"ר משפטי'</b>: ראה שם פל\"ב, ו. ראה גם אוה\"ת (יהל אור) תהלים ע' רלז."],["2862","8","<b>הנה אנכי שולח מלאך</b>: משפטים כג, כ."],["2863","9","<b>יפול מצדך אלף ורבבה</b>: תהלים צב, ז."],["2864","10","<b>ורש\"י פי'</b>: ראה רש\"י לתהלים שם."],["2865","11","<b>ושננתם</b>: ואתחנן ו, ז."],["2866","12","<b>זה שינון. . אין מפסיקי' לק\"ש</b>: ברכות פ\"א, סה\"ב. ירושלמי שבת פ\"א, סה\"ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171358\" data-slug=\"likkutei-sichot\" data-id=\"1300171358\">לקו\"ש אבות כרך יז ע' 358</a> הערה 24."],["2867","13","<b>אתם ראיתם</b>: יתרו כ, יט."],["2868","14","<b>לא תעשון אתי</b>: שם כ, כ."],["2869","15","<b>מ\"ע</b>: מה ענין."],["2870","16","<b>בדרשות רז\"ל</b>: ראה מכילתא כאן. ר\"ה כד, סע\"א ואילך.\n\n<b>א</b>  והמדרש מפרש דקאי על קיבוץ של רעמסס שנתקבצו ביום א'. וצ\"ל שזה הי' הכנה למ\"ת ע\"ד יציאת מצרים שהי' הכנה למ\"ת. ורש\"י מפרש דרך אהבה וחיבה. עכ\"פ לא היו נשרים ממש. והגם שמפרשים וכן התרגום פי' כמו על כנפי נשרים, מ\"מ אין מקרא יוצא מפשוטו. ומשמע שהי' נשרים ממש, והיכן מצינו נשרים ממש.\n\n<b>ב</b>  וצ\"ל לפי פי' הגמ' כיון שחסר ב' אלפים, למה חשיב אותם מתחילה לכתוב ריבותיים, הי' לכתוב רק י\"ח אלף. וגם לפי' הת\"י צ\"ל פי' שנאן.\n\n<b>ג</b>  הא כתיב וירד הוי' על הר סיני. אך ע\"פ פשוט י\"ל, דהנה מן השמים השמיעך את קולו ליסרך ועל הארץ הראך, ודרשו ע\"ז שהי' חיבור שמים וארץ שהרכין שמים על הארץ."]]],[2000450290,"תעשון אתי זהו מלאכים חמה ולבנה, אלקי כסף כ\"א כרובי זהב, אלקי זהב שלא יוסיפו על ב', לא תעשון לכם בבתי כנסיות כ\"א בבית עולמים, מ\"מ פשטא דקרא צ\"ל מוסב דע\"ז.\n<b>אך</b> הענין הוא דרבינו נ\"ע פי' פסוק כי מן השמים דברתי<sup data-n=\"2871\">18</sup>, שהתו' היא בחי' שמים אש<sup data-n=\"2872\">19</sup> ומים<sup data-n=\"2873\">17</sup> וכמשי\"ת, כי השמים כסאי פי' על התו'<sup data-n=\"2874\">20</sup> שהתו' שהיא בחי' שמים היא כסאו כבי'. וי\"ל שהוא מגמ' פסחי' ד\"ן ע\"ב רבא רמי כתי' כי גדול עד שמים חסדך (תלים נ\"ז ) וכתי' כי גדול מעל שמים חסדך (שם ק\"ח<sup data-n=\"2875\">21</sup> ) הא כיצד כאן בעושי' לשמה וכאן בעושי' שלא לשמה (עושי' לשמה מעל שמים ושלא לשמה עד שמים דמצוה מיהו קעביד כדרב יהודה, רש\"י), וא\"כ משמע קצת שהיא בחי' שמים רק שמי שעוסק לשמה מעל שמים, וכ\"מ ממארז\"ל למה נק' שמם שמים<sup data-n=\"2876\">22</sup> ששמי' מעשיהם של בריות, והשומא ודאי היא ע\"פ דרכי התו' כו'. וכ\"מ בזהר כמשי\"ת לקמן בהג\"ה<sup data-n=\"2877\">23</sup> מ\"ש ע\"פ השמים מספרי' כבוד אל<sup data-n=\"e10\">ד</sup>.",[["2871","18","<b>כי מן השמים דברתי</b>: יתרו כ, יט."],["2872","19","<b>שמים אש ומים</b>: בפיסקא הבאה מציין: מהמד\"ר בראשית ספ\"ד. ראה גם חגיגה יב, סע\"א. רש\"י בראשית א, ח. סה\"מ תרל\"ג ח\"ב ר\"ע שסו."],["2873","17","<b>רבינו נ\"ע פי'. . שהתו'. . שמים אש ומים</b>: תו\"א בתחילתו כאן (הובא בסמוך בד\"ה וצריך להבין)."],["2874","20","<b>השמים כסאי. . התו'</b>: ישעי' סו, א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו\"א כאן א, ב</a> (מובא בסמוך ד\"ה וזהו השמים)."],["2875","21","<b>נ\"ז. . ק\"ח</b>: פסוק יא. . פסוק ה."],["2876","22","<b>למה נק' שמם שמים</b>: ראה ב\"ר פ\"ד, ז. יל\"ש בראשית א, א (רמז ג]. סה\"מ תרל\"ג שם."],["2877","23","<b>לקמן בהג\"ה</b>: בד\"ה וזהו השמים בסופה.\n\n<b>ד</b>  [במקום התיבות המובאות בפנים: ”וכ\"מ בזהר. . כבוד אל\" כתב]\nוכ\"מ מהזהר בראשית ד\"ח ע\"א פי' השמים מספרים דא חתן דעאל לחופה, [מכאן מתחיל הערתו] דהנה חמשה דמים טמאים באשה, וצריכה בדיקה ופסיקת טהרה ושבעה נקיים. כן יובן בנש\"י, דה\"א דמים טמאים היינו הרע, ששרשו אינו רע, רק מה' גבורות קדושות, ובירידת ההשתלשלות נעשה רע ודמים טמאים. וצריכים בדיקה היינו בדיקת חמץ, [כאן נחתך הגליון, ואולי חסר ב' או ג' תיבות] היינו גסות, ושאור הוא היצה\"ר כמארז\"ל מי מעכב שאור שבעיסה מעכב. וכמו בפרט ז' נקיים, כן בכלל שבע שבתות. וכשם שבפרט פוסקת טהרה מבע\"י, כך בכלל שבע שבתות תמימות דוקא. ואח\"כ ראוי' ליחוד [הבא לקמן נרשם עה\"ג ולא צויין לאיפה שייך — ”(ופעמים נמצא בזוהר, שהשמים מספרים על טבילה, וקאי ג\"כ על מ\"ת כי טבילה במים. ומים נמשכים מנהר. ומה שמו של נהר יובל שמו. וזהו שער הנו\"ן דבינה כו')\"]. וזהו דא חתן דעאל לחופא דקאי על מ\"ת שנק' ביום חתונתו במשנה סוף תענית.\nוהגם ששם משמע דקאי על לוחות אחרונות, דקאמר שם, לא הי' י\"ט כט\"ו באב וכיוהכ\"פ, שזהו זמן לוחות אחרונות ביוהכ\"פ. מ\"מ על לוחות הראשונות וודאי קאי נמי ביום חתונתו. דאם לא הי' חטא העגל לא הי' השבירה והי' רק לוחות ראשונות. ורק המשנה מדברת כמו עתה שאין לנו רק לוחות אחרונות קאמר התם יוהכ\"פ.\nופי' מפרשי הזהר דעאל לחופה, היינו שז\"א עולה בכתר לקבל כתר דז\"א. וברמ\"ז שם, להמשיך כתר לנוק'. ולכן כתוב בספרים, שבליל שבועות צריך להיות ניעור כל הלילה, משום שבלילה אין שום יחוד למע'. ורק תומ\"י בכלות הלילה ויתחיל יום, אז עיקר היחוד. ולכן צריך להיות ניעור כל הלילה, להכין א\"ע לקבל יחוד זה. ונמצא דהזוהר מפרש השמים מספרים על תורה, ולפי\"ז כ\"ש השמים דברתי והשמים כסאי קאי על תורה, וכפי' רבינו נ\"ע."]]],[2000450291,"<b>וצריך</b> להבין איך<sup data-n=\"2878\">24</sup> שייך עליו ית' לומר כסאי והדום רגלי, שהרי אין לו דמות הגוף<sup data-n=\"2879\">25</sup> ואינו בגדר מקום וכמ\"ש הנה מקום אתי<sup data-n=\"2880\">26</sup> שהוא מקומו של עולם<sup data-n=\"2881\">27</sup> ואין העולם מקומו (כמארז\"ל במד\"ר ר\"פ ויצא תוך פס\"ח ע\"פ ויפגע במקום<sup data-n=\"2882\">28</sup>, וכ\"ה בפ' תשא פמ\"ה קרוב לס\"פ ע\"פ הנה מקום אתי, וכנוסח אין לו דמות הגוף ולא גוף, וידוע הקושיא ע\"ז בשל\"ה<sup data-n=\"2883\">29</sup> דכיון שאין לו דמות הגוף מכש\"כ שאינו גוף, וכמ\"ש מזה בכ\"ד, וע' בד\"ה אור אין סוף למעלה עד אין קץ ס\"ס ד'<sup data-n=\"2884\">30</sup>. אך הענין הוא כי האצי' נק' גופא<sup data-n=\"e11\">ה</sup>, ובי\"ע הם בחי' דמות הגוף זה, וכנודע בענין<sup data-n=\"e12\">ו</sup> כדמותנו<sup data-n=\"2885\">31</sup> <sup data-n=\"e13\">ז</sup>, ולכן לא מיבעי שבי\"ע אינם בערך כו' והיינו שאין לו בחי' דמות הגוף אלא גם אצי'<sup data-n=\"e14\">ח</sup> כלא חשיב, והיינו ולא גוף, וכמא' אלי' בת\"ז דלאו מכא\"מ איהו<sup data-n=\"2886\">32</sup> כלל<sup data-n=\"e15\">ט</sup>). אך להבין הענין כי הנה התורה היא מן השמים<sup data-n=\"2887\">33</sup> כמ\"ש כי",[["2878","24","<b>איך</b>: מכאן מתחיל לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a> פרט למה שבא בסוגרים כו' כנ\"ל הערה 1."],["2879","25","<b>אין לו דמות הגוף</b>: פיוט יגדל. ראה המובא בסמוך בהחצ\"ע. רמב\"ם פיה\"מ סנהדרין פ\"י היסוד הג'. שהיחוה\"א ספ\"ב ובמ\"מ, הגהות והע\"ק מציין ללקו\"ת לג\"פ כאן. מאמר ד\"ה כה. . השמים כסאי ש\"פ נח תשמ\"ה."],["2880","26","<b>הנה מקום אתי</b>: תשא לג, כא."],["2881","27","<b>הוא מקומו של עולם</b>: ראה המובא בסמוך בהחצ\"ע. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a> הערה 2."],["2882","28","<b>במד\"ר. . פס\"ח. . ויפגע במקום</b>: ס\"ט. ויצא כח, יא."],["2883","29","<b>הקושיא ע\"ז בשל\"ה</b>: ראה בית נאמן י, ב. מובא גם בהמשך תער\"ב ח\"א ע' ח. ראה גם אוה\"ת בלק ע' תתקעו [נדפס גם באוה\"ת על ענינים ס\"ע צב]."],["2884","30","<b>בד\"ה אור אין סוף. . ד'</b>: ראה אוה\"ת על ענינים ע' קיג ס\"ג."],["2885","31","<b>ובי\"ע. . כדמותנו</b>: בראשית א, כו. ראה לקמן ד\"ה ומקנה רב על יד הערה 75. אוה\"ת ואתחנן ע' פו."],["2886","32","<b>דלאו מכא\"מ איהו כלל</b>: ת\"ז בהקדמה יז, ב."],["2887","33","<b>התורה היא מן השמים</b>: ראה גם ב\"מ נט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670049\" data-slug=\"torat-chaim\" data-id=\"2300670049\">תו\"ח לך צג, ג</a> ובהערה 15.\n\n<b>ה</b>  כמאמר אליהו גופין תקינת לון.\n\n<b>ו</b>  בצלמינו שקאי [על] עצם הדבר.\n\n<b>ז</b>  שקאי על בי\"ע, ולכן כתיב וביד הנביאים אדמה, שכל השגת נבואתם הי' רק מבי\"ע. ישעי' ראה מרכבה דבריאה, ויחזקאל מרכבה דיצירה, ולכן ארז\"ל ע\"ז, אינו דומה לבן כרך שראה את המלך לבן כפר. זכרי' ראה מרכבה דעשי', מרכבה דסוסים ע' בד\"ה לסוסתי ברכבי פרעה הא' [<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381174\" data-slug=\"likkutei-torah\" data-id=\"4001381174\">לקו\"ת שה\"ש יא, סע\"ב</a>]. לבד במשה כתיב במראה ולא בחידות, כי כל הנביאים נתנבאו בכה, מוסיף עליהם משה נתנבא בזה הדבר, והיינו כמו שמראה באצבע ואומר זה.\n\n<b>ח</b>  שנק' גוף.\n\n<b>ט</b>  לפי פי' זה קאי על עצמו' ומהותו ית' שמושלל מגדר ספי' דאצי'. ועוד יש לפרש שקאי על הארה שמאיר בכלים דאצילות הנק' חיוהי, שגם זה מושלל ואינו בערך הכלים. כי ההפרש בין אצי' לבי\"ע, רק שבאצי' היחוד כגוף עם הנשמה, שאינו יכול לפשוט וללבוש. ובי\"ע הם נקראין לבושין, שהלבוש למשל יכול לפשוט וללבוש אחר. ונמצא שאפילו באצי' מושלל האור ואינו בערך הכלי. ולכן כתיב בתיקונים איהו וגרמוהי מתייחד בהם וע\"י לברוא יש מאין. ונמצא שהמה רק כלים שע\"י נבראו יש מאין. ולא הם בוראים היש. ועד\"מ האומן שעושה כלי ע\"י כלי אומנתו הטובים למלאכה, היתכן שישבחו את הכלים. רק משבחים את האומן. כי הנ\"מ בין כלי אומנות טובים או לא תלוי רק בשיהוי זמן. וכמו\"כ למעלה הספי' המה רק כלים לברוא בהם יש מאין, ולא הם בוראים. והגם כי ע\"ס דאצי' נק' אלקות (פי' געטלעך בל\"א) ולא אלוקה, כי אלקות מאלוקה רחוק מאד. ונמצא לפי\"ז אין לו דמות הגוף היינו בי\"ע, ואפי' גוף כלים דאצילות, אינו בערך לגבי אור שמאיר בהם. וכיון ששללנו אור א\"ס כ\"כ, א\"כ תיגדל הקושיא איך שייך לומר כסאי והדום רגלי."]]],[2000450292,"מן השמים דברתי וגו' דהיינו שהוא בחי' שמים כי שמים אש ומים (וצ\"ל הלא אורייתא מחכ' נפקת<sup data-n=\"2888\">34</sup> כמ\"ש בזהר בכ\"ד, וע' לקמן בד\"ה כי עמך מקו\"ח<sup data-n=\"2889\">35</sup> מפרש שמים בענין התו' שם מים שהכוונה על חכ', וכן לקמן במאמר זה<sup data-n=\"2890\">36</sup> פי' שמים תושב\"כ שם מים, וכאן מפרש על חו\"ג, ואו' שהתורה היא בחי' שמים, אך הענין דהלא נת' בכ\"ד<sup data-n=\"2891\">37</sup> שאם<sup data-n=\"2892\">*38</sup> היות שאורייתא מחכ' נפקת זהו רק שיצאת מהחכ' אבל שרשה ומקורה היא בכתר (ומקור דברים אלו נא' מפי רבינו ז\"ל שבועות תקנ\"ה בד\"ה ויהי קול מעל<sup data-n=\"2893\">38</sup> לרקיע<sup data-n=\"e16\">י</sup>) וא\"כ האיך מפרש על חכ' וחו\"ג, אלא שבכ\"מ שהתו' נמשכת, ומשם נמשכת למטה יותר נק' ע\"ש בחי' ההוא עד\"מ כי מן השמים דברתי עמכם שדבורו של הקב\"ה חשיב מעשה ה\"ה בבחי' שמים<sup data-n=\"e17\">יא</sup>, ובפי' שמים ב' הפי' אמת הם, ופי' זה דאש ומים הוא מהמד\"ר בראשית ספ\"ד נטל אש ומים ופתכן זב\"ז ומהם נעשו שמים<sup data-n=\"2894\">39</sup>, ולכן מפרש כאן כן, ופי' שם מים כ\"ה ברש\"י בחומש ע\"פ לרקיע שמים<sup data-n=\"2895\">40</sup>, שמפרש מ\"ש במד\"ר שא מים<sup data-n=\"2896\">41</sup> שם מים שזהו כמו טעון מים שפירשו המפרשים<sup data-n=\"2897\">42</sup>, ולפ\"ז צ\"ל שירידת התו' הוא דרך התלבשות ולא דרך מעבר, וכ\"מ מפי' האריז\"ל בסידור שפי' ונתן לנו תורת אמת מבריאה<sup data-n=\"2898\">43</sup> וע' בלק\"ת בפ' עקב בביאור ע\"פ ואכלת ושבעת פ\"ג בענין תורתך שלמדתנו תורתך כמ\"ש באצי' שלמדתנו כמו שהיא תורת הבריאה כו', ואם רק דרך מעבר מאי נפ\"מ בין תו'",[["2888","34","<b>אורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2889","35","<b>בד\"ה כי עמך מקו\"ח</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">תו\"א מקץ לד, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370161\" data-slug=\"torah-or\" data-id=\"3901370161\">לה, א</a>."],["2890","36","<b>לקמן במאמר זה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">תו\"א כאן א, ג</a> [לקמן מאמר ד\"ה ומקנה רב] ד\"ה והנה זהו."],["2891","37","<b>נת' בכ\"ד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370050\" data-slug=\"torah-or\" data-id=\"3901370050\">תו\"א לך יא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380336\" data-slug=\"likkutei-torah\" data-id=\"4001380336\">לקו\"ת במדבר ז, א</a>. בסמוך הערה 38."],["2892","*38","<b>שאם</b>: כ\"ה גם בסמוך בפנים. ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["2893","38","<b>בד\"ה ויהי קול מעל לרקיע</b>: ראה מאמרי אדה\"ז על נביאים ע' רלב. לעיל המשך כי תשא פ\"ז הערה 171."],["2894","39","<b>מהמד\"ר. . נטל. . שמים</b>: ראה שם. וראה גם לקמן (בחלק ההנחות) הנחה ד\"ה ב\"ה אלקי ישראל על יד הערה 40. סה\"מ תרל\"ג שבהערה 19. המשך תער\"ב ח\"א ס\"ע תקעד."],["2895","40","<b>שמים. . שם מים. . ברש\"י. . שמים</b>: בראשית א, ח. ראה גם חגיגה יב, א. סה\"מ תרל\"ג שם."],["2896","41","<b>במד\"ר שא מים</b>: ב\"ר פ\"ד, ז."],["2897","42","<b>שפירשו המפרשים</b>: ראה מפרשי רש\"י. וראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 89."],["2898","43","<b>מפי' האריז\"ל בסידור שפי' ונתן לנו תורת אמת מבריאה</b>: במקומו (ובא לציון). ראה גם לעיל המשך חייב אדם לברך פכ\"ה על יד הערה 947 ואילך. וש\"נ.\n\n<b>י</b>  שרקיע הוא כמ\"ש ועל ראשי החיות רקיע כעין הקרח הנורא, ופי' שראשי החיות הוא חיוון עילאין חג\"ת דאצי'. רקיע כעין הקרח בחי' בינה, כמ\"ש מבטן מי יצא הקרח, ומי עולה נו\"ן, נ' שע\"ב. והנורא קאי על א\"א, וקול התורה הוא מעל הרקיע הזה במעלה ומדריגה. כי קול מורכב מג' יסודות, אש רוח מים. מים הוא בחי' חכמה. אש הוא תולדות אור, כי במקום אור נוטלים אש. והגם כי שרגא בטיהרא למאי מהני. אבל עכ\"פ הוא תולדות אור. רוח הוא אויר אור יו\"ד, אוירא דכיא. ובשלג הוא קאי על ג\"ר דע\"ק.\n\n<b>יא</b>  וא\"כ ניחא הכל, כי המשכת התורה מכתר נק' ע\"ש הכתר, וכמ\"ש ויהי קול מעל לרקיע. וכשנמשכת מחכ' למדות נק' אורייתא מחכ' נפקת ע\"ש החכ'. וכשנמשכת למטה נק' שמים אש ומים."]]],[2000450293,"שבאצי' לתורת הבריאה<sup data-n=\"e18\">יב</sup>. אך לפ\"ז צ\"ל מ\"ש לא בשמים היא<sup data-n=\"2899\">44</sup>, דאם* היות שניתנה משמים לארץ עכ\"ז מאחר שזהו דרך התלבשות, א\"כ ישנה גם בשמים, אך זה לק\"מ מאחר שכבר ניתנה לארץ א\"כ אין לאמר ויקחה לנו וישמענו אותה<sup data-n=\"2900\">45</sup> כו'<sup data-n=\"e19\">יג</sup>, אך אמרם ז\"ל אין משגיחין בב\"ק<sup data-n=\"2901\">46</sup> לא בשמים היא כו', לכאו' כפשוטו שלא בשמים היא, אמנם באמת ל\"ק מידי שאין משגיחין בב\"ק להכריע משם פסק ההלכה איך היא אלא העיקר כמו שנמשכה למטה, וכן לא בשמים היא כ\"א נתנה לארץ דוקא<sup data-n=\"e20\">יד</sup> ובכאן צ\"ל פסק ההלכה, ולכן היושבת בגנים<sup data-n=\"2902\">47</sup> ג\"ע התחתון והעליון<sup data-n=\"2903\">48</sup> חבירי' מלאכי'<sup data-n=\"2904\">49</sup> מקשיבים לקולך של לימוד התורה שלמדו בהיותם חי ע\"פ האדמה דוקא כמ\"ש בד\"ה חייב אדם לברך<sup data-n=\"2905\">50</sup> מאה ברכות<sup data-n=\"e21\">טו</sup>, וקצת ראי' לזה ממארז\"ל קמיפלגי במתיבתא דרקיע<sup data-n=\"2906\">51</sup> כו' ואמרו מאן נוכח רבה ב\"נ שאמר אני יחיד כו', והלא קוב\"ה ודאי יחיד ומיוחד כו'<sup data-n=\"e22\">טז</sup>, אלא כי העיקר הוא כמו שנמשכה למטה, וכן ארז\"ל אלה מועדי כו' אתם אפי' מוטעים אתם שוגגי'<sup data-n=\"2907\">52</sup> כו', ובמד\"ר אני (כבי') ואתם נשאל לב\"ד שמ\"ט<sup data-n=\"2908\">53</sup> כו', אבל מ\"מ ישנה גם בשמים כנ\"ל כו'). וכך גבי התו' כתי' מימינו אש דת למו<sup data-n=\"2909\">54</sup> [וע' בפ' ויחי דרי\"ט ב' רמ\"ג א' ובפ' וארא דכ\"ז רע\"א, ל\"ב סע\"א, יתרו פ\"א א', פ\"ב סע\"א, פ\"ד רע\"א, תרומה קס\"ו ב', ויקהל ר\"ו סע\"ב, קרח קע\"ו א', חקת קפ\"ב רע\"א, וע' עוד מענין מן השמים דברתי ביתרו דפ\"ה סע\"א].",[["2899","44","<b>לא בשמים היא</b>: נצבים ל, יב."],["2900","45","<b>ויקחה. . אותה</b>: נצבים שם."],["2901","46","<b>אין משגיחין בב\"ק</b>: ב\"מ נט, ב. ראה גם לעיל המשך חייב אדם לברך פכ\"ט על יד הערה 1146."],["2902","47","<b>היושבת בגנים</b>: שה\"ש ח, יג."],["2903","48","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680032\" data-slug=\"torat-chaim\" data-id=\"2300680032\">בגנים ג</a>\"ע התחתון והעליון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680032\" data-slug=\"torat-chaim\" data-id=\"2300680032\">תו\"ח וישב קצח, א</a> ובהערה 6. בשלח ח\"א רלז, א. וש\"נ."],["2904","49","<b>חבירי' מלאכי'</b>: שהש\"ר שם. זהר ויקרא כב, א."],["2905","50","<b>בד\"ה חייב אדם לברך</b>: נדפס לעיל פכ\"ב על יד הערה 842 ואילך."],["2906","51","<b>קמיפלגי במתיבתא דרקיע</b>: ראה ב\"מ פו, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121064\" data-slug=\"likkutei-sichot\" data-id=\"1300121064\">לקו\"ש תזריע כרך יב ע' 64</a> ואילך ובהנסמן שם."],["2907","52","<b>אלה מועדי. . שוגגי'</b>: אמור כג, ד. ראה ר\"ה כה, א."],["2908","53","<b>ובמד\"ר אני. . שמ\"ט</b>: ראה דב\"ר פ\"ב, יד (ר\"ה ויו\"כ). שמו\"ר פט\"ו, ב (מועדות) ובהנסמן שם. הלשון שבפנים פסיקתא פ' החודש (נג, ב). שוח\"ט פא, ו."],["2909","54","<b>מימינו אש דת למו</b>: ברכה לג, ב.\n\n<b>יב</b>  כי ההפרש בין מעבר להתלבשות, יש ע\"ז כמה משלים. אך בקצרה הוא זה, דאם דרך התלבשות, אז נתלבש ונשתנה לפי המקום שנתלבש. אבל דרך מעבר, עובר עצם הדבר כמו שהוא, רק נשאר רושם, כי אין דבר שבקדושה נעקר לגמרי.\n\n<b>יג</b>  עד\"מ א' שיש לו חפץ ולחבירו יש ג\"כ חפץ זה, א\"כ א\"צ ליקח אצל חבירו.\n\n<b>יד</b>  כמו שאנו מברכין נותן התורה בחי' מתנה, עד\"מ הנותן מתנה לחבירו נותן לו בעין יפה, שיתנהג בה כחפצו ורצונו. גם התורה ניתן לנו לפסוק הלכה עפ\"י דרכי התורה.\n\n<b>טו</b>  אבל לימוד התורה שלמעלה אינם מתאוים לשמוע, רק לימוד של מטה, מפני שזהו ענין בירורים. אשר גם המה שייכים לזה.\n\n<b>טז</b>  ועוד דרבה אמר טהור, משום דכתיב לטהרו פתח הכתוב כו', והלא התורה ישנו ג\"כ למעלה שכתוב בה לטהרו."]]],[2000450294,"<b>והנה</b> כתיב ושמרתם את חוקתי ועשיתם אתם<sup data-n=\"2910\">55</sup> אתם כתיב שהאדם הוא העושה את התורה [עמ\"ש בפ' מקץ<sup data-n=\"2911\">56</sup> סד\"ה רני ושמחי בת הראשון] (ועמ\"ש<sup data-n=\"2912\">57</sup> בשה\"ש בד\"ה צאינה וראינה ס\"ב וס\"ג בפי' שאו ידיכם קדש<sup data-n=\"2913\">58</sup> וברכו את הוי'<sup data-n=\"e23\">יז</sup> וז\"ל סס\"ב וזהו לא זז<sup data-n=\"2914\">59</sup> מחבבה<sup data-n=\"e24\">יח</sup> עד שקראה אמי<sup data-n=\"e25\">יט</sup>, שכמו שהאם מברכת את בנה<sup data-n=\"e26\">כ</sup> עד\"מ כך ישראל מברכין לאביהם שבשמים כבי' שהם הם הממשיכים בחי' קדוש להיות ה' צבאות<sup data-n=\"e27\">כא</sup> מקדש העליון ע\"י נשיאות ידיהם ביחו\"ע ויחו\"ת<sup data-n=\"e28\">כב</sup>, ובפ\"ג ביאר ענין כאלו עשאוני בכלל בפ' ק\"ש והיו הדברים האלה<sup data-n=\"2915\">60</sup> שבד\"ת הכתוב מדבר, ובד\"פ באריכות ענין כאלו עשאוני כו' בבחי' תורה ומצות ולכן קראה אמי) וכך אנו מבקשים בברכת אהבת עולם אהבתנו כו' לשמור ולעשות ולקיים תחלה לעשותה ואח\"כ לקיימה והיינו ע\"י אב הרחמן רחם עלינו ותן בלבינו בינה שמבחי' רחמים עליונים נמשך בינה והתבוננות בלב להיות בה ועל ידה עשיית והתהוות התורה [ועיין בתניא פמ\"ה (שם נת' שדרך ישר לעסוק בתומ\"צ לשמן ע\"י מדה\"ר מדתו של יעקב<sup data-n=\"2916\">61</sup> לעורר ר\"ר על ירידת ניצוץ נפשו ממקורו חיי החיים במשכא דחויא<sup data-n=\"2917\">62</sup> ובפרט ע\"י מחדו\"מ שלו הנה מלך אסור ברהטים ברהיטי מוחא<sup data-n=\"2918\">63</sup>, ושז\"ע גלות השכינה, וזשאה\"כ וישק כו' וישא את קולו ויבך<sup data-n=\"2919\">64</sup> שיעקב מדה\"ר דאצי' מעורר ר\"ר וישא את קולו (ע' בסידור בהקדמה בד\"ה הקל קול יעקב) למקור הרחמים העליונים בחי' אב הרחמים (וע' בלק\"ת בד\"ה שיר המעלות",[["2910","55","<b>ושמרתם את חוקתי ועשיתם אתם</b>: קדושים כ, ח. במאמרי אדה\"ז תקס\"ה ח\"ב כאן ע' תשה מביא: ”עד\"מ מארז\"ל ע\"פ ועשיתם אותם אתם כתיב\". ואולי גם כאן ההמשך ”ועשיתם אתם\" הכוונה לבחוקותי כו, ג (וע\"ז מביא בפנים ”אתם כתיב\") ראה זהר בחוקותי קיג, סע\"א. ויק\"ר פל\"ה, ז. וראה הערה הבאה. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370284\" data-slug=\"torah-or\" data-id=\"3901370284\">תו\"א בשלח סג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380963\" data-slug=\"likkutei-torah\" data-id=\"4001380963\">לקו\"ת ר\"ה סא, סע\"א</a> (ובהנסמן במ\"מ לשם]."],["2911","56","<b>בפ' מקץ</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370168\" data-slug=\"torah-or\" data-id=\"3901370168\">תו\"א לו, ד</a>. וראה גם לקמן מאמר ד\"ה פי' פתחה בחכמה ובהערה 51."],["2912","57","<b>ועמ\"ש</b>: בלקו\"ת."],["2913","58","<b>שאו ידיכם קדש</b>: תהלים קלד, ב."],["2914","59","<b>לא זז מחבבה</b>: פדר\"כ פסקא א."],["2915","60","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550342\" data-slug=\"torat-chaim\" data-id=\"2300550342\">תו\"ח פקודי ח\"ב תמח, ב</a> ובהערה 109."],["2916","61","<b>מדה\"ר. . יעקב</b>: ראה זהר לך פז, ב. מאמרי אדה\"א בראשית ע' קנו. וש\"נ."],["2917","62","<b>במשכא דחויא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, ב</a>). הנסמן במאמרי אדה\"א נ\"ך ע' תלד."],["2918","63","<b>מלך. . ברהיטי מוחא</b>: שה\"ש ו, ז. ת\"ז תקונא שתיאה קמד, ב. ראה גם מאמרי אדה\"א דברים ח\"א ע' לב. וש\"נ. פיה\"מ נח, א. אוה\"ת נצבים ר\"ע א'קצו."],["2919","64","<b>וישק. . ויבך</b>: ויצא כט, יא.\n\n<b>יז</b>  והאיך שייך לברך את הוי'. וכן בתפלה אומרים ברוך אתה הוי'. וכי כלום חסר ח\"ו שצריך לברכו.\n\n<b>יח</b>  עד שקראה בתי (בחי' מקבל), לא זז מחבבה עד שקראה אחותי (שווין בקומתן), לא זז מחבבה.\n\n<b>יט</b>  בחי' משפיע.\n\n<b>כ</b>  נושאת ידי' על הראש ומברכת.\n\n<b>כא</b>  אות הוא בצבא דילי', שזה השם שייך לנבראים שחנה אמרה זה השם.\n\n<b>כב</b>  שהם ב' הפסוקים שבק\"ש שמע וב\"ש, שמע הוא יחו\"ע, הוי' אחד פי' הגם שנתהוו ז' רקיעים וארץ וד' רוחות, שזה מורה הח' והד', מ\"מ המה בטלים ונכללים באלופו ש\"ע באל\"ף. כי כולא קמי' כלא חשיבא. ונמשך מזה התשוקה מי לי בשמים ועמך לא חפצתי, שלא יחפוץ לא בג\"ע העליון שנק' שמים, ולא בגעה\"ת שנק' ארץ, אפי' עמך זה שנאמר כי עמך מקור חיים, ג\"כ לא יחפוץ. וברוך שם הוא יחו\"ת, התבוננות ביטול היש לאין, שם הארה בעלמא. וכבוד הוא ג\"כ הארה. ונמצא שהוא הארה דהארה, ומלכותו הוא ג\"כ הארה, כמו שם המלכות, שהוא רק הארה ולא עצמיות המלך. ונמצא שהוא הארה דהארה דהארה. ומזה נמשך לעולם ועד נצחיות, עלמות אין מספר עולמות אין מספר וע\"י התבוננות זו יוכל לברך את הוי'."]]],[2000450295,"ממעמקי' פ\"ב מענין ב' בחי' רחמים אלו) ומקורם ויבך לעורר משם ר\"ר על כנס\"י ונש\"י להעלותם ולייחדם באוא\"ס ב\"ה בבחי' יחוד עליון בבחי' נשיקין<sup data-n=\"2920\">65</sup> אתדבקות רוחא ברוחא<sup data-n=\"2921\">66</sup> כמ\"ש ישקני מנשיקות פיהו<sup data-n=\"2922\">67</sup> דהיינו התקשרות דבור האדם בדבר ה' זו הלכה<sup data-n=\"2923\">68</sup> כו' ומח' במח' ומעשה במעהמ\"צ, ועסק התו' בדבור ומחשבת העיון הם בחי' נשיקין ממש, (ע' בפירש\"י ע\"פ זה בשה\"ש משמע דקאי על בחי' פנימיות התורה שנק' במד\"ר שמיני פי\"ג<sup data-n=\"2924\">70</sup> תורה חדשה כמשנ\"ת מזה בלק\"ת<sup data-n=\"2925\">69</sup> שה\"ש בביאור ע\"פ כי על כל כבוד חופה פ\"ג ע\"ש, ולכן כתי' לע\"ל בבכי יבואו<sup data-n=\"2926\">71</sup> שזהו ההמשכה מבחי' רחמים גדולים שיהי' לע\"ל, משא\"כ נשיאת הקול על התעוררות זהו עכשיו בהיום לעשותם<sup data-n=\"2927\">72</sup> היום אם בקולו תשמעו<sup data-n=\"2928\">73</sup>, וע' בד\"ה ראה אנכי נותן שלא נדפס<sup data-n=\"2929\">74</sup> ), וגם כמו יוהכ\"פ שהוא התגלות הבינה<sup data-n=\"2930\">75</sup> (שנק' שבת<sup data-n=\"2931\">76</sup> שבתון<sup data-n=\"2932\">*77</sup> ) הרי זהו ע\"י שמעוררי' רחמים וע'<sup data-n=\"2933\">77</sup> בפ' ויקרא דט\"ו ע\"ב, והיינו לפי שבחי' רחמים זהו קו האמצעי בריח התיכון כו'], (ויש לחבר זה עם משנ\"ת בסש\"ב שהרי לוחות האחרונות שנתקיימו ניתנו ביוהכ\"פ<sup data-n=\"2934\">78</sup>, וא\"כ ענינם וסדרן אחד הוא כו', וזהו ואשא אתכם על כנפי נשרים ואביא אתכם אלי לפולחני שבכדי לבוא לפולחני לעשות התורה צ\"ל בחי' התעוררות רחמים שזהו כנפי נשרים שהנשר הוא רחמני<sup data-n=\"2935\">79</sup> כמ\"ש בלק\"ת בד\"ה כנשר יעיר ובביאור והניף<sup data-n=\"2936\">80</sup> ).",[["2920","65","<b>בבחי' נשיקין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370107\" data-slug=\"torah-or\" data-id=\"3901370107\">תו\"א ויצא כג, א</a>."],["2921","66","<b>אתדבקות רוחא ברוחא</b>: ראה זהר משפטים קכד, ב."],["2922","67","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב."],["2923","68","<b>בדבר ה' זו הלכה</b>: שבת קלח, ב. עמוס ח, יב."],["2924","70","<b>פי\"ג</b>: ס\"ג."],["2925","69","<b>בפירש\"י. . תורה חדשה. . בלק\"ת</b>: ראה גם הנסמן במאמרי אדה\"א דברים ח\"ב ע' תקצ. שה\"א ג, ב הערה 10."],["2926","71","<b>בבכי יבואו</b>: ירמי' לא, ח."],["2927","72","<b>בהיום לעשותם</b>: ואתחנן ז, יא."],["2928","73","<b>היום אם בקולו תשמעו</b>: תהלים צה, ז."],["2929","74","<b>בד\"ה ראה. . שלא נדפס</b>: ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' שעט. אוה\"ת פ' ראה ע' תרמא ואילך (סה\"מ תרכ\"ו ע' ריד). ע' תרנח. סה\"מ תרל\"ג ח\"ב ע' תנ וע' תס."],["2930","75","<b>יוהכ\"פ שהוא התגלות הבינה</b>: ראה גם לעיל המשך חייב אדם לברך פ\"מ ובהערה 1783."],["2931","76","<b>יוהכ\"פ. . שבת שבתון</b>: אחרי טז, לב. אמור כג, לב. ראה גם הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540686\" data-slug=\"torat-chaim\" data-id=\"2300540686\">תו\"ח בא ח\"א צד, ב</a>."],["2932","*77","<b>הבינה. . שבת שבתון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380231\" data-slug=\"likkutei-torah\" data-id=\"4001380231\">לקו\"ת אמור לו, ב</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380267\" data-slug=\"likkutei-torah\" data-id=\"4001380267\">בהר מד, רע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270268\" data-slug=\"or-hatorah-hb\" data-id=\"8316270268\">אוה\"ת וישב ח\"ב ע' רסח</a>."],["2933","77","<b>וע'</b>: בזהר."],["2934","78","<b>לוחות האחרונות. . ביוהכ\"פ</b>: ראה תענית ל, ב. רש\"י תשא לד, כט. הוספות לשו\"ע אדה\"ז חאו\"ח רסתקפ\"א (ע' תרפב)."],["2935","79","<b>שהנשר הוא רחמני</b>: ראה (בנוסף להערה הבאה) ירושלמי פאה פ\"א, ה\"א. תנחומא עקב ב. מאמרי אדה\"א דברים ח\"ג ע' תתעט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540482\" data-slug=\"torat-chaim\" data-id=\"2300540482\">תו\"ח בשלח ח\"א ריג, ב</a> ובהערה 213."],["2936","80","<b>בלק\"ת בד\"ה כנשר יעיר ובביאור והניף</b>: האזינו עז, ג. עח, א ואילך. אמור לז, ג."]]],[2000450296,"<h3>[ואהי' אצלו אמון כו' וכיצד תהי' התבוננות זו]</h3>\n<b>וכיצד</b><sup data-n=\"2937\">*81</sup> תהי' התבוננות זו מבואר בק\"ש שמע לשון הבנה<sup data-n=\"2938\">81</sup>, והבנה זו היא בתיבת שמע עצמה כי שמע שם ע' פי' כי עי\"ן רבתי היא בחי' לך ה' הגדולה",[["2937","*81","<b>וכיצד</b>: לערך כאן מתחיל מאמר חדש והפתיחה היא ואהי' אצלו אמון שנאמרה בשבת יום ב' דשבועות. לע\"ע לא מצאנו פתיחה זו מכ\"ק אדמו\"ר מהר\"ש. ראה לקמן (בחלק ההנחות) הנחה ד\"ה זה."],["2938","81","<b>שמע לשון הבנה</b>: ואתחנן ו, ד. ראה זהר אד\"ר נשא קלח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו. וש\"נ. הנחות תקע\"ז ע' קמח. וש\"נ."]]],[2000450297,"והגבו'<sup data-n=\"2939\">83</sup> כו' ז' מדות<sup data-n=\"2940\">82</sup> עליונות שהם בחי' לך דהיינו שהם בטלים אליו ונכללים במקורן שעדיין אינן בבחי' המשכה והתפשטות למטה להיות עולים בשם גדולה וגבורה וכו' ואזי נקרא בשם ע' רבתי (וע' בלק\"ת בד\"ה אם בחקתי תלכו השני פ\"א, ע' רבתי היינו בחי' אור ז' הימים, וע' בביאור מאמר זה שלא נדפס<sup data-n=\"2941\">84</sup> מפרש עוד למעלה יותר, ועמ\"ש במ\"א שזהו ז\"ת דעתיקא<sup data-n=\"2942\">85</sup>, וי\"ל שזהו ע\"י בירור הנה\"ב כמש\"ש מתעלה בבחי' זו, וזהו דכתי' ימי שנותינו בהם<sup data-n=\"2943\">86</sup> שבעים שנה בהם בהמה<sup data-n=\"2944\">87</sup> בירור דנה\"ב סתם זמן שנצרך לבירורו זהו ע' שנה, וע\"י בירור זה דע' שנה מתעלה בז\"ת דע\"י שנק' ג\"כ ע' רבתי, כי שרש האותיות הם בכתר כמ\"ש לקמן בד\"ה מזוזה מימין<sup data-n=\"2945\">88</sup> וע' באגה\"ק סי' ה' בד\"ה ויעש דוד שם, אלא שנק' רבתי כו', וכאן מפרש על ז\"ת דאימא וכמשי\"ת בביאור על מאמר זה<sup data-n=\"2946\">89</sup> ), והמשכה שנמשך ומתפשט למטה הוא רק בחי' שם לבד שהוא הארה בעלמא וכמא' ברוך שם כבוד מלכותו לע\"ו<sup data-n=\"2947\">90</sup> שאין זו אלא מבחי' שם ומדת מלכותו ית' כי מלכותך מלכות כל עולמים<sup data-n=\"2948\">91</sup> כתיב [ועיין בפ' תרומה דק\"ס ע\"ב שמע שם ע' כו' ובמק\"מ שם, ובפ' ויקהל דרי\"ו* סע\"א, ובפ' פנחס דרל\"ו ב' שם דאתכלילן<sup data-n=\"2949\">92</sup> מן ע' רברבא כו' ובפ' ואתחנן דרס\"ג א' ובמק\"מ שם, ועמ\"ש במ\"א ע\"פ בן פורת עלי עין<sup data-n=\"2950\">93</sup>], וזהו ענין בינה להבין דבר מתוך דבר<sup data-n=\"2951\">94</sup>, פי' תוך דבר נק' בחי' ממלא כל עלמין שהיא בחי' שם דהיינו בחי' זיו והארה הנמשך תוך עלמין, וצריך להבין מזה שאינו אלא זיו כנ\"ל שהוא ית' הוא הסובב כל עלמין ולית מחשבה<sup data-n=\"2952\">95</sup> כו' ולאו מכל מדות אלין כלל.\n<b>(ונמצא</b> מפרש דבר סוכ\"ע מתוך דבר ממכ\"ע, ולכאו' פי' הפשוט תוך היינו פנימיות ונמצא כי בערך סוכ\"ע נגד ממכ\"ע ה\"צ<sup data-n=\"2953\">96</sup> לפרש תוך דבר סוכ\"ע דבר ממכ\"ע, וכמ\"ש בפ' אמור בד\"ה ונקדשתי בתוך בנ\"י ססי' ה', פי' תוך היינו נקודה הפנימיות של הלב ובהג\"ה הראה מקום לד\"ה ה' לי בעוזרי בפי' קליטה שיהי' נקלט תוך תוכו ופנימיותו, ולמה פי' כאן תוך דבר ממכ\"ע, אך הענין דכאן נת'",[["2939","83","<b>לך ה' הגדולה והגבו'</b>: דבהי\"א כט, יא."],["2940","82","<b>שמע שם ע'. . רבתי. . ז' מדות</b>: זהר פינחס רלו, ב. ראה הנסמן בסמוך בפנים. מאמרי אדה\"א ויקרא ח\"ב ע' תשמא ואילך. וש\"נ. סה\"מ תרל\"ג ח\"א ע' רב. וש\"נ."],["2941","84","<b>בביאור מאמר זה שלא נדפס</b>: ראה מאמרי אדה\"ז תקס\"ו ע' קפא."],["2942","85","<b>ז\"ת דעתיקא</b>: ראה הגהות הצ\"צ במאמרי אדה\"ז תקס\"ו ע' קע."],["2943","86","<b>ימי שנותינו בהם</b>: תהלים צ, י. ראה גם מאמרי אדה\"ז תקס\"ו כאן ע' קעט. מאמרי אדה\"א דברים ח\"ב ע' תקנה ואילך. לקמן (בחלק ההנחות) בהנחה כאן (ד\"ה ואהי' אצלו אמון) על יד הערה 15."],["2944","87","<b>בהם בהמה</b>: ראה גם המשך מצה זו תר\"ם ע' מב."],["2945","88","<b>שרש האותיות. . לקמן בד\"ה מזוזה מימין</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מב, ב</a>."],["2946","89","<b>בביאור על מאמר זה</b>: לקמן מאמר ד\"ה ישמח משה על יד הערה 15 ואילך."],["2947","90","<b>ברוך שם. . לע\"ו</b>: פסחים נו, א."],["2948","91","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג.\n*92)דרי\"ו: כ\"ה בכ\"מ בכתבי הצ\"צ. ראה גם לקמן מאמר ד\"ה ומקנה רב ובהערה 149."],["2949","92","<b>דאתכלילן</b>: בזהר: דאתכליל."],["2950","93","<b>בן פורת עלי עין</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370465\" data-slug=\"torah-or\" data-id=\"3901370465\">תו\"א ויחי קה, ג</a>."],["2951","94","<b>בינה להבין דבר מתוך דבר</b>: ראה חגיגה יד, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. אגה\"ק סט\"ו (קכד, רע\"א). וראה גם סה\"מ תרכ\"ט ע' רטז. וש\"נ."],["2952","95","<b>ולית מחשבה</b>: ת\"ז בהקדמה יז, ב."],["2953","96","<b>ה\"צ</b>: הי' צריך."]]],[2000450298,"ע\"פ מ\"ש רבינו נ\"ע בד\"ה ביום השמע\"צ, שמאלו תחת לראשי, כי\"ק אאזמו\"ר נ\"ע<sup data-n=\"2954\">98</sup>, שלא נדפס<sup data-n=\"2955\">97</sup>, שתוך דבר הוא התבוננות לבוא לבחי' ביטול היש לאין, ודבר הוא בחי' ביטול אמיתי להבין איך שלמעלה היש ולמטה אין, והיינו בחי' ד\"ת וד\"ע<sup data-n=\"2956\">99</sup>.\n<b>וביאור</b> הענין הוא, דהנה בינה ליבא<sup data-n=\"2957\">100</sup> ובה הלב מבין דבר מתוך דבר, פי' ההתבוננות בגדולת ה' איך שנתהוו יש מאין הוא בא לידי השגה ותפיסא ממש בעין השכל במוח כו', וזהו חיצוניות בינה, אבל פנימיות בינה היינו לב שמבין דבר מתוך דבר דהיינו כשמשיג אמיתיות דש' הוי' כו' (וכמ\"ש רש\"י בפי' החומש ושמי הוי'<sup data-n=\"2958\">101</sup> לא נודעתי לא ניכרתי להם במדת אמיתות שלי) היינו איך שנהפוך הוא באמת דקמי' כלא וכאין חשיב הנברא כו', והבורא הוא היש האמיתי (וע' מענין יש ואין ואין ויש בד\"ה תפול עליהם אימתה<sup data-n=\"2959\">102</sup> ) מצד שהוא מקורא דכולא<sup data-n=\"2960\">103</sup> כו', בינה זו היא בלב דוקא שהרי זהו הבנת ענין חדש מה שלא הבין בראשונה אלא שהבין דבר מתוך דבר עד\"מ אדם שמשיג איזה שכל שמלמדי' אותו לא יהי' באדם המקבל התחדשות מצד שכל עצמו כלל כ\"א שכל שקבל, אך כאשר יבין וישכיל דבר אחר שכל חדש מתוך השכל שקיבל, ה\"ז יחשב שכל חדש שהמציא מדעת עצמו היינו שהולידו מן שכל שקיבל כו' וזה נק' נבון שמבין דבר מתוך דבר כידוע, וכמ\"כ יובן למעלה בב' הפכי' הללו דיש מאין כו' נא' כי אל דעות הוי'<sup data-n=\"2961\">104</sup> שהמה ב' דעות עליונות שהמשיך ה' בסדר ההשתלשלו' שיהי' כך ב' הפכים מיש לאין אצל המשפיע ומאין ליש אצל המקבל ושניהם אמת כו'. והמבין שיבין דבר מתוך דבר היינו שישכיל מהשגת מאין ליש איך שאצל המשפיע הוא בהיפך יש לאין שזהו התחדשות שכל חדש הגם שהולידו מהשגתו הראשונה כו', וזהו דבר מתוך דבר שהם ב' דברים הפכים ועכ\"ז שניהם אמת כו', וע\"כ יוכל להוליד זא\"ז כו', ולכן ביום השמיני דוקא שהוא פנימיות בינה<sup data-n=\"2962\">106</sup> שבלב שמבין דבר מתוך דבר באמיתות דש' הוי', והיינו להיות ואמת הוי' לעולם<sup data-n=\"2963\">107</sup> כו' עצרת תהי' לכם<sup data-n=\"2964\">105</sup>, לכם דוקא, לפי שעיקר התהוות השמחה בהתבוננות כמ\"ש ישמח ישראל בעושיו<sup data-n=\"2965\">108</sup>, זהו כשמבין דבר מתוך דבר באמיתות דש' הוי', איך דקמי' כלא ממש חשיב כו', אז יגל וישמח בה' אמת שאין הדבר כמו שהבין בראשונה מאין ליש כו', ועד\"ז הוא כוונת רבינו ז\"ל כאן ג\"כ בפי' דבר מתוך דבר, שמתוך ממכ\"ע יוכל לבוא לבחי' סוכ\"ע שאין הכוונה שממכ\"ע הוא התוך היינו",[["2954","98","<b>אאזמו\"ר נ\"ע</b>: כ\"ק אדמו\"ר האמצעי."],["2955","97","<b>בד\"ה ביום השמע\"צ. . שלא נדפס</b>: בלקו\"ת. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשפד ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'שמה ואילך. אוה\"ת ויגש כרך ה ע' 1966."],["2956","99","<b>ד\"ע וד\"ת</b>: נסמן בסמוך הערה 104."],["2957","100","<b>בינה ליבא</b>: ת\"ז בהקדמה יז, א."],["2958","101","<b>וכמ\"ש רש\"י. . ושמי הוי'</b>: וארא ו, ג."],["2959","102","<b>יש ואין ואין ויש בד\"ה תפול עליהם אימתה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540402\" data-slug=\"torat-chaim\" data-id=\"2300540402\">תו\"ח בשלח ח\"א קפח, א</a>."],["2960","103","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["2961","104","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a> ובהערה 11."],["2962","106","<b>ביום השמיני. . בינה</b>: ראה גם לקו\"ת שמ\"ע פח, ד. צ, ג (ס\"ג). מאמרי אדה\"א דברים ח\"ד ע' א'שדמ ובהנסמן שם."],["2963","107","<b>ואמת הוי' לעולם</b>: תהלים קיז, ב."],["2964","105","<b>ביום השמיני. . עצרת תהי' לכם</b>: פינחס כט, לה."],["2965","108","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."]]],[2000450299,"בחי' פנימיות, אלא שזהו כמו הקדמה שעי\"ז יבוא לבחי' דבר סוכ\"ע כו', משא\"כ שם פי' תוך דנש\"י לכן פי' כפשוטו תוך פנימיות הלב, וע' בפ' תצא בד\"ה כי תצא השני פ\"ג מענין עצמיות נקודת הלב, ומענין הארת נקודת הלב, ובהג\"ה שם בשם הרמ\"ז).\n<b>ועי\"ז</b> נמשך להיות ואהבת את הוי' אלקיך<sup data-n=\"2966\">109</sup> ממש לדבקה בו ית' בא\"ס ב\"ה ממש כמ\"ש מי לי בשמים<sup data-n=\"2967\">110</sup> ועמך לא חפצתי וגו' שיהי' רק חפצו ורצונו שהוי' אור א\"ס ב\"ה עצמו יהי' אלקיך שורה בקרבך דהיינו שיהא גילוי אור א\"ס ב\"ה עצמו על נפשו [ועמ\"ש בד\"ה רני ושמחי השני<sup data-n=\"2968\">111</sup> גבי וזהו ענין בואו לפניו ברננה כו' דהיינו שלבבו יבין כו' שעי\"ז יבוא כו'], והיינו ע\"י בכל לבבך שהוא כמ\"ש אם ישים אליו לבו<sup data-n=\"2969\">112</sup> רוחו ונשמתו אליו יאסוף כי רוח אייתי רוח<sup data-n=\"2970\">113</sup> ואמשיך רוח שע\"י רוח האדם העולה למעלה [עמ\"ש בזה בד\"ה האזינו<sup data-n=\"2971\">114</sup> בפי' והרוח תשוב כו' ע\"ש] שישים אליו דהיינו שלבבו יכסוף לדבקה בו ית' ולהמשיך בבחי'<sup data-n=\"2972\">115</sup> גילוי אלהותו ית' על נפשו ותוך נפשו אזי רוחו ונשמתו מבחי' סוכ\"ע אליו יאסוף להיות מתאסף השראתו אצלו בקרב איש ולב עמוק [ועיין ר\"פ צו ת\"ח האי עולה כו' ואתנהיר כולא מרזא דקדש הקדשים כו' ושם עמוד ב' עד אין סוף כו', וע\"ש בפי' הרמ\"ז שכדי להיות עלייה זו צ\"ל כח מלמעלה וזהו ענין שמע שם ע' כו' ע\"ש. וכמ\"כ תפלה במקום קרבנות<sup data-n=\"2973\">116</sup> וכמ\"ש בד\"ה לבבתיני<sup data-n=\"2974\">117</sup> הנה ע\"י שמע שם ע' נמשך להיות העלאה דבכל לבבך אם ישים אליו לבו כו'] ומזה נמשך להיות והיו הדברים האלה אשר אנכי מי שאנכי<sup data-n=\"2975\">118</sup> מצוך כו' שעי\"ז נמשך גילוי אלהותו והתהוות התורה [וכמ\"ש סד\"ה רני ושמחי הראשון<sup data-n=\"2976\">119</sup> גבי ויקם עדות ביעקב כו' ובחי' זו נק' אמי כו' ע\"ש] בבחי' שמים אש ומים, כי הנה התורה קדמה אלפים שנה לעולם<sup data-n=\"2977\">120</sup> פי' עולם נק' בחי' אש ומים [עמ\"ש מענין עולם בד\"ה וארא<sup data-n=\"2978\">121</sup> גבי וששה קצוות רוחניים כו' ובד\"ה ויאמר משה<sup data-n=\"2979\">122</sup> אכלוהו היום גבי שעוסקי' בבנינו של עולם ועיין בפע\"ח שער הברכות<sup data-n=\"2980\">123</sup> בפי' מלך העולם] והתורה גבהה מעלתה מאד בבחי' אלפים שנה שהם למעלה מבחי' עולם [ועמ\"ש סד\"ה ויהי מקץ מענין אלפים שנה כו' חכים ולא בחכ' ידיעא מבין ולא בבינה",[["2966","109","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["2967","110","<b>מי לי בשמים</b>: תהלים עג, כה."],["2968","111","<b>בד\"ה רני ושמחי השני</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370170\" data-slug=\"torah-or\" data-id=\"3901370170\">תו\"א מקץ לז, ב</a>."],["2969","112","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["2970","113","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, רע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["2971","114","<b>בד\"ה האזינו</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381011\" data-slug=\"likkutei-torah\" data-id=\"4001381011\">לקו\"ת האזינו עב, א</a>."],["2972","115","<b>בבחי'</b>: באוה\"ת כאן ע' תתרכה: בח' (!). בתו\"א (ובבוך 1162 כת\"י הר\"ש סופר ראה לעיל הערה 1): בחי'."],["2973","116","<b>תפלה במקום קרבנות</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["2974","117","<b>בד\"ה לבבתיני</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381245\" data-slug=\"likkutei-torah\" data-id=\"4001381245\">לקו\"ת שה\"ש כט, א</a>."],["2975","118","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["2976","119","<b>סד\"ה רני ושמחי הראשון</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370168\" data-slug=\"torah-or\" data-id=\"3901370168\">תו\"א מקץ לו, ד</a>."],["2977","120","<b>התורה קדמה אלפים שנה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["2978","121","<b>בד\"ה וארא </b>: תו\"א שם נה, רע\"ג."],["2979","122","<b>ובד\"ה ויאמר משה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א בשלה סה, ב</a>."],["2980","123","<b>בפע\"ח שער הברכות</b>: פ\"א. פ\"ב."]]],[2000450300,"ידיעא כו' ובד\"ה השני ויהי מקץ נת' שזהו ענין נפלאותיך ומחשבותיך וסד\"ה ת\"ר<sup data-n=\"2981\">124</sup> מצות נר חנוכה בש\"א כו' גבי כי לאלפים היינו אאלפך חכמה כו' ועמ\"ש סד\"ה מראיהם ומעשיהם<sup data-n=\"2982\">125</sup> ועיין בפ' בלק דקצ\"ג ב' ע\"פ כי עשית פלא כו' אלף כו', וע' בלק\"ת<sup data-n=\"2983\">126</sup> תלים ס\"ח בפי' אלפים שאנן<sup data-n=\"2984\">127</sup>, וי\"ל שזהו ענין אלפים שנה דתורה שקדמה לעולם כו'] וכדי שתמשך לבחי' עולם דהיינו להיות מימינו אש כו' שהוא רמ\"ח מ\"ע שמימין ושס\"ה מל\"ת<sup data-n=\"2985\">128</sup> משמאל כו', הנה המשכה זו היא ע\"י אתעדל\"ת בואהבת בכל לבבך רוח אייתי רוח ואמשיך רוח [ועמ\"ש בד\"ה וכל בניך<sup data-n=\"2986\">129</sup> בפי' אל תקרי בניך אלא בוניך כו', ומזה יובן ענין על שלא ברכו בתורה תחלה<sup data-n=\"2987\">130</sup> שהמשכה זו נק' ברכו בתורה וכענין בריכה הנז' בדרוש ברכת המזון<sup data-n=\"2988\">131</sup>]. ועי\"ז ודברת בם<sup data-n=\"2989\">132</sup> ודברת לשון הנהגה והמשכה<sup data-n=\"2990\">133</sup> דהיינו להיות המשכת אור א\"ס ב\"ה בתורה [ועמ\"ש ע\"פ הזהר וישלח דקע\"ה ב' ע\"פ כי ישרים דרכי<sup data-n=\"2991\">134</sup> כו' שזהו ענין המשכת הקו מאור א\"ס שיומשך ויתלבש בהתורה שהיא בו\"ק הנק' אש ומים כנ\"ל, ועמ\"ש בד\"ה יונתי<sup data-n=\"2992\">135</sup> כו']. וזהו ענין וידבר ה' אל משה<sup data-n=\"2993\">136</sup> שהמשכת הוי' להיות התורה צ\"ל המשכה תחלה לבחי' משה שהוא מבחי' כי מן המים משיתיהו<sup data-n=\"2994\">137</sup> [כי מים יורדים מגבוה לנמוך<sup data-n=\"2995\">138</sup>, ועמ\"ש מענין משה בד\"ה אלה מסעי<sup data-n=\"2996\">139</sup> גבי כי דלה דלה לנו כו'].\n<b>וזהו</b> השמים כסאי שהשמים היא התורה הרי היא כסא עד\"מ שנעשה לשבת וישיבה זו היא השפלה לגבי עמידה שכשהאדם עומד הנה הוא בעל קומה וראשו ומוחו גבוהים מעל הארץ וע\"י ישיבה נשפל קומתו, כך התורה נעשה כסא לאור א\"ס ב\"ה לבחי' ראשו שהיא בחי' רצונו וחכמתו ובינתו דאנת חכים<sup data-n=\"2997\">140</sup> ולא בחכ' ידיעא ומבין ולא בבינה ידיעא ובתורה יורדים ומשתלשלי' חכמתו ובינתו בדברים גשמיים כתפילין וציצית וצדקה ותרומות ומעשרות וקרבנות כו' [ועמ\"ש מענין זה בד\"ה ויושט המלך<sup data-n=\"2998\">141</sup> ובד\"ה קול דודי<sup data-n=\"2999\">142</sup> גבי דומה דודי לצבי ועמ\"ש בד\"ה",[["2981","124","<b>סד\"ה ויהי מקץ. . ויהי מקץ. . וסד\"ה ת\"ר</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370146\" data-slug=\"torah-or\" data-id=\"3901370146\">תו\"א מקץ לא, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370148\" data-slug=\"torah-or\" data-id=\"3901370148\">שם לא, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">שם לד, ד</a>."],["2982","125","<b>סד\"ה מראיהם ומעשיהם</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א יתרו סט, ג</a>."],["2983","126","<b>בלק\"ת</b>: מהאריז\"ל."],["2984","127","<b>שאנן</b>: כ\"ה גם באוה\"ת כאן ע' 2050. ואוצ\"ל: שאינן. וראה לקמן ד\"ה ומעתה יובן."],["2985","128","<b>רמ\"ח מ\"ע. . ושס\"ה מל\"ת</b>: מכות כג, סע\"ב."],["2986","129","<b>בד\"ה וכל בניך</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת ראה כט, א</a>."],["2987","130","<b>שלא ברכו בתורה תחלה</b>: ב\"מ פה, ב. נדרים פא, א. ראה גם דרך חיים פא, א. סה\"מ תרכ\"ט ע' רצ. וש\"נ. תרל\"ג ח\"ב ע' תלו ואילך וש\"נ."],["2988","131","<b>בדרוש ברכת המזון</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380781\" data-slug=\"likkutei-torah\" data-id=\"4001380781\">לקו\"ת עקב טז, סע\"ד</a>"],["2989","132","<b>ודברת בם</b>: ואתחנן ו, ז."],["2990","133","<b>ודברת לשון הנהגה והמשכה</b>: ראה גם (בנוסף לתו\"א כאן). מאמרי אדה\"א בראשית ע' תיט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550564\" data-slug=\"torat-chaim\" data-id=\"2300550564\">תו\"ח פקודי ח\"ב תס, ב</a>. וש\"נ."],["2991","134","<b>ע\"פ הזהר. . כי ישרים דרכי</b>: ביאוה\"ז וישלח יט, ב ואילך."],["2992","135","<b>בד\"ה יונתי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a> ואילך."],["2993","136","<b>וידבר ה' אל משה</b>: וארא ו, י."],["2994","137","<b>כי מן המים משיתיהו</b>: שמות ב, י."],["2995","138","<b>מים יורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["2996","139","<b>בד\"ה אלה מסעי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380679\" data-slug=\"likkutei-torah\" data-id=\"4001380679\">לקו\"ת מסעי פח, ד</a>."],["2997","140","<b>דאנת חכים</b>: ת\"ז בהקדמה יז, ב."],["2998","141","<b>בד\"ה ויושט המלך</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370423\" data-slug=\"torah-or\" data-id=\"3901370423\">תו\"א מג\"א צד, סע\"ב</a> ואילך."],["2999","142","<b>ובד\"ה קול דודי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381192\" data-slug=\"likkutei-torah\" data-id=\"4001381192\">לקו\"ת שה\"ש טו, ד</a>."]]],[2000450301,"כי עמך מקו\"ח<sup data-n=\"3000\">143</sup> גבי המשפילי לראות בשמים כו', ועיין בפ' יתרו דף פ\"ה סע\"ב ע\"פ אענה את השמים<sup data-n=\"3001\">144</sup>, שמים ממש דכתי' השמים כסאי כו', ובפ' פקודי דרמ\"א א' השמים כסאי דא רקיעא דיעקב שריא בי' וע\"ש במק\"מ והיינו כמ\"ש ויקם עדות ביעקב<sup data-n=\"3002\">145</sup> ועמ\"ש סד\"ה מי מנה עפר יעקב<sup data-n=\"3003\">146</sup>, ועיין ברע\"מ פ' שופטים דער\"ה א' ע\"פ העדותי בכם היום<sup data-n=\"3004\">147</sup> את השמים, ובפ' ויקרא די\"ו* א' ע\"פ כי גדול מעל שמים חסדך<sup data-n=\"3005\">148</sup>, וס\"פ ויקרא דך\"ה סע\"ב ע\"פ הרעיפו שמים ממעל<sup data-n=\"3006\">149</sup>, ועמ\"ש בד\"ה האזינו השמים<sup data-n=\"3007\">150</sup> ועיין בפ' תרומה קל\"ו ב' ע\"פ השמים מספרים<sup data-n=\"3008\">151</sup> ובמק\"מ שם והוא ענין אחד עם מש\"כ בפי' השמים כסאי, ובפ' בראשית דף ח' א' פי' פסוק השמים מספרים על חג השבועות שבו מתן תורה וע\"ש בפי' הרמ\"ז וא\"כ כ\"ש שעולה בקנה א' עם מש\"כ, ועמ\"ש בסידור<sup data-n=\"3009\">152</sup> ע\"פ השמים מספרים].\n<b>ועפ\"ז</b><sup data-n=\"3010\">153</sup> יובן מ\"ש כי מן השמים כו' לא תעשון אתי, פי' אם<sup data-n=\"3011\">154</sup> היות כי ראיתם שמן השמים דברתי עמכם א\"כ התו' היא בחי' שמים, ואורייתא וקוב\"ה כולא חד<sup data-n=\"3012\">155</sup> כו', עכ\"ז לא תעשון אתי כמו אותי<sup data-n=\"3013\">156</sup> אלקי זהב ואלקי כסף, פי' כסף וזהב הם אהוי\"ר<sup data-n=\"3014\">157</sup>, ואם כי העבודה צ\"ל ע\"י אהוי\"ר ורמ\"ח מ\"ע שרשן היא בחי' אהבה ויראה שרש שס\"ה ל\"ת<sup data-n=\"3015\">158</sup> כו' כמ\"ש במ\"א, הנה האהוי\"ר הם רק גדפין<sup data-n=\"3016\">159</sup> לבד שכמו ע\"י הכנפי' עוף הפורח בא למקום אשר יחפוץ כן אהוי\"ר הם גדפין שבהם וע\"י תבוא הנשמה לאשתאבא בגופא דמלכא<sup data-n=\"3017\">160</sup> שזהו עיקר העלי' ע\"י ירידתה בגוף ונה\"ב, וכמ\"ש ואנשי קדש תהיון לי<sup data-n=\"3018\">161</sup> קדש שלמעלה גם מבחי' קדוש כו', ולכן לא תעשון אותי כבי' זהב וכסף אהוי\"ר שזהו עדיין יש מי שאוהב<sup data-n=\"3019\">162</sup> כ\"א ואנשי קדש, והגם כי",[["3000","143","<b>בד\"ה כי עמך מקו\"ח</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370160\" data-slug=\"torah-or\" data-id=\"3901370160\">תו\"א מקץ לד, ד</a>."],["3001","144","<b>אענה את השמים</b>: הושע ב, כג."],["3002","145","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["3003","146","<b>סד\"ה מי מנה עפר יעקב</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380599\" data-slug=\"likkutei-torah\" data-id=\"4001380599\">לקו\"ת בלק ע, ב</a>."],["3004","147","<b>העדותי בכם היום</b>: ואתחנן ד, כו. נצבים ל, יט."],["3005","148","<b>כי גדול מעל שמים חסדיך</b>: נסמן לעיל הערה 21."],["3006","149","<b>הרעיפו שמים ממעל</b>: ישעי' מה, ח."],["3007","150","<b>בד\"ה האזינו השמים</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, א</a>."],["3008","151","<b>השמים מספרים</b>: תהלים יט, ב."],["3009","152","<b>בסידור</b>: ראה שם שחרית לשבת קעח, ג ואילך."],["3010","153","<b>ועפ\"ז</b>: מכאן עד סיום המאמר נכתב בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש."],["3011","154","<b>אם</b>: כ\"ה גם בסמוך בפנים. ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["3012","155","<b>ואורייתא וקוב\"ה כולא חד</b>: מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא (פ\"ד</a> ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["3013","156","<b>לא תעשון אתי כמו אותי</b>: ר\"ה כד, ב."],["3014","157","<b>כסף וזהב הם אהוי\"ר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370126\" data-slug=\"torah-or\" data-id=\"3901370126\">תו\"א וישב כו, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550788\" data-slug=\"torat-chaim\" data-id=\"2300550788\">תו\"ח ויקהל ח\"ב תיד, א</a> ובהערה 852."],["3015","158","<b>ורמ\"ח מ\"ע. . אהבה ויראה שרש שס\"ה ל\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא</a> פ\"ד ובמ\"מ, הגהות והע\"ק לשם. של\"ה נא, ב. מאמרי אדה\"א קונטרסים ע' פז, וש\"נ."],["3016","159","<b>האהוי\"ר. . גדפין</b>: ראה תניא פ\"מ. פמ\"א ובמ\"מ הגהות והע\"ק שם ע' רסט. מאמרי אדה\"א בראשית ע' עה. וש\"נ."],["3017","160","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670390\" data-slug=\"torat-chaim\" data-id=\"2300670390\">תו\"ח בראשית מ, ב</a> הערה 25."],["3018","161","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. יו\"כ סט, ב."],["3019","162","<b>יש מי שאוהב</b>: ראה גם לעיל המשך חייב אדם לברך פי\"ט ובהערה 714."]]],[2000450302,"קדושתי למעלה מקדושתכם<sup data-n=\"3020\">163</sup> עכ\"ז ע\"י תומ\"צ יכול לבא לדבקה בו אוא\"ס חיי החיים<sup data-n=\"3021\">164</sup> ע\"ד רשב\"י ע\"י שהי' תורתו אומנתו<sup data-n=\"3022\">165</sup> הי' קשור ודבוק בחד קטירא אתקטרנא בי' אחידא<sup data-n=\"3023\">166</sup> כו' וזהו תכלית הכוונה רק שא\"א כ\"א ע\"י קדימת אהוי\"ר כו'.\n<b>ומעתה</b> יובן ג\"כ ענין רכב אלקים רבותים, דהנה כדי להיות מ\"ת בא בהשתלשלו' המדרגות עד שתוכל התו' להתלבש בגשמי', וזהו שדרשו בגמ' ח\"י אלפי', כי רבותים זהו ב\"פ עשר והיינו ע\"ס דאו\"י וע\"ס דאו\"ח כמ\"ש בלק\"ת מהאריז\"ל בתלים ע\"פ זה, רק ב' אלפים שאנן היינו שאינן שהם בבחי' אין, והיינו בחי' כתר דאו\"י וכתר דאו\"ח (ובלק\"ת<sup data-n=\"3024\">167</sup> מהאריז\"ל שם אמר כתר וחכ' לרוב העלמם אינם נגלי', א\"כ צ\"ל שלא ישאר רק ט\"ז, אך י\"ל שלא חשיב רק באו\"י לבד, ובאו\"ח מל' היא הכתר, או י\"ל שכאשר הכתר נמנה אין הדעת נמנה<sup data-n=\"3025\">168</sup>, וכשהדעת נמנה אזי אין הכתר נמנה ואז החכ' היא בחי' אין וכמ\"ש רבינו ז\"ל בכ\"ד שהחכ' נק' אין כמ\"ש והחכ' מאין תמצא<sup data-n=\"3026\">169</sup>, ונת' בכ\"מ שזהו מחמת דכתי' תמצא, ע' בד\"ה מים רבים<sup data-n=\"3027\">170</sup> ובד\"ה וככה<sup data-n=\"3028\">171</sup>, ובד\"ה חייב אדם לברך<sup data-n=\"3029\">172</sup> מאה ברכות, וא\"כ נשאר ח\"י אלף, כי ב' אלפים אינם, וי\"ל שזהו אלפי' שנה שקדמה תו' כנ\"ל.\n<b>והת\"י</b> מפרש ך\"ב על ע\"ס דאו\"י ואו\"ח, ומה שהכתר וחכ' לרוב מעלתם הם נעלמי' זהו אם הי' בדרך העלאה מלמטלמ\"ע, אבל מלמעלה למטה אין מונע כמ\"ש בד\"ה ואתחנן<sup data-n=\"3030\">173</sup> ובחינוך<sup data-n=\"3031\">174</sup>, וזהו דכתי' מי יעלה בהר ה'<sup data-n=\"3032\">175</sup> נקי כפים<sup data-n=\"3033\">176</sup> כו', אבל מלמעלמ\"ט וירד ה'<sup data-n=\"3034\">177</sup> הגם כי לא נזדכך העולם עדיין מטעם הנ\"ל, וכן הטעם ברבותים שהע\"ס דאו\"י הם מלמעלמ\"ט, והאו\"ח המל' היא הכתר, והב' אלפים הם בחי' אלפי' שנה שקדמו להורות מקום מעלת התו' הגם כי מן השמים אש ומים דברתי שנתגלו עשרת הדברות ע\"כ בעצם גם היא מעל לרקיע כו', ולכן לא תעשון",[["3020","163","<b>קדושתי למעלה מקדושתכם</b>: ויק\"ר פכ\"ד, ט."],["3021","164","<b>חיי החיים</b>: יומא עא, א."],["3022","165","<b>רשב\"י. . תורתו אומנתו</b>: שבת יא, א."],["3023","166","<b>בחד קטירא. . בי' אחידא</b>: ראה זהר אד\"ז האזינו רפח, א. רצב, א. לעיל המשך אם כסף תלוה פי\"א ובהערה 205."],["3024","167","<b>(ובלק\"ת</b>: אולי סיום החצע\"ג הוא בסיום פסקא זו."],["3025","168","<b>הכתר נמנה אין הדעת נמנה</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, פ\"ה. פ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540373\" data-slug=\"torat-chaim\" data-id=\"2300540373\">תו\"ח בא ח\"א פט, ג</a>. וש\"נ. (וראה גם לעיל המשך חייב אדם לברך פל\"ז על יד הערה 1549)."],["3026","169","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380255\" data-slug=\"likkutei-torah\" data-id=\"4001380255\">לקו\"ת בהר מא, ד</a>. ביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. וש\"נ."],["3027","170","<b>בד\"ה מים רבים</b>: תרל\"ו. ראה שם שהחכ' נק' אין פק\"א. פקס\"ט. פקע\"ו."],["3028","171","<b>ובד\"ה וככה</b>: תרל\"ז. ראה שם פכ\"ג ואילך. פמ\"ז."],["3029","172","<b>ובד\"ה חייב אדם לברך</b>: שנדפס לעיל. ראה שם שהחכ' נק' אין פי\"ט. פמ\"א."],["3030","173","<b>בד\"ה ואתחנן</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרסז."],["3031","174","<b>ובחינוך</b>: שע\"ת ח\"ב ק, ב ואילך. ס' זה מובא בעוד מקומות בדרושי כ\"ק אדמו\"ר מהר\"ש ומהם: בסה\"מ תרכ\"ז ע' רצז [ושם: בס' החינוך]. ע' שלב [ושם: שער התפלה]. תרכ\"ט ע' רלא. תרל\"ב ח\"א ע' קעג [ושם: בס' החינוך]."],["3032","175","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["3033","176","<b>נקי כפים</b>: תהלים כד, ד."],["3034","177","<b>וירד ה'</b>: יתרו יט, כ."]]],[2000450303,"כנ\"ל, ורש\"י מפרש ד' ריבוי אלפי' דכתי' אז ראה ויספרה הכינה<sup data-n=\"3035\">178</sup> כו', ד\"פ אמרה בינו לבין עצמו<sup data-n=\"3036\">179</sup>, והיינו נגד ד' עולמות אבי\"ע, ובכ\"א הוא ריבוי אלפי' ע\"ד שנת' בתו\"א בד\"ה משה ידבר<sup data-n=\"3037\">180</sup>, ובד\"ה מראיהם ומעשיהם<sup data-n=\"3038\">181</sup> (שנאמרו בשבועות א'<sup data-n=\"3039\">182</sup> ) בענין ועושה חסד ונוצר חסד בשניהם נא' לאלפי', אלף יוד בראש יוד בסוף, ועכ\"ז גם בסוף הוא יו\"ד דוקא, ולמ\"ת הי' ד' רבוי אלפי' ע\"ד בשלמה דכתי' שלשת אלפי' משל<sup data-n=\"3040\">183</sup> שנת' שזהו עד מדרגתו בחי' ח\"ת<sup data-n=\"3041\">184</sup> וכאן ההמשכה מעל לרקיע דחיון עילאין<sup data-n=\"3042\">185</sup> כו' לכן צ\"ל ד' רבוי אלפי' כו' והם שנונים מפני כי לימוד התו' צ\"ל ושננתם שיהיו חדודי', אם ברור לך הדבר כאחותך<sup data-n=\"3043\">186</sup> כו' לכן הי' שאנן שנונים כו'.",[["3035","178","<b>אז ראה ויספרה הכינה</b>: איוב כח, כז."],["3036","179","<b>ד\"פ אמרה בינו לבין עצמו</b>: ראה שמו\"ר רפ\"מ. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381009\" data-slug=\"likkutei-torah\" data-id=\"4001381009\">לקו\"ת האזינו עא, ג</a>. סה\"מ תרל\"ב ח\"א ע' נ. וש\"נ."],["3037","180","<b>בד\"ה משה ידבר</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370303\" data-slug=\"torah-or\" data-id=\"3901370303\">תו\"א יתרו סז, ד</a>."],["3038","181","<b>ובד\"ה מראיהם ומעשיהם</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370309\" data-slug=\"torah-or\" data-id=\"3901370309\">תו\"א שם סט, סע\"ב</a> ואילך."],["3039","182","<b>שנאמרו בשבועות א'</b>: בשנת תקס\"ו. ראה מאמרי אדה\"ז תקס\"ו ע' רד וע' ריב."],["3040","183","<b>בשלמה דכתי' שלשת אלפי' משל</b>: מ\"א ה, יב. ראה לקמן מאמר ד\"ה על חומותיך על יד הערה 30. ו(בחלק ההנחות) בהנחה שם על יד הערה 28. סה\"מ תרכ\"ט ע' צה. וש\"נ. תרס\"ו ע' רלז. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540838\" data-slug=\"torat-chaim\" data-id=\"2300540838\">תו\"ח וארא ח\"א פג, ב</a>. וש\"נ."],["3041","184","<b>בשלמה. . בחי' ח\"ת</b>: ראה לקמן (בחלק ההנחות) הנחה ד\"ה על חומותיך ובהערה 29."],["3042","185","<b>דחיון עילאין</b>: ראה גם לעיל המשך חייב אדם לברך פ\"מ. וש\"נ."],["3043","186","<b>אם ברור לך הדבר כאחותך</b>: שבת קמה, ב."]]],[2000450304,"<h3>ומקנה רב כו' מרגלים כו' והארץ הדום רגלי כו'</h3>\n<b>בס\"ד מו\"מ ח\"ל</b>\n<b>ומקנה</b> רב<sup data-n=\"3044\">1</sup> הי' לבני ראובן ולבני גד<sup data-n=\"3045\">2</sup> כו', יותן את הארץ הזאת לעבדיך לאחוזה<sup data-n=\"3046\">3</sup> כו' ואתנו אחוזת<sup data-n=\"3047\">4</sup> כו'. והנה בפ' זו רבו הדקדוקים מאד, הא' למה חטפו",[["3044","1","<b>ומקנה רב</b>: דרוש השלישי (לאחר ד\"ה ואשא אתכם וד\"ה ואהי' אצלו אמון) מההמשך המבאר ד\"ה השמים כסאי שב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a> (וביאוריו) כמצויין לעיל ברד\"ה ואשא אתכם.\nמאמר זה מבאר פסקאות והארץ הדום רגלי־ והנה זהו שב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו\"א שם א, ב</a>. ג.\nהכותרת שבריש המאמר נעתקה מבוך 1162 ואינה מופיעה בבוך זה 1089. אודות ביכלאך אלו ראה המצויין בריש ד\"ה ואשא אתכם.\nהמאמר (מלבד הפתיחה והסיום שנכתבו בגוכתי\"ק) הוא לשון התו\"א עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע, וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש כמצויין בפרטיות בריש ההמשך (ד\"ה ואשא אתכם).\nהמאמר מלבד הפתיחה והסיום נדפס גם בלקו\"ת לג\"פ ב, ג. אוה\"ת בראשית כרך ו ע' תתרכו.\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות.\nמאמר זה נזכר לקמן במאמר ד\"ה גדול יהי' על יד הערות 8־ 52. ד\"ה על חומותיך על יד הערה 18. ד\"ה ישמח משה על יד הערה *72. ד\"ה בנים אתם על יד הערות 4־ 109-110."],["3045","2","<b>ומקנה רב. . ולבני גד</b>: מטות לב, א."],["3046","3","<b>יותן. . לעבדיך</b>: מטות שם, ה."],["3047","4","<b>ואתנו אחוזת</b>: שם לב, לב."]]],[2000450305,"ב\"ג ובני ראובן נחלתם מעבר לירדן בשביל מקניהם עד שלא ידעו עדיין תחלה טיבה של ארץ כנען כ\"כ לענין המקנה, ב' למה הוכיחן משה כה עשו אבותיכם<sup data-n=\"3048\">5</sup> כו' היינו בשילוח מרגלים, ולא בכ\"פ שרצו לחזור למצרים, ג' למה תלה להם אח\"כ זכיית חלקם מעבר הירדן בכיבוש וחלוקת הארץ כמ\"ש בפירוש בתנאי וכ\"פ המפרשים ע\"פ ואתנו אחוזת נחלתינו, ד' לשון אחוזת נחלתינו ולא אמר נחלתינו כמ\"ש בארץ כנען תנחלו נחלה<sup data-n=\"3049\">6</sup> וכדומה רבות. והענין הוא, דהנה במד\"ר ס\"פ מטות דרשו על ב\"ג וב\"ר פסוק נחלה מבוהלת<sup data-n=\"3050\">7</sup> כו' לא תבורך, ויש בזה ב' פי' במפרשי המד\"ר, הא' לא תבורך מפני כי גלו תחלה כמ\"ש המד\"ר מקודם<sup data-n=\"3051\">8</sup>, הב' מפני כי בא\"כ כתי' תמיד עיני ה' אלקיך בה<sup data-n=\"3052\">9</sup>, א\"כ שם הברכה יותר, ולכן מעבר לירדן לא תבורך כו'. ויובן בהקדם ענין מה שנת' בכ\"ד שענין מה שלא רצו המרגלים וכל דור המדבר לעלות לא\"כ מפני כי לא רצו להשפיל א\"ע במצות מעשיות<sup data-n=\"3053\">10</sup>, שבכלל כל המצות תלוי' בארץ כמ\"ש וזאת המצוה כו' לעשות בארץ<sup data-n=\"3054\">11</sup>, ונא' אח\"כ שמע ישראל שהיא חובת הגוף<sup data-n=\"3055\">12</sup>, אלא שכל המצות תלויות בארץ כמ\"ש בד\"ה וזאת המצוה שלא נדפס<sup data-n=\"3056\">13</sup>, ונק' תלוי' בארץ ע\"ש התלבשותם בדברים גשמי' ציצית בצמר הגשמי ותפילין כו', והם רצו שיהי' העבודה במח'<sup data-n=\"3057\">14</sup> בינה להיותם דור דיעה<sup data-n=\"3058\">15</sup> כו'. וזהו ע\"ד אותם שקיצצו כו' שהפרידו הארץ בחי' מל'<sup data-n=\"3059\">16</sup>, ולכן חלף הילוכם מם יום לתור נתעכבו ישראל מם שנה במדבר<sup data-n=\"3060\">17</sup> בארץ לא<sup data-n=\"3061\">18</sup> כו', ואח\"כ עלו לא\"כ לקיים מצות התלוי' בה ממש, וכל המצות שג\"כ תלוי' בה כנ\"ל, רק ב\"ג וב\"ר באה נחלתם מעבר לירדן שהיא בחי' אחוזת נחלתם כו'.",[["3048","5","<b>כה עשו אבותיכם</b>: מטות שם ח."],["3049","6","<b>כמ\"ש בארץ כנען תנחלו נחלה</b>: ראה מטות לב, יח: התנחל. . נחלתו. מסעי לה, ח: נחלתו אשר ינחלו. פ' שופטים יט, יד: בנחלתך אשר תנחל. וראה קרח יח, כג-כד. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 13."],["3050","7","<b>נחלה מבוהלת</b>: משלי כ, כא. ראה רש\"י שם. ידי משה במדרש כאן. וראה גם חדושי הרד\"ל שם."],["3051","8","<b>כמ\"ש המד\"ר מקודם</b>: פכ\"ב, ז."],["3052","9","<b>תמיד עיני ה' אלקיך בה</b>: עקב יא, יב. ראה ידי משה לבמדב\"ר שם."],["3053","10","<b>שלא רצו המרגלים. . במצות מעשיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">לקו\"ת שלח לז, ב</a> ובהנסמן במ\"מ לשם. לו סע\"ד ואילך. לח, ג. מא, ב. מאמרי אדה\"א במדבר ח\"ג ע' א'כא."],["3054","11","<b>וזאת המצוה. . בארץ</b>: ואתחנן ו, א."],["3055","12","<b>שמע ישראל שהיא חובת הגוף</b>: ואתחנן שם, ד. ראה קדושין לז, א וברש\"י שם. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091080\" data-slug=\"likkutei-sichot\" data-id=\"1300091080\">לקו\"ש עקב כרך ט ע' 80</a> ואילך ובהערות שם. אחרי כרך יז ע' 190."],["3056","13","<b>בד\"ה וזאת המצוה שלא נדפס</b>: ראה גם מאמר ד\"ה זה בבוך 1135 מא, סע\"א."],["3057","14","<b>והם רצו. . במח'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">לקו\"ת שלח לז, ב</a> ובהנסמן במ\"מ לשם. מאמרי אדה\"א במדבר שם."],["3058","15","<b>להיותם דור דעה</b>: ראה זהר בשלח סב, ב. פע\"ח שחה\"מ שכ\"א, פ\"א. מאמרי אדה\"א דברים ח\"א ע' עו. וש\"נ."],["3059","16","<b>אותם שקיצצו. . שהפרידו. . מל'</b>: ראה גם ת\"ז תס\"ט קיז, סע\"ב (ובניצוצי זהר שם). וראה גם רבינו בחיי נח יא, ד. ס' מאירת עינים — לר\"י דמן עכו ירושלים תשל\"ה — פ' בראשית ד, א (מד, ב ואילך) והערה עא. וראה גם פי' הראב\"ד לס\"י פ\"א, סמי\"א. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010018\" data-slug=\"or-hatorah-hb\" data-id=\"8159010018\">אוה\"ת בראשית כרך ז ע' תתשסו</a>. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 28 ואילך ובהערה 30."],["3060","17","<b>מם יום. . מם שנה במדבר</b>: שלח יד, לד. רש\"י שם לג."],["3061","18","<b>בארץ לא</b>: ירמי' ב, ב."]]],[2000450306,"<b>והענין</b> הוא דכתי' השמים כסאי והארץ הדום רגלי<sup data-n=\"3062\">19</sup>, הדום<sup data-n=\"3063\">20</sup> בלשון הפסוק הוא כמו שרפרף בלשון הגמרא<sup data-n=\"3064\">21</sup> שהוא ג\"כ כסא קטן והוא מה שמעמידין תחת רגלי היושב להגביה הרגל מעל הארץ וע\"ז אמרו בגמ' ע\"פ כרסון רמיו<sup data-n=\"3065\">22</sup> אחד לכסא ואחד לשרפרף, כסא הוא הגדול שיושבין עליו ושרפרף הוא הקטן שמעמידין תחת הרגלים. והענין כי הנה כנס\"י נקרא רגל כמ\"ש בנים אתם<sup data-n=\"3066\">23</sup> לה' אלקיכם וברא כרעא דאבוה<sup data-n=\"3067\">24</sup>, והנה כמו עד\"מ שנמצא מעלה יתירה ברגל מה שאין בראש שהרגלים הם המהלכים והם נושאים את הראש ומוליכין אותו למחוז חפצו ונמצא הראש צריך להרגל וגם גידי הראש וחיותו שהדם הוא הנפש הם ברגלים וכשמקיזין דם מהרגל<sup data-n=\"3068\">25</sup> מתרפא הראש ומתקיים, וכן כמה רפואות<sup data-n=\"3069\">*26</sup> יש שעושין ברגלים ומתרפא הראש, ובבחינה זו נק' הרגל ראש<sup data-n=\"3070\">26</sup> והראש רגל שהוא למטה מהרגל במדרגה זו, וכך הוא למעלה ע\"י התכללות המשכות המדרגות נעוץ תחלתן בסופן<sup data-n=\"3071\">27</sup> וסוב\"ת אור ישר ואור חוזר, אור ישר נק' מלמעלמ\"ט כל מה שלמעלה הוא העליון ואור חוזר ממטלמ\"ע כל מה שלמטה הוא העליון, וזהו נעוץ תחלתן בסופן שסופן הוא תחלתן שבחי' הרגל נק' ראש, וישראל נקראו ראשית<sup data-n=\"3072\">28</sup> וכתי' וירא ראשית לו<sup data-n=\"3073\">29</sup> וע\"י אתעדל\"ת נעשה למעלה תיקון אורות עליונים [ועמ\"ש בד\"ה צאינה וראינה<sup data-n=\"3074\">30</sup> בפי' שאו ידיכם קדש<sup data-n=\"3075\">31</sup> וברכו את הוי', וזהו ג\"כ מארז\"ל לא זז מחבבה<sup data-n=\"3076\">32</sup> עד שקראה אמי, וא\"ח עטרת בעלה<sup data-n=\"3077\">33</sup> עטרה על הראש, וז\"ש בזכרי' סי' ד' ז' את האבן הראשה, שהיא בחי' אבן מאסו הבונים<sup data-n=\"3078\">34</sup> היתה לראש פינה, וכתי' כי מראש צורים אראנו<sup data-n=\"3079\">35</sup> תשורי מראש אמנה<sup data-n=\"3080\">36</sup>, ועיין<sup data-n=\"3081\">37</sup> בפ' תשא דקפ\"ט ב' ע\"פ נכון יהי' הר בית ה'<sup data-n=\"3082\">38</sup> בראש ההרים, ועמ\"ש במ\"א ע\"פ מגיד מראשית<sup data-n=\"3083\">39</sup> אחרית ומקדם כו', ועד\"ז י\"ל ג\"כ מה שהיו\"ט נק' רגל ע'",[["3062","19","<b>השמים כסאי והארץ הדום רגלי</b>: ישעי' סו, א."],["3063","20","<b>הדום</b>: מכאן הוא לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו\"א כאן א, ב</a>."],["3064","21","<b>שרפרף בלשון הגמרא</b>: נסמן בהערה הבאה."],["3065","22","<b>כרסון רמיו</b>: דניאל ז, ט. חגיגה יד, א."],["3066","23","<b>בנים אתם</b>: פ' ראה יד, א."],["3067","24","<b>וברא כרעא דאבוה</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550364\" data-slug=\"torat-chaim\" data-id=\"2300550364\">תו\"ח ויקהל ח\"ב שצו, א</a> הערה 118."],["3068","25","<b>וכשמקיזין דם מהרגל</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' לז. שער האמונה סג, ב ובהערה 9. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550546\" data-slug=\"torat-chaim\" data-id=\"2300550546\">תו\"ח תצוה ח\"ב שלה, סע\"א</a>. סה\"מ תרכ\"ז ע' שנ. עטר\"ת ע' תי. לקמן מאמר ד\"ה מה יפו על יד הערה 39. בראשית על יד הערה 100 (ובהנסמן בהערה 1 שם). ד\"ה שלש רגלים (בהוספה) על יד הערה 43."],["3069","*26","<b>כמה רפואות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380686\" data-slug=\"likkutei-torah\" data-id=\"4001380686\">לקו\"ת מסעי צ, ג</a>."],["3070","26","<b>ובבחינה זו נק' הרגל ראש</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091075\" data-slug=\"likkutei-sichot\" data-id=\"1300091075\">לקו\"ש עקב כרך ט ע' 75</a> הערה 30."],["3071","27","<b>נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז. סידור שער הת\"ת צח, ג ואילך. סה\"מ תר\"ל ע' שכ."],["3072","28","<b>וישראל נקראו ראשית</b>: תנחומא — באבער — בראשית ג. וש\"נ. אלפא ביתא דר\"ע אות ב (ד\"א בי\"ת) (אוצר המדרשים אייזענשטיין כרך ב ע' 411). רש\"י ולק\"ט ר\"פ בראשית. רש\"י סנהדרין צא, ב ד\"ה מששת. מאמרי אדה\"ז תקס\"ה ח\"ב כאן ע' תשי."],["3073","29","<b>וירא ראשית לו</b>: ברכה לג, כא."],["3074","30","<b>בד\"ה צאינה וראינה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, סע\"ב</a> ואילך."],["3075","31","<b>שאו ידיכם קדש</b>: תהלים קלד, ב."],["3076","32","<b>לא זז מחבבה</b>: פדר\"כ פסקא א."],["3077","33","<b>וא\"ח עטרת בעלה</b>: משלי יב, ד."],["3078","34","<b>אבן מאסו הבונים</b>: תהלים קיח, כב."],["3079","35","<b>כי מראש צורים אראנו</b>: בלק כג, ט."],["3080","36","<b>תשורי מראש אמנה</b>: שה\"ש ד, ח."],["3081","37","<b>ועיין</b>: בזהר."],["3082","38","<b>נכון יהי' הר בית ה'</b>: ישעי' ב, ב."],["3083","39","<b>ע\"פ מגיד מראשית</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רכג ואילך. סה\"מ תרל\"ב ח\"א ע' קז ואילך [ובהנסמן בריש המאמר שם]."]]],[2000450307,"בלק\"ת<sup data-n=\"3084\">40</sup> ס\"פ משפטים גבי מצות ראיה בג' רגלים, וזהו ג\"כ ענין בנהר יעברו ברגל<sup data-n=\"3085\">41</sup> היינו למעלה מבחי' הנהר היוצא מעדן<sup data-n=\"3086\">42</sup> כמ\"ש במ\"א] (ועכ\"ז אינו דומה לבחי' עגולים שבבחי' עגולים לא יש כלל ראש וסוף כמ\"ש באריכות במ\"א בענין האופן בתוך האופן<sup data-n=\"3087\">43</sup> וע' בד\"ה לעומת המסגרת<sup data-n=\"3088\">44</sup>, ובמ\"א בענין ומתחת זרועות עולם<sup data-n=\"3089\">45</sup>, אבל כאן הכוונה דיש ראש וסוף רק שמלמעלמ\"ט החכ' ראש והמל' סוף, ומלמטלמ\"ע בהיפוך אבל עכ\"ז הנה יש ראש וסוף, וצ\"ע אם בגבולי אלכסוני' דז\"א<sup data-n=\"3090\">46</sup> ג\"כ כן הוא וגם מצד התכללות המדות דתיקון אם גם בהם ההתכללות עד\"ז שהסוף הוא ג\"כ ראש, וע' בביאור והניף בפ' אמור<sup data-n=\"3091\">47</sup> ענין היותם רך כקנה מצ\"ע זהו ענין בחי' ריכוך, וגם התכללותם מצד הארת א\"ס בהם ז\"ע ביטולם ע\"ד המשל ופחד עמו כו', א\"כ א\"ז שייך לענין הנ\"ל, רק בגבולי אלכסונים ענין היותם י\"ב מורה שיש בהם ראש וסוף, והסוף הוא ג\"כ ראש דאל\"כ אינם י\"ב כ\"א ששה, אבל חיבור מוחין ומדות נראה שבהם אינו שייך כ\"א התכללות לבד ולא ע\"ד ראש וסוף ושהסוף הוא ג\"כ ראש, כ\"א עם מדת המל' דנתב\"ס וסוב\"ת כו', ומ\"מ אינם כמו עיגולים כנ\"ל כו').\n<b>וזהו</b> שמצינו במשה שבחטא העגל נטלו ממנו אלף אורות<sup data-n=\"3092\">49</sup> [ובשבת חוזרין ונותנין אליו במתנה וזהו ישמח משה במתנת חלקו<sup data-n=\"3093\">50</sup>]<sup data-n=\"3094\">51</sup> וע\"ז רמזו רז\"ל במ\"ש ע\"פ לך רד רד מגדולתך כלום נתתי לך גדולה אלא בשביל ישראל<sup data-n=\"3095\">52</sup>, והיינו לפי",[["3084","40","<b>בלק\"ת</b>: מהאריז\"ל."],["3085","41","<b>בנהר יעברו ברגל</b>: תהלים סו, ו. ראה לקו\"ת שמ\"ע פח, ד ואילך. צו יא, ד. טו, ד. לקמן מאמר ד\"ה מה יפו על יד הערות 62-3."],["3086","42","<b>הנהר היוצא מעדן</b>: בראשית ב, י."],["3087","43","<b>האופן בתוך האופן</b>: יחזקאל א, טז. י, י. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370309\" data-slug=\"torah-or\" data-id=\"3901370309\">תו\"א יתרו סט, ב</a>. מאמרי אדה\"ז תקס\"ו ע' ריב. מאמרי אדה\"א במדבר ח\"ב ע' תכז."],["3088","44","<b>בד\"ה לעומת המסגרת</b>: ראה אוה\"ת תרומה ע' א'תסד ואילך."],["3089","45","<b>ומתחת זרועות עולם</b>: ברכה לג, כז. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380256\" data-slug=\"likkutei-torah\" data-id=\"4001380256\">לקו\"ת בהר מב, רע\"א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381204\" data-slug=\"likkutei-torah\" data-id=\"4001381204\">שה\"ש יח, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381292\" data-slug=\"likkutei-torah\" data-id=\"4001381292\">מא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381221\" data-slug=\"likkutei-torah\" data-id=\"4001381221\">שע\"ת כג, א</a> ובהערה 9. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540130\" data-slug=\"torat-chaim\" data-id=\"2300540130\">תו\"ח וארא ח\"א נה, ד</a>. וש\"נ."],["3090","46","<b>בגבולי אלכסוני' דז\"א</b>: ראה ס\"י פ\"ה, מ\"א. לעיל המשך כי תשא פ\"ח בהערה 196."],["3091","47","<b>בביאור והניף בפ' אמור</b>: לקו\"ת שם לז, ד ואילך.\n48)המשל ופחד עמו: איוב כה, ב. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה מקום שאמרו ובהערה 31."],["3092","49","<b>במשה. . אלף אורות</b>: לקמן במאמר ד\"ה ישמח משה בתחילתו מציין לסידוד האריז\"ל — בתפלת העמידה לשבת במקומו (ר\"ש רשקוב (ד\"ה משה). קול יעקב). ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381101\" data-slug=\"likkutei-torah\" data-id=\"4001381101\">לקו\"ת ברכה צג, ג</a> (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770394\" data-slug=\"or-hatorah-hb\" data-id=\"8316770394\">אוה\"ת שה\"ש כרך ב ע' תשסב</a>־ סה\"מ תרנ\"ג ע' קפג־ עזר\"ת ע' לא־ תרע\"ח ע' רלח) ושם: פע\"ח שער השבת פ\"ח. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200014\" data-slug=\"or-hatorah-hb\" data-id=\"8159200014\">אוה\"ת תשא ע' ב'נז</a>־ סה\"מ תרל\"ב ח\"א ע' פב (וע' רמד)־ תרל\"ד ע' קמ־ תרנ\"ג ע' קפג־ תרס\"ב ע' תיב (ובמהדורת תנש\"א ע' תכא)־ תרס\"ו ע' פז ושם: לק\"ת מהאריז\"ל ס\"פ תשא. אוה\"ת ויקרא כרך ג ע' תשכו ושם: לק\"ת — להאריז\"ל פ' ויקרא. לקמן (בחלק ההנחות) הנחה ד\"ה ישמח משה־ סה\"מ תרפ\"ט ע' 58־ תש\"ו ע' 36 ושם: בכהאר\"י ז\"ל. תש\"ג ע' 89 בהערה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061255\" data-slug=\"likkutei-sichot\" data-id=\"1300061255\">לקו\"ש שמות כרך ו ע' 245</a>. מאמרי אדה\"ז תקס\"ה ח\"ב כאן ס\"ע תשי ואילך. ס\"ע תשכ ואילך. לקמן מאמר ד\"ה ישמח משה הנ\"ל (ד\"ה והנה טעם הדבר). ובההנחה הנ\"ל שם (סוד\"ה וזהו ואהבת). וראה זהר בשלח נח, א."],["3093","50","<b>[ובשבת. . חלקו]</b>: הובא בתו\"א כאן."],["3094","51","<b>ישמח משה במתנת חלקו</b>: תפלת העמידה לשבת."],["3095","52","<b>לך רד. . בשביל ישראל</b>: תשא לב, ז. ברכות לב, א. רש\"י תשא שם."]]],[2000450308,"שהיו ישראל בבחי' הרגל שלו וכמ\"ש שש מאות אלף רגלי<sup data-n=\"3096\">53</sup> העם אשר אנכי בקרבו והם היו לו בחי' מקיף ובחי' ראש אף שהם היו לו בבחי' רגל ודאי [ועמ\"ש מזה בד\"ה מי שם פה לאדם<sup data-n=\"3097\">54</sup>], (ועמ\"ש בד\"ה ועמדו רגליו ביום ההוא<sup data-n=\"3098\">55</sup> על הר הזתים מענין ישכר וזבולון, בענין בחי' תמכין דאורייתא<sup data-n=\"3099\">*56</sup> כו', ושם נת' ג\"כ שיש כוונת נעיצת התחילה בסוף יותר מבבחי' ראש המתפשט, ולכאורה זהו יתרון המעלה מלבד מה שרגל הוא ג\"כ ראש, שזהו כמו שמפרשים נעתב\"ס וסוב\"ת בכ\"מ, אבל שם פי' שכוונת נעיצת התחילה הוא בסוף דוקא יותר מבראש המתפשט כו', ונת' מזה במ\"א בד\"ה המגיד מראשית אחרית<sup data-n=\"3100\">56</sup> באורך), וכך הוא בכל ישראל ע\"י שמתקן מעשיו שהם בכח המעשה בעשי' גשמיות בבחי' רגלים נעשה מוחו ולבו זכים אלף פעמים ככה<sup data-n=\"3101\">57</sup> [ועמ\"ש בדרוש המרגלים בפ' שלח<sup data-n=\"3102\">58</sup>, והנה מרגלים י\"ל ג\"כ קרוב ללשון רגל<sup data-n=\"3103\">59</sup> והיינו כי נשתלחו לתור את הארץ<sup data-n=\"3104\">60</sup> שהיא בחי' מצות מעשיות שהם בחי' רגל אלא שהם לא רצו בהשפלה זו כו'. והנה מש\"כ אלף פעמים ככה י\"ל שהוא ע\"ד אלף אורות דמשה שנמשך לו ע\"י נש\"י שהם בחי' רגל כו', וכך הוא לפי ערך זה בכל א' מישראל כו'. וענין אלף י\"ל שהוא בחי' אאלפך חכמה וכנ\"ל<sup data-n=\"3105\">61</sup> ועמ\"ש בד\"ה ויקרא אל משה<sup data-n=\"3106\">62</sup> מענין א' זעירא וא' רברבא ע\"ש. ויובן ג\"כ ע\"ד משנ\"ת בד\"ה מי מנה<sup data-n=\"3107\">63</sup> בענין אף עשיתיו אף מרבה בחי' רביעית היינו גילוי רצון העליון שלמעלה מחב\"ד חג\"ת כו' והוא נמשך ומתגלה ע\"י העשייה דוקא ע\"ש]. (ויובן עוד ע\"פ מארז\"ל במשנה ט'<sup data-n=\"3108\">*64</sup> פ\"ג דאבות, כל שמעשיו מרובי' מחכמתו חכמתו מתקיימת, שקיום החכ' הוא ע\"י המעשה דוקא, וי\"ל דהנה ארז\"ל במד\"ר אלף נכנסי' למקרא<sup data-n=\"3109\">64</sup> יוצא ממנו מאה למשנה, מאה למשנה עשרה לתלמוד, מיו\"ד שלתלמוד אחד להוראה, וזהו דכתי' אדם אחד מאלף מצאתי<sup data-n=\"3110\">65</sup>, ונודע כי מקרא בעשיי' והיינו שנשפל עד העשי' כמ\"ש בביאור",[["3096","53","<b>שש מאות אלף רגלי</b>: בהעלותך יא, כא. ראה גם לקמן מאמר ד\"ה ישמח משה על יד הערה 90. ו(בחלק ההנחות) בהנחה שם על יד הערה 105. מאמרי אדה\"א קונטרסים ע' תיז. וש\"נ."],["3097","54","<b>בד\"ה מי שם פה לאדם</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370234\" data-slug=\"torah-or\" data-id=\"3901370234\">תו\"א שמות נב, ב</a>."],["3098","55","<b>בד\"ה ועמדו רגליו ביום ההוא</b>: סה\"מ תר\"ל ע' שכ ואילך."],["3099","*56","<b>ישכר. . תמכין דאורייתא</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערות 74-75."],["3100","56","<b>שכוונת נעיצת התחילה. . המגיד מראשית אחרית</b>: סה\"מ תרל\"ב ח\"א ע' קז. ראה גם שם בח\"ב ע' שסז ובהנסמן שם בפנים. ס\"ע תקכט. תרל\"ג ח\"א ע' קטז. וש\"נ."],["3101","57","<b>נעשה מוחו ולבו. . ככה</b>: בנוסף להבא לקמן בפנים ראה גם הנסמן בסה\"מ תרל\"ד ע' קמ. תרל\"ב ח\"א ע' פג."],["3102","58","<b>בדרוש המרגלים בפ' שלח</b>: לקו\"ת שם לז, א."],["3103","59","<b>מרגלים. . ללשון רגל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560017\" data-slug=\"or-hatorah-hb\" data-id=\"8316560017\">אוה\"ת בראשית כרך ג ע' תעה</a>. הובא לקמן במאמר ד\"ה מה יפו על יד הערה 82. ד\"ה בראשית על יד הערה 57."],["3104","60","<b>לתור את הארץ</b>: שלח יג, טז."],["3105","61","<b>אאלפך חכמה וכנ\"ל</b>: לעיל ד\"ה ואשא אתכם על יד הערה 124."],["3106","62","<b>בד\"ה ויקרא אל משה</b>: לקו\"ת ר\"פ ויקרא א, (א) ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקה ואילך."],["3107","63","<b>בד\"ה מי מנה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380589\" data-slug=\"likkutei-torah\" data-id=\"4001380589\">לקו\"ת בלק סז, ד</a>."],["3108","*64","<b>ט'</b>: ולגי' אדה\"ז בסידורו מ\"י."],["3109","64","<b>אלף נכנסי' למקרא</b>: ראה ויק\"ר רפ\"ב. קה\"ר פ\"ז, כח. ראה גם אוה\"ת ירמי' ע' שפ ס\"ו. (יהל אור) תהלים ע' שכא ס\"ה. המשך תרס\"ו ע' תכ ואילך."],["3110","65","<b>אדם אחד מאלף מצאתי</b>: קהלת ז, כח."]]],[2000450309,"ולא תשבית<sup data-n=\"3111\">66</sup> בפ' ויקרא, וע' בבה\"ז<sup data-n=\"3112\">67</sup> במאמר לא טוב כו' עזר כנגדו אתתא דההוא נער, וכ\"מ מהביאור דלקמן על מא\"ז<sup data-n=\"3113\">68</sup>, ומשנה ביצי' ותלמוד בבריאה, ונמצא שמאלף דעשיי' יכולים לבוא מאה להשגה שביצי' וממאה דיצי' יו\"ד להשגת הבריאה, ומיו\"ד דבריאה אחד לגילוי האצי' כו', ולפ\"ז י\"ל שאם האחד שבא לגילוי השגת האצי' זהו דוקא ע\"י שמעשיו מרובי' מחכמתו שעי\"ז חכמתו מתקיימת, פי' עומדת חזק עד שבא לתכלית השלימות להכלל ע\"י לימוד תורתו באצי' העליון כו', וכשיוצא לידי פועל שמורה הוראות בישראל מובן שבא לכלל שרי אלפי'<sup data-n=\"3114\">*69</sup> כו' שיש להם כח מאלף כו', שהרי אמר שמאלף יוצא אחד להוראה, ולכן כשנתמנה להורות הרי נשלם פעולת כח המעשה שלו עד שהגיע לשלימות, ונמצא כי ע\"י מעשה נעשה מוחו ולבו היינו לב שומע להבין כמ\"ש בשלמה<sup data-n=\"3115\">69</sup> כו' עד שיוכל להורות לעמו כו' א\"כ ה\"ז נעשה מוחו ולבו זכים אלף פעמים ככה כו', ועוי\"ל קיום ל' חיזוק ע\"ד הבנין כשעומד על יסוד טוב ה\"ה חזק לבלי יתמוטט, ונודע כי למעלה היסוד הוא למעלה<sup data-n=\"3116\">70</sup> כו' וקיום ויסוד הבי\"ע היא הארת האצי' המהוה ומחי' אותם תמיד כו', וא\"כ פי' חכ' מתקיימת כשמעשיו מרובי' עד שבא להארת האצי', וגם י\"ל שיורה הלכה למעשה דוקא וזהו להוראה כו'. ועפ\"ז יובן ג\"כ ענין עשי' לעילא<sup data-n=\"3117\">71</sup> שלהיות כח העשיי' הוא גבוה מאד רק שנשפל למטה לכן יכולה לפעול עד שמוחו ולבו זכים אלף פעמים ככה.\n<b>אך</b> עדיין צ\"ל שבמאה\"ז עשי' לעילא פי' שמיעה בהאי אתר תלי' בחי' מל', עשי' לעילא בינה, והבינה היא בחי' בריאה שבאצי', וכאן נת' שזהו הארת האצי', וי\"ל דפי' מוחו ולבו קאי על האדם המתעסק בעשיית המצות, וכשמאיר בו הארת האצי' הגם שזהו מבריאה שבאצי' עכ\"ז להיותה מבחי' האצי' בכלל עכ\"פ נעשו מוחו ולבו זכים א\"פ ככה כו', וגם י\"ל כי חו\"ב הם תרדל\"מ<sup data-n=\"3118\">72</sup> ולכן הגם כי הבינה מצ\"ע ה\"ה בריאה שבאצי' מ\"מ ע\"י היותם תרדל\"מ ה\"ז אצי' ממש כו'. וענין אומרו ככה יובן ג\"כ שנגד המעשה הוא שנק' ככה, דהנה יש ג' בחי' זה, כה, ככה<sup data-n=\"3119\">73</sup>, ונת' במ\"א בענין משה נתנבא בזה<sup data-n=\"3120\">74</sup> שזהו באספקלרי' המאירה דאצי' כו' בחי' בצלמנו כו'",[["3111","66","<b>מקרא בעשי'. . בביאור ולא תשבית</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, סע\"א</a> ואילך."],["3112","67","<b>בבה\"ז</b>: בראשית ב, ד. ולהצ\"צ כרך ב ע' תרכ ואילך."],["3113","68","<b>מהביאור דלקמן על מא\"ז</b>: בפיסקא הבאה."],["3114","*69","<b>שרי אלפי'</b>: יתרו יח, כא."],["3115","69","<b>לב שומע להבין כמ\"ש בשלמה</b>: מל\"א ג, ט."],["3116","70","<b>למעלה היסוד הוא למעלה</b>: ראה גם פרדס שעה\"כ שכ\"ג, פ\"י מערכת יסוד. אוה\"ת בראשית כרך ג ס\"ע 1122 ואילך. המשך והחרים תרל\"א ע' מח. ד\"ה באתי לגני תשי\"ט פ\"ב ואילך [סה\"מ מלוקט א ע' סז ואילך. סה\"מ באתי לגני ח\"א ע' קיד ואילך]."],["3117","71","<b>עשי' לעילא</b>: ראה זהר בהר קח, ב. ביאוה\"ז בהר פב, סע\"ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעא ואילך. סה\"מ תרע\"ח ע' שצו ואילך."],["3118","72","<b>חו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["3119","73","<b>ג' בחי' זה כה ככה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370530\" data-slug=\"torah-or\" data-id=\"3901370530\">תו\"א מג\"א קיח, ד</a>. מאמרי אדה\"ז תקס\"ח ח\"א ע' צח."],["3120","74","<b>משה נתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540144\" data-slug=\"torat-chaim\" data-id=\"2300540144\">תו\"ח בשלח ח\"א קמד, ב</a> הערה 29."]]],[2000450310,"משא\"כ כל הנביאים נתנבאו בכה כדמותנו<sup data-n=\"3121\">75</sup>, שביד הנביאים אדמה<sup data-n=\"3122\">76</sup>, כי נבואתם הי' מבי\"ע שישעי' ראה מרכבת הבריאה<sup data-n=\"3123\">77</sup> ויחזקאל ביצי'<sup data-n=\"3124\">78</sup> וזכרי' בעשי'<sup data-n=\"3125\">79</sup>, וזהו הנק' כה, אבל ככה נא' במג\"א שהי' ההתלבשות בשושן אשר בעילם המדינה<sup data-n=\"3126\">81</sup> נא' שם מה ראו על ככה<sup data-n=\"3127\">82</sup> שגם בבחי' ככה מ\"מ הגיע להם בחי' מה כמשנ\"ת במ\"א<sup data-n=\"3128\">83</sup>, ולפ\"ז יובן גם כאן שהגם שהמעשה נתלבש בדברים גשמי' ציצית מצמר הגשמי דנוגה וכן כולם, עכ\"ז כשעושה אותם בבחי' קבעומ\"ש שקדם כמ\"ש במ\"א ובכוונת הלב כמ\"ש בש\"ע גבי תפילין<sup data-n=\"3129\">84</sup> לשעבד הלב והמוח, ובכלל כוונה זו היא כל כוונות הנא' בכהאריז\"ל, ע' בביאור ועתה יגדל נא<sup data-n=\"3130\">85</sup> בפ' שלח, נעשה מוחו ולבו זכים להורות אלף פעמים מכמו היותו ככה כשנכנס ללימוד המלובש בעשי' כו').\n<b>והנה</b> להיות הדום לבחי' רגל שהוא בחי' כנסת ישראל דהיינו להגביה' ולהעלותה ממטה למעלה הוא ע\"י בחי' הארץ שהם מצות מעשיות וכללותן היא הצדקה וע\"ז נא' צדקה תרומם גוי<sup data-n=\"3131\">86</sup> תרומם ממטה למעלה [ועמ\"ש מזה בד\"ה המגביהי לשבת<sup data-n=\"3132\">87</sup> ובד\"ה כי ביום הזה יכפר<sup data-n=\"3133\">88</sup> גבי אני כברוש רענן כו'], והגבהה והעלאה זו היא בבחי' גוי שהם אותיות גו\"י דהיינו העלא' המדות שנחלקין דרך כלל לג' בחינות חסד דין רחמים [כי נה\"י אינו אלא התפשטות חג\"ת וענפיהן<sup data-n=\"3134\">89</sup> ועמ\"ש מזה בד\"ה חייב אינש לבסומי בפוריא<sup data-n=\"3135\">90</sup>], והתעלותן היא לבחי' יו\"ד שהיא בחי' החכ' ע\"י הוא\"ו שהוא הממשיך ומחבר המחשבה כו' [ויובן זה עפמ\"ש בפ' בלק דר\"ג ע\"ב ציורא ודיוקנא דאבוי אתרשים בי' ממש וכמ\"ש במ\"א<sup data-n=\"3136\">91</sup>, ועמ\"ש בד\"ה ראה אנכי<sup data-n=\"3137\">92</sup> בענין נחל איתן כו', וע' באגה\"ק בסופו ע\"פ וצדקה כנחל איתן, וזהו ג\"כ מ\"ש וצדקתך",[["3121","75","<b>בצלמנו. . כדמותנו</b>: בראשית א, כו. ראה אוה\"ת ואתחנן ע' פו. וראה גם לעיל מאמר ד\"ה ואשא אתכם על יד הערה 31."],["3122","76","<b>שביד הנביאים אדמה</b>: הושע יב, יא."],["3123","77","<b>שישעי' ראה מרכבת הבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להנ\"ל יבמות מט, ב ד\"ה מנשה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540375\" data-slug=\"torat-chaim\" data-id=\"2300540375\">תו\"ח בא ח\"א קיד, סע\"ג</a>. וש\"נ."],["3124","78","<b>ויחזקאל ביצי'</b>: ראה ע\"ח שער ק\"נ שמ\"ט, פ\"ב. מאמרי אדה\"א נ\"ך ע' קמא. וש\"נ. תו\"ח שם ובהערה 194. ולהעיר מויקהל משה [זאלקווא תקל\"ה ו, א — ראה אודותיו <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830299\" data-slug=\"or-hatorah-hb\" data-id=\"8158830299\">אוה\"ת בלק ע' תתקפה</a> —]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">תו\"א משפטים עח, ב</a> : בריאה."],["3125","79","<b>וזכרי' בעשי'</b>: ראה גם פיה\"מ מ, ג. מא, א. נז, רע\"א [ושם: דעשי' ויצי']. שעה\"י קמו, ב. אוה\"ת מג\"א ע' קפב. המשך וככה תרל\"ז פנ\"ו ע' פד. סה\"מ תרמ\"ז ע' קכה. לקמן (בחלק ההנחות) בהנחה ד\"ה ואשא אתכם על יד הערה 64.\n80)ככה נאמר במג\"א: נסמן בהערה 82."],["3126","81","<b>בשושן אשר בעילם המדינה</b>: דניאל ח, ב [בדילוג]."],["3127","82","<b>מה ראו על ככה</b>: אסתר ט, כו [ושם ומה — אבל ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו\"א מג\"א צט, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370041\" data-slug=\"torah-or\" data-id=\"3901370041\">שה\"א י, א</a>. סה\"מ תרכ\"ו ע' יא. המשך מצה זו תר\"ם ע' לח. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 109]."],["3128","83","<b>כמשנ\"ת במ\"א</b>: ראה הערה 73."],["3129","84","<b>בש\"ע גבי תפילין</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, סי\"א."],["3130","85","<b>בביאור ועתה יגדל נא</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>."],["3131","86","<b>צדקה תרומם גוי</b>: משלי יד, לד. ראה גם להבא לקמן מאמר ד\"ה בנים אתם על יד הערה 71 ואילך (ובהנסמן בריש המאמר שם)."],["3132","87","<b>בד\"ה המגביהי לשבת</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו\"א מקץ לח, ג</a>."],["3133","88","<b>כי ביום הזה יכפר</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380189\" data-slug=\"likkutei-torah\" data-id=\"4001380189\">לקו\"ת אחרי כו, ב</a>."],["3134","89","<b>[כי. . וענפיהן</b>: הובא בתו\"א כאן."],["3135","90","<b>בד\"ה חייב אינש לבסומי בפוריא</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370427\" data-slug=\"torah-or\" data-id=\"3901370427\">תו\"א מג\"א צה, ב</a>."],["3136","91","<b>עפמ\"ש. . וכמ\"ש במ\"א</b>: בזהר. . ראה ביאוה\"ז לשם קג, א ואילך. ולהצ\"צ ביאוה\"ז ח\"ב ע' תתקצג ואילך."],["3137","92","<b>בד\"ה ראה אנכי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380789\" data-slug=\"likkutei-torah\" data-id=\"4001380789\">לקו\"ת ראה יח, ב</a>."]]],[2000450311,"אלקים עד מרום<sup data-n=\"3138\">93</sup>]. ככה ממש נעשה למטה בנפש האדם העלאת המדות בשכלו ובינתו כי כשהמדות נפרדות מהשכל הם נחשבות לדבר בפני עצמו ולכן יש לך אדם שמתעורר לבו בשעת התפלה וכיוצא בה שאז היא שעת גדלות המוחין<sup data-n=\"3139\">94</sup> ואח\"כ חולפת ועוברת האהבה ופונה לדרכו מהיפך להיפך באין מבין כי הם שני הפכים והיינו מפני שהמדות נפרדים מהשכל, משא\"כ בהתכללותן כו', והרי אז הוא עילוי המדות ביתר שאת שנעשו בחי' מוחין (וצ\"ל שכמו בירידת השפע מלמעלמ\"ט יש בחי' מעבר והתלבשות כמשנ\"ל<sup data-n=\"3140\">95</sup> ענין ההפרש ביניהם שבהתלבשות נק' ע\"ש כו' כן דוגמת זה יש בעלי' מלמטלמ\"ע ג\"כ ב' בחי' אלו, וכן העלי' היא ע\"ד הירידה בבחי' ההתלבשות כו' ולכן אמר שנעשו בחי' מוחין. ועוי\"ל ע\"פ מ\"ש במ\"א בש' הבעש\"ט ז\"ל<sup data-n=\"3141\">96</sup> בתי' הקושי' על שרפי' עומדי' ממעל לו<sup data-n=\"3142\">97</sup> היתכן שיעמדו למעלה מש' אד' המהוום, אלא מפני שרצונם בקריאתם ובאמירת קדוש ליכלל וליבטל באוא\"ס הסוכ\"ע שלמעלה מש' אד' לשון אדון כו'<sup data-n=\"3143\">98</sup> וה\"ה כאלו עומדי' שם וכ\"ש בעליית המדות למוחין שיקראו ע\"ש בחי' המוחין כו') וזהו בכל נפשך<sup data-n=\"3144\">99</sup> דהיינו בכל כחות הנפש אפי' בבחי' רגל שגם בחי' הרגל תרום ותגביה [וזהו נר לרגלי דבריך<sup data-n=\"3145\">100</sup>, וע'<sup data-n=\"3146\">101</sup> בפ' פקודי דרמ\"א א' והארץ הדום רגלי דא רקיעא דדוד מלכא שריא ביה כו', ובגין דבעי לאתפשטא יתיר לתתא אמר הדום רגלי, וענין דבעי לאתפשטא יתיר י\"ל ע\"ד רגליה יורדות<sup data-n=\"3147\">102</sup> כו', ועוד יובן ע\"ד מ\"ש<sup data-n=\"3148\">103</sup> בפ' קרח דקע\"ח סע\"א בההיא שעתא דבעא יומא לאתקדשא הוו נפקי רוחיהון כו' ואתקדש יומא ולא אתבריאו ועמש\"ש ע\"ז בבה\"ז<sup data-n=\"3149\">104</sup> וזהו אם תשיב משבת רגליך<sup data-n=\"3150\">105</sup>, ועמ\"ש במ\"א ע\"פ אז ישיר<sup data-n=\"3151\">106</sup> בענין מלך עומד על הלוח אגוסטוס יושב כו', ומשם יובן מעלת השמים כסאי שעי\"ז והארץ הדום כו' ולא יומשך ויתפשט למקום שא\"צ].\n<b>והנה</b> זהו דרך כלל שנק' שמים וארץ תורה ומצות ודרך פרט בתורה עצמה שמים זו תושב\"כ שמים שם מים<sup data-n=\"3152\">108</sup> דאורייתא מחכ' נפקת<sup data-n=\"3153\">109</sup> וארץ נקרא",[["3138","93","<b>וצדקתך אלקים עד מרום</b>: תהלים עא, יט."],["3139","94","<b>התפלה. . גדלות המוחין</b>: ראה תניא פי\"ב. מ\"מ הגהות והע\"ק לשם."],["3140","95","<b>מעבר והתלבשות כמשנ\"ל</b>: במאמר ד\"ה ואשא אתכם (ד\"ה וצריך להבין)."],["3141","96","<b>בש' הבעש\"ט ז\"ל</b>: ראה גם לעיל המשך וידבר וגו' ויצוום פ\"ח ובהערה 136."],["3142","97","<b>שרפי' עומדי' ממעל לו</b>: ישעי' ו, ב."],["3143","98","<b>אד' לשון אדון כו'</b>: ראה זהר בראשית טז, סע\"ב. שמות יג, א. שער היחוד והאמונה רפ\"ז. ברכות ז, רע\"ב. אוה\"ת ש\"ש ע' א'תפז ואילך."],["3144","99","<b>בכל נפשך</b>: ואתחנן ו ה [ושם: ובכל]."],["3145","100","<b>נר לרגלי דבריך</b>: תהלים קיט, קה."],["3146","101","<b>וע'</b>: בזהר."],["3147","102","<b>רגליה יורדות</b>: משלי ה, ה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381333\" data-slug=\"likkutei-torah\" data-id=\"4001381333\">לקו\"ת שה\"ש נא, ב</a>. לקמן מאמר ד\"ה בנים אתם על יד הערה 15 ואילך."],["3148","103","<b>מ\"ש</b>: בזהר."],["3149","104","<b>בבה\"ז</b>: צה, א."],["3150","105","<b>אם תשיב משבת רגליך</b>: ישעי' נח, יג."],["3151","106","<b>ע\"פ אז ישיר</b>: מאמרי אדה\"ז תקס\"ה ח\"א ע' רלט ואילך. אוה\"ת בשלח ע' תצה ואילך."],["3152","108","<b>שמים. . שם מים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח. לעיל מאמר ד\"ה ואשא אתכם על יד הערות 40-41."],["3153","109","<b>דאורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."]]],[2000450312,"תושבע\"פ<sup data-n=\"3154\">107</sup> כי ארץ מלשון רצון כמארז\"ל למה נקרא שמה ארץ שרצתה<sup data-n=\"3155\">110</sup> כו' וארץ אותיות א' רץ<sup data-n=\"3156\">111</sup> כו'. והענין כי תורה שבע\"פ היא השגת תכלית הרצון לידע איך ומה כגון סוכה שהיא גבוה<sup data-n=\"3157\">112</sup> כו' שאין זה מבואר בתושב\"כ ותושב\"כ היא רק בחי' אותיות להיות כדמותן בצלמן שהן שמותיו של הקב\"ה<sup data-n=\"3158\">113</sup> ולכן נק' קורא בתורה<sup data-n=\"3159\">114</sup> כמו שקורא בשם [ועמ\"ש מזה בד\"ה לכן אמור לבנ\"י<sup data-n=\"3160\">115</sup>] והיינו מלמעלה למטה אבל תושבע\"פ עיקרה ממטה למעלה ע\"י השגת הרצון בנפש תכלל הנפש במקורה למעלה [וזהו ענין סלסלה ותרוממך<sup data-n=\"3161\">116</sup> ועמ\"ש מזה בביאור ע\"פ כי ביום הזה יכפר<sup data-n=\"3162\">117</sup>]. (וכן י\"ל שיש ב' בחי' אלו דשמים וארץ במעהמ\"צ ג\"כ, דהנה נת' בד\"ה ועתה יגדל נא<sup data-n=\"3163\">118</sup> בפ' שלח שיש ב' בחי' במצות בעשייתם, הא' שע\"י עשייתם מקיים מצות המלך ע\"ד ותגזור אומר ויקם<sup data-n=\"3164\">119</sup>, והב' הוא להמשיך אוא\"ס ורצה\"ע ב\"ה<sup data-n=\"3165\">120</sup> במצוה זו ששרשה ויסודתה בהררי קדש העליון אשר קדשנו במצותיו<sup data-n=\"3166\">121</sup>, והנה תחילת עשיית המצוה<sup data-n=\"3167\">122</sup> לא תהי' בשביל להמשיך אוא\"ס ב\"ה ורצה\"ע ב\"ה לבד, שהרי זהו רק כמו שעושה בדרך סגולה או רפואה עד\"מ, או מו\"מ כדי להרויח שאין זו עבודה ותחת אשר לא עבדת<sup data-n=\"3168\">123</sup> כתי' שהמצות צריכים להיות דרך עבודת עבד שמקיים גזירת רבו וציויו אף<sup data-n=\"3169\">124</sup> בלי טעם ודעת ושום תשים עליך מלך<sup data-n=\"3170\">125</sup> כו', ועי\"ז נמשך ממילא אוא\"ס ב\"ה, משא\"כ בלא קבלת עול מלכותו ית' אינו ממשיך כלום כי הוא המרומם לבדו המתנשא מימות עולם<sup data-n=\"3171\">126</sup> רק המלך בלבד שבשביל שהוא מלך כו'<sup data-n=\"3172\">127</sup>, עכ\"ל. ובהביאור שם<sup data-n=\"3173\">128</sup> כי במצות יש ב' בחי' הא' המצוה עצמה לפי שעי\"ז יומשך ונעשה יחוד למעלה ע\"י אתרוג ושופר, ואין זה עבודה שהרי יש לה טעם",[["3154","107","<b>שמים זו תושב\"כ. . וארץ נקרא תושבע\"פ</b>: ראה ערה\"כ לבעל סדה\"ד מערכת שמים. לעיל המשך חייב אדם לברך פכ\"ד ובהערה 884."],["3155","110","<b>למה נק' שמה ארץ שרצתה</b>: ב\"ר פ\"ה, ח. ראה גם שה\"א נד, א ובהערה 5. סה\"מ תרכ\"ט ע' רפא."],["3156","111","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">וארץ אותיות א</a>' רץ</b>: ראה (בנוסף להנחה כאן — לקמן בחלק ההנחות — על יד הערה 153. תו\"א כאן א, ג). מאמרי אדה\"ז תקס\"ה ח\"א ע' רלג. ח\"ב כאן (ע' תשיב). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830257\" data-slug=\"or-hatorah-hb\" data-id=\"8158830257\">אוה\"ת בלק ע' תתקמג</a>."],["3157","112","<b>סוכה שהיא גבוה</b>: משנה סוכה ב, א [ושם גבוהה — ראה שנויי נוסחאות במשניות שם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">תו\"א כאן א, ג</a>. ח\"ש יז, ב. יתרו עד, א. לקו\"ת פינחס עו, ב. ראה עו, ב. שה\"ש מא, ב. מאמרי אדה\"א הנחות תקע\"ז ס\"ע קמה. המשך תער\"ב ח\"א ע' סג. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 150]."],["3158","113","<b>ותושב\"כ. . שמותיו של הקב\"ה</b>: ראה זהר יתרו פז, א. פתיחת הרמב\"ן עה\"ת. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' נב."],["3159","114","<b>קורא בתורה</b>: ברכות י, ב. יג, א (במשנה). ועוד."],["3160","115","<b>בד\"ה לכן אמור לבנ\"י</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370259\" data-slug=\"torah-or\" data-id=\"3901370259\">תו\"א וארא נח, א</a>."],["3161","116","<b>סלסלה ותרוממך</b>: משלי ד, ח."],["3162","117","<b>בביאור ע\"פ כי ביום הזה יכפר</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380195\" data-slug=\"likkutei-torah\" data-id=\"4001380195\">לקו\"ת אחרי כז, ד</a>."],["3163","118","<b>בד\"ה ועתה יגדל נא</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380468\" data-slug=\"likkutei-torah\" data-id=\"4001380468\">לקו\"ת שלח לט, א</a> (ומעתיק לשונו)."],["3164","119","<b>ותגזור אומר ויקם</b>: ראה איוב כב, כח."],["3165","120","<b>אוא\"ס ורצה\"ע ב\"ה</b>: תיבת ב\"ה ניתוספה בין השיטין. בלקו\"ת: אור א\"ס ב\"ה ורצון העליון."],["3166","121","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["3167","122","<b>המצוה</b>: בלקו\"ת: המצות."],["3168","123","<b>ותחת אשר לא עבדת</b>: תבוא כח, מז."],["3169","124","<b>אף</b>: בלקו\"ת ניתוסף: גם."],["3170","125","<b>ושום תשים עליך מלך</b>: פ' שופטים יז, טו."],["3171","126","<b>המרומם. . מימות עולם</b>: ע\"פ ברכת יוצר."],["3172","127","<b>רק המלך. . כו'</b>: בלקו\"ת כאן: כנ\"ל — תיבות אלו מובאים בלקו\"ת לעיל לח, ד."],["3173","128","<b>ובהביאור שם</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a> (ומעתיק לשונו)."]]],[2000450313,"וה\"ז דוגמת רפואה וסגולה כו', ואמנם בחי' ב' נק' מצות המלך בלי טעם גם אלו לא הי' נעשה היחוד עכ\"ז כו'<sup data-n=\"3174\">129</sup> כמו אם<sup data-n=\"3175\">130</sup> אלו נצטוה לחטוב עצים<sup data-n=\"3176\">131</sup> עד\"מ, וזהו<sup data-n=\"3177\">132</sup> מצות המלך שאין לבקש שום טעם כלל, רק קב\"ע כי מאחר שמצד עצם מרומם הוא לבדו כו', והוא בחי' גלגלתא דחפיא על מוחא<sup data-n=\"3178\">133</sup>, ועיקר צד סיבת חיבורו לנבראים הוא מצד היותו מלך כמ\"ש המלך המרומם כו', וא\"כ ממילא מובן שא\"א להמשיכו זולת ע\"י קבעמ\"ש הנ\"ל<sup data-n=\"3179\">134</sup>, ועי\"ז דוקא נמשך ונעשה ג\"כ היחוד למעלה, וזהו משארז\"ל מצות צריכות כוונה<sup data-n=\"3180\">135</sup> דהיינו קבלת עומ\"צ שמצות מלך היא עכ\"ל, וב' בחי' אלו י\"ל שזהו ג\"כ שמים וארץ כמו שבד\"כ תו' היא שמים ומצות ארץ, כן בד\"פ בתו' תושב\"כ שמים ותושבע\"פ ארץ כנ\"ל, וכן במצות טעם המצוה זהו שמים, וקבעמ\"צ זהו ארץ כו').\n<b>ושלשה</b> נקראו ארץ כנס\"י ותו' שבע\"פ ומצות וכולן נרמזין במקרא אחד ארץ ארץ ארץ שמעי דבר ה' בירמי' כ\"ב ך\"ט<sup data-n=\"3181\">136</sup> [וע' בשל\"ה פ' ויחי<sup data-n=\"3182\">137</sup> מ\"ש בענין ג\"פ ארץ וג\"פ היכל ה' המה בירמי' ז' ד' וע' ברע\"מ פ' עקב דער\"ב סע\"ב מענין ג\"פ היכל, והנה ענין תושבע\"פ שנק' ארץ והמצות שנק' ארץ יובן עפמ\"ש בד\"ה וישב יעקב<sup data-n=\"3183\">138</sup> ענין בארץ מגורי אביו היא עסק התשבע\"פ, וענין בארץ כנען הוא מעשה המצות ועמ\"ש בד\"ה וללבן שתי בנות<sup data-n=\"3184\">139</sup> בענין בארצות החיים ב' ארצות כו', ועמ\"ש בביאור ענין המרגלים<sup data-n=\"3185\">140</sup> בפ' שלח שהם ב' בחי' דבור ומעשה, ועמ\"ש בד\"ה לכן אמור לבנ\"י<sup data-n=\"3186\">141</sup> בענין אל הארץ אשר נשאתי את ידי כו', וענין בחי' כנס\"י שנק' ארץ עמ\"ש בביאור ע\"פ ששים המה מלכות<sup data-n=\"3187\">142</sup> כו' אחת היא יונתי ע\"ש בשם המ\"ח<sup data-n=\"3188\">143</sup> ועמ\"ש בד\"ה הבאים ישרש<sup data-n=\"3189\">144</sup> בענין כי תהיו כו' ארץ חפץ, ועמ\"ש בד\"ה לך לך<sup data-n=\"3190\">145</sup> מארצך אל הארץ כו' ועמ\"ש בד\"ה ויגש אליו יהודה<sup data-n=\"3191\">146</sup>, וע' מענין השמים כסאי כו' ברבות בא ר\"פ י\"ז משפטי' תוך פל\"א<sup data-n=\"3192\">147</sup> בחקתי ר\"פ ל\"ו",[["3174","129","<b>עכ\"ז כו'</b>: בלקו\"ת: ועכ\"ז."],["3175","130","<b>אם</b>: בלקו\"ת כאן ליתא."],["3176","131","<b>אלו נצטוה לחטוב עצים</b>: ראה מו\"נ ח\"ג פנ\"א (ד\"ה הערה). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211017\" data-slug=\"likkutei-sichot\" data-id=\"1300211017\">לקו\"ש שמות כרך כא ע' 17</a> הערה 51. וראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 157 שמוסיף: או לשאוב."],["3177","132","<b>וזהו</b>: בלקו\"ת ניתוסף: נק'."],["3178","133","<b>גלגלתא דחפיא על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["3179","134","<b>הנ\"ל</b>: בלקו\"ת: כנ\"ל."],["3180","135","<b>מצות צריכות כוונה</b>: ערובין צה, סע\"ב."],["3181","136","<b>בירמי' כ\"ב ך\"ט</b>: תיבות אלו אינם בתו\"א."],["3182","137","<b>בשל\"ה פ' ויחי</b>: דש, א."],["3183","138","<b>בד\"ה וישב יעקב</b>: אוה\"ת וישב כרך ז ע' 2472 ואילך."],["3184","139","<b>בד\"ה וללבן שתי בנות</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370106\" data-slug=\"torah-or\" data-id=\"3901370106\">תו\"א ויצא כב, ד</a>."],["3185","140","<b>בביאור ענין המרגלים בפ' שלח</b>: לקו\"ת שם לו, א."],["3186","141","<b>בד\"ה לכן אמור לבנ\"י</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370258\" data-slug=\"torah-or\" data-id=\"3901370258\">תו\"א וארא נז, ד</a> ואילך."],["3187","142","<b>ע\"פ ששים המה מלכות</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381286\" data-slug=\"likkutei-torah\" data-id=\"4001381286\">לקו\"ת שה\"ש לט, סע\"ג</a> ואילך."],["3188","143","<b>המ\"ח</b>: נעתק גם לעיל בהמשך וידבר וגו' ויצוום רפ\"ה."],["3189","144","<b>בד\"ה הבאים ישרש</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370240\" data-slug=\"torah-or\" data-id=\"3901370240\">תו\"א שמות נג, ד</a>."],["3190","145","<b>בד\"ה לך לך</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490017\" data-slug=\"or-hatorah-hb\" data-id=\"8316490017\">אוה\"ת לך כרך ד ע' תרעח</a>. ר\"ע 1352. ע' 1358. ע' 1362. ע' 1364. ע' 1380."],["3191","146","<b>בד\"ה ויגש אליו יהודה</b>: תו\"א מג, ג ואילך."],["3192","147","<b>תוך פל\"א</b>: באוה\"ת ישעי' כרך א ר\"ע שיד: פל\"א קרוב לס\"פ דקמ\"ט ע\"ב [בדפוס אמשטרדם שנת ת\"א-ב. ולפנינו סי\"ג] ע\"פ את העני עמך. ראה גם לקמן במאמר ד\"ה אני לדודי על יד הערה 91."]]],[2000450314,"נשא ר\"פ י\"ב<sup data-n=\"3193\">148</sup> ובגמרא פ\"ט דברכות נ\"ט א', פ\"ב דחגיגה די\"ב סע\"א, י\"ד א' י\"ו<sup data-n=\"3194\">149</sup> א', קדושין ל\"א א', פ\"ק דסנהדרין ז' א', אבות ס\"פ שנו חכמים].\n<b>ועפ\"ז</b> יובן ענין ב\"ג וב\"ר שאמרו ואתנו אחוזת נחלתינו כו', דהנה נת' שענין הארץ הוא בחי' מעהמ\"צ בגשמיות וזהו הדום רגלי, וז\"ע מצות התלוי' בארץ להיות כי ארץ היא בחי' מל'<sup data-n=\"3195\">150</sup> יורדת לברר בירורי' דבי\"ע וכמ\"ש רגלי' יורדות, וכתי' ותקם בעוד לילה ותתן טרף<sup data-n=\"3196\">151</sup> בכדי להעלות רפ\"ח ניצוצין<sup data-n=\"3197\">152</sup>, וכן כל המצות שהם ג\"כ שלוחים מלאכי אלקים כמ\"ש בדרושי יוהכ\"פ בד\"ה לבאר ענין יוהכ\"פ<sup data-n=\"3198\">153</sup> פ\"ב, שהם עולים ויורדי' בסולם בכדי להעלות הניצוצות, וכמארז\"ל לא ניתנו המצות אלא לצרף בהם את הבריות<sup data-n=\"3199\">154</sup> שנת' מזה בכ\"ד, והבירור שבא\"כ<sup data-n=\"3200\">155</sup> הוא הבירור היותר מהיר להיות כי שם הי' ז' אומות הכנעני שרש זמה\"ר<sup data-n=\"3201\">156</sup> שבאדם כו' כמ\"ש במ\"א, משא\"כ בעבר הירדן שזהו רק פרטים כו', אבל ב\"ג וב\"ר חשבו שבעבר הירדן הוא בירור יותר חשוב להיותם רחוקים יותר מקדושה, שהרי בא\"כ עכ\"פ דורש אותה, ותמיד עיני ה' אלקיך בה, ולכן גלו תחילה שבירור זה הרחוק אינו ע\"י קרבת אלקים שטוב לי<sup data-n=\"3202\">157</sup> ע\"ד קרבנות וכדומה כ\"א ע\"ד ג'<sup data-n=\"3203\">158</sup> כענין לא זרועה דמדבר, כן כתי' לא מאסתים ולא<sup data-n=\"3204\">159</sup> כו' ג\"כ בחי' לא, ולכן הזכיר להם משה חטא המרגלי', שלפי שחשב משה שרצו לישאר ולא לילך בכבישת א\"כ ה\"ז דומה למרגלים, אבל כשהתנצלו שרצונם להמתין גם אחר החלוקה, נתרצה, ומשה א' רק לאחר הכיבוש",[["3193","148","<b>נשא ר\"פ י\"ב</b>: לקמן במאמר ד\"ה אני לדודי על יד הערה 87 ובאוה\"ת ישעי' שם: נשא פי\"ב קרוב לר\"פ דרמ\"ו ג' [בדפוס אמשטרדם שנת ת\"א-ב. ולפנינו ס\"ג]."],["3194","149","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370066\" data-slug=\"torah-or\" data-id=\"3901370066\">י\"ו</b>: לקמן במאמר ד</a>\"ה אני לדודי על יד הערה 85 מציין: ודט\"ז. אבל כ\"ה בכ\"מ בכתבי הצ\"צ. ומהם: לעיל מאמר ד\"ה ואשא אתכם על יד הערה *92 ועל יד הערות 147-8. לקמן מאמר ד\"ה גדול יהי' על יד הערה 76. תו\"א וירא יד, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380059\" data-slug=\"likkutei-torah\" data-id=\"4001380059\">לקו\"ת פקודי ד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">ז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380100\" data-slug=\"likkutei-torah\" data-id=\"4001380100\">ויקרא ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380167\" data-slug=\"likkutei-torah\" data-id=\"4001380167\">תזריע כא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380208\" data-slug=\"likkutei-torah\" data-id=\"4001380208\">קדושים ל, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380433\" data-slug=\"likkutei-torah\" data-id=\"4001380433\">בהעלותך ל, ד</a>. ועוד. שה\"ש יג, ד (ב\"פ). אוה\"ת בא ע' שיד. בשלח ע' שנד. ישעי' ע' קפה. ע' רלו וע' שיב."],["3195","150","<b>ארץ. . מל'</b>: ראה זהר תוספתא בראשית לא, ב."],["3196","151","<b>ותקם בעוד לילה ותתן טרף</b>: משלי לא, טו. ראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ע' שצה ואילך. תקס\"ה ח\"ב ע' תתקמח (הובא לקמן במאמר ד\"ה שיר המעלות ממעמעקים על יד הערה 52. ו(בחלק ההנחות) בהנחה שם על יד הערה 40). ע' תתקמט בשם כהאריז\"ל (הובא לקמן שם ובהערה 64). תקס\"ח ח\"א ס\"ע תקמט ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550441\" data-slug=\"torat-chaim\" data-id=\"2300550441\">תו\"ח יתרו ח\"ב ערב, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600645\" data-slug=\"or-hatorah-hb\" data-id=\"8316600645\">אוה\"ת לך כרך ד ס\"ע 1452</a> ואילך. משלי כרך א ס\"ע תרמה ואילך."],["3197","152","<b>רפ\"ח ניצוצין</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["3198","153","<b>בד\"ה לבאר ענין יוהכ\"פ</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו\"ת יוכ\"פ סח, ב</a>."],["3199","154","<b>לא ניתנו המצות אלא לצרף בהם את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. לעיל המשך אם כסף תלוה פי\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171426\" data-slug=\"likkutei-sichot\" data-id=\"1300171426\">לקו\"ש אבות כרך יז ע' 415</a> הערה 53. שופטים כרך יט ע' 182 הערה 42."],["3200","155","<b>שבא\"כ</b>: שבארץ כנען."],["3201","156","<b>ז' אומות. . זמה\"ר</b>: ראה מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. ש\"א סא, ב ובהערה 20. סה\"מ תר\"ל ע' רפח."],["3202","157","<b>קרבת אלקים שטוב לי</b>: ע\"פ תהלים עג, כ."],["3203","158","<b>ג'</b>: גלות."],["3204","159","<b>לא מאסתים ולא</b>: בחוקותי כו, מד."]]],[2000450315,"להיות כי אחר שיתחילו ישראל לברר א\"כ יוקל להם הבירור בעבר הירדן, ע\"ד התפלה בבית בשעה שהצבור מתפללין<sup data-n=\"3205\">160</sup>, והם הוסיפו עוד ז' שנים דחלוקה שזהו גמר התחלת הבירור כל אחד חלקו, ותלוי בפלוגתא חז\"ל אם יש ברירה א\"ל<sup data-n=\"3206\">161</sup>, ולכן גם קודם שידעו טיבה של א\"כ עכ\"ז רצו בעבר הירדן שלפי סברתם זהו בירור יותר גדול, ולכן אמרו אחוזת נחלתינו ולא נחלה להיות כי זהו בח\"ל<sup data-n=\"3207\">162</sup> אמרו לשון אחוזה ע\"ד דכתי' בגשן ויאחזו בה<sup data-n=\"3208\">163</sup>, שא\"ז כ\"א אחיזה לבד ולא השייך באמת ולכן ביחזקאל<sup data-n=\"3209\">164</sup> נחלקו א\"כ לכולם כו', וכ\"ז מפני ומקנה רב, מקנה זהו בחי' צאן אדם<sup data-n=\"3210\">165</sup> כו' רב ע\"ד שארז\"ל כל רב מבבל בחי' טורי דפרודא<sup data-n=\"3211\">167</sup> לכן בררו אחוזת נחלתם בעבר הירדן ולא בא\"כ שכל רבי מא\"כ<sup data-n=\"3212\">166</sup> כו' ששם מאיר יו\"ד חכ' ביטול בעצם כו'.",[["3205","160","<b>התפלה בבית בשעה שהצבור מתפללין</b>: ראה שו\"ע אדה\"ז הל' תפלה ס\"צ, ס\"י."],["3206","161","<b>אם יש ברירה א\"ל</b>: ראה ערובין לו, ב. לז, ב. חולין קלה, ב. ועוד."],["3207","162","<b>בעבר הירדן. . זהו בח\"ל</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן: שאינה א\"י. אוה\"ת מטות ע' א'שמ. סה\"מ תרכ\"ט ע' רפב. וש\"נ."],["3208","163","<b>ויאחזו בה</b>: ויגש מז, כז."],["3209","164","<b>ביחזקאל</b>: מז, יג ואילך. מח."],["3210","165","<b>צאן אדם</b>: ראה יחזקאל לד, לא. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 178."],["3211","167","<b>טורי דפרודא</b>: זהר בראשית כט, ב. ויצא קנח, א. פקודי רלד, סע\"א."],["3212","166","<b>כל רב מבבל. . רבי מא\"כ</b>: ראה אוה\"ת נ\"ך כרך ב ע' א'מו. וש\"נ. מאמרי אדה\"ז תקס\"ח ח\"א ע' צד ואילך. אוה\"ת ואתחנן ע' עו. סה\"מ תרכ\"ז ע' ריג. תר\"ל ע' לה."]]],[2000450316,"<h3>גדול יהי' כבוד כו' אי זה בית כו'</h3>\n<b></b><b>בס\"ד ש\"ח ל\"ח, חגי ב' ט'</b>\nחצר כו' מאדך\nשבת חזון\n<b>גדול</b> יהי' כבוד הבית הזה<sup data-n=\"3213\">1</sup> האחרון מן הראשון<sup data-n=\"3214\">2</sup>. הנה רז\"ל בב\"ב ד\"ג ע\"א פי' זה על ב\"ש, וכן הוא פי' הפשוט<sup data-n=\"3215\">3</sup>, אמנם בזהר בראשית דך\"ח ע\"א<sup data-n=\"3216\">4</sup> פי' על לע\"ל",[["3213","1","<b>גדול יהי' כבוד הבית הזה</b>: דרוש הרביעי מההמשך המבאר ד\"ה השמים כסאי שב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a> (וביאוריו) כמצויין לעיל ברד\"ה ואשא אתכם.\nמאמר זה מבאר פסקא האחרונה שבדרוש הנ\"ל ד<a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">תו\"א א, ג</a> ד\"ה אך אי זה בית.\nהכותרת שבריש המאמר: ”בס\"ד ש\"ח [ שבת חזון] ל\"ח, חגי ב' ט'\" נעתקה מבוך 1162 ואינה מופיעה בבוך זה 1089. אודות ביכלאך אלו ראה המצויין לעיל בריש ד\"ה ואשא אתכם.\nהמאמר (מלבד הפתיחה, וכן איזה הערות שנכתבו בגוכתי\"ק) הוא לשון התו\"א עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע, וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש כמצויין בפרטיות בריש ההמשך (ד\"ה ואשא אתכם).\nהמאמר מלבד הפתיחה נדפס גם בלקו\"ת לג\"פ ג, ד. אוה\"ת בראשית כרך ו ע' תתרכח.\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות.\nמאמר זה נזכר לקמן במאמר ד\"ה על חומותיך על יד הערה 108. ד\"ה אני לדודי על יד הערות 29-27."],["3214","2","<b>גדול יהי'. . האחרון מן הראשון</b>: חגי ב, ט — כנ\"ל בהכותרת."],["3215","3","<b>פי' הפשוט</b>: מפרשים לחגי שם."],["3216","4","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051074\" data-slug=\"likkutei-sichot\" data-id=\"1300051074\">דך\"ח ע\"א</a></b>: ובד\"ה גדול יהי' מש\"פ מטו\"מ שנת תשכ\"ב [קונ' שבת נחמו תש\"נ — סה\"מ מלוקט ד ע' שלג] הערה 4 מוסיף: תקו\"ז תיקון ח. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051074\" data-slug=\"likkutei-sichot\" data-id=\"1300051074\">לקו\"ש לך כרך ה ע' 62</a> הערה 46. ח\"ש כרך י ע' 211 ס\"ד (אג\"ק שלו ח\"ב ע' ד וע' כג)."]]],[2000450317,"ע\"ש. ובזה לא שייך פלוגתא דרב ושמואל<sup data-n=\"3217\">5</sup> אם בבנין או בשנים כי בשניהם יהי' גדול כמ\"ש ביחזקאל<sup data-n=\"3218\">6</sup>, ויהי' נצחי<sup data-n=\"3219\">7</sup> כו', והוא ע\"י העבודה דעכשיו בבחי' השמים כסאי זו תורה, והארץ הוא מעהמ\"צ הם הדום רגלי כמשנ\"ת בד\"ה ומקנה רב<sup data-n=\"3220\">8</sup> ע\"ש. אבל בחורבן בהמ\"ק כתי' השליך משמים ארץ<sup data-n=\"3221\">9</sup> תפארת ישראל ולא זכר הדום רגליו, פי' כי תפארת ישראל היא שהשמים כסאי והארץ הדום רגלי, וכמ\"ש בת\"א בד\"ה כי עמך מקו\"ח<sup data-n=\"3222\">10</sup> בפי' השקיפה כו' מן השמים וברך כו' שבבחי' זו אנו נתראים לדבר גדול כו' וה\"ז תפארת ישראל, אמנם בחורבן הבית ארז\"ל וויתר הקב\"ה<sup data-n=\"3223\">11</sup> על כו' ולא וויתר על ביטול תורה כו', כמשנ\"ת מזה בד\"ה ושננתם<sup data-n=\"3224\">12</sup> באורך, ולכן השליך משמים ארץ, ולא זכר הדום רגליו כו'.\n<b>ולהבין</b> זה צ\"ל מ\"ש בסיפא דקרא, אי זה בית<sup data-n=\"3225\">13</sup> כו', כי הכסא והשרפרף אין דרכן להעמידן בחוץ אלא בתוך הבית ובחי' בית היינו בכל מאדך<sup data-n=\"3226\">14</sup> שהוא בבחי' מקיף כמו עד\"מ בית שהוא מקיף את האדם בגגו ובקירותיו [ועמ\"ש בד\"ה מזמור שיר חנוכת הבית<sup data-n=\"3227\">15</sup>] (וכמו\"כ בחי' בכל מאדך מאחר שהיא למעלה מהגבלת הכלי ה\"ז יצא מכלל או\"פ ונשאר בבחי' מקיף כו', ולמעלה בחי' בית בכלל נק' בית תפילה כמ\"ש כי ביתי בית תפילה יקרא<sup data-n=\"3228\">16</sup> וכן בעבודת האדם) בית זה הוא בית תפלה שע\"י התפלה ח\"י פעמים ברוך אתה כו' היא המשכת מקיפי' מבחי' סוכ\"ע [והיא בחי' רוחו ונשמתו אליו יאסוף כנ\"ל]<sup data-n=\"3229\">17</sup> שהם נמשכין ע\"י כריעות והשתחויות באבות ובהודאה תחלה וסוף שהם בחי' ביטול [ועמ\"ש בד\"ה יהודה אתה<sup data-n=\"3230\">18</sup>], (והנה כדי לבוא לבחי' זו דבית תפלה, יש קודם ב' בחי' חצירים, כמ\"ש אשרי תבחר ותקרב ישכון חצירך<sup data-n=\"3231\">19</sup>, ל' רבים,",[["3217","5","<b>פלוגתא דרב ושמואל</b>: ב\"ב שם. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161007\" data-slug=\"likkutei-sichot\" data-id=\"1300161007\">לקו\"ש שמות כרך טז ע' 7</a> הערה 52."],["3218","6","<b>בבנין. . כמ\"ש ביחזקאל</b>: פ\"מ ואילך."],["3219","7","<b>בשנים. . ויהי' נצחי</b>: ראה זהר פינחס רכא, א. בראשית כאן כח, א. תקו\"ז תיקון ח ובניצוצי זהר שם. עט\"ר ע' כו."],["3220","8","<b>בד\"ה ומקנה רב</b>: המאמר שלפנ\"ז (בד\"ה והנה להיות)."],["3221","9","<b>השליך משמים ארץ</b>: איכה ב, א."],["3222","10","<b>בת\"א בד\"ה כי עמך מק\"ח</b>: פ' מקץ לה, א."],["3223","11","<b>וויתר הקב\"ה</b>: ראה ירושלמי חגיגה פ\"א, ה\"ז. פתיחתא דאיכ\"ר ב."],["3224","12","<b>בד\"ה ושננתם</b>: ראה מאמרי אדה\"ז תקס\"ז ע' שח ואילך. ע' שיד ואילך. אמ\"ב שער הק\"ש עו, ד ואילך. פא, ב ואילך. אוה\"ת ואתחנן ע' רמו ואילך. ע' רפז ואילך. סה\"מ תרל\"ו ח\"ב ע' רצז ואילך. ע' תקמד ואילך."],["3225","13","<b>אי זה בית</b>: ישעי' סו, א."],["3226","14","<b>בכל מאדך</b>: ואתחנן ו, ה."],["3227","15","<b>בד\"ה מזמור שיר חנוכת הבית</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381122\" data-slug=\"likkutei-torah\" data-id=\"4001381122\">לקו\"ת ברכה צח, ד</a> ואילך."],["3228","16","<b>כי ביתי בית תפילה יקרא</b>: ישעי' נו, ז. ראה גם לקמן מאמר ד\"ה זה עני ובהערה 64."],["3229","17","<b>[והיא. . כנ\"ל]</b>: נמצא בתו\"א כאן."],["3230","18","<b>בד\"ה יהודה אתה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370207\" data-slug=\"torah-or\" data-id=\"3901370207\">תו\"א מה, ג</a>."],["3231","19","<b>אשרי תבחר ותקרב ישכון חצירך </b>[ב: חציריך]: תהלים סה, ה."]]],[2000450318,"וכתי' כלתה נפשי לחצרות הוי'<sup data-n=\"3232\">20</sup> ג\"כ לשון רבים, והענין הוא כנודע שיש ב' בחי' חצר, היינו חצר החיצונה וחצר הפנימית אשר בו בית המלך, ולכן לא יבא איש בתוכו אשר לא יקרא ואחת דתו<sup data-n=\"3233\">21</sup> כו' כמ\"ש במג\"א, משא\"כ בחצר החיצונה שהכל יכולים לכנוס בו כו', וגם מובן אשר ליכנס בבית המלך א\"א כ\"א ע\"י ב' חצרים הנ\"ל, ויובן ד\"ז בעבודה בנפש האדם ע\"פ מ\"ש בפ' ראה<sup data-n=\"3234\">22</sup> בד\"ה כי תשמע בקול פ\"ב, דחצר החיצונה הוא בחי' פסוד\"ז, וחצר הפנימיות הוא ק\"ש, כי בפסוד\"ז נז' גדולתו ית' שהוא מחי' ומהוה עולמות ומלאכי' כמ\"ש הללו את ה' מן השמים<sup data-n=\"3235\">23</sup> כו' מן הארץ<sup data-n=\"3236\">24</sup> כו', הללוהו ברקיע עוזו<sup data-n=\"3237\">25</sup>, וקרי\"ס נס נפלא בעוה\"ז כו', אשר מקור חיותן נק' חצר החיצונה כו', אבל ק\"ש קבעומ\"ש ועול מצות זהו בחי' חצר הפנימיות הפונה קדים<sup data-n=\"3238\">26</sup>, קדמונו של עולם<sup data-n=\"3239\">27</sup>, והמלך ישב על כסא מל' בבית המ'<sup data-n=\"3240\">28</sup> הוא שמו\"ע ביטול, ומשם ויושט המלך את שרביט הזהב<sup data-n=\"3241\">29</sup> רשפי אש האהבה, כמעלת הזהב כו' לבחי' חצר הפנימיות שיתגלה גם בק\"ש בקיום ואהבת<sup data-n=\"3242\">30</sup>, וזהו אשרי תבחר כו' חצירך ב' חצירות הנ\"ל והדר נשבעה בטוב ביתך כו', וזהו בדרך פרט בתפלה, ואמנם בעבודת האדם בכלל ההפרש בין בית לחצר<sup data-n=\"3243\">31</sup> כי אם<sup data-n=\"3244\">32</sup> היות ששניהם נעשו מאבנים, שגדר החצר הוא ג\"כ מאבנים כמו בית, עכ\"ז יש הפרש גדול ביניהם, והוא שהבית הוא מקורה בגג, והחצר הוא בלתי מקורה, והנה כמו בחצר שבלתי מקורה הוא יורדי' גשמי' בתוכו, ועוף הפורח שוכן בתוכו כו', כן עד\"ז יובן בעבודת האדם בעסקו בתפלה ותו' יש מי שמשים שכלו רק לבחי' האותיות לבד, ואם היות כי גם זו דרך ישרה, שיראה שיאמר הצירופי תיבות כמו שהם באותיותיהם ודקדוקיהם וכמ\"ש בטור ובש\"ע או\"ח<sup data-n=\"3245\">33</sup> בפרטי דקדוקי ק\"ש ושאר התפלה שלפני' ולאחרי', עכ\"ז א\"ז עבודה תמה, כי להיות שבזה מלובש רק כח המחשבה לבד בלתי כח השכל והשכל פנוי, הרי יכול ליפול בשכלו מחשבות זרות רבות ורעות הטורדות ומבלבלות מוחו עד שנעשה מוחו ולבו בל עמו כו', וה\"ז כמו החצר הבלתי מקורה שהגשמי' יורדי' לתוכו והעופות שוכנים שם, ולכן מי שהוא בר שכל יעמיק דעתו ושכלו עד מקום",[["3232","20","<b>כלתה נפשי לחצרות הוי'</b>: תהלים פד, ג."],["3233","21","<b>אשר לא יקרא ואחת דתו</b>: ע\"פ אסתר ד, יא."],["3234","22","<b>בפ' ראה</b>: בלקו\"ת שם כג, ב."],["3235","23","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["3236","24","<b>מן הארץ</b>: תהלים שם, ז."],["3237","25","<b>הללהו ברקיע עוזו</b>: שם קנ, א."],["3238","26","<b>חצר הפנימיות הפונה קדים</b>: יחזקאל מו, א."],["3239","27","<b>קדים קדמונו של עולם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370395\" data-slug=\"torah-or\" data-id=\"3901370395\">תו\"א ויקהל פז, ד</a>. סה\"מ תרכ\"ז ע' עה. וראה גם שה\"א קב, א ובהנסמן בהערות לשם."],["3240","28","<b>והמלך ישב. . המ'</b>: לקמן על יד הערה 41 ובאוה\"ת בראשית כאן ע' 2056: יושב — אסתר ה, א."],["3241","29","<b>ויושט המלך את שרביט הזהב</b>: אסתר ה, ב־ ח, ד [בדילוג]."],["3242","30","<b>ואהבת</b>: ואתחנן ו, ה."],["3243","31","<b>ההפרש בין בית לחצר</b>: להבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380342\" data-slug=\"likkutei-torah\" data-id=\"4001380342\">לקו\"ת במדבר ח, ג</a> פ\"ב (צויין בסמוך בפנים על יד הערה 37). מאמרי אדה\"ז על ענינים ע' קכד ואילך."],["3244","32","<b>אם</b>: כ\"ה בכ\"מ בדרושי כ\"ק אדמו\"ר מהר\"ש — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["3245","33","<b>בטור ובש\"ע או\"ח</b>: הל' ק\"ש סס\"א. וראה גם להבא לקמן (בנוסף על הערה 31). לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 56 ואילך. שער היחוד ע' קיב ובהנסמן במ\"מ לשם. יחידות א' כ\"ו שבט תשכ\"א."]]],[2000450319,"שיד שכלו ועמקות תבונתו מגיע לפי' המלות שבתפלה ונושא הענין אחר העיון היטב בבחי' התקשרות והתלהטות היטב מתוך תוך פנימיות נקודת לבבו כו', ובחי' זו נק' בית שכמו שהבית הוא פנימי וגם מקורה היטב שלא יכנסו גשמי' בתוכו וכן העופות עד\"מ לא ישכנו שמה בלתי רשות בעה\"ב, כן לא יכנסו מחשבות זרות ולא יעלה על לבו שום דבר המתאוה כ\"א יהי' קשור ודבוק באלקים חיים ומלך עולם<sup data-n=\"3246\">34</sup> ע\"י התפלה שהיא מל' התופל כלי חרס<sup data-n=\"3247\">35</sup>, או צמיד פתיל<sup data-n=\"3248\">36</sup>, והיינו דבוק וקשור כו', וגם פי' המלות בתפלה כפי פשוטו נק' בתי' והיכלות דעשייה, כמ\"ש בפ' במדבר<sup data-n=\"3249\">37</sup> בד\"ה וארשתיך לי ספ\"ב, וזהו כלתה נפשי לחצרות ה' הם ב' בחי' חצרות הנ\"ל שדרך בם יוכל לכנוס לבית תפלה ששם בית המ' מש\"ע<sup data-n=\"3250\">38</sup>, ע\"י בחי' הביטול בכריעות והשתחואות וע' בד\"ה ועשו לי מקדש<sup data-n=\"3251\">39</sup> בענין השתחואות דתפילה באורך כו'.\n<b>ואמנם</b> עדיין צ\"ל הלא גם חצר הפנימיות איננו מקורה ולפי משל הנ\"ל הרי הגשמי' יורדים בתוכו כו' וא\"כ מה יועיל בחי' עמקות דעתו ופנימיותו מאחר שאינו מקורה כו'. אך הענין יובן ממ\"ש במג\"א אשר יבא אל המ'<sup data-n=\"3252\">40</sup> אל החצר הפנימי' כו' אחת דתו כו', וא\"כ שוה חצר הפנימיות לבית, דהא בבית יש ג\"כ דלתות המשמשי' כניסה ויציאה, ועכ\"ז לא יכנס למלך בלתי רשות שהוא מחמת פחד וביטול מהמלך וכן חצר הפנימיות היא ג\"כ שוה לענין זה, ולכן אם היותו בלתי מקורה עכ\"ז אין רשות להמפילים מחשבות זרות והרהורי' רעים לכנוס שם כלל וממילא לא יבלבלוהו מעסק התדבקות באלקים חיים באמרו ק\"ש שוה כמו ביטול דתפלה כו', וה\"ז כמו ממוצע בין חצר החיצונה ובין בית, וכח חצר זה נמשך מתפלה שנק' בית כנ\"ל, וכמובן ממ\"ש במג\"א, והמ' יושב כו' בבית כו' נוכח פתח הבית<sup data-n=\"3253\">41</sup>, שלכאו' לל\"ל נוכח פתח כו' אלא להגיד לנו מאין נמשך כח זה בחצר הפנימיות הלא איננו מקורה כו' אלא שזהו מפני שהמל' מלכו ש\"ע יושב נגד הפתח שפתוחה לחצר הפנימי' שהיא פונה קדים כנ\"ל כו').",[["3246","34","<b>באלקים חיים ומלך עולם</b>: ע\"פ ירמי' י, י."],["3247","35","<b>התפלה. . התופל כלי חרס</b>: כלים פ\"ג, מ\"ה. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370355\" data-slug=\"torah-or\" data-id=\"3901370355\">תו\"א תרומה עט, סע\"ד</a>. מאמרי אדה\"ז תקע\"א ע' פ. מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' מח. סה\"מ תרכ\"ט ע' כח וע' תא. תרמ\"ד ע' רטו. תער\"ב ח\"א ע' תריח. ח\"ב ע' תשפו. תש\"ט ע' 79 (הב') בהערה. ד\"ה באתי לגני תש\"ל פי\"א בהערה (קונ' יו\"ד שבט תש\"נ — סה\"מ מלוקט ד ע' קמה). לקו\"ש ח\"י אלול כרך כ\"ד ע' 315."],["3248","36","<b>צמיד פתיל</b>: חוקת יט, טו. ראה גם סה\"מ תרכ\"ז ע' עב."],["3249","37","<b>בפ' במדבר</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380110\" data-slug=\"likkutei-torah\" data-id=\"4001380110\">לקו\"ת שם ח, ג</a>."],["3250","38","<b>המ' מש\"ע</b>: המלך מלכו של עולם."],["3251","39","<b>בד\"ה ועשו לי מקדש</b>: לקמן על יד הערה 51 מציין תרט\"ו — אוה\"ת תרומה ע' א'תכו ואילך. וראה שם ע' א'תלה ואילך. וראה גם ד\"ה אדם כי יקריב במאמרי אדמו\"ר הצ\"צ תרט\"ו ע' רלה."],["3252","40","<b>אשר יבא אל המ'</b>: אסתר ד, יא [ושם: יבוא]."],["3253","41","<b>והמ' יושב. . הבית</b>: אסתר ה, א."]]],[2000450320,"<b>והענין</b> כי א\"א להיות גילוי אור א\"ס ב\"ה דלית מח' תב\"כ<sup data-n=\"3254\">42</sup> ולאו מכל מדות<sup data-n=\"3255\">43</sup> וכו' בבחי' פנימיות הלב רק מעט מזעיר הארה בעלמא, ואפילו גילוי במוח והשגה דלית<sup data-n=\"3256\">44</sup> מחשבה כו' (וכנ\"ל שבחצר הפנימיות מאיר הארת המ' היושב בבית המל', ומ\"מ הוא רק הארה לבד כו') רק בבחי' מקיף וסובב לבד וע\"ז נא' ואל זה אביט<sup data-n=\"3257\">45</sup> שרומז על בחי' תפלה, ופי' הפסוק ואת כל אלה ידי עשתה<sup data-n=\"3258\">46</sup> בחי' עשיה היינו מעשה המצות, ויהיו כל אלה נאם ה' היא בחי' תושבע\"פ שהיא נאם ודבר ה' בחי' דבור, משא\"כ אל זה אביט הוא בחי' תפלה אביט הוא בחי' הבטה הוא<sup data-n=\"3259\">47</sup> הסתכלות בבחי' עיניך יונים<sup data-n=\"3260\">48</sup> שהיא בחי' המח' לבד והיא היא בחי' מקיף וסובב כמו עד\"מ מחשבה שמקפת מחשבתו את הדבר שחושב עליו וכן הראי' והסתכלות כו', משא\"כ דבור ומעשה הם פנימיים כו', והבטה זו היא אל עני ונכה רוח בחי' ביטול דלית לי' מגרמי' כלום אפי' תורה ומצות (פי' שאינו מחזיק טובה לעצמו במה שמקיים תומ\"צ כי לכך נוצרת כמארז\"ל במשנה דאבות<sup data-n=\"3261\">49</sup> ), לפי שהמשכה זו א\"א להשיג ע\"י התומ\"צ שהם פנימי' רק ע\"י ביטול בתפלה וכריעות והשתחוואות כמשל המלך שכורעים ומשתחוים לו מפני שא\"א להתקרב אליו מגודל מעלתו (דהנה בעשיית דבר מצוה, ע\"י שמקיים רצה\"ע הרי עי\"ז נעשה קצת קירוב בין האדם המצווה ועושה בין הפרט רצון שבציוי, ואפי' עם בעל הרצון<sup data-n=\"3262\">50</sup> מקור כל רצונות הפרטיים, משא\"כ כריעות והשתחואות מלבד מה שמורה על ביטולו לגמרי כמ\"ש בד\"ה ועשו לי מקדש (תרט\"ו)<sup data-n=\"3263\">51</sup> שה\"ע ביטול ע\"י כפיפת כל קומתו שמשפיל ראשו שוה לגופו ע\"פ שטח הארץ, הנה בד\"ז הכל שוין קטן וגדול והיינו מפני העדר תפיסתו כו', ואינו דומה לעשיית מצוה שזהו קירוב והתראותו לדבר חשוב שהוא מקיים רצון בוראו, רק שבחי' קבעמ\"ש שקדם כמשנ\"ת בד\"ה ומקנה רב<sup data-n=\"3264\">52</sup> לכאו' י\"ל ששוה להשתחואה דשמו\"ע, ומ\"מ אינו דומה שזהו במוח, וזה בכל גופו בפועל כמשרז\"ל עד שיראה איסר<sup data-n=\"3265\">53</sup>, וגם עד שיתפקקו חוליותיו<sup data-n=\"3266\">54</sup> כו') אזי ממילא נמשך אליו בחינה זו, וזהו ברוך אתה כלומר ברוך מעצמך ומאיליך<sup data-n=\"3267\">55</sup> [ועמ\"ש בד\"ה שימני כחותם<sup data-n=\"3268\">56</sup>].",[["3254","42","<b>דלית מח' תב\"כ</b>: ראה ת\"ז בהקדמה יז, א."],["3255","43","<b>ולאו מכל מדות</b>: ראה ת\"ז שם, ב."],["3256","44","<b>דלית</b>: בתו\"א כאן: לית."],["3257","45","<b>ואל זה אביט</b>: ישעי' סו, ב."],["3258","46","<b>ואת כל אלה ידי עשתה</b>: התחלת הכתוב ואל זה אביט."],["3259","47","<b>הוא</b>: בתו\"א כאן: היא."],["3260","48","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א. ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 78."],["3261","49","<b>במשנה דאבות</b>: פ\"ב, מ\"ח."],["3262","50","<b>בעל הרצון</b>: ראה גם בענין בעל הרצון לקמן (בחלק ההנחות) הנחה ד\"ה ביום ההוא יהי' ובהערה 20."],["3263","51","<b>בד\"ה ועשו לי מקדש (תרט\"ו)</b>: אוה\"ת תרומה ע' א'תכז. וראה גם ד\"ה אדם כי יקריב במאמרי אדמו\"ר הצ\"צ תרט\"ו ע' רלד. סה\"מ תרל\"ב ח\"א ע' עג."],["3264","52","<b>בד\"ה ומקנה רב</b>: שנדפס לפנ\"ז (ד\"ה והנה להיות)."],["3265","53","<b>עד שיראה איסר</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380668\" data-slug=\"likkutei-torah\" data-id=\"4001380668\">לקו\"ת</a> דלהלן. ראה ברכות כח, ב. ראה גם תו\"א ח\"ש טז, סע\"ב. לקו\"ת מטות פו, סע\"ג. תורת לו\"י ע' רסח."],["3266","54","<b>עד שיתפקקו חוליותיו</b>: ראה ברכות כח, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380636\" data-slug=\"likkutei-torah\" data-id=\"4001380636\">לקו\"ת פינחס עט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670447\" data-slug=\"torat-chaim\" data-id=\"2300670447\">תו\"ח נח נד, ב</a>."],["3267","55","<b>ומאיליך</b>: כ\"ה בבוך 1089. אבל בבוך 1162 ובתו\"א: ומאליך."],["3268","56","<b>בד\"ה שימני כחותם</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381310\" data-slug=\"likkutei-torah\" data-id=\"4001381310\">לקו\"ת שה\"ש מה, ג</a>. סידור שער התפילין טז, ב."]]],[2000450321,"<b>והנה</b> בבחינה זו של המשכת המקיף כתיב לא הביט און ביעקב<sup data-n=\"3269\">57</sup>, שבבחי' פנימיות כתיב בוחן לבות וכליות<sup data-n=\"3270\">58</sup> דהיינו להבחין התשוקה המורגשת אם הוא מקרב איש ולב עמוק<sup data-n=\"3271\">59</sup> באמת לאמתו, משא\"כ בבחי' מקיף לא הביט און וגו' רק ה' אלהיו עמו שנמשך מאליו תמיד [ועמ\"ש מזה בד\"ה ארדה נא ואראה<sup data-n=\"3272\">60</sup> (הכוונה על ד\"ע שאינו מכריח הבחירה ע\"ש, ולכאו' צ\"ל הלא חו\"ב הם פנימי', ונמצא כי בהם בוחן דוקא, ובד\"ע שבכלל זהו דעת המחבר חו\"ב שם לא הביט, אך המעיין בד\"ה וככה<sup data-n=\"3273\">61</sup> בענין דעת ידיעה דע וידעת שנת' שם לק\"מ שבאמת דעת זה הוא מבחי' גבוה שבכתר, שלמעלה משרש חו\"ב ג\"כ ע\"ש באורך), ובביאור ע\"פ לבבתיני<sup data-n=\"3274\">62</sup>. והנה עד\"ז יובן מה שבחורבן בהמ\"ק נאמר השליך משמים ארץ כו' ולא זכר הדום רגליו כו'. וע' מזה בפ' ויחי דרי\"ט סע\"א וכד האי ארץ אתרחקא משמים דלעילא כו', ודרל\"ח א' ע\"פ הבט משמים<sup data-n=\"3275\">63</sup> כו', ודרמ\"ב ב' ע\"פ עד די<sup data-n=\"3276\">64</sup> כרסוון רמיו כו' תרין כורסוון<sup data-n=\"3277\">65</sup> ירושלים<sup data-n=\"3278\">66</sup> ואינון מארי דאורייתא, ירושלים יראה שלם<sup data-n=\"3279\">67</sup> שהיראה עכשיו בגלות כמ\"ש בהערה לתיקון חצות<sup data-n=\"3280\">68</sup>, וכולהו לא נפלו אלא מעלבונה דאוריי'<sup data-n=\"3281\">69</sup>, והיינו משארז\"ל ולא ויתר על ביטול תורה, והיינו כי כשעוסקי' בתורה ממשיכים להיות השמים בחי' כסא לאור א\"ס ב\"ה ממש ומאירי' בהן מוחין דגדלות השמים מספרים<sup data-n=\"3282\">70</sup> כו' ועי\"ז והארץ הדום כו' וכמ\"ש בפ'<sup data-n=\"3283\">71</sup> יתרו דפ\"ה סע\"ב ע\"פ אני אענה את השמים<sup data-n=\"3284\">72</sup> ועי\"ז והם יענו את הארץ כו', משא\"כ כשאין עוסקי' בתורה ואין מאירים מוחין דגדלות בהמדות אזי אין מתקיים מ\"ש אני אענה את השמים וממילא השליך משמים ארץ וכ<sup data-n=\"3285\">74</sup>מ\"ש באדר\"ז דרצ\"ג סע\"ב מ\"ט השליך משמים ארץ משום דכתי' אלביש שמים קדרות<sup data-n=\"3286\">73</sup> כו' בלא אלף<sup data-n=\"3287\">*74</sup> כו' שאין מאיר בחי' אלפים דאאלפך חו\"ב",[["3269","57","<b>לא הביט און ביעקב</b>: בלק כג, כא."],["3270","58","<b>בוחן לבות וכליות</b>: תהלים ז, י [ושם ובחן וכ\"ה באגה\"ק סו\"ס כד — אבל כ\"ה גם בתו\"א כאן. וראה גם אבן עזרא שם]. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 93 מובא: אני הוי' חוקר לב ובוחן כליות — ירמי' יז, י [ושם: בחן]. במאמרי אדה\"ז תקס\"ה כאן ס\"ע תשיד מובא הכתוב: בוחן לבבות ה' — ראה משלי יז, ג."],["3271","59","<b>מקרב איש ולב עמוק</b>: ע\"פ תהלים סד, ז."],["3272","60","<b>בד\"ה ארדה נא ואראה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370067\" data-slug=\"torah-or\" data-id=\"3901370067\">תו\"א וירא טו, א</a>."],["3273","61","<b>בד\"ה וככה</b>: תרל\"ז פפ\"ד (ס\"ע קלז) ואילך."],["3274","62","<b>ובביאור ע\"פ לבבתיני</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381250\" data-slug=\"likkutei-torah\" data-id=\"4001381250\">לקו\"ת שה\"ש ל, ב</a>."],["3275","63","<b>הבט משמים</b>: תהלים פ, טו."],["3276","64","<b>עד די כרסוון רמיו</b>: דניאל ז, ט."],["3277","65","<b>כרסוון. . כורסוון</b>: כ\"ה בבוך 1089. בבוך 1162 וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450603\" data-slug=\"or-hatorah-hb\" data-id=\"8316450603\">אוה\"ת</a> כאן ר\"ע 2058: כורסוון. . כורסוון. בזהר: כרסוון. . כרסוון. וראה אוה\"ת איכה ע' א'עג: כורסווין."],["3278","66","<b>תרין כורסוון ירושלים</b>: בזהר: תרי כרסוון לתתא ירושלים."],["3279","67","<b>ירושלים יראה שלם</b>: ראה ב\"ר פנ\"ו, י. תוד\"ה הר תענית טז, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רצה ובהנסמן במ\"מ לשם. עט\"ר שער ר\"ה ע' 56. סה\"מ תרכ\"ז ע' תיד. וש\"נ. לקמן (בחלק ההנחות) הנחה ד\"ה ומקנה רב ובהערה 79."],["3280","68","<b>בהערה לתיקון חצות</b>: סידור קנב, סע\"א."],["3281","69","<b>וכולהו לא נפלו אלא מעלבונה דאוריי'</b>: זהר ויחי רמב, ב שם."],["3282","70","<b>השמים מספרים</b>: תהלים יט, ב."],["3283","71","<b>בפ'</b>: בזהר פ'."],["3284","72","<b>אני אענה את השמים</b>: הושע ב, כג [בהוספת תיבת: אני — ראה לעיל המשך חייב אדם לברך ספל\"ב ובהערה 1295]."],["3285","74","<b>דאאלפף חו\"ב</b>: ע\"פ איוב לג, ג. שבת קד, א."],["3286","73","<b>אלביש שמים קדרות</b>: ישעי' נ, ג."],["3287","*74","<b>בלא אלף</b>: ראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 109."]]],[2000450322,"בהמדות כו', ועמ\"ש במ\"א ע\"פ מ\"ש בפ' בלק דקצ\"א א' ע\"פ שחורה אני<sup data-n=\"3288\">75</sup> כו' נפיק דודה כו', וע' עוד מענין כורסוון רמיו בפ' ויקרא דט\"ו ב' וע' באד\"ר דקל\"ז סע\"ב, וע' עוד מענין השליך משמים ארץ בפ' יתרו פ\"ה א' משפטים קי\"ו<sup data-n=\"3289\">76</sup> א' דמאן יהיב ארץ בשמים דכתי'<sup data-n=\"3290\">77</sup> השליך משמים ארץ אלא ודאי כו' ע\"ש. ומשם יובן מאמר רבה בב\"ח בפרק הספינה דף ע\"ד בענין היכא דנשקי ארעא ורקיעא בהדי הדדי והוא בחי' כי כל בשמים וארץ דאחיד<sup data-n=\"3291\">78</sup> בשמיא וארעא כו'. וע' עוד מענין השליך ס\"פ תרומה דקע\"ה סע\"א וזהו ולא זכר הדום רגליו בחי' והארץ הדום כו'.\n<b>ועוי\"ל</b> עפמש\"ל<sup data-n=\"3292\">79</sup> כי הכסא והשרפרף אין דרכן להעמידן בחוץ אלא בתוך הבית כו', והנה הכסא הוא בחי' שמים בחי' תורה שנק' חתן והשרפרף תשבע\"פ שנק' כלה וכן כנס\"י<sup data-n=\"3293\">81</sup>, והבית הוא המקיף לשניהן כמו חופה שעי\"ז דוקא נעשה יחוד חתן וכלה וכמ\"ש מזה בד\"ה תורה צוה<sup data-n=\"3294\">80</sup>, ולכן בחורבן בהמ\"ק שנסתלק בחי' מקיף עליון דבחי' בית אזי השליך משמים ארץ כו', ופי' גלות זו לבחי' ארץ תשבע\"פ יובן ע\"פ מ\"ש בד\"ה להבין ענין הברכות<sup data-n=\"3295\">82</sup> בענין חותם בברוך כו'. ומכ\"ז יובן מארז\"ל אם ישראל עושין תשובה נגאלין<sup data-n=\"3296\">83</sup> כי תשובה בכל מאדך היינו המשכת מקיף עליון דבחי' בית כו' ועמ\"ש סד\"ה כי ההרים ימושו<sup data-n=\"3297\">84</sup>. והנה לע\"ל כתיב ועמדו רגליו ביום ההוא על הר הזתים<sup data-n=\"3298\">85</sup>, כי לע\"ל יהי' עליות העולמות<sup data-n=\"3299\">86</sup> כנודע מענין וישם מדברה כעדן<sup data-n=\"3300\">87</sup> ועשיי' יהי' כמו אצי' א\"כ מה שעכשיו הדום רגליו הוא בחי' היכל קדה\"ק דיצירה ועשיי' לע\"ל יהי' זה בחי' הר הזתים שהוא כתר דאצי' כו', והיינו כי עכשיו והארץ היא הדום שהיא בחי' מל'<sup data-n=\"3301\">88</sup> ולע\"ל יהי' עליי' המל' בכתר<sup data-n=\"3302\">89</sup> כו' כנודע.",[["3288","75","<b>שחורה אני</b>: שה\"ש א, ה."],["3289","76","<b>קי\"ו</b>: כ\"ה ציון הדף בזהר מהדורת קאפוסט תקס\"ט. ועד\"ז מובא בכ\"מ בכתבי הצ\"צ. ראה לעיל ד\"ה ומקנה רב ובהערה 149."],["3290","77","<b>דכתי'</b>: בזהר: דקאמר."],["3291","78","<b>כי כל. . דאחיד</b>: דהי\"א כט, יא. ראה זהר בראשית לא, א. ת\"ז תמ\"ז פד, א: ותרגום יונתן. סה\"מ תרל\"ב ח\"ב ע' שפא. ראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 106: ות\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תשמב. וש\"נ."],["3292","79","<b>עפמש\"ל</b>: בריש המאמר (ד\"ה ולהבין זה)."],["3293","81","<b>תורה שנק' חתן. . כלה. . כנס\"י</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381102\" data-slug=\"likkutei-torah\" data-id=\"4001381102\">לקו\"ת ברכה צג, סע\"ד</a> ואילך. מאמרי אדה\"א קונטרסים ע' רעג. וש\"נ. לעיל בההמשך שם ובהערה 983."],["3294","80","<b>תורה שנק' חתן. . תשבע\"פ שנק' כלה. . בד\"ה תורה צוה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381105\" data-slug=\"likkutei-torah\" data-id=\"4001381105\">לקו\"ת ברכה צד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381110\" data-slug=\"likkutei-torah\" data-id=\"4001381110\">צה, ד</a>. לעיל המשך חייב אדם לברך פכ\"ו ובהערה 985."],["3295","82","<b>בד\"ה להבין ענין הברכות</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א בראשית ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560197\" data-slug=\"or-hatorah-hb\" data-id=\"8316560197\">אוה\"ת בראשית כרך ג ע' תקסה</a> ואילך. המשך הנ\"ל פל\"ד."],["3296","83","<b>אם ישראל עושין תשובה נגאלין</b>: סנהדרין צז, ב."],["3297","84","<b>סד\"ה כי ההרים ימושו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380881\" data-slug=\"likkutei-torah\" data-id=\"4001380881\">לקו\"ת תצא מא, א</a>."],["3298","85","<b>ועמדו רגליו. . הזתים</b>: זכרי' יד, ד (ושם: הזיתים — ראה גם לעיל המשך וידבר וגו' ויצוום פי\"א על יד הערה 192)."],["3299","86","<b>לע\"ל יהי' עליות העולמות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380117\" data-slug=\"likkutei-torah\" data-id=\"4001380117\">לקו\"ת צו י, סע\"ב</a>. ואתחנן ז, ב ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשעב ואילך."],["3300","87","<b>וישם מדברה כעדן</b>: ישעי' נא, ג. ראה סידור שער התפלה כד, ד. שע\"ת כט, ב ואילך. לקו\"ת (צו שם) ואתחנן ז, ג."],["3301","88","<b>הדום. . מל'</b>: ראה פרדס שער עה\"כ שכ\"ג, פ\"ה מערכת הדום. מאו\"א מערכת הדום סעיף ג."],["3302","89","<b>ולע\"ל יהי' עליי' המל' בכתר</b>: ראה לקו\"ת ואתחנן ומאמרי אדה\"ז שבהערה 86. ש\"א פז, א."]]],[2000450323,"<b>וזהו</b> ג\"כ מ\"ש גדול יהי' כבוד הבית האחרון כו' כי לפי ערך זה גם הבית והמקיף יהי' מבחי' עליונה יותר ממה שהוא עכשיו וכמ\"ש וגבה מאד<sup data-n=\"3303\">90</sup> שבחי' בכל מאדך יהי' מבחי' עליונה יותר ועמ\"ש בד\"ה מזמור שיר חנוכת הבית].",[["3303","90","<b>וגבה מאד</b>: ישעי' נב, יג."]]],[2000450324,"<h3>על חומותיך ירושלים כו'</h3>\n<b></b><b>בס\"ד ש\"פ ואתחנן, ישעי' סי' נ\"ב וא\"ו,</b>\nואת כל אלה ידי כו' אל עני\nואתחנן\n<b>על</b> חומותיך ירושלים<sup data-n=\"3304\">1</sup> הפקדתי שומרים<sup data-n=\"3305\">2</sup>, פי' שומרים הם בחי' או\"מ ע\"ד ואתה משמרה בקרבי<sup data-n=\"3306\">3</sup>, וצ\"ל הלא חומה היא ג\"כ בחי' מקיף שמקיף את העיר ועי\"ז משתמרת העיר ומהו ענין השומרים כו'. והענין דהנה פסוק זה בנחמת ירושלים וזהו בהפטרה דשוש אשיש<sup data-n=\"3307\">4</sup> נחמה הז'<sup data-n=\"3308\">5</sup> ומתחילי' נחמו נחמו<sup data-n=\"3309\">6</sup> ב\"פ י\"ל ע\"ד ב' בחי' דח\"י כמשי\"ת, ומסיימי' בהפקדת שומרים שזהו בפרטיות נחמה הז' נגד כל הז' מקיפים<sup data-n=\"3310\">7</sup> שנכללים בב' בחי' דח\"י כו'. ויובן בהקדים ביאור ענין מ\"ש ואת כל אלה ידי עשתה כו' ויהיו<sup data-n=\"3311\">8</sup> כל אלה נאום ה' כו', דזכר כאן ב' מדרגות עשי' ודבור שהוא",[["3304","1","<b>על חומותיך ירושלים</b>: מאמר זה הוא דרוש הראשון (מהמשך הדרושים הבאים לקמן) שמבאר פיסקא ראשונה מביאור הראשון (על מאמר ד\"ה השמים כסאי) ד\"ה להבין שרשי הדברים הנ\"ל שנדפס במאמרי אדה\"ז תקס\"ה ח\"ב הנחת כ\"ק אדמו\"ר האמצעי ע' תשטו — תשיח (עד ד\"ה והנה שרש ענין). והוא דרוש החמישי מההמשך שבו נתבארו הדרושים דהשמים כסאי וביאוריו שנאמרו בשנת תקס\"ה כמצויין לעיל ברד\"ה ואשא אתכם.\nהכותרת שבריש המאמר: נעתקה מבוך 1162 ואינה מופיעה בבוך זה 1089. אודות ביכלאך אלו ראה המצויין לעיל בריש ד\"ה ואשא אתכם.\nהמאמר (מלבד הפתיחה, וכן הערות שבתוך ההחצע\"ג שנכתבו בגוכתי\"ק) הוא לשון מאמרי אדה\"ז תקס\"ה הנ\"ל עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע, והדברים המובאים בתוך חצאי עיגול שהם בתוך חצאי מרובע [( )] הם מכ\"ק אדמו\"ר האמצעי שנכתבו במאמרי אדה\"ז הנ\"ל בין חצאי עיגול. וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש.\nהמאמר מלבד הפתיחה והסיום נדפס גם בלקו\"ת לג\"פ ה, ב. אוה\"ת בראשית כרך ו ע' 2060 פ\"א.\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות.\nמאמר זה נזכר לקמן בד\"ה ישמח משה על יד הערה 54. ד\"ה אני לדודי על יד הערות 29-27."],["3305","2","<b>על חומותיך ירושלים הפקדתי שומרים</b>: ישעי' סב, ו ואוצ\"ל כן בהכותרת."],["3306","3","<b>ואתה משמרה בקרבי</b>: ברכת אלקי נשמה מברכות ס, ב."],["3307","4","<b>בהפטרה דשוש אשיש</b>: דפ' נצבים — ישעי' סא, י ואילך."],["3308","5","<b>בהפטרה דשוש אשיש נחמה הז'</b>: ראה תוס' מגילה לא, ב ד\"ה ר\"ח. רמב\"ם הל' תפלה פי\"ג, הי\"ט. וראה גם בסדר ההפטורות בסיומם. טושו\"ע או\"ח סתכ\"ח, ס\"ח."],["3309","6","<b>נחמו נחמו</b>: ישעי' מ, א."],["3310","7","<b>הז' מקיפים</b>: ראה בסיום המאמר."],["3311","8","<b>ואת כל אלה ידי עשתה כו' ויהיו</b>: ישעי' סו, ב [בהוספת תיבת: כו' — וכ\"ה במאמרי אדה\"ז תקס\"ה ואוה\"ת כאן]."]]],[2000450325,"ענין תשב\"כ ותושבע\"פ, דהנה ידוע דשרש תושב\"כ הוא בחכמה<sup data-n=\"3312\">9</sup> וכתי' בחכמה עשיה כמ\"ש כולם בחכ' עשית<sup data-n=\"3313\">10</sup> כו' והוא לפי שהחכ' נתלבשה דוקא באותיות שבכתב<sup data-n=\"3314\">11</sup> ודיו<sup data-n=\"3315\">12</sup> שהוא רק בחי' עשי' גשמיות וגם שיהי' הקלף מעובד<sup data-n=\"3316\">13</sup> כו', וזהו מפני מעלת ומדריגת תשב\"כ שא\"א לה לירד מן החכמה עליונה כ\"א ע\"י ההלבשה בבחי' העשי' דוקא והוא ציור אותיות בכתב כו' (וע' בפ' ויקרא בביאור ולא תשבית שמובן ענין פי' מקרא בעשיי'<sup data-n=\"3317\">14</sup> לפי שמקרא לרוב מעלתו יורד ומתלבש עד העשיי' כו', וכמו ראי' תופסת דבר גשמי דוקא ולא רוחני כשמיעה שתופסת רוחני<sup data-n=\"3318\">15</sup> דוקא כמו הקול כמ\"ש אזן מילין תבחן<sup data-n=\"3319\">16</sup> ולא גשמי הנראה לעינים דוקא, ולכאורה הלא ראי' בחכ' ושמיעה בבינה<sup data-n=\"3320\">17</sup>, ועמ\"ש לעיל בענין שמיעה<sup data-n=\"3321\">18</sup> בהאי אתר תליא משא\"כ עשיי' לעילא, אלא דהיא הנותנת שלפי שראי' בחכ' א\"א לירד ולהתלבש כ\"א בדבר גשמי דוקא כו'), משא\"כ תושבע\"פ אינה צריכה להתלבשות כ\"כ בבחי' העשי' באותיות הכתב אלא שגם הלבוש יותר פנימי דילה והוא לבוש הדבור כי הרי ידוע דעיקרה הוא הדבור ולכך נק' תושבע\"פ כו' [ע' זהר ויקהל דף ריש ע\"א], והטעם הוא לפי שכל אור היותר עליון<sup data-n=\"3322\">19</sup> צריך הוא לבוא בהתלבשות ביותר לבוש גשמי וכל שאינו אור עליון כ\"כ א\"צ לבוא ללבושים חיצונים כ\"כ כו' וכמ\"ש במ\"א [בת\"א בד\"ה כי אברהם לא ידענו<sup data-n=\"3323\">20</sup>], (וע' בפ' לך לך בד\"ה הנה<sup data-n=\"3324\">21</sup> אברם<sup data-n=\"3325\">22</sup>, ובפ' וירא בד\"ה פתח",[["3312","9","<b>דשרש תושב\"כ הוא בחכמה</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["3313","10","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["3314","11","<b>באותיות שבכתב</b>: ראה גם פרדס שער האותיות שכ\"ז, פ\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540171\" data-slug=\"torat-chaim\" data-id=\"2300540171\">תו\"ח וארא ח\"א ע, א</a> ובהנסמן לשם."],["3315","12","<b>ודיו</b>: ראה גם שו\"ע אדה\"ז הל' תפילין סל\"ב, ס\"ד."],["3316","13","<b>שיהי' הקלף מעובד</b>: ראה שו\"ע יו\"ד הל' ס\"ת סרע\"א, ס\"א — ס\"ג. שו\"ע אדה\"ז הל' תפילין סל\"ב, ס\"י."],["3317","14","<b>בפ' ויקרא בביאור ולא תשבית. . מקרא בעשיי'</b>: לקו\"ת שם ה, סע\"א ואילך."],["3318","15","<b>ראי'. . גשמי. . כשמיעה. . רוחני</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370070\" data-slug=\"torah-or\" data-id=\"3901370070\">תו\"א וירא טו, ד</a>. מקץ מ, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380310\" data-slug=\"likkutei-torah\" data-id=\"4001380310\">לקו\"ת</a> [בהוספות ל] ויקרא נד, ג. מאמרי אדה\"ז תקס\"ד ע' רו. תקס\"ט ע' פט ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' רלח. שער האמונה מג, ב ואילך. אוה\"ת תצוה ע' א'תשנח. סה\"מ תרכ\"ח ע' יד. תרכ\"ט ע' ק. ע' קפג. ע' ריד. תרל\"ב ח\"א ע' פ וע' רלט."],["3319","16","<b>אזן מילין תבחן</b>: איוב יב, יא."],["3320","17","<b>ראי' בחכ' ושמיעה בבינה</b>: ראה לעיל המשך חייב אדם לברך פ\"ח ובהערה 235."],["3321","18","<b>ועמ\"ש לעיל בענין שמיעה</b>: במאמר ד\"ה ומקנה רב על יד הערה 71 ואילך. וש\"נ."],["3322","19","<b>שכל אור היותר עליון</b>: ראה (בנוסף להמצויין בסמוך בפנים) לקמן (בחלק ההנחות) הנחה ד\"ה ביום ההוא יהי' ובהערה 47."],["3323","20","<b>בת\"א בד\"ה כי אברהם לא ידענו</b>: ראה שם מג\"א צג, ג."],["3324","21","<b>בפ' לך לך בד\"ה הנה אברם</b>: תו\"א שם יא, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380199\" data-slug=\"likkutei-torah\" data-id=\"4001380199\">לקו\"ת אחרי כח, ד</a>. סה\"מ תרל\"ו ח\"ב ע' שנו."],["3325","22","<b>בד\"ה הנה אברם</b>: כן צויין גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380754\" data-slug=\"likkutei-torah\" data-id=\"4001380754\">לקו\"ת ואתחנן י, ג</a>. ברכה צג, ג. בסמוך בפנים ובסה\"מ תרל\"ו שם מציין: בד\"ה לך לך."]]],[2000450326,"אלי'<sup data-n=\"3326\">23</sup>, ובפ' מקץ בד\"ה ת\"ר מצות נ\"ח<sup data-n=\"3327\">24</sup> ב\"ש<sup data-n=\"3328\">25</sup>, ובכ\"ד בענין ויבא משה בתוך הענן<sup data-n=\"3329\">26</sup> שהענן נעשה לבוש למשה, שנת' שם איך שאור היותר עליון מוכרח לבוא למטה בלבושי' רבים וגשמי' כו'<sup data-n=\"3330\">27</sup>, וע\"ד שאה\"כ ותרב חכמת שלמה<sup data-n=\"3331\">28</sup> כו' ויחכם מכל האדם<sup data-n=\"3332\">29</sup> כו' וידבר שלשת אלפים משל<sup data-n=\"3333\">30</sup> שנת' בכ\"ד ע' בד\"ה לך לך הנ\"ל, שמחכ' שלמה עד שיתגלה למטה הי' צריך ג' אלפים משל אלף משלי' נגד כל עולם (והגם שכמ\"י<sup data-n=\"3334\">31</sup> הי' מרכבה לבחי' המל' עכ\"ז מפני שבשלמה כתי' בחכמה שהי' לו לשון נתינה<sup data-n=\"3335\">32</sup> שזהו אינו דומה למרכבה סתם למדת המל' שבטל לגבי רוכבו משא\"כ בשלמה ח\"ת הי' נתון לו כו'<sup data-n=\"3336\">33</sup>, ועד\"ז יובן כאן). וזהו שנאמר בתושב\"כ ואת כל אלה ידי עשתה בבחי' לבוש העשי' דוקא [וע\"ד לחכימא ברמיזא<sup data-n=\"3337\">34</sup> מה שא\"א לפרש כלל בהדבור בת\"א בד\"ה לכן אמור לבנ\"י<sup data-n=\"3338\">35</sup>, ובלק\"ת פ' אמור סד\"ה ביאור ע\"פ והניף הכהן אותם<sup data-n=\"3339\">36</sup>, וכן מבואר במד\"ר פ' בראשית פי\"ב<sup data-n=\"3340\">37</sup> דמ\"ש ואת כל אלה ידי עשתה קאי על התורה על שם אלה החוקים והמשפטים והתורות<sup data-n=\"3341\">38</sup> ע\"ש] ובתושבע\"פ נאמר ויהיו כל אלה נאום ה' פי' נאום הוא בחי' הדבור כידוע בלשון תרגום נאום הוא הדבור וכמו נומינו<sup data-n=\"3342\">39</sup> לשליח במשנה ספ\"ו דגיטין<sup data-n=\"3343\">40</sup>. והיינו דבר ה' זו הלכה<sup data-n=\"3344\">41</sup>",[["3326","23","<b>ובפ' וירא בד\"ה פתח אלי'</b>: תו\"א שם יד, ב ד\"ה אך."],["3327","24","<b>ובפ' מקץ בד\"ה ת\"ר מצות נ\"ח ב\"ש</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו\"א שם לב, ד</a> ואילך."],["3328","25","<b>בד\"ה ת\"ר מצות נ\"ח ב\"ש</b>: בתו\"א שם הד\"ה: ת\"ר מצות נ\"ח כו' בש\"א. בסה\"מ תרל\"ו ח\"ב ע' שא מציין: ת\"ר נ\"ח מצות נ\"ח."],["3329","26","<b>ויבא משה בתוך הענן</b>: משפטים כד, יח. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 25 כותב: ”וכמ\"ש בת\"א באריכות בכמה מקומות\" — ראה גם אגה\"ק סכ\"ט (קמח, א). תו\"א ח\"ש טז, א. ביאוה\"ז בשלח מג, א. מאמרי אדה\"א דברים ח\"ג ע' א'רעז. מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' נב. ע' רז. סה\"מ תרכ\"ח ע' נד ואילך. תרל\"ב ח\"א ע' צח. ע' קפז ואילך. תרל\"ה ח\"א ע' צ."],["3330","27","<b>כו'</b>: כנראה מגוכתי\"ק הנה כאן הי' סיום ההגה, אלא שאח\"כ מחק סיום הסוגר והתיבה שלאח\"ז והמשיך כבפנים. וראה לקמן בהערה 33."],["3331","28","<b>ותרב חכמת שלמה</b>: מל\"א ה, י."],["3332","29","<b>ויחכם מכל האדם</b>: מל\"א ה, יא."],["3333","30","<b>וידבר שלשת אלפים משל</b>: מל\"א ה, יב. ראה גם לעיל מאמר ד\"ה ואשא אתכם ובהערה 183."],["3334","31","<b>שכמ\"י</b>: אוצ\"ל: שדמ\"י ( שדוד מלך ישראל — ראה לעיל המשך אם כסף תלוה פי\"ד ובהערה 306). לקמן (בחלק ההנחות) בהנחה כאן כתוב: וההפרש בין שלמה לשאר אותן שהיו מרכבה לבחי' המל' הוא."],["3335","32","<b>שבשלמה כתי' בחכמה. . לשון נתינה</b>: מל\"א ג, יב. ה, ט. כו. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 30 מביא: החכ' נתון לך — דהי\"ב א, יב [בדילוג]."],["3336","33","<b>כו'</b>: באוה\"ת כאן ר\"ע תתרלא: כו'). אבל בבוך 1162 כתב כאן סיום הסוגר ואח\"כ מחקו. וכן סיום הסוגר אינה מופיע בבוך זה 1089 (אודות ביכלאך אלו ראה הערה 1). ראה גם לעיל בהערה 27."],["3337","34","<b>לחכימא ברמיזא</b>: ראה מדרש משלי כב, טו. לעיל המשך וידבר וגו' ויצוום פ\"ה ובהערה 105."],["3338","35","<b>בת\"א בד\"ה לכן אמור לבנ\"י</b>: וארא נז, סע\"ד."],["3339","36","<b>ובלק\"ת פ' אמור. . אותם</b>: לט, ג. נעתק בשינויים לעיל בהמשך וידבר וגו' ויצוום שם."],["3340","37","<b>במד\"ר פ' בראשית פי\"ב</b>: ס\"ב."],["3341","38","<b>אלה החוקים והמשפטים והתורות</b>: בחוקותי כו, מו."],["3342","39","<b>נאום. . נומינו</b>: ראה גם מלאכת שלמה־ תויו\"ט־ ותוספות רע\"ק סוף יבמות."],["3343","40","<b>וכמו. . דגיטין</b>: תיקון הצ\"צ. במאמרי אדה\"ז כאן ע' תשטו: כמו נומית לבן עזאי כו'."],["3344","41","<b>דבר ה' זו הלכה</b>: שבת קלח, ב. עמוס ח, יב."]]],[2000450327,"דתושבע\"פ דוקא, וזהו בחי' התהוות נאום דהוי' כו' [ועמ\"ש מזה בד\"ה רני ושמחי בת<sup data-n=\"3345\">42</sup> בפירוש לי הכסף לי הזהב נאום ה'<sup data-n=\"3346\">43</sup>, ומ\"ש ע\"פ ויאבק איש עמו<sup data-n=\"3347\">44</sup> בפירוש משם אורידך נאום ה'<sup data-n=\"3348\">45</sup>].\n<b>והנה</b> ידוע דשרש תשב\"כ ותושבע\"פ הוא בחי' ז\"א ונוק' כי תושבע\"פ מל' קרינן לה<sup data-n=\"3349\">46</sup> ואוריי' מחכ' נפקת היינו בחי' ז\"א שהוא תושב\"כ<sup data-n=\"3350\">47</sup> כו', וא\"כ הרי על בנין דזו\"נ דאצי' הוא שאומר כאן ואת כל אלה ידי עשתה ויהיו כל אלה נאום ה' כו'. וביאור הדברים להיות ידוע בדרך כלל בכל ההשתלשלו' הנה הוא בחי' נרנח\"י<sup data-n=\"3351\">48</sup>, ולנר\"נ יש כלים<sup data-n=\"3352\">49</sup> ולחי' יחידה אין להם כלים<sup data-n=\"3353\">50</sup> כלל, דהיינו דנר\"נ הם אורות פנימים בכלים ונק' מוחא ולבא וכבדא<sup data-n=\"3354\">51</sup> כידוע, וגם יש להם אורות מקיפים, אבל חי' יחידה הן רק בחי' אורות מקיפים עליונים שאין להם בחי' כלים לפי שלא יצאו להיות בבחי' צמצום דאור פנימי כו' [ועמ\"ש מזה בסדור סד\"ה ועשו להם ציצית<sup data-n=\"3355\">52</sup> ובלק\"ת בהביאור ע\"פ השמים כסאי שבסוף שה\"ש<sup data-n=\"3356\">53</sup>, ונת' מזה ג\"כ בהביאור ע\"פ בעצם היום הזה<sup data-n=\"3357\">54</sup> נמול אברהם ובהביאור ע\"פ וידבר אלקים את כל הדברים האלה לאמר פ\"א<sup data-n=\"3358\">55</sup>]. והענין הוא בכלל דבחי' הכתר הוא הכולל אורות מקיפים הללו דבחי' יחידה לפי שהיא ממוצע בין המאציל לנאצלים<sup data-n=\"3359\">56</sup> ומחמת בחי' יחידה שבו הוא מבחי' התחתונה שבמאציל כו' [וכ\"כ במאו\"א אות יו\"ד סל\"ט יחידה בכתר וע' בזח\"א פ' בראשית דכ\"ב סע\"ב גבי אבל איהו חד ולא בחושבן<sup data-n=\"3360\">57</sup>, וע' בתו\"א פ' וירא גבי וזהו אנת<sup data-n=\"3361\">58</sup> הוא חד ולא בחושבן ובפ' וארא בד\"ה וארא אל אברהם<sup data-n=\"3362\">59</sup> גבי אך הענין שבאמת לגבי",[["3345","42","<b>בד\"ה רני ושמחי בת</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370166\" data-slug=\"torah-or\" data-id=\"3901370166\">תו\"א מקץ לו, ב</a>."],["3346","43","<b>לי הכסף ולי הזהב נאום ה'</b>: חגי ב, ח."],["3347","44","<b>ע\"פ ויאבק איש עמו</b>: וישלח לב, כב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, ב</a>."],["3348","45","<b>משם אורידך נאום ה'</b>: עובדי' א, ד."],["3349","46","<b>תושבע\"פ מל' קרינן לה</b>: ראה ת\"ז בהקדמה יז, א."],["3350","47","<b>ז\"א שהוא תושב\"כ</b>: ראה גם ע\"ח שער יעקב ולאה של\"ז, פ\"א. שע\"ת קה, ג הערה 21."],["3351","48","<b>נרנח\"י</b>: ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["3352","49","<b>ולנר\"נ יש כלים</b>: בהנחה כאן על יד הערה 38: ”כ\"ה בזהר ובס\"י\" (ראה בהערה שם). ראה אבן עזרא משפטים כג, כה. יסוד מורא — להנ\"ל — ש\"ז. ע\"ח שער אח\"פ ש\"ד, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקיז־ בראשית ע' שסה־ קונטרסים ע' שכא־ אמ\"ב שער התפילין קכד, א."],["3353","50","<b>ולחי' יחידה אין להם כלים</b>: ראה שעה\"י קכח, ב ובהערה 51. מאמרי אדה\"א קונטרסים ע' רנג. וש\"נ. לקמן מאמר ד\"ה זה עני על יד הערה 57."],["3354","51","<b>מוחא ולבא וכבדא</b>: ראה לעיל הערה 49."],["3355","52","<b>בסדור סד\"ה ועשו להם ציצית</b>: שער הציצית ד, ג ואילך."],["3356","53","<b>ובלק\"ת. . שה\"ש</b>: באוה\"ת שבהערה הבאה מציין: ביאור כי כאשר השמים החדשים שבלק\"ת סוף שה\"ש — נא, א."],["3357","54","<b>בהביאור ע\"פ בעצם היום הזה</b>: אוה\"ת לך כרך ג ע' תשכה."],["3358","55","<b>ובהביאור ע\"פ וידבר. . פ\"א</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380376\" data-slug=\"likkutei-torah\" data-id=\"4001380376\">לקו\"ת במדבר יז, א</a>."],["3359","56","<b>הכתר הוא. . ממוצע. . לנאצלים</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תס. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540828\" data-slug=\"torat-chaim\" data-id=\"2300540828\">תו\"ח שמות ח\"א יא, ג</a>. וש\"נ. סה\"מ תרכ\"ז ע' שמח."],["3360","57","<b>ולא בחושבן</b>: בזהר: בלא חושבן."],["3361","58","<b>ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370063\" data-slug=\"torah-or\" data-id=\"3901370063\">תו\"א</a> פ' וירא גבי וזהו אנת</b>: יד, א."],["3362","59","<b>ובפ' וארא בד\"ה וארא אל אברהם</b>: נה, סע\"ב."]]]]});
